from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timedelta
from typing import Dict, List, Optional
import uuid


@dataclass(frozen=True)
class ToolCapability:
    name: str
    version: str
    enabled: bool = True


@dataclass(frozen=True)
class ResourceLimit:
    cpu_limit: int
    memory_mb: int
    max_processes: int


@dataclass
class ExecutionProfile:

    execution_profile_id: str

    sandbox_policy: str

    tool_profile: str

    cpu_policy: str

    resource_limits: ResourceLimit

    capabilities: List[ToolCapability] = field(default_factory=list)

    labels: Dict[str, str] = field(default_factory=dict)

    created_at: datetime = field(default_factory=datetime.utcnow)

    expires_at: datetime = field(
        default_factory=lambda: datetime.utcnow() + timedelta(hours=12)
    )

    # ---------------------------------------------------------
    # Capability Management
    # ---------------------------------------------------------

    def register_capability(
        self,
        capability: ToolCapability,
    ) -> None:

        self.capabilities.append(capability)

    def capability(
        self,
        name: str,
    ) -> Optional[ToolCapability]:

        for capability in self.capabilities:

            if capability.name.lower() == name.lower():
                return capability

        return None

    def supports_tool(
        self,
        name: str,
    ) -> bool:

        capability = self.capability(name)

        return capability is not None and capability.enabled

    # ---------------------------------------------------------
    # Labels
    # ---------------------------------------------------------

    def add_label(
        self,
        key: str,
        value: str,
    ) -> None:

        self.labels[key] = value

    def label(
        self,
        key: str,
    ) -> Optional[str]:

        return self.labels.get(key)

    # ---------------------------------------------------------
    # Resource Policy
    # ---------------------------------------------------------

    def cpu_limit(self) -> int:

        return self.resource_limits.cpu_limit

    def memory_limit(self) -> int:

        return self.resource_limits.memory_mb

    def process_limit(self) -> int:

        return self.resource_limits.max_processes

    # ---------------------------------------------------------
    # Lease
    # ---------------------------------------------------------

    def expired(self) -> bool:

        return datetime.utcnow() > self.expires_at

    def extend(
        self,
        duration: timedelta,
    ) -> None:

        self.expires_at += duration

    # ---------------------------------------------------------
    # Validation
    # ---------------------------------------------------------

    def validate(self) -> bool:

        return (

            self.execution_profile_id != ""

            and

            self.sandbox_policy != ""

            and

            self.tool_profile != ""

            and

            self.cpu_policy != ""

            and

            len(self.capabilities) > 0

            and

            not self.expired()

        )


class ExecutionProfileFactory:

    @staticmethod
    def create(

        sandbox_policy: str,

        tool_profile: str,

        cpu_policy: str,

        resource_limits: ResourceLimit,

    ) -> ExecutionProfile:

        return ExecutionProfile(

            execution_profile_id=
                f"profile-{uuid.uuid4().hex}",

            sandbox_policy=
                sandbox_policy,

            tool_profile=
                tool_profile,

            cpu_policy=
                cpu_policy,

            resource_limits=
                resource_limits,

        )
