package composition;

import java.time.Instant;
import java.util.Objects;

/**
 * Immutable runtime context produced after infrastructure
 * composition. It is consumed by the ComputeOrchestrator
 * and later trusted by the ContainerLaunchService.
 */
public final class RuntimeExecutionContext {

    // --------------------------------------------------------
    // Canonical Runtime Identity
    // --------------------------------------------------------

    private final String volumeBindingId;

    private final String networkBindingId;

    private final String executionProfileId;

    // --------------------------------------------------------
    // Runtime Configuration
    // --------------------------------------------------------

    private final String storageClass;

    private final String networkZone;

    private final String sandboxPolicy;

    private final String toolProfile;

    private final String cpuPolicy;

    // --------------------------------------------------------
    // Metadata
    // --------------------------------------------------------

    private final Instant createdAt;

    public RuntimeExecutionContext(

            String volumeBindingId,

            String networkBindingId,

            String executionProfileId,

            String storageClass,

            String networkZone,

            String sandboxPolicy,

            String toolProfile,

            String cpuPolicy

    ) {

        this.volumeBindingId =
                Objects.requireNonNull(volumeBindingId);

        this.networkBindingId =
                Objects.requireNonNull(networkBindingId);

        this.executionProfileId =
                Objects.requireNonNull(executionProfileId);

        this.storageClass =
                Objects.requireNonNull(storageClass);

        this.networkZone =
                Objects.requireNonNull(networkZone);

        this.sandboxPolicy =
                Objects.requireNonNull(sandboxPolicy);

        this.toolProfile =
                Objects.requireNonNull(toolProfile);

        this.cpuPolicy =
                Objects.requireNonNull(cpuPolicy);

        this.createdAt =
                Instant.now();

    }

    // --------------------------------------------------------
    // Identity
    // --------------------------------------------------------

    public String volumeBindingId() {

        return volumeBindingId;

    }

    public String networkBindingId() {

        return networkBindingId;

    }

    public String executionProfileId() {

        return executionProfileId;

    }

    // --------------------------------------------------------
    // Runtime Configuration
    // --------------------------------------------------------

    public String storageClass() {

        return storageClass;

    }

    public String networkZone() {

        return networkZone;

    }

    public String sandboxPolicy() {

        return sandboxPolicy;

    }

    public String toolProfile() {

        return toolProfile;

    }

    public String cpuPolicy() {

        return cpuPolicy;

    }

    // --------------------------------------------------------
    // Validation
    // --------------------------------------------------------

    public boolean isValid() {

        return

                !volumeBindingId.isBlank()

                        &&

                        !networkBindingId.isBlank()

                        &&

                        !executionProfileId.isBlank()

                        &&

                        !storageClass.isBlank()

                        &&

                        !networkZone.isBlank()

                        &&

                        !sandboxPolicy.isBlank()

                        &&

                        !toolProfile.isBlank()

                        &&

                        !cpuPolicy.isBlank();

    }

    // --------------------------------------------------------
    // Helpers
    // --------------------------------------------------------

    public boolean belongsToZone(

            String zone

    ) {

        return networkZone.equalsIgnoreCase(zone);

    }

    public boolean usesStorageClass(

            String storage

    ) {

        return storageClass.equalsIgnoreCase(storage);

    }

    public boolean usesSandboxPolicy(

            String policy

    ) {

        return sandboxPolicy.equalsIgnoreCase(policy);

    }

    public boolean sameIsolationContext(

            RuntimeExecutionContext other

    ) {

        return

                volumeBindingId.equals(other.volumeBindingId)

                        &&

                        networkBindingId.equals(other.networkBindingId)

                        &&

                        executionProfileId.equals(other.executionProfileId);

    }

    public Instant createdAt() {

        return createdAt;

    }

}
