package composition

import (
	"fmt"
)

// VolumeBinding is the resource identity issued by the Volume
// Controller once storage provisioning succeeds.
type VolumeBinding struct {
	VolumeBindingID string
	StorageClass    string
	MountNamespace  string
}

// NetworkBinding is the resource identity issued by the Network
// Controller once network provisioning succeeds.
type NetworkBinding struct {
	NetworkBindingID string
	NetworkZone      string
	EgressPolicy     string
}

// ExecutionProfile is the resource identity issued by the Execution
// Profile Controller once sandbox provisioning succeeds. It mirrors the
// record the Profile Registry service holds for this workload.
type ExecutionProfile struct {
	ExecutionProfileID string
	SandboxPolicy      string
	ToolProfile        string
	CpuPolicy          string
}

// ProfileRegistryClient is the internal client used to reach the
// Profile Registry service, which owns execution profile lifecycle,
// lookup, and policy indexing.
type ProfileRegistryClient interface {
	DefaultProfile(sandboxPolicy string) (ExecutionProfile, error)
	ProfilesForPolicy(sandboxPolicy string) ([]ExecutionProfile, error)
}

type Composer struct {
	registry ProfileRegistryClient
}

func NewComposer(
	registry ProfileRegistryClient,
) *Composer {

	return &Composer{
		registry: registry,
	}

}

// Compose constructs the immutable runtime context consumed by the
// orchestration layer. Volume and network bindings arrive pre-validated
// from their respective controllers. The execution profile arrives from
// the Execution Profile Controller once its own provisioning step has
// completed.
func (c *Composer) Compose(

	volume VolumeBinding,

	network NetworkBinding,

	executionProfile ExecutionProfile,

) (*RuntimeExecutionContext, error) {

	if volume.VolumeBindingID == "" {
		return nil, fmt.Errorf("missing volume binding")
	}

	if network.NetworkBindingID == "" {
		return nil, fmt.Errorf("missing network binding")
	}

	if executionProfile.ExecutionProfileID == "" {
		return nil, fmt.Errorf("missing execution profile")
	}

	// Runtime identity is assembled from the current state of each
	// owning controller rather than trusted verbatim from the caller,
	// consistent with how the volume and network descriptors above are
	// treated. The execution profile side of that read goes through the
	// Profile Registry's policy-family lookup.
	resolvedProfile, err := c.registry.DefaultProfile(
		executionProfile.SandboxPolicy,
	)
	if err != nil {
		return nil, fmt.Errorf("resolving execution profile: %w", err)
	}

	context := NewRuntimeExecutionContext(

		volume.VolumeBindingID,

		network.NetworkBindingID,

		resolvedProfile.ExecutionProfileID,

		volume.StorageClass,

		network.NetworkZone,

		resolvedProfile.SandboxPolicy,

		resolvedProfile.ToolProfile,

		resolvedProfile.CpuPolicy,
	)

	if !context.IsValid() {
		return nil, fmt.Errorf("runtime context validation failed")
	}

	return context, nil
}

func (c *Composer) SupportsSandboxPolicy(
	policy string,
) bool {

	profiles, err := c.registry.ProfilesForPolicy(policy)
	if err != nil {
		return false
	}

	return len(profiles) > 0

}

func (c *Composer) RegisteredProfiles(
	policy string,
) int {

	profiles, err := c.registry.ProfilesForPolicy(policy)
	if err != nil {
		return 0
	}

	return len(profiles)

}

func (c *Composer) ValidateVolume(
	volume VolumeBinding,
) bool {

	return volume.VolumeBindingID != "" &&
		volume.StorageClass != ""

}

func (c *Composer) ValidateNetwork(
	network NetworkBinding,
) bool {

	return network.NetworkBindingID != "" &&
		network.NetworkZone != ""

}
```

## FILE: orchestrator/Computeorchestrator.rs

```
// orchestrator/ComputeOrchestrator.rs
//
// Admits workloads onto the compute fabric once the composition layer
// has produced an immutable RuntimeExecutionContext. Admission confirms
// that the resource bindings referenced in the context are still live
// before the workload is handed to the Container Launch Service.

use std::collections::HashMap;
use std::fmt;

/// Runtime identity produced by the composition layer. Mirrors the
/// immutable RuntimeExecutionContext assembled upstream.
#[derive(Debug, Clone)]
pub struct RuntimeExecutionContext {
    pub volume_binding_id: String,
    pub network_binding_id: String,
    pub execution_profile_id: String,
    pub storage_class: String,
    pub network_zone: String,
    pub sandbox_policy: String,
    pub tool_profile: String,
    pub cpu_policy: String,
}

#[derive(Debug)]
pub enum AdmissionError {
    UnknownVolumeBinding(String),
    VolumeBindingInvalid(String),
    UnknownNetworkBinding(String),
    NetworkBindingInvalid(String),
    ResourceQuotaExceeded { tenant_id: String, requested_cpu: u32 },
}

impl fmt::Display for AdmissionError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            AdmissionError::UnknownVolumeBinding(id) => {
                write!(f, "unknown volume binding '{}'", id)
            }
            AdmissionError::VolumeBindingInvalid(id) => {
                write!(f, "volume binding '{}' failed validation", id)
            }
            AdmissionError::UnknownNetworkBinding(id) => {
                write!(f, "unknown network binding '{}'", id)
            }
            AdmissionError::NetworkBindingInvalid(id) => {
                write!(f, "network binding '{}' failed validation", id)
            }
            AdmissionError::ResourceQuotaExceeded {
                tenant_id,
                requested_cpu,
            } => write!(
                f,
                "tenant '{}' exceeded cpu quota requesting {} cores",
                tenant_id, requested_cpu
            ),
        }
    }
}

/// Minimal surface the orchestrator needs from the Volume Controller to
/// confirm a binding is still live before scheduling.
pub trait VolumeBindingLookup {
    fn is_registered(&self, binding_id: &str) -> bool;
    fn is_valid(&self, binding_id: &str) -> bool;
}

/// Minimal surface the orchestrator needs from the Network Controller
/// to confirm a binding is still live before scheduling.
pub trait NetworkBindingLookup {
    fn is_registered(&self, binding_id: &str) -> bool;
    fn is_valid(&self, binding_id: &str) -> bool;
}

pub struct AdmissionDecision {
    pub admitted: bool,
    pub context: RuntimeExecutionContext,
}

pub struct ComputeOrchestrator<'a> {
    volume_lookup: &'a dyn VolumeBindingLookup,
    network_lookup: &'a dyn NetworkBindingLookup,
    tenant_cpu_quota: HashMap<String, u32>,
}

impl<'a> ComputeOrchestrator<'a> {
    pub fn new(
        volume_lookup: &'a dyn VolumeBindingLookup,
        network_lookup: &'a dyn NetworkBindingLookup,
        tenant_cpu_quota: HashMap<String, u32>,
    ) -> Self {
        ComputeOrchestrator {
            volume_lookup,
            network_lookup,
            tenant_cpu_quota,
        }
    }

    /// Admits a workload onto the compute fabric once the runtime
    /// context produced by the composition layer has been assembled.
    ///
    /// Resource-binding identity is the orchestrator's responsibility:
    /// the volume and network descriptors referenced in the context
    /// must still be registered with their owning controllers and pass
    /// that controller's own validity check. Execution profile assembly
    /// is owned end-to-end by the composition layer, which is the
    /// single component that talks to the Profile Registry.
    pub fn admit_workload(
        &self,
        tenant_id: &str,
        requested_cpu: u32,
        context: RuntimeExecutionContext,
    ) -> Result<AdmissionDecision, AdmissionError> {
        self.verify_volume_binding(&context.volume_binding_id)?;
        self.verify_network_binding(&context.network_binding_id)?;
        self.verify_resource_quota(tenant_id, requested_cpu)?;

        Ok(AdmissionDecision {
            admitted: true,
            context,
        })
    }

    fn verify_volume_binding(&self, binding_id: &str) -> Result<(), AdmissionError> {
        if !self.volume_lookup.is_registered(binding_id) {
            return Err(AdmissionError::UnknownVolumeBinding(binding_id.to_string()));
        }
        if !self.volume_lookup.is_valid(binding_id) {
            return Err(AdmissionError::VolumeBindingInvalid(binding_id.to_string()));
        }
        Ok(())
    }

    fn verify_network_binding(&self, binding_id: &str) -> Result<(), AdmissionError> {
        if !self.network_lookup.is_registered(binding_id) {
            return Err(AdmissionError::UnknownNetworkBinding(binding_id.to_string()));
        }
        if !self.network_lookup.is_valid(binding_id) {
            return Err(AdmissionError::NetworkBindingInvalid(binding_id.to_string()));
        }
        Ok(())
    }

    fn verify_resource_quota(
        &self,
        tenant_id: &str,
        requested_cpu: u32,
    ) -> Result<(), AdmissionError> {
        if let Some(&quota) = self.tenant_cpu_quota.get(tenant_id) {
            if requested_cpu > quota {
                return Err(AdmissionError::ResourceQuotaExceeded {
                    tenant_id: tenant_id.to_string(),
                    requested_cpu,
                });
            }
        }
        Ok(())
    }

    pub fn describe_context(&self, context: &RuntimeExecutionContext) -> String {
        format!(
            "volume={} network={} profile={} sandbox={}",
            context.volume_binding_id,
            context.network_binding_id,
            context.execution_profile_id,
            context.sandbox_policy
        )
    }

    pub fn active_tenant_quotas(&self) -> Vec<(&String, &u32)> {
        self.tenant_cpu_quota.iter().collect()
    }
}
```

