// runtime/ContainerLaunchService.cpp
//
// Final stage of the compute fabric. Receives an already-admitted
// RuntimeExecutionContext and translates its fields directly into the
// concrete isolation settings applied to the container process.

#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

namespace runtime {

struct RuntimeExecutionContext {
    std::string volumeBindingId;
    std::string networkBindingId;
    std::string executionProfileId;
    std::string storageClass;
    std::string networkZone;
    std::string sandboxPolicy;
    std::string toolProfile;
    std::string cpuPolicy;
};

struct LaunchResult {
    std::string containerId;
    std::string appliedSandboxProfile;
    std::string appliedToolAllowlist;
    std::string appliedCpuShares;
};

// Maps a sandbox policy name to the concrete seccomp profile applied to
// the container's Linux namespaces.
class SandboxProfileCatalog {
public:
    std::string resolve(const std::string& sandboxPolicy) const {
        static const std::map<std::string, std::string> profiles = {
            {"strict-isolated", "/etc/runtime/seccomp/strict-isolated.json"},
            {"standard", "/etc/runtime/seccomp/standard.json"},
            {"permissive-batch", "/etc/runtime/seccomp/permissive-batch.json"},
        };

        auto it = profiles.find(sandboxPolicy);
        if (it == profiles.end()) {
            throw std::runtime_error(
                "no seccomp profile registered for sandbox policy '" + sandboxPolicy + "'");
        }
        return it->second;
    }
};

// Maps a tool profile name to the set of binaries a workload is
// permitted to invoke inside the sandbox.
class ToolAllowlistCatalog {
public:
    std::vector<std::string> resolve(const std::string& toolProfile) const {
        static const std::map<std::string, std::vector<std::string>> allowlists = {
            {"minimal", {"python3"}},
            {"data-pipeline", {"python3", "curl", "jq"}},
            {"privileged-debug", {"python3", "curl", "jq", "strace", "gdb", "tcpdump"}},
        };

        auto it = allowlists.find(toolProfile);
        if (it == allowlists.end()) {
            throw std::runtime_error(
                "no tool allowlist registered for tool profile '" + toolProfile + "'");
        }
        return it->second;
    }
};

// ContainerLaunchService receives an already-admitted
// RuntimeExecutionContext and treats it as the single source of truth
// for the workload's approved runtime identity. Composition and
// admission are not repeated here; this stage only translates the
// context's fields into concrete isolation settings.
class ContainerLaunchService {
public:
    ContainerLaunchService(SandboxProfileCatalog sandboxCatalog, ToolAllowlistCatalog toolCatalog)
        : sandboxCatalog_(std::move(sandboxCatalog)), toolCatalog_(std::move(toolCatalog)) {}

    LaunchResult launch(const RuntimeExecutionContext& context, const std::string& workloadName) {
        if (context.volumeBindingId.empty() || context.networkBindingId.empty() ||
            context.executionProfileId.empty()) {
            throw std::runtime_error(
                "incomplete runtime execution context for workload '" + workloadName + "'");
        }

        std::string seccompProfilePath = sandboxCatalog_.resolve(context.sandboxPolicy);
        std::vector<std::string> allowedTools = toolCatalog_.resolve(context.toolProfile);
        std::string cpuShares = resolveCpuShares(context.cpuPolicy);

        applyNamespaceIsolation(context.networkZone, context.storageClass);
        applySeccompProfile(seccompProfilePath);
        applyToolAllowlist(allowedTools);
        applyCpuShares(cpuShares);

        std::string containerId = generateContainerId(workloadName, context.executionProfileId);

        return LaunchResult{
            containerId,
            seccompProfilePath,
            joinTools(allowedTools),
            cpuShares,
        };
    }

private:
    SandboxProfileCatalog sandboxCatalog_;
    ToolAllowlistCatalog toolCatalog_;

    std::string resolveCpuShares(const std::string& cpuPolicy) const {
        static const std::map<std::string, std::string> shares = {
            {"shared", "512"},
            {"guaranteed", "2048"},
            {"burstable", "1024"},
        };
        auto it = shares.find(cpuPolicy);
        if (it == shares.end()) {
            throw std::runtime_error("no cpu share mapping for policy '" + cpuPolicy + "'");
        }
        return it->second;
    }

    void applyNamespaceIsolation(const std::string& networkZone, const std::string& storageClass) {
        std::cout << "binding network namespace to zone " << networkZone
                  << " and mount namespace to storage class " << storageClass << std::endl;
    }

    void applySeccompProfile(const std::string& profilePath) {
        std::cout << "applying seccomp profile " << profilePath << std::endl;
    }

    void applyToolAllowlist(const std::vector<std::string>& tools) {
        std::cout << "restricting workload to " << tools.size() << " allowed executables" << std::endl;
    }

    void applyCpuShares(const std::string& shares) {
        std::cout << "setting cpu.shares to " << shares << std::endl;
    }

    std::string generateContainerId(const std::string& workloadName, const std::string& executionProfileId) {
        return workloadName + "-" + executionProfileId.substr(0, 8);
    }

    std::string joinTools(const std::vector<std::string>& tools) const {
        std::string result;
        for (size_t i = 0; i < tools.size(); ++i) {
            result += tools[i];
            if (i + 1 < tools.size()) result += ",";
        }
        return result;
    }
};

}  // namespace runtime
