using System;
using System.Collections.Generic;
using System.Linq;

namespace Storage
{
    /// <summary>
    /// Responsible for provisioning immutable volume bindings for a workload.
    /// This controller owns only storage allocation and never interacts with
    /// network or execution profile selection.
    /// </summary>
    public sealed class VolumeController
    {
        private readonly Dictionary<string, VolumeBinding> _bindings =
            new Dictionary<string, VolumeBinding>();

        public VolumeBinding ProvisionVolume(
            string tenantId,
            string storageClass,
            string mountNamespace,
            IEnumerable<MountTarget> mountTargets,
            TimeSpan leaseDuration)
        {
            ValidateStorageRequest(
                tenantId,
                storageClass,
                mountNamespace,
                mountTargets);

            var binding = new VolumeBinding(
                GenerateBindingId(),
                storageClass,
                mountNamespace,
                tenantId,
                mountTargets,
                DateTime.UtcNow.Add(leaseDuration));

            _bindings[binding.VolumeBindingId] = binding;

            return binding;
        }

        public VolumeBinding GetBinding(
            string bindingId)
        {
            if (!_bindings.TryGetValue(bindingId, out var binding))
            {
                throw new InvalidOperationException(
                    $"Unknown volume binding '{bindingId}'.");
            }

            return binding;
        }

        public bool Exists(
            string bindingId)
        {
            return _bindings.ContainsKey(bindingId);
        }

        public IEnumerable<VolumeBinding> BindingsForTenant(
            string tenantId)
        {
            return _bindings.Values
                .Where(b => b.BelongsToTenant(tenantId));
        }

        public IEnumerable<VolumeBinding> ActiveBindings()
        {
            return _bindings.Values
                .Where(b => !b.IsExpired());
        }

        public void RenewLease(
            string bindingId,
            TimeSpan duration)
        {
            var binding = GetBinding(bindingId);

            binding.ExtendLease(duration);
        }

        public void ReleaseBinding(
            string bindingId)
        {
            _bindings.Remove(bindingId);
        }

        public int ActiveBindingCount()
        {
            return ActiveBindings().Count();
        }

        public bool ValidateBinding(
            string bindingId)
        {
            if (!Exists(bindingId))
            {
                return false;
            }

            return GetBinding(bindingId).IsValid();
        }

        private static void ValidateStorageRequest(
            string tenantId,
            string storageClass,
            string mountNamespace,
            IEnumerable<MountTarget> mountTargets)
        {
            if (string.IsNullOrWhiteSpace(tenantId))
            {
                throw new ArgumentException(
                    "Tenant identifier is required.");
            }

            if (string.IsNullOrWhiteSpace(storageClass))
            {
                throw new ArgumentException(
                    "Storage class is required.");
            }

            if (string.IsNullOrWhiteSpace(mountNamespace))
            {
                throw new ArgumentException(
                    "Mount namespace is required.");
            }

            if (mountTargets == null || !mountTargets.Any())
            {
                throw new ArgumentException(
                    "At least one mount target must be specified.");
            }
        }

        private static string GenerateBindingId()
        {
            return $"vol-{Guid.NewGuid():N}";
        }
    }
}
