## FILE: services/ArchiveValidationService.go

```
package services

import (
	"archive/zip"
	"errors"
	"io"
	"path/filepath"
	"strings"
)

type ArchiveValidationService struct {
}

func NewArchiveValidationService()
	*ArchiveValidationService {

	return &ArchiveValidationService{}
}

func (s *ArchiveValidationService)
ValidateArchive(
	reader *zip.Reader,
) error {

	for _, file := range reader.File {

		if err :=
			s.validateEntry(file.Name); err != nil {

			return err
		}
	}

	return nil
}

func (s *ArchiveValidationService)
validateEntry(
	entry string,
) error {

	cleaned :=
		filepath.Clean(
			entry,
		)

	if strings.HasPrefix(
		cleaned,
		"/",
	) {

		return errors.New(
			"absolute paths forbidden",
		)
	}

	if strings.Contains(
		cleaned,
		"..",
	) {

		return errors.New(
			"path traversal detected",
		)
	}

	if len(cleaned) > 512 {

		return errors.New(
			"path too long",
		)
	}

	return nil
}

func (s *ArchiveValidationService)
ValidateArchiveSize(
	reader *zip.Reader,
) error {

	var total uint64

	for _, file := range reader.File {

		total += file.UncompressedSize64

		if total >
			(2 * 1024 * 1024 * 1024) {

			return errors.New(
				"archive exceeds limit",
			)
		}
	}

	return nil
}

func (s *ArchiveValidationService)
ValidateFileTypes(
	reader *zip.Reader,
) error {

	allowed := map[string]bool{
		".txt":  true,
		".pdf":  true,
		".csv":  true,
		".json": true,
		".log":  true,
	}

	for _, file := range reader.File {

		extension :=
			strings.ToLower(
				filepath.Ext(
					file.Name,
				),
			)

		if extension == "" {
			continue
		}

		if !allowed[extension] {

			return errors.New(
				"unsupported file type",
			)
		}
	}

	return nil
}

func (s *ArchiveValidationService)
InspectArchive(
	reader *zip.Reader,
) error {

	if err :=
		s.ValidateArchive(
			reader,
		); err != nil {

		return err
	}

	if err :=
		s.ValidateArchiveSize(
			reader,
		); err != nil {

		return err
	}

	if err :=
		s.ValidateFileTypes(
			reader,
		); err != nil {

		return err
	}

	for _, file := range reader.File {

		rc, err := file.Open()

		if err != nil {
			return err
		}

		_, err =
			io.CopyN(
				io.Discard,
				rc,
				1024,
			)

		rc.Close()

		if err != nil &&
			err != io.EOF {

			return err
		}
	}

	return nil
}
