## FILE: extractor/ArchiveExtractor.rs

```
use std::fs;
use std::path::PathBuf;

use zip::ZipArchive;

use crate::extractor::ExtractionPolicy;
use crate::extractor::SymlinkHandler;

pub struct ArchiveExtractor {

    policy: ExtractionPolicy,
    symlink_handler: SymlinkHandler,
}

impl ArchiveExtractor {

    pub fn new(
        policy: ExtractionPolicy,
        symlink_handler: SymlinkHandler
    ) -> Self {

        Self {
            policy,
            symlink_handler,
        }
    }

    pub fn extract(
        &self,
        archive: &mut ZipArchive<
            std::fs::File
        >
    ) -> Result<PathBuf, String> {

        let root =
            self.policy
                .extraction_root
                .clone();

        fs::create_dir_all(
            &root
        ).map_err(
            |_| "directory creation failed"
                .to_string()
        )?;

        for i in 0..archive.len() {

            let mut file =
                archive.by_index(i)
                    .map_err(
                        |_| "invalid archive"
                            .to_string()
                    )?;

            let path =
                self.policy
                    .resolve_output_path(
                        file.name()
                    )?;

            if file.is_dir() {

                fs::create_dir_all(
                    &path
                ).map_err(
                    |_| "directory creation failed"
                        .to_string()
                )?;

                continue;
            }

            if self
                .symlink_handler
                .is_symlink(
                    &file
                ) {

                self.symlink_handler
                    .extract_symlink(
                        &mut file,
                        &path
                    )?;

                continue;
            }

            if let Some(parent)
                = path.parent() {

                fs::create_dir_all(
                    parent
                ).map_err(
                    |_| "directory creation failed"
                        .to_string()
                )?;
            }

            let mut outfile =
                fs::File::create(
                    &path
                ).map_err(
                    |_| "file creation failed"
                        .to_string()
                )?;

            std::io::copy(
                &mut file,
                &mut outfile
            ).map_err(
                |_| "copy failed"
                    .to_string()
            )?;
        }

        Ok(root)
    }
}
