func (s *EvidenceService)
DownloadIndexedFile(
	fileID string,
) (
	io.ReadCloser,
	error,
) {

	record, err :=
		s.indexRepo.
			GetIndexedFile(
				fileID,
			)

	if err != nil {

		return nil, err
	}

	reader, err :=
		storage.
