package repositories

import (
	"database/sql"
	"time"
)

type EvidenceRecord struct {
	ID             string
	CaseID         string
	UploadedBy     string
	FileName       string
	Status         string
	ExtractionPath string
	CreatedAt      time.Time
}

type EvidenceRepository struct {
	db *sql.DB
}

func NewEvidenceRepository(
	db *sql.DB,
) *EvidenceRepository {

	return &EvidenceRepository{
		db: db,
	}
}

func (r *EvidenceRepository)
CreateEvidence(
	userID string,
	caseID string,
	fileName string,
) (
	*EvidenceRecord,
	error,
) {

	query := `
	INSERT INTO evidence
	(
		case_id,
		uploaded_by,
		file_name,
		status,
		created_at
	)
	VALUES
	(
		$1,$2,$3,$4,NOW()
	)
	RETURNING
		id,
		created_at
	`

	record := &EvidenceRecord{
		CaseID: caseID,
		UploadedBy: userID,
		FileName: fileName,
		Status: "PENDING_EXTRACTION",
	}

	err := r.db.QueryRow(
		query,
		caseID,
		userID,
		fileName,
		record.Status,
	).Scan(
		&record.ID,
		&record.CreatedAt,
	)

	if err != nil {
		return nil, err
	}

	return record, nil
}

func (r *EvidenceRepository)
UpdateExtractionPath(
	evidenceID string,
	extractionPath string,
) error {

	query := `
	UPDATE evidence
	SET extraction_path = $1
	WHERE id = $2
	`

	_, err := r.db.Exec(
		query,
		extractionPath,
		evidenceID,
	)

	return err
}

func (r *EvidenceRepository)
GetEvidence(
	evidenceID string,
) (
	*EvidenceRecord,
	error,
) {

	query := `
	SELECT
		id,
		case_id,
		uploaded_by,
		file_name,
		status,
		extraction_path,
		created_at
	FROM evidence
	WHERE id = $1
	`

	record := &EvidenceRecord{}

	err := r.db.QueryRow(
		query,
		evidenceID,
	).Scan(
		&record.ID,
		&record.CaseID,
		&record.UploadedBy,
		&record.FileName,
		&record.Status,
		&record.ExtractionPath,
		&record.CreatedAt,
	)

	if err != nil {
		return nil, err
	}

	return record, nil
}
