## FILE: workers/DeploymentEventPublisher.go

```
// Package workers publishes runtime delegation projections onto the
// platform's delegation-publication Kafka topic so that every deployment
// service that needs a fast, execution-optimized view of "who is currently
// delegated to do what" can consume it asynchronously.
package workers

import (
	"encoding/json"
	"fmt"
	"time"
)

const delegationPublicationTopic = "deployment.runtime-delegations.v1"

// RuntimeDelegationEvent mirrors the shared runtime-delegation contract
// produced by DelegationProjectionService. It intentionally contains only
// the fields that projection emits — there is no delegationGeneration here
// because the projection never populates one.
type RuntimeDelegationEvent struct {
	DelegationID   string            `json:"delegationId"`
	DeploymentID   string            `json:"deploymentId"`
	EnvironmentID  string            `json:"environmentId"`
	DelegateUserID string            `json:"delegateUserId"`
	AllowedActions []string          `json:"allowedActions"`
	ExpiresAt      time.Time         `json:"expiresAt"`
	ApprovalID     string            `json:"approvalId"`
	Metadata       map[string]string `json:"metadata"`
}

// KafkaProducer is the minimal surface this publisher needs. Kept as an
// interface so tests can substitute an in-memory producer.
type KafkaProducer interface {
	Publish(topic string, key string, value []byte) error
}

type DeploymentEventPublisher struct {
	producer KafkaProducer
}

func NewDeploymentEventPublisher(producer KafkaProducer) *DeploymentEventPublisher {
	return &DeploymentEventPublisher{producer: producer}
}

// Publish serializes the projection and hands it to Kafka.
//
// Delivery is at-least-once: a producer retry after a transient broker
// error can result in the same event being delivered twice, and — because
// Kafka only guarantees ordering within a single partition — a retried
// publish for an *older* projection can in rare cases land after a newer
// one if the two were produced from different application instances (e.g.
// during a rolling deploy of DelegationProjectionService itself). Nothing
// in this event carries a monotonic version number, so a consumer cannot
// tell the two cases apart; it must treat every message as authoritative
// in arrival order.
//
// This publisher does not attempt to fix that — it publishes exactly what
// it is given. Ordering/versioning is a concern for whatever produces the
// projection and whatever consumes it downstream.
func (p *DeploymentEventPublisher) Publish(event RuntimeDelegationEvent, metadata map[string]string) error {
	if event.DelegationID == "" {
		return fmt.Errorf("cannot publish runtime delegation event: missing delegationId")
	}

	event.Metadata = metadata

	payload, err := json.Marshal(event)
	if err != nil {
		return fmt.Errorf("failed to marshal runtime delegation event: %w", err)
	}

	// Partition key is the delegationId so that all updates for a given
	// delegation land on the same partition and are consumed in send order
	// by a single worker instance.
	if err := p.producer.Publish(delegationPublicationTopic, event.DelegationID, payload); err != nil {
		return fmt.Errorf("failed to publish runtime delegation event: %w", err)
	}

	return nil
}
