## FILE: workers/RuntimeDelegationWorker.rs

```
//! Consumes runtime delegation projections from the
//! `deployment.runtime-delegations.v1` Kafka topic and persists them into
//! the execution-optimized runtime store (RuntimeDelegationRepository).
//!
//! This worker is intentionally simple: it does not interpret the
//! delegation in any way, it does not decide whether an update should
//! "win" over what is currently stored, and it performs no authorization
//! logic. It trusts that whatever arrives on the topic is the thing that
//! should currently be true for that delegationId, and persists it.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// Mirrors workers.DeploymentEventPublisher's RuntimeDelegationEvent (Go)
/// and models.RuntimeDelegation (JVM). Same shared schema, no
/// delegationGeneration field — it was never present upstream.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RuntimeDelegationEvent {
    pub delegation_id: String,
    pub deployment_id: String,
    pub environment_id: String,
    pub delegate_user_id: String,
    pub allowed_actions: Vec<String>,
    pub expires_at: String, // RFC3339
    pub approval_id: String,
    pub metadata: HashMap<String, String>,
}

/// Minimal client surface onto RuntimeDelegationRepository (.NET), reached
/// over the platform's internal RPC layer.
pub trait RuntimeDelegationRepositoryClient {
    fn upsert(&self, event: &RuntimeDelegationEvent) -> Result<(), String>;
}

pub struct RuntimeDelegationWorker<R: RuntimeDelegationRepositoryClient> {
    repository: R,
}

impl<R: RuntimeDelegationRepositoryClient> RuntimeDelegationWorker<R> {
    pub fn new(repository: R) -> Self {
        Self { repository }
    }

    /// Called once per consumed Kafka message.
    ///
    /// Consumption is at-least-once and the topic is partitioned by
    /// delegationId, so under normal operation messages for a single
    /// delegation are processed in send order. That guarantee only holds
    /// as long as every producer instance is publishing from a single,
    /// consistent view of "what generation is newest" — this worker has no
    /// way to independently verify that, since the event itself carries no
    /// generation or sequence number to check against what is already
    /// stored.
    ///
    /// Processing is idempotent per message (re-applying the same event
    /// twice is harmless), but it is not commutative: applying event A
    /// after event B produces a different final state than applying B
    /// after A, and this worker has no information that would let it
    /// reorder them correctly if they arrive out of order.
    pub fn handle_message(&self, raw_payload: &[u8]) -> Result<(), String> {
        let event: RuntimeDelegationEvent = serde_json::from_slice(raw_payload)
            .map_err(|e| format!("failed to deserialize runtime delegation event: {e}"))?;

        if event.delegation_id.is_empty() {
            return Err("runtime delegation event missing delegation_id".to_string());
        }

        self.repository.upsert(&event)
    }
}
```

