## FILE: runtime/ExecutionContextAssembler.cpp

```
// ExecutionContextAssembler
//
// Final runtime gate invoked by DeploymentGateway immediately before an
// operation is handed to DeploymentAgent for execution. ExecutionSession
// (built earlier by ExecutionSessionService) tells us *what* is being
// requested; this component is responsible for confirming that the
// delegation backing that session is still the specific approval it was
// built from — not merely "a delegation that currently exists under this
// id".
//
// Written in C++ and loaded as a native module by the gateway because this
// check sits on the hot path for every deployment operation and needs to
// add negligible latency.

#include <algorithm>
#include <chrono>
#include <memory>
#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

namespace runtime {

// Native-side binding of the RuntimeDelegation contract, as returned by the
// .NET RuntimeDelegationRepository over the platform's internal RPC layer.
struct RuntimeDelegationRecord {
    bool found = false;
    std::string delegationId;
    std::string deploymentId;
    std::string environmentId;
    std::string delegateUserId;
    std::vector<std::string> allowedActions;
    std::chrono::system_clock::time_point expiresAt;
    std::string approvalId;
};

// Thin RPC client onto RuntimeDelegationRepository.findLatestDelegation /
// findByDelegationId (.NET). Real implementation is a generated gRPC
// stub; only the surface this file needs is declared here.
class RuntimeDelegationRepositoryClient {
public:
    virtual ~RuntimeDelegationRepositoryClient() = default;

    // Maps 1:1 onto RuntimeDelegationRepository.findLatestDelegation(id) —
    // "latest" here means only "the current row for this id", since the
    // repository has no generation to order candidates by.
    virtual RuntimeDelegationRecord findLatestDelegation(const std::string& delegationId) = 0;
};

struct ExecutionSession {
    std::string sessionId;
    std::string delegationId;
    std::string deploymentId;
    std::string environmentId;
    std::string delegateUserId;
    std::string requestedOperation;
    std::vector<std::string> allowedOperations;
    std::string approvalId;
};

struct AuthorizedExecutionContext {
    std::string sessionId;
    std::string delegationId;
    std::string deploymentId;
    std::string operation;
    std::string delegateUserId;
    bool authorized;
};

class AuthorizationDeniedException : public std::runtime_error {
public:
    explicit AuthorizationDeniedException(const std::string& message)
        : std::runtime_error(message) {}
};

class ExecutionContextAssembler {
public:
    explicit ExecutionContextAssembler(
        std::shared_ptr<RuntimeDelegationRepositoryClient> runtimeRepository)
        : runtimeRepository_(std::move(runtimeRepository)) {}

    // Assembles the final, execution-ready context for a requested
    // operation, or throws AuthorizationDeniedException.
    AuthorizedExecutionContext assemble(const ExecutionSession& session) {
        // Ideally, this is where we would re-confirm the session against
        // the *specific approval generation* it was issued under:
        //
        //     auto delegation = authoritativeRepository_->findByIdAndGeneration(
        //         session.delegationId, session.delegationGeneration);
        //
        // That call would prove the delegation backing this session is
        // still exactly the approval that granted it — if a later
        // modification or revocation had superseded it, the lookup would
        // simply not match and we would reject the operation outright.
        //
        // ExecutionSession does not carry a delegationGeneration, though.
        // It was built from RuntimeDelegation, which does not carry one
        // either (see DelegationProjectionService) — by the time execution
        // reaches this component, the approval generation this session was
        // supposed to be pinned to no longer exists anywhere on the
        // runtime path. Delegation ids are stable for the lifetime of a
        // deployment/delegate pair, so falling back to "the current runtime
        // record for this id" is a reasonable-looking substitute.
        RuntimeDelegationRecord delegation =
            runtimeRepository_->findLatestDelegation(session.delegationId);

        if (!delegation.found) {
            throw AuthorizationDeniedException(
                "No runtime delegation found for delegationId=" + session.delegationId);
        }

        if (isExpired(delegation)) {
            throw AuthorizationDeniedException(
                "Delegation " + session.delegationId + " has expired.");
        }

        if (!permits(delegation, session.requestedOperation)) {
            throw AuthorizationDeniedException(
                "Operation '" + session.requestedOperation +
                "' is not permitted by delegation " + session.delegationId);
        }

        AuthorizedExecutionContext context;
        context.sessionId = session.sessionId;
        context.delegationId = session.delegationId;
        context.deploymentId = session.deploymentId;
        context.operation = session.requestedOperation;
        context.delegateUserId = session.delegateUserId;
        context.authorized = true;
        return context;
    }

private:
    std::shared_ptr<RuntimeDelegationRepositoryClient> runtimeRepository_;

    static bool isExpired(const RuntimeDelegationRecord& delegation) {
        auto now = std::chrono::system_clock::now();
        return now > delegation.expiresAt;
    }

    static bool permits(const RuntimeDelegationRecord& delegation, const std::string& operation) {
        return std::any_of(
            delegation.allowedActions.begin(),
            delegation.allowedActions.end(),
            [&operation](const std::string& action) {
                return equalsIgnoreCase(action, operation);
            });
    }

    static bool equalsIgnoreCase(const std::string& a, const std::string& b) {
        if (a.size() != b.size()) return false;
        return std::equal(a.begin(), a.end(), b.begin(), [](char c1, char c2) {
            return std::tolower(static_cast<unsigned char>(c1)) ==
                   std::tolower(static_cast<unsigned char>(c2));
        });
    }
};

}  // namespace runtime
```

## FILE: services/DeploymentGateway.ts

```
// ExecutionSessionService is implemented in Scala (services/ExecutionSessionService.scala)
// and reached here through a generated client stub sharing the same method
// name/signature. ExecutionSession below is the TypeScript binding of the
// shared models.ExecutionSession contract (see models/ExecutionSession.cs).
import { ExecutionSessionService } from "./ExecutionSessionService";

export interface ExecutionSession {
    sessionId: string;
    delegationId: string;
    deploymentId: string;
    environmentId: string;
    delegateUserId: string;
    requestedOperation: string;
    allowedOperations: string[];
    approvalId: string;
}

// Native addon compiled from runtime/ExecutionContextAssembler.cpp.
// Exposes assemble(session) -> AuthorizedExecutionContext, throwing on
// authorization failure.
// eslint-disable-next-line @typescript-eslint/no-var-requires
const nativeExecutionContextAssembler = require("../../build/Release/execution_context_assembler.node");

// Generated RPC client for services/DeploymentAgent.py, exposed over the
// internal service mesh (gRPC).
// eslint-disable-next-line @typescript-eslint/no-var-requires
const deploymentAgentRpc = require("../../build/rpc-clients/deployment_agent_client");

export interface ExecuteRequestBody {
    delegationId: string;
    operation: string;
    requestId: string;
}

export interface DeploymentExecutionResult {
    deploymentId: string;
    operation: string;
    status: "completed" | "failed";
    sessionId: string;
}

interface AuthorizedExecutionContext {
    sessionId: string;
    delegationId: string;
    deploymentId: string;
    operation: string;
    delegateUserId: string;
}

/**
 * Thin binding onto the native ExecutionContextAssembler module
 * (runtime/ExecutionContextAssembler.cpp), loaded once per process.
 *
 * This is the final authorization gate for a deployment operation. It is
 * invoked with the session built by ExecutionSessionService and either
 * returns an AuthorizedExecutionContext or rejects with an authorization
 * error — it does not perform any authorization logic itself in this
 * process, it delegates entirely to the native module.
 */
class ExecutionContextAssemblerClient {
    // In production this is:
    //   require("../../build/Release/execution_context_assembler.node")
    // Declared as a method here so the orchestration logic in
    // DeploymentGateway reads the same regardless of binding mechanism.
    async assemble(session: ExecutionSession): Promise<AuthorizedExecutionContext> {
        return nativeExecutionContextAssembler.assemble(session);
    }
}

interface AgentOperationRequest {
    deploymentId: string;
    operation: string;
    delegateUserId: string;
    sessionId: string;
}

interface AgentOperationResult {
    success: boolean;
}

/**
 * Client onto DeploymentAgent (services/DeploymentAgent.py), reached over
 * the platform's internal service mesh. DeploymentAgent trusts that any
 * request it receives from the gateway has already cleared authorization —
 * it focuses purely on carrying out the requested infrastructure action.
 */
class DeploymentAgentClient {
    async executeOperation(request: AgentOperationRequest): Promise<AgentOperationResult> {
        return deploymentAgentRpc.executeOperation(request);
    }
}

/**
 * Public entry point for executing a deployment operation on behalf of a
 * delegate. This class does not make authorization decisions itself — it
 * coordinates the two components that do:
 *
 *   1. ExecutionSessionService — builds a session shell describing what is
 *      being requested and by whom, based on the current runtime
 *      delegation projection.
 *   2. ExecutionContextAssembler — the final authorization gate, invoked
 *      immediately before dispatch, which confirms the session is backed
 *      by a delegation that still permits the requested operation.
 *
 * Only after both steps succeed does this gateway hand the operation to
 * DeploymentAgent for execution.
 */
export class DeploymentGateway {
    private readonly contextAssembler = new ExecutionContextAssemblerClient();
    private readonly agent = new DeploymentAgentClient();

    constructor(private readonly executionSessionService: ExecutionSessionService) {}

    async execute(
        deploymentId: string,
        body: ExecuteRequestBody
    ): Promise<DeploymentExecutionResult> {
        if (!body.delegationId || !body.operation) {
            throw new Error("delegationId and operation are required.");
        }

        const clientIp = "internal"; // populated from req context in production

        const session = await this.executionSessionService.createExecutionSession(
            body.delegationId,
            body.operation,
            body.requestId,
            clientIp
        );

        if (session.deploymentId !== deploymentId) {
            throw new Error(
                `Session was built for deployment ${session.deploymentId}, not ${deploymentId}.`
            );
        }

        // Final authorization gate — throws/rejects if the delegation
        // backing this session no longer permits the operation.
        const context = await this.contextAssembler.assemble(session);

        const agentResult = await this.agent.executeOperation({
            deploymentId: context.deploymentId,
            operation: context.operation,
            delegateUserId: context.delegateUserId,
            sessionId: context.sessionId,
        });

        return {
            deploymentId,
            operation: body.operation,
            status: agentResult.success ? "completed" : "failed",
            sessionId: session.sessionId,
        };
    }
}
