"""
DeploymentAgent

Carries out deployment operations (deploy, rollback, restart-cluster,
rotate-secrets, emergency-patch) against the target environment's
infrastructure APIs.

DeploymentAgent is intentionally the least "clever" component in the
pipeline. It is reached only through DeploymentGateway, after the gateway
has already built an execution session and cleared it through
ExecutionContextAssembler. By design, this agent does not re-derive or
re-check delegation authority — that responsibility belongs entirely to the
gateway/assembler pair upstream. This agent's job is to execute the
requested operation and report what happened.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Dict

from platform_rpc import audit_logger_rpc  # generated client for utils/AuditLogger.go


class AuditLoggerClient:
    """
    Thin binding onto utils/AuditLogger.go, reached over the platform's
    internal RPC layer. Every service that performs a security-relevant
    action logs it here; this client just shapes the call.
    """

    def log_operation(
        self,
        *,
        deployment_id: str,
        operation: str,
        delegate_user_id: str,
        session_id: str,
        outcome: str,
        detail: str,
    ) -> None:
        audit_logger_rpc.record_event(
            {
                "eventType": "DEPLOYMENT_OPERATION_EXECUTED",
                "deploymentId": deployment_id,
                "operation": operation,
                "delegateUserId": delegate_user_id,
                "sessionId": session_id,
                "outcome": outcome,
                "detail": detail,
            }
        )


class UnknownOperationError(Exception):
    pass


class OperationExecutionError(Exception):
    pass


@dataclass
class AgentOperationRequest:
    deployment_id: str
    operation: str
    delegate_user_id: str
    session_id: str


@dataclass
class AgentOperationResult:
    success: bool
    detail: str


class DeploymentAgent:
    def __init__(self, audit_logger: AuditLoggerClient | None = None) -> None:
        self._audit_logger = audit_logger or AuditLoggerClient()
        self._handlers: Dict[str, Callable[[AgentOperationRequest], str]] = {
            "deploy": self._handle_deploy,
            "rollback": self._handle_rollback,
            "restart_cluster": self._handle_restart_cluster,
            "rotate_secrets": self._handle_rotate_secrets,
            "emergency_patch": self._handle_emergency_patch,
        }

    def execute_operation(self, request: AgentOperationRequest) -> AgentOperationResult:
        handler = self._handlers.get(request.operation)

        if handler is None:
            raise UnknownOperationError(
                f"No handler registered for operation '{request.operation}'."
            )

        try:
            detail = handler(request)
        except Exception as exc:  # noqa: BLE001 - surfaced to caller below
            self._audit_logger.log_operation(
                deployment_id=request.deployment_id,
                operation=request.operation,
                delegate_user_id=request.delegate_user_id,
                session_id=request.session_id,
                outcome="failed",
                detail=str(exc),
            )
            raise OperationExecutionError(str(exc)) from exc

        self._audit_logger.log_operation(
            deployment_id=request.deployment_id,
            operation=request.operation,
            delegate_user_id=request.delegate_user_id,
            session_id=request.session_id,
            outcome="completed",
            detail=detail,
        )

        return AgentOperationResult(success=True, detail=detail)

    # -- operation handlers ------------------------------------------------
    #
    # Each handler wraps the actual infrastructure call (Kubernetes API,
    # cloud provider SDK, secrets manager, etc). Stubbed here since the
    # underlying infra client is out of scope for authorization reasoning.

    def _handle_deploy(self, request: AgentOperationRequest) -> str:
        return f"Deployment {request.deployment_id} rolled out by {request.delegate_user_id}."

    def _handle_rollback(self, request: AgentOperationRequest) -> str:
        return f"Deployment {request.deployment_id} rolled back by {request.delegate_user_id}."

    def _handle_restart_cluster(self, request: AgentOperationRequest) -> str:
        return f"Cluster for {request.deployment_id} restarted by {request.delegate_user_id}."

    def _handle_rotate_secrets(self, request: AgentOperationRequest) -> str:
        return f"Secrets rotated for {request.deployment_id} by {request.delegate_user_id}."

    def _handle_emergency_patch(self, request: AgentOperationRequest) -> str:
        return f"Emergency patch applied to {request.deployment_id} by {request.delegate_user_id}."
