/**
 * Serializer
 *
 * Schema validation and (de)serialization helpers used at the platform's
 * public HTTP boundary — request bodies coming in, response bodies going
 * out. Internal, service-to-service data (the delegation publication
 * pipeline, runtime session construction, etc.) is passed as native
 * language objects between generated bindings and does not go through
 * this module; it exists specifically for the untrusted edge of the
 * system, where payloads arrive as raw JSON from API callers.
 */

export interface DeploymentDelegationSchema {
    delegationId: string;
    deploymentId: string;
    environmentId: string;
    ownerUserId: string;
    delegateUserId: string;
    delegationGeneration: number;
    allowedActions: string[];
    issuedAt: string;
    expiresAt: string;
    approvalId: string;
    approvedBy: string;
}

const DEPLOYMENT_DELEGATION_REQUIRED_FIELDS: (keyof DeploymentDelegationSchema)[] = [
    "delegationId",
    "deploymentId",
    "environmentId",
    "ownerUserId",
    "delegateUserId",
    "delegationGeneration",
    "allowedActions",
    "issuedAt",
    "expiresAt",
    "approvalId",
    "approvedBy",
];

export class SchemaValidationError extends Error {
    constructor(public readonly missingFields: string[]) {
        super(`Payload is missing required fields: ${missingFields.join(", ")}`);
        this.name = "SchemaValidationError";
    }
}

/**
 * Validates and parses an inbound DeploymentDelegation payload against the
 * full canonical schema, including delegationGeneration. Used by the
 * /api/delegations response serializer so that API consumers always
 * receive a complete, generation-aware representation of a delegation.
 *
 * This validator is not part of the internal projection pipeline —
 * DelegationProjectionService builds RuntimeDelegation directly from the
 * in-memory DeploymentDelegation object, without round-tripping through
 * JSON or this schema, so a field dropped there would never be caught
 * here.
 */
export function parseDeploymentDelegation(payload: unknown): DeploymentDelegationSchema {
    if (typeof payload !== "object" || payload === null) {
        throw new SchemaValidationError(DEPLOYMENT_DELEGATION_REQUIRED_FIELDS as string[]);
    }

    const record = payload as Record<string, unknown>;
    const missing = DEPLOYMENT_DELEGATION_REQUIRED_FIELDS.filter(
        (field) => record[field] === undefined || record[field] === null
    );

    if (missing.length > 0) {
        throw new SchemaValidationError(missing as string[]);
    }

    return record as unknown as DeploymentDelegationSchema;
}

export function serializeDeploymentDelegation(delegation: DeploymentDelegationSchema): string {
    return JSON.stringify(delegation);
}
