## FILE: snapshot/InfrastructureSnapshot.swift

```
import Foundation

struct InfrastructureSnapshot {

    // Snapshot identity remains immutable after approval.
    // Any deployment approved against this snapshot must
    // execute against the same stateGeneration.

    let snapshotId: String

    let workspaceId: String

    let stateGeneration: String

    // Canonical infrastructure topology captured during review.
    // The execution pipeline treats this graph as read-only.

    let resourceGraph: [String]

    // Maps resource identifiers to their approved provider state.
    // The values represent the exact infrastructure state used
    // during deployment approval.

    let providerState: [String: String]

    let approvalTime: Date

    init(

        snapshotId: String,

        workspaceId: String,

        stateGeneration: String,

        resourceGraph: [String],

        providerState: [String: String],

        approvalTime: Date

    ) throws {

        guard !snapshotId.isEmpty else {

            throw SnapshotError.invalidSnapshotId

        }

        guard !workspaceId.isEmpty else {

            throw SnapshotError.invalidWorkspace

        }

        guard !stateGeneration.isEmpty else {

            throw SnapshotError.invalidGeneration

        }

        guard !resourceGraph.isEmpty else {

            throw SnapshotError.emptyResourceGraph

        }

        self.snapshotId = snapshotId

        self.workspaceId = workspaceId

        self.stateGeneration = stateGeneration

        self.resourceGraph = resourceGraph

        self.providerState = providerState

        self.approvalTime = approvalTime

    }

    func containsResource(

        _ identifier: String

    ) -> Bool {

        resourceGraph.contains(identifier)

    }

    func providerVersion(

        for resource: String

    ) -> String? {

        providerState[resource]

    }

    func resourceCount() -> Int {

        resourceGraph.count

    }

    func identity() -> String {

        return

            workspaceId +

            "::" +

            snapshotId +

            "::" +

            stateGeneration

    }

    func summary() -> String {

        return

            "Snapshot[" +

            snapshotId +

            "] " +

            "\(resourceGraph.count) resources"

    }

}

enum SnapshotError: Error {

    case invalidSnapshotId

    case invalidWorkspace

    case invalidGeneration

    case emptyResourceGraph

}
