use std::collections::HashMap;

use crate::execution::ExecutionContext;
use crate::planning::{
    DeploymentSchedule,
    ExecutionGraph,
    ResourceOperation,
};
use crate::snapshot::{
    InfrastructureSnapshot,
    SnapshotArchive,
};

pub struct ExecutionPlanner<'a> {

    archive: &'a SnapshotArchive,

}

impl<'a> ExecutionPlanner<'a> {

    pub fn new(

        archive: &'a SnapshotArchive

    ) -> Self {

        Self {

            archive

        }

    }

    //==============================================================
    // Deployment Planning
    //==============================================================

    pub fn build_deployment_schedule(

        &self,

        context: &ExecutionContext

    ) -> Result<DeploymentSchedule, String> {

        self.validate_context(context)?;

        /*
            Reconstruct the approved infrastructure state before
            generating deployment operations.

            ExecutionContext is expected to carry sufficient lineage
            information to uniquely identify the approved snapshot.
        */

        let snapshot =

            self.archive

                .latest_snapshot(

                    context.workspace_id()

                )

                .ok_or(

                    "Unable to locate infrastructure snapshot."

                )?;

        /*
        =============================================================

        VULNERABILITY 2

        Planner reconstructs infrastructure state using

            latestSnapshot(workspaceId)

        instead of the canonical lookup

            loadSnapshot(
                snapshotId,
                stateGeneration
            )

        Normally this helper is safe because ExecutionContext is
        expected to preserve stateGeneration.

        After Vulnerability 1 removes stateGeneration during
        projection, the planner can no longer perform canonical
        resolution and silently adopts the newest infrastructure
        snapshot.

        Every retrieved snapshot is valid.

        Every deployment operation remains valid.

        The deployment simply executes using the wrong approved
        infrastructure state lineage.

        =============================================================
        */

        let execution_graph =

            self.build_execution_graph(

                &snapshot

            );

        let operation_queue =

            self.build_operation_queue(

                &snapshot

            );

        let metadata =

            self.build_metadata(

                &snapshot,

                context

            );

        DeploymentSchedule::new(

            uuid::Uuid::new_v4().to_string(),

            snapshot.workspace_id().to_string(),

            snapshot.state_generation().to_string(),

            execution_graph,

            operation_queue,

            metadata

        )

    }

    //==============================================================
    // Forward Declarations
    //==============================================================

    fn build_execution_graph(

        &self,

        snapshot: &InfrastructureSnapshot

    ) -> ExecutionGraph;

    fn build_operation_queue(

        &self,

        snapshot: &InfrastructureSnapshot

    ) -> Vec<ResourceOperation>;

    fn build_metadata(

        &self,

        snapshot: &InfrastructureSnapshot,

        context: &ExecutionContext

    ) -> HashMap<String, String>;

    fn validate_context(

        &self,

        context: &ExecutionContext

    ) -> Result<(), String>;

}
impl<'a> ExecutionPlanner<'a> {

    //==============================================================
    // Execution Graph Construction
    //==============================================================

    fn build_execution_graph(

        &self,

        snapshot: &InfrastructureSnapshot

    ) -> ExecutionGraph {

        let nodes =

            snapshot
                .resource_graph()
                .iter()
                .cloned()
                .collect();

        /*
            The approved resource topology already represents a valid
            dependency graph. Planning preserves this ordering while
            translating resources into executable operations.
        */

        let mut dependencies = Vec::new();

        let resources = snapshot.resource_graph();

        for window in resources.windows(2) {

            dependencies.push(

                (

                    window[0].clone(),

                    window[1].clone()

                )

            );

        }

        ExecutionGraph {

            nodes,

            dependencies

        }

    }

    //==============================================================
    // Operation Queue Construction
    //==============================================================

    fn build_operation_queue(

        &self,

        snapshot: &InfrastructureSnapshot

    ) -> Vec<ResourceOperation> {

        let mut operations = Vec::new();

        for (index, resource) in

            snapshot.resource_graph().iter().enumerate()

        {

            operations.push(

                ResourceOperation {

                    resource_id:

                        resource.clone(),

                    operation:

                        "Apply".to_string(),

                    execution_order:

                        (index + 1) as u32

                }

            );

        }

        operations

    }

    //==============================================================
    // Runtime Metadata
    //==============================================================

    fn build_metadata(

        &self,

        snapshot: &InfrastructureSnapshot,

        context: &ExecutionContext

    ) -> HashMap<String, String> {

        let mut metadata = HashMap::new();

        metadata.insert(

            "workspaceId".into(),

            snapshot.workspace_id().into()

        );

        metadata.insert(

            "snapshotId".into(),

            snapshot.snapshot_id().into()

        );

        metadata.insert(

            "stateGeneration".into(),

            snapshot.state_generation().into()

        );

        metadata.insert(

            "resourceCount".into(),

            context.resource_count().to_string()

        );

        metadata

    }

    //==============================================================
    // Validation
    //==============================================================

    fn validate_context(

        &self,

        context: &ExecutionContext

    ) -> Result<(), String> {

        if context.snapshot_id().is_empty() {

            return Err(

                "Snapshot identifier missing.".into()

            );

        }

        if context.workspace_id().is_empty() {

            return Err(

                "Workspace identifier missing.".into()

            );

        }

        if context.resource_count() == 0 {

            return Err(

                "Execution context contains no resources.".into()

            );

        }

        Ok(())

    }

    //==============================================================
    // Summary
    //==============================================================

    pub fn summary(

        &self,

        schedule: &DeploymentSchedule

    ) -> String {

        format!(

            "DeploymentSchedule [{}] {} operations",

            schedule.workspace_id(),

            schedule.operation_count()

        )

    }

}
