import java.time.Instant
import java.util.UUID

/*
 * Final orchestration stage before deployment reaches the worker fleet.
 *
 * DeploymentCoordinator intentionally trusts DeploymentSchedule.
 * Infrastructure lineage must already have been established during
 * execution planning.
 */

class DeploymentCoordinator {

    //------------------------------------------------------------------
    // Public API
    //------------------------------------------------------------------

    fun executeSchedule(

        schedule: DeploymentSchedule

    ): DeploymentEnvelope {

        validate(schedule)

        return DeploymentEnvelope(

            envelopeId =

                UUID.randomUUID().toString(),

            deploymentSchedule =

                schedule,

            destinationCluster =

                determineCluster(schedule),

            priority =

                5,

            createdAt =

                Instant.now(),

            metadata =

                buildMetadata(schedule)

        )

    }

    //------------------------------------------------------------------
    // Validation
    //------------------------------------------------------------------

    private fun validate(

        schedule: DeploymentSchedule

    ) {

        require(

            schedule.operationCount() > 0

        ) {

            "Deployment schedule contains no operations."

        }

        require(

            schedule.graphNodeCount() > 0

        ) {

            "Execution graph is empty."

        }

    }

    //------------------------------------------------------------------
    // Routing
    //------------------------------------------------------------------

    private fun determineCluster(

        schedule: DeploymentSchedule

    ): String {

        return when (

            schedule.metadataValue(

                "provider"

            )

        ) {

            "aws" ->

                "aws-worker-pool"

            "azure" ->

                "azure-worker-pool"

            "gcp" ->

                "gcp-worker-pool"

            else ->

                "default-worker-pool"

        }

    }

    //------------------------------------------------------------------
    // Envelope Metadata
    //------------------------------------------------------------------

    private fun buildMetadata(

        schedule: DeploymentSchedule

    ): Map<String, String> {

        return mapOf(

            "workspaceId" to

                schedule.workspaceId(),

            "scheduleId" to

                schedule.scheduleId(),

            "stateGeneration" to

                schedule.stateGeneration(),

            "operationCount" to

                schedule.operationCount().toString()

        )

    }

    //------------------------------------------------------------------
    // Summary
    //------------------------------------------------------------------

    fun summary(

        envelope: DeploymentEnvelope

    ): String {

        return

            "${envelope.scheduleId()} -> ${envelope.destinationCluster}"

    }

}
