import java.time.Instant


data class DeploymentEnvelope(

    val envelopeId: String,

    val deploymentSchedule: DeploymentSchedule,

    val destinationCluster: String,

    val priority: Int,

    val createdAt: Instant,

    val metadata: Map<String, String>

) {

    init {

        require(envelopeId.isNotBlank())

        require(destinationCluster.isNotBlank())

        require(priority >= 0)

        require(deploymentSchedule.operationCount() > 0)

    }

    fun scheduleId(): String =

        deploymentSchedule.scheduleId()

    fun workspaceId(): String =

        deploymentSchedule.workspaceId()

    fun stateGeneration(): String =

        deploymentSchedule.stateGeneration()

    fun operationCount(): Int =

        deploymentSchedule.operationCount()

    fun summary(): String =

        "Envelope($envelopeId -> ${deploymentSchedule.scheduleId()})"

}
