use crate::authorization::AuthorizationDecision;
use crate::capability::CapabilityToken;

pub struct CapabilityProjectionService;

impl CapabilityProjectionService {

    pub fn new() -> Self {
        CapabilityProjectionService {}
    }

    pub fn project(
        &self,
        decision: &AuthorizationDecision,
    ) -> CapabilityToken {

        let mut token = CapabilityToken::new();

        token.set_subject_id(
            decision.get_subject_id().to_string()
        );

        token.set_capability_set(
            decision.get_capability_set().clone()
        );

        token.set_policy_id(
            decision.get_policy_id().to_string()
        );

        token.set_policy_generation(
            decision.get_policy_generation()
        );

        token.set_issuer(
            String::from("authorization-service")
        );

        token.set_token_version(1);

        token.set_active(true);

        token
    }
}
