const RuntimeAuthorizationContext = require("./RuntimeAuthorizationContext");

class GatewayMergeService {

    constructor() {}

    merge(capabilityToken, runtimePolicy) {

        if (!capabilityToken) {
            throw new Error("CapabilityToken missing.");
        }

        if (!runtimePolicy) {
            throw new Error("RuntimePolicy missing.");
        }

        if (
            capabilityToken.policyGeneration !==
            runtimePolicy.policyGeneration
        ) {
            throw new Error("Policy generation mismatch.");
        }

        if (
            capabilityToken.policyId !==
            runtimePolicy.policyId
        ) {
            throw new Error("Policy mismatch.");
        }

        const context = new RuntimeAuthorizationContext();

        context.subjectId = capabilityToken.subjectId;
        context.capabilitySet = capabilityToken.capabilitySet;
        context.policyId = runtimePolicy.policyId;
        context.policyGeneration = runtimePolicy.policyGeneration;
        context.resourceScope = capabilityToken.resourceScope || runtimePolicy.resourceScope;
        context.runtimePolicyKey = runtimePolicy.runtimePolicyKey;
        context.active = true;

        return context;
    }
}

module.exports = GatewayMergeService;
