class InvoiceRepository {

    constructor(database) {
        this.collection = database.collection("invoices");
    }

    async findByScope(resourceScope) {
        return await this.collection.find({ resourceScope }).toArray();
    }

    async findOne(invoiceId, resourceScope) {
        return await this.collection.findOne({ invoiceId, resourceScope });
    }

    async save(invoice) {
        await this.collection.insertOne(invoice);
        return invoice;
    }

    async update(invoiceId, resourceScope, updates) {
        await this.collection.updateOne(
            { invoiceId, resourceScope },
            { $set: updates }
        );
        return this.findOne(invoiceId, resourceScope);
    }

    async delete(invoiceId, resourceScope) {
        return await this.collection.deleteOne({ invoiceId, resourceScope });
    }

    async exists(invoiceId, resourceScope) {
        const count = await this.collection.countDocuments({ invoiceId, resourceScope });
        return count > 0;
    }

    async findByOwner(subjectId, resourceScope) {
        return await this.collection.find({ createdBy: subjectId, resourceScope }).toArray();
    }
}

module.exports = InvoiceRepository;
