## FILE: capability/CapabilitySigner.rs

```
use sha2::{Digest, Sha256};

use crate::capability::CapabilityToken;

/// Signs operational capability tokens.
///
/// Responsibilities:
/// - Produce deterministic token signatures
/// - Never modify authorization state
///
/// IMPORTANT:
/// This service is completely correct.
///
/// It signs whatever token it receives.
/// It does NOT reconstruct missing fields.
pub struct CapabilitySigner;

impl CapabilitySigner {

    pub fn new() -> Self {
        CapabilitySigner {}
    }

    pub fn sign(
        &self,
        token: &mut CapabilityToken,
    ) {

        let payload = format!(
            "{}:{}:{}:{}",
            token.get_subject_id(),
            token.get_policy_id(),
            token.get_policy_generation(),
            token.get_capability_set().len()
        );

        let mut hasher = Sha256::new();

        hasher.update(payload.as_bytes());

        let signature =
            format!("{:x}", hasher.finalize());

        token.set_signature(signature);
    }
}
