package authorization;

import java.util.HashSet;
import java.util.Set;

public class AuthorizationDecision {

    private String subjectId;

    private String resourceId;

    private String resourceScope;

    private Set<String> capabilitySet = new HashSet<>();

    private String policyId;

    private long policyGeneration;

    public AuthorizationDecision() {}

    public String getSubjectId() { return subjectId; }
    public void setSubjectId(String subjectId) { this.subjectId = subjectId; }

    public String getResourceId() { return resourceId; }
    public void setResourceId(String resourceId) { this.resourceId = resourceId; }

    public String getResourceScope() { return resourceScope; }
    public void setResourceScope(String resourceScope) { this.resourceScope = resourceScope; }

    public Set<String> getCapabilitySet() { return capabilitySet; }
    public void setCapabilitySet(Set<String> capabilitySet) { this.capabilitySet = capabilitySet; }
    public void addCapability(String capability) { capabilitySet.add(capability); }
    public boolean hasCapability(String capability) { return capabilitySet.contains(capability); }

    public String getPolicyId() { return policyId; }
    public void setPolicyId(String policyId) { this.policyId = policyId; }

    public long getPolicyGeneration() { return policyGeneration; }
    public void setPolicyGeneration(long policyGeneration) { this.policyGeneration = policyGeneration; }

    @Override
    public String toString() {
        return "AuthorizationDecision{" +
                "subjectId='" + subjectId + '\'' +
                ", resourceId='" + resourceId + '\'' +
                ", resourceScope='" + resourceScope + '\'' +
                ", capabilitySet=" + capabilitySet +
                ", policyId='" + policyId + '\'' +
                ", policyGeneration=" + policyGeneration +
                '}';
    }
}
