#[derive(Clone, Debug)]
pub struct CapabilityToken {
    subject_id: String,
    resource_scope: Option<String>,
    capability_set: HashSet<String>,
    policy_id: String,
    policy_generation: u64,
    issuer: String,
    token_version: u32,
    active: bool,
    created_at: DateTime<Utc>,
    signature: Option<String>,
}

impl CapabilityToken {

    pub fn new() -> Self {
        CapabilityToken {
            subject_id: String::new(),
            resource_scope: None,
            capability_set: HashSet::new(),
            policy_id: String::new(),
            policy_generation: 0,
            issuer: String::new(),
            token_version: 1,
            active: true,
            created_at: Utc::now(),
            signature: None,
        }
    }

    pub fn get_subject_id(&self) -> &String { &self.subject_id }
    pub fn set_subject_id(&mut self, value: String) { self.subject_id = value; }

    pub fn get_resource_scope(&self) -> &Option<String> { &self.resource_scope }
    pub fn set_resource_scope(&mut self, value: String) { self.resource_scope = Some(value); }

    pub fn get_capability_set(&self) -> &HashSet<String> { &self.capability_set }
    pub fn set_capability_set(&mut self, value: HashSet<String>) { self.capability_set = value; }

    pub fn get_policy_id(&self) -> &String { &self.policy_id }
