        return await this.invoiceRepository.delete(invoiceId, context.resourceScope);
    }

    ensureCapability(context, capability) {
        if (!context) {
            throw new Error("Missing authorization context.");
        }
        if (!context.active) {
            throw new Error("Inactive authorization context.");
        }
        if (!context.hasCapability(capability)) {
            throw new Error("Missing capability: " + capability);
        }
    }
}

module.exports = InvoiceService;
