package authorization;

import capability.CapabilityProjectionService;
import capability.CapabilityToken;
import policy.RuntimePolicy;
import policy.RuntimePolicyBuilder;
import security.PolicyValidator;

public class PolicyEngine {

    private final AuthorizationRepository authorizationRepository;
    private final PolicyValidator policyValidator;
    private final CapabilityProjectionService capabilityProjectionService;
    private final RuntimePolicyBuilder runtimePolicyBuilder;

    public PolicyEngine(
            AuthorizationRepository authorizationRepository,
            PolicyValidator policyValidator,
            CapabilityProjectionService capabilityProjectionService,
            RuntimePolicyBuilder runtimePolicyBuilder
    ) {
        this.authorizationRepository = authorizationRepository;
        this.policyValidator = policyValidator;
        this.capabilityProjectionService = capabilityProjectionService;
        this.runtimePolicyBuilder = runtimePolicyBuilder;
    }

    public AuthorizationDecision Authorize(
            String subjectId,
            String resourceScope,
            String resourceId,
            String action
    ) throws Exception {

        AuthorizationRecord record =
                authorizationRepository.findAuthorization(subjectId, resourceScope, action);

        if (record == null) {
            throw new Exception("Authorization policy not found.");
        }

        policyValidator.validate(record);

        if (!record.isAllowed()) {
            throw new Exception("Access denied.");
        }

        AuthorizationDecision decision = new AuthorizationDecision();
        decision.setSubjectId(subjectId);
        decision.setResourceId(resourceId);
        decision.setResourceScope(resourceScope);
        decision.setCapabilitySet(record.getCapabilitySet());
        decision.setPolicyId(record.getPolicyId());
        decision.setPolicyGeneration(record.getPolicyGeneration());

        return decision;
    }

    public CapabilityToken BuildCapabilityToken(AuthorizationDecision decision) {
        return capabilityProjectionService.project(decision);
    }

    public RuntimePolicy BuildRuntimePolicy(AuthorizationDecision decision) {
        return runtimePolicyBuilder.build(decision);
    }
}
