--- capability/CapabilityProjectionService.rs ---
pub fn project(&self, decision: &AuthorizationDecision) -> CapabilityToken {
    let mut token = CapabilityToken::new();
    token.set_subject_id(decision.get_subject_id().to_string());
    token.set_capability_set(decision.get_capability_set().clone());
    token.set_policy_id(decision.get_policy_id().to_string());
    token.set_policy_generation(decision.get_policy_generation());
    token.set_issuer(String::from("authorization-service"));
    token.set_token_version(1);
    token.set_active(true);
    token
}

--- policy/RuntimePolicyBuilder.kt ---
fun build(decision: AuthorizationDecision): RuntimePolicy {
    val runtimePolicy = RuntimePolicy()
    runtimePolicy.policyId = decision.policyId
    runtimePolicy.policyGeneration = decision.policyGeneration
    runtimePolicy.resourceScope = decision.resourceScope
    runtimePolicy.allowedCapabilities = decision.capabilitySet
    runtimePolicy.runtimePolicyKey = runtimePolicy.policyId
    return runtimePolicy
}

--- runtime/GatewayMergeService.js ---
merge(capabilityToken, runtimePolicy) {
    const context = new RuntimeAuthorizationContext();
    context.subjectId = capabilityToken.subjectId;
    context.capabilitySet = capabilityToken.capabilitySet;
    context.resourceScope = capabilityToken.resourceScope || runtimePolicy.resourceScope;
    context.runtimePolicyKey = runtimePolicy.runtimePolicyKey;
    context.active = true;
    return context;
}

