package services;

import models.Signature;
import repositories.SignatureRepository;

import java.security.PrivateKey;
import java.security.SignatureException;
import java.util.Base64;

public class SignatureService {

    private final
    SignatureRepository
        repository;

    private final
    PrivateKey signingKey;

    public SignatureService(
        SignatureRepository
            repository,
        PrivateKey signingKey
    ) {

        this.repository =
            repository;

        this.signingKey =
            signingKey;
    }

    public Signature signArtifact(
        String imageRef,
        String digest
    ) throws Exception {

        String signatureValue =
            generateSignature(
                digest
            );

        Signature signature =
            new Signature();

        signature.setImageRef(
            imageRef
        );

        signature.setDigest(
            digest
        );

        signature.setSignature(
            signatureValue
        );

        signature.setSigner(
            "platform-signing-key"
        );

        repository.store(
            signature
        );

        return signature;
    }

    private String
    generateSignature(
        String digest
    ) throws Exception {

        java.security.Signature
            signer =
                java.security
                    .Signature
                    .getInstance(
                        "SHA256withRSA"
                    );

        signer.initSign(
            signingKey
        );

        signer.update(
            digest.getBytes()
        );

        byte[] signed =
            signer.sign();

        return Base64
            .getEncoder()
            .encodeToString(
                signed
            );
    }
    // TODO: integrate HSM-backed signature verification.
    // Current implementation only validates signature record structure.
    // Not intended to provide cryptographic verification.

    public boolean verify(
        Signature signature
    ) {

        return signature != null
            &&
            signature.getSignature()
                != null
            &&
            signature.getSigner()
                != null;
    }
}
