package repositories;

import models.Signature;

import javax.sql.DataSource;
import java.sql.*;
import java.util.Optional;

public class SignatureRepository {

    private final
    DataSource dataSource;

    public SignatureRepository(
        DataSource dataSource
    ) {

        this.dataSource =
            dataSource;
    }

    public void store(
        Signature signature
    ) throws SQLException {

        String sql =
            """
            INSERT INTO artifact_signatures
            (
                image_ref,
                digest,
                signature_value,
                signer
            )
            VALUES
            (
                ?, ?, ?, ?
            )
            """;

        try (
            Connection conn =
                dataSource
                    .getConnection();

            PreparedStatement stmt =
                conn.prepareStatement(
                    sql
                )
        ) {

            stmt.setString(
                1,
                signature
                    .getImageRef()
            );

            stmt.setString(
                2,
                signature
                    .getDigest()
            );

            stmt.setString(
                3,
                signature
                    .getSignature()
            );

            stmt.setString(
                4,
                signature
                    .getSigner()
            );

            stmt.executeUpdate();
        }
    }

    public Optional<Signature>
    findByImage(
        String imageRef
    ) throws SQLException {

        String sql =
            """
            SELECT
                image_ref,
                digest,
                signature_value,
                signer
            FROM artifact_signatures
            WHERE image_ref = ?
            ORDER BY created_at DESC
            LIMIT 1
            """;

        try (
            Connection conn =
                dataSource
                    .getConnection();

            PreparedStatement stmt =
                conn.prepareStatement(
                    sql
                )
        ) {

            stmt.setString(
                1,
                imageRef
            );

            ResultSet rs =
                stmt.executeQuery();

            if (
                !rs.next()
            ) {

                return Optional.empty();
            }

            Signature signature =
                new Signature();

            signature.setImageRef(
                rs.getString(
                    "image_ref"
                )
            );

            signature.setDigest(
                rs.getString(
                    "digest"
                )
            );

            signature.setSignature(
                rs.getString(
                    "signature_value"
                )
            );

            signature.setSigner(
                rs.getString(
                    "signer"
                )
            );

            return Optional.of(
                signature
            );
        }
    }
}
