package admission;

import models.Signature;
import repositories.SignatureRepository;
import services.SignatureService;

public class ImagePolicyValidator {

    private final
    SignatureRepository
        signatureRepository;

    private final
    SignatureService
        signatureService;

    public ImagePolicyValidator(
        SignatureRepository
            signatureRepository,
        SignatureService
            signatureService
    ) {

        this.signatureRepository =
            signatureRepository;

        this.signatureService =
            signatureService;
    }

    public ValidationResult
    validate(
        String imageRef
    ) {

        Signature signature =
            signatureRepository
                .findByImage(
                    imageRef
                )
                .orElse(
                    null
                );

        if (
            signature == null
        ) {

            return ValidationResult
                .deny(
                    "Missing signature"
                );
        }

        boolean trusted =
            signatureService
                .verify(
                    signature
                );

        if (
            !trusted
        ) {

            return ValidationResult
                .deny(
                    "Invalid signature"
                );
        }

        if (
            !"platform-signing-key"
                .equals(
                    signature
                        .getSigner()
                )
        ) {

            return ValidationResult
                .deny(
                    "Untrusted signer"
                );
        }
// TODO:
// Verify that the digest of the artifact being deployed
// matches the digest originally signed by the platform.
// Current validation only verifies signature existence
// and trusted signer identity.

        return ValidationResult
            .allow();
    }
}
