            request
                .at(
                    "/request/object/spec/template/spec/containers/0/image"
                )
                .asText();

        ValidationResult result =
            validator.validate(
                imageRef
            );

        if (
            !result.allowed()
        ) {

            return AdmissionResponse
                .deny(
                    result.reason()
                );
        }

        return AdmissionResponse
            .allow();
    }
}
