package services;

import models.Artifact;

public class ArtifactPolicyService {

    public PolicyDecision
    evaluate(
        Artifact artifact
    ) {

        if (
            artifact == null
        ) {

            return PolicyDecision
                .deny(
                    "Missing artifact"
                );
        }

        if (
            artifact.getDigest()
                == null
        ) {

            return PolicyDecision
                .deny(
                    "Missing digest"
                );
        }

        if (
            artifact.getStatus()
                == null
        ) {

            return PolicyDecision
                .deny(
                    "Missing status"
                );
        }

        if (
            !artifact
                .getStatus()
                .equals(
                    "READY_FOR_DEPLOYMENT"
                )
        ) {

            return PolicyDecision
                .deny(
                    "Artifact not approved"
                );
        }

        return PolicyDecision
            .allow();
    }

    public static class PolicyDecision {

        private final
        boolean allowed;

        private final
        String reason;

        private PolicyDecision(
            boolean allowed,
            String reason
        ) {

            this.allowed =
                allowed;

            this.reason =
                reason;
        }

        public static PolicyDecision
        allow() {

            return new PolicyDecision(
                true,
                null
            );
        }

        public static PolicyDecision
        deny(
            String reason
        ) {

            return new PolicyDecision(
                false,
                reason
            );
        }

        public boolean allowed() {

            return allowed;
        }

        public String reason() {

            return reason;
        }
    }
}
