```
using System;
using System.Collections.Generic;

using EnterpriseAgent.Planning;

namespace EnterpriseAgent.Approval
{

    public sealed class ToolApprovalService
    {
        private readonly ApprovalRepository repository;

        public ToolApprovalService(

            ApprovalRepository repository

        )
        {
            this.repository = repository;
        }

        //------------------------------------------------------------------

        public ApprovedToolInvocation Approve(

            ToolInvocationPlan plan,

            string toolId

        )
        {
            ValidatePlan(

                plan,

                toolId

            );

            string endpoint =

                repository.ResolveApprovedEndpoint(

                    toolId,

                    plan.WorkspaceIdValue()

                );

            string generation =

                repository.ResolveApprovalGeneration(

                    toolId,

                    endpoint

                );

            IReadOnlyDictionary<string, string>

                allowedArguments =

                    BuildAllowedArguments(

                        plan,

                        toolId

                    );

            return new ApprovedToolInvocation(

                toolId,

                endpoint,

                generation,

                allowedArguments,

                TimeSpan.FromMinutes(5),

                DateTime.UtcNow

            );
        }

        //------------------------------------------------------------------

        private void ValidatePlan(

            ToolInvocationPlan plan,

            string toolId

        )
        {
            if (

                !plan.ContainsTool(

                    toolId

                )

            )
            {
                throw new InvalidOperationException(

                    "Requested tool was not planned."

                );
            }

            if (

                !plan.HasArguments(

                    toolId

                )

            )
            {
                throw new InvalidOperationException(

                    "Tool arguments missing."

                );
            }
        }

        //------------------------------------------------------------------

        private IReadOnlyDictionary<string, string>

        BuildAllowedArguments(

            ToolInvocationPlan plan,

            string toolId

        )
        {
            var allowed =

                new Dictionary<string, string>();

            foreach (

                var pair in

                plan.ArgumentsFor(

                    toolId

                )

            )
            {
                allowed[pair.Key] =

                    pair.Value;
            }

            return allowed;
        }

        //------------------------------------------------------------------

        public string Summary(

            ApprovedToolInvocation approval

        )
        {
            return

                $"{approval.ToolId} -> " +

                $"{approval.EndpointId}";

        }
    }
}
