```
package projection;

import approval.ApprovedToolInvocation;

import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

public final class InvocationProjectionService {

    //------------------------------------------------------------------
    // Runtime Projection
    //------------------------------------------------------------------

    public RuntimeToolInvocation project(

        ApprovedToolInvocation approved

    ) {

        validateApproval(

            approved

        );

        Map<String, String> arguments =

            projectArguments(

                approved

            );

        long timeoutSeconds =

            convertTimeout(

                approved

            );

        Instant approvalTime =

            approved.getApprovalTimestamp()

                    .toInstant();

        /*
            RuntimeToolInvocation is intentionally a minimal execution
            artifact consumed by the gateway. It carries the tool
            identifier, the approved arguments, the timeout, and the
            approval timestamp needed to dispatch execution. Execution
            components are isolated from the approval and planning
            pipeline and never call back into approval services, so
            this projection is the single point where approved state
            is handed off to the runtime execution path.
        */

        RuntimeToolInvocation runtime =

            new RuntimeToolInvocation(

                approved.getToolId(),

                arguments,

                timeoutSeconds,

                approvalTime

            );

        return runtime;

    }

    //------------------------------------------------------------------
    // Argument Projection
    //------------------------------------------------------------------

    private Map<String, String> projectArguments(

        ApprovedToolInvocation approved

    ) {

        Map<String, String> projected =

            new HashMap<>();

        for (

            Map.Entry<String, String> entry :

            approved.getAllowedArguments().entrySet()

        ) {

            projected.put(

                entry.getKey(),

                entry.getValue()

            );

        }

        return projected;

    }

    //------------------------------------------------------------------
    // Timeout Projection
    //------------------------------------------------------------------

    private long convertTimeout(

        ApprovedToolInvocation approved

    ) {

        return approved

            .getTimeout()

            .getSeconds();

    }

    //------------------------------------------------------------------
    // Validation
    //------------------------------------------------------------------

    private void validateApproval(

        ApprovedToolInvocation approved

    ) {

        if (

            approved == null

        ) {

            throw new IllegalArgumentException(

                "Approved invocation cannot be null."

            );

        }

        if (

            approved.getToolId() == null ||

            approved.getToolId().isBlank()

        ) {

            throw new IllegalArgumentException(

                "Tool identifier is required."

            );

        }

        if (

            approved.getAllowedArguments() == null

        ) {

            throw new IllegalArgumentException(

                "Approved arguments are required."

            );

        }

        if (

            approved.getTimeout().isNegative() ||

            approved.getTimeout().isZero()

        ) {

            throw new IllegalArgumentException(

                "Timeout must be greater than zero."

            );

        }

        if (

            approved.getApprovalTimestamp() == null

        ) {

            throw new IllegalArgumentException(

                "Approval timestamp is required."

            );

        }

    }

    //------------------------------------------------------------------
    // Projection Summary
    //------------------------------------------------------------------

    public String summarize(

        RuntimeToolInvocation runtime

    ) {

        return

            runtime.toolId()

            + " -> "

            + runtime.argumentCount()

            + " approved argument(s)";

    }

    //------------------------------------------------------------------
    // Runtime Validation
    //------------------------------------------------------------------

    public void validateRuntime(

        RuntimeToolInvocation runtime

    ) {

        if (

            runtime == null

        ) {

            throw new IllegalArgumentException(

                "Runtime invocation cannot be null."

            );

        }

        if (

            runtime.toolId().isBlank()

        ) {

            throw new IllegalStateException(

                "Runtime tool identifier missing."

            );

        }

        if (

            runtime.timeoutSeconds() <= 0

        ) {

            throw new IllegalStateException(

                "Runtime timeout is invalid."

            );

        }

    }

}
