import { Component } from '@angular/core';

import { DocumentService }
from '../services/document.service';

@Component({
  selector: 'app-upload-document',

  template: `
    <h2>Upload Document</h2>

    <input
      type="file"
      (change)="onFileSelected($event)"
    />

    <button
      (click)="upload()"
    >
      Upload
    </button>

    <p>{{ message }}</p>
  `
})
export class UploadDocumentComponent {

  selectedFile?: File;

  message = '';

  constructor(
    private documentService:
      DocumentService
  ) {}

  onFileSelected(
    event: any
  ): void {

    this.selectedFile =
      event.target.files[0];
  }

  upload(): void {

    if (!this.selectedFile) {
      return;
    }

    this.documentService
      .uploadDocument(
        this.selectedFile
      )
      .subscribe({
        next: () => {
          this.message =
            'Document uploaded';
        },

        error: () => {
          this.message =
            'Upload failed';
        }
      });
  }
}
