```
use std::collections::{HashMap, HashSet};

use chrono::{Duration, Utc};

use crate::capability::model::{
    ApprovedToolCapability,
    ParameterDefinition,
};

/// Repository responsible for loading the canonical approved
/// capability produced by the policy engine.
///
/// NOTE:
/// This repository only returns immutable approval records.
/// Runtime representations are produced elsewhere.
pub struct CapabilityRepository {
    cache: HashMap<String, ApprovedToolCapability>,
}

impl CapabilityRepository {

    pub fn new() -> Self {

        Self {
            cache: HashMap::new(),
        }

    }

    pub fn find_approved_capability(
        &mut self,
        tool_id: &str,
        environment: &str,
        department: &str,
    ) -> Option<ApprovedToolCapability> {

        let cache_key =
            self.build_cache_key(
                tool_id,
                environment,
                department,
            );

        if let Some(capability) =
            self.cache.get(&cache_key)
        {
            return Some(capability.clone());
        }

        let capability =
            self.load_capability(
                tool_id,
                environment,
                department,
            )?;

        self.cache.insert(
            cache_key,
            capability.clone(),
        );

        Some(capability)

    }

    fn load_capability(
        &self,
        tool_id: &str,
        environment: &str,
        department: &str,
    ) -> Option<ApprovedToolCapability> {

        //
        // Simulated persistence lookup.
        // In production this would query PostgreSQL.
        //

        let mut departments =
            HashSet::new();

        departments.insert(
            department.to_string(),
        );

        Some(

            ApprovedToolCapability {

                capability_id:
                    "cap-91bc7"
                        .to_string(),

                tool_id:
                    tool_id.to_string(),

                provider_id:
                    "kubernetes-prod-provider"
                        .to_string(),

                capability_revision: 7,

                approval_id:
                    "APR-77431"
                        .to_string(),

                environment:
                    environment.to_string(),

                approved: true,

                revoked: false,

                allowed_parameters:
                    self.default_schema(),

                departments,

                expires_at:
                    Utc::now()
                        + Duration::hours(12),

            }

        )

    }

    fn default_schema(
        &self,
    ) -> Vec<ParameterDefinition> {

        vec![

            ParameterDefinition {

                name:
                    "service".into(),

                maximum_length: 64,

                required: true,

            },

            ParameterDefinition {

                name:
                    "namespace".into(),

                maximum_length: 64,

                required: true,

            },

            ParameterDefinition {

                name:
                    "reason".into(),

                maximum_length: 256,

                required: true,

            },

        ]

    }

    fn build_cache_key(
        &self,
        tool_id: &str,
        environment: &str,
        department: &str,
    ) -> String {

        format!(
            "{}:{}:{}",
            tool_id,
            environment,
            department
        )

    }

    pub fn list_approved_tools(
        &self,
    ) -> Vec<String> {

        vec![

            "restart-service".into(),
            "scale-deployment".into(),
            "restart-pod".into(),
            "flush-queue".into(),
            "invalidate-cache".into(),

        ]

    }

    pub fn count(
        &self,
    ) -> usize {

        self.list_approved_tools()
            .len()

    }

    pub fn clear_cache(
        &mut self,
    ) {

        self.cache.clear();

    }

}
