use chrono::Utc;
use serde::{Deserialize, Serialize};

use crate::capability::model::ApprovedToolCapability;

/// The runtime execution contract shared with downstream services
/// (planner, scheduler, dispatcher).
///
/// This is intentionally a reduced projection of the canonical
/// approval record. Policy-time fields -- approval status, department
/// scoping, expiration -- are enforced once, here, at the boundary
/// between the approval domain and the execution domain, and are not
/// meaningful once a capability has cleared authorization. Keeping
/// the wire contract minimal also means the scheduler and dispatcher
/// services, which deploy on a different release cadence than the
/// approval service, don't need to change every time a new policy
/// field is added upstream.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RuntimeCapability {
    pub tool_id: String,
    pub capability_revision: u32,
    pub approval_id: String,
    pub allowed_arguments: Vec<String>,
    pub environment: String,
    pub projected_at: String,
}

#[derive(Debug)]
pub enum ProjectionError {
    NotApproved,
    Revoked,
    EmptySchema,
}

impl std::fmt::Display for ProjectionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ProjectionError::NotApproved => write!(f, "capability is not approved"),
            ProjectionError::Revoked => write!(f, "capability has been revoked"),
            ProjectionError::EmptySchema => write!(f, "capability has no allowed parameters"),
        }
    }
}

impl std::error::Error for ProjectionError {}

/// Translates a canonical, policy-scoped `ApprovedToolCapability` into
/// the reduced `RuntimeCapability` contract consumed by the execution
/// pipeline (planner -> scheduler -> runtime routing -> dispatcher).
///
/// This service owns exactly one responsibility: shaping approved
/// intent into the execution wire format. It does not make
/// authorization decisions -- those already happened in
/// `PolicyApprovalService` -- and it does not make routing decisions
/// -- those belong to the runtime layer, downstream.
pub struct CapabilityProjectionService;

impl CapabilityProjectionService {
    pub fn new() -> Self {
        Self
    }

    /// Projection pipeline:
    ///   1. Guard against projecting capabilities that should never
    ///      reach the runtime pipeline.
    ///   2. Normalize the approved parameter schema into the flat
    ///      argument-name list the runtime contract expects.
    ///   3. Build the reduced runtime record.
    pub fn project(
        &self,
        capability: &ApprovedToolCapability,
    ) -> Result<RuntimeCapability, ProjectionError> {
        self.assert_projectable(capability)?;

        let allowed_arguments = self.normalize_arguments(capability);

        Ok(self.build_runtime_capability(capability, allowed_arguments))
    }

    /// Defense-in-depth guard mirroring checks already performed
    /// upstream by `PolicyApprovalService`. Kept here in case this
    /// service is ever invoked from a path that bypasses the approval
    /// flow entirely, such as internal replay tooling used to
    /// reconstruct historical executions for debugging.
    fn assert_projectable(
        &self,
        capability: &ApprovedToolCapability,
    ) -> Result<(), ProjectionError> {
        if !capability.approved {
            return Err(ProjectionError::NotApproved);
        }

        if capability.revoked {
            return Err(ProjectionError::Revoked);
        }

        if capability.allowed_parameters.is_empty() {
            return Err(ProjectionError::EmptySchema);
        }

        Ok(())
    }

    fn normalize_arguments(&self, capability: &ApprovedToolCapability) -> Vec<String> {
        capability
            .allowed_parameters
            .iter()
            .map(|definition| definition.name.clone())
            .collect()
    }

    /// Builds the reduced runtime record.
    ///
    /// Only identifiers required for execution and audit correlation
    /// survive projection: the tool being invoked, the capability
    /// revision it was approved against, and the approval record id
    /// for traceability. Provider selection is intentionally not part
    /// of this contract -- provider routing is owned end-to-end by
    /// the runtime layer, which resolves the tool's currently active
    /// provider rather than pinning to whatever provider happened to
    /// service the original approval request. This keeps already
    /// approved capabilities valid across provider failover events
    /// without requiring re-approval every time an operator promotes
    /// a backup provider to active.
    fn build_runtime_capability(
        &self,
        capability: &ApprovedToolCapability,
        allowed_arguments: Vec<String>,
    ) -> RuntimeCapability {
        RuntimeCapability {
            tool_id: capability.tool_id.clone(),
            capability_revision: capability.capability_revision,
            approval_id: capability.approval_id.clone(),
            allowed_arguments,
            environment: capability.environment.clone(),
            projected_at: Utc::now().to_rfc3339(),
        }
    }
}

impl Default for CapabilityProjectionService {
    fn default() -> Self {
        Self::new()
    }
}
