```
package runtime

/**
 * Kotlin-side mirror of the runtime capability contract received from
 * the scheduler. The field set matches the wire schema emitted by the
 * capability projection service.
 *
 * [pinnedProviderId] exists for tools that have opted out of
 * automatic provider failover and must always execute against the
 * exact provider their approval was granted for. It is null whenever
 * the upstream capability did not carry an explicit provider pin.
 */
data class RuntimeCapability(
    val toolId: String,
    val capabilityRevision: Int,
    val approvalId: String,
    val allowedArguments: List<String>,
    val environment: String,
    val pinnedProviderId: String? = null
)

data class ResolvedProvider(
    val providerId: String,
    val endpoint: String,
    val resolvedVia: String
)

data class ProviderRegistration(
    val providerId: String,
    val endpoint: String
)

class ProviderResolutionException(message: String) : RuntimeException(message)

/**
 * Backing store for provider registrations.
 *
 * A tool can have multiple registered providers -- see the
 * multi-provider examples in the platform's tool catalog (AWS,
 * Azure, Kubernetes, Disaster Recovery). Exactly one registration is
 * marked active per tool at any time, and that active registration
 * can change during a failover event -- for example, promoting the
 * Disaster Recovery provider after a regional AWS incident -- without
 * requiring re-approval of capabilities that were already granted.
 */
class ProviderRegistry(
    private val activeRegistrations: Map<String, ProviderRegistration>,
    private val pinnedRegistrations: Map<Pair<String, String>, ProviderRegistration>
) {

    /**
     * Resolves a tool to whichever provider is currently marked
     * active for it. This is the default resolution path, used
     * whenever the caller does not pin to a specific provider.
     */
    fun resolve(toolId: String, capabilityRevision: Int): ProviderRegistration {
        return activeRegistrations[toolId]
            ?: throw ProviderResolutionException(
                "no active provider registered for tool '$toolId'"
            )
    }

    /**
     * Resolves a tool to a specific, explicitly pinned provider. Used
     * for tools that have opted out of automatic failover and must
     * always execute against the exact provider their approval names.
     */
    fun resolve(toolId: String, providerId: String, capabilityRevision: Int): ProviderRegistration {
        return pinnedRegistrations[Pair(toolId, providerId)]
            ?: throw ProviderResolutionException(
                "provider '$providerId' is not a registered provider for tool '$toolId'"
            )
    }

    companion object {
        /**
         * Seeds the registry with the platform's current provider
         * topology. `restart-service` was recently failed over to the
         * AWS provider after a Kubernetes control-plane incident in
         * the primary region; the Kubernetes provider remains
         * registered for pinned resolution but is no longer active.
         */
        fun loadCurrentTopology(): ProviderRegistry {
            val active = mapOf(
                "restart-service" to ProviderRegistration(
                    providerId = "aws-prod-provider",
                    endpoint = "https://aws-mcp.internal.corp"
                ),
                "scale-deployment" to ProviderRegistration(
                    providerId = "kubernetes-prod-provider",
                    endpoint = "https://k8s-mcp.internal.corp"
                )
            )

            val pinned = mapOf(
                Pair("restart-service", "kubernetes-prod-provider") to ProviderRegistration(
                    providerId = "kubernetes-prod-provider",
                    endpoint = "https://k8s-mcp.internal.corp"
                ),
                Pair("restart-service", "aws-prod-provider") to ProviderRegistration(
                    providerId = "aws-prod-provider",
                    endpoint = "https://aws-mcp.internal.corp"
                ),
                Pair("restart-service", "disaster-recovery-provider") to ProviderRegistration(
                    providerId = "disaster-recovery-provider",
                    endpoint = "https://dr-mcp.internal.corp"
                )
            )

            return ProviderRegistry(active, pinned)
        }
    }
}

/**
 * Resolves which physical provider should service a tool invocation
 * at execution time.
 *
 * This resolver trusts the runtime capability it is handed. It has no
 * visibility into which provider the approval service originally
 * authorized -- that identifier is a policy-time detail that belongs
 * to the approval and projection stages -- so it treats "no pin
 * present" as "use whatever is currently active," which is the
 * platform's intended behavior for tools participating in automatic
 * failover.
 */
class ProviderResolver(
    private val registry: ProviderRegistry
) {

    /**
     * Resolution pipeline:
     *  1. Validate the runtime capability carries enough identifying
     *     information to resolve against.
     *  2. If the capability carries an explicit provider pin, honor
     *     it exactly.
     *  3. Otherwise, resolve against whichever provider is currently
     *     marked active for the tool and capability revision.
     */
    fun resolveProvider(capability: RuntimeCapability): ResolvedProvider {

        validateCapability(capability)

        val pinnedProviderId = capability.pinnedProviderId

        val registration = if (pinnedProviderId != null) {
            registry.resolve(
                capability.toolId,
                pinnedProviderId,
                capability.capabilityRevision
            )
        } else {
            registry.resolve(
                capability.toolId,
                capability.capabilityRevision
            )
        }

        return ResolvedProvider(
            providerId = registration.providerId,
            endpoint = registration.endpoint,
            resolvedVia = if (pinnedProviderId != null) "pinned" else "active-registration"
        )
    }

    private fun validateCapability(capability: RuntimeCapability) {
        require(capability.toolId.isNotBlank()) {
            "runtime capability is missing a tool id"
        }
        require(capability.capabilityRevision > 0) {
            "runtime capability has an invalid capability revision"
        }
        require(capability.approvalId.isNotBlank()) {
            "runtime capability is missing an approval id"
        }
    }
}
