data class ExtractedPackage(

    val packageId: String,

    val extractionRoot: String,

    val extractedFiles:
        List<ExtractedFile>,

    val extractedAt: Long
)

data class ExtractedFile(

    val relativePath: String,

    val absolutePath: String,

    val symbolicLink: Boolean,

