## FILE: packages/PackageExtractor.kt

```
package packages

import java.io.File
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardCopyOption
import java.util.UUID
import java.util.zip.ZipEntry
import java.util.zip.ZipInputStream

class PackageExtractor {

    fun extract(
        packageArchive: File,
        extractionBase: String
    ): ExtractedPackage {

        val packageId =
            UUID.randomUUID().toString()

        val extractionRoot =
            "$extractionBase/$packageId"

        val rootDirectory =
            File(extractionRoot)

        rootDirectory.mkdirs()

        val extractedFiles =
            mutableListOf<ExtractedFile>()

        ZipInputStream(
            packageArchive.inputStream()
        ).use { zip ->

            var entry: ZipEntry? =
                zip.nextEntry

            while (entry != null) {

                val target =
                    File(
                        rootDirectory,
                        entry.name
                    )

                target.parentFile?.mkdirs()

                if (entry.isDirectory) {

                    target.mkdirs()

                    entry = zip.nextEntry
                    continue
                }

                Files.copy(
                    zip,
                    target.toPath(),
                    StandardCopyOption.REPLACE_EXISTING
                )

                extractedFiles.add(
                    buildMetadata(
                        rootDirectory.toPath(),
                        target.toPath()
                    )
                )

                entry = zip.nextEntry
            }
        }

        return ExtractedPackage(
            packageId = packageId,
            extractionRoot = extractionRoot,
            extractedFiles = extractedFiles,
            extractedAt =
                System.currentTimeMillis()
        )
    }

    private fun buildMetadata(
        root: Path,
        file: Path
    ): ExtractedFile {

        val relativePath =
            root.relativize(file)
                .toString()

        return ExtractedFile(
            relativePath = relativePath,

            absolutePath =
                file.toAbsolutePath()
                    .toString(),

            symbolicLink =
                Files.isSymbolicLink(file),

            sizeBytes =
                Files.size(file)
        )
    }
}
