## FILE: validation/EvaluationManifestLoader.py

```
import yaml


class EvaluationManifest:
    def __init__(
        self,
        model_path,
        dataset_path,
        metric
    ):
        self.model_path = model_path
        self.dataset_path = dataset_path
        self.metric = metric


class EvaluationManifestLoader:

    REQUIRED_FIELDS = {
        "model",
        "dataset",
        "metric"
    }

    def load(self, manifest_path):

        with open(
            manifest_path,
            "r",
            encoding="utf-8"
        ) as handle:

            document = yaml.safe_load(
                handle
            )

        self._validate(document)

        return EvaluationManifest(
            model_path=
                document["model"],

            dataset_path=
                document["dataset"],

            metric=
                document["metric"]
        )

    def _validate(
        self,
        document
    ):

        missing = (
            self.REQUIRED_FIELDS -
            set(document.keys())
        )

        if missing:

            raise ValueError(
                "Missing manifest fields: "
                + ", ".join(missing)
            )

        dataset = document["dataset"]

        if not isinstance(
            dataset,
            str
        ):

            raise ValueError(
                "Dataset path must be a string"
            )

        if dataset.strip() == "":

            raise ValueError(
                "Dataset path cannot be empty"
            )

        model = document["model"]

        if not isinstance(
            model,
            str
        ):

            raise ValueError(
                "Model path must be a string"
            )
