## FILE: evaluation/DatasetReferenceResolver.go

```
package evaluation

import (
	"fmt"
	"os"
	"path/filepath"
)

type DatasetReferenceResolver struct {
}

func (r *DatasetReferenceResolver)
	Resolve(
		extractionRoot string,
		datasetPath string,
	) (string, error) {

	if datasetPath == "" {
		return "", fmt.Errorf(
			"dataset path missing",
		)
	}

	candidate :=
		filepath.Join(
			extractionRoot,
			datasetPath,
		)

	_, err :=
		os.Stat(candidate)

	if err != nil {
		return "", err
	}

	resolvedPath, err :=
		filepath.EvalSymlinks(
			candidate,
		)

	if err != nil {
		return "", err
	}

	return resolvedPath, nil
}

func (r *DatasetReferenceResolver)
	Exists(
		extractionRoot string,
		datasetPath string,
	) bool {

	candidate :=
		filepath.Join(
			extractionRoot,
			datasetPath,
		)

	_, err :=
		os.Stat(candidate)

	return err == nil
}
