```
package evaluation

import (
	"fmt"

	"model-evaluation-platform/packages"
	"model-evaluation-platform/validation"
)

type EvaluationJob struct {
	PackageID   string
	ModelPath   string
	DatasetPath string
	Metric      string
}

type EvaluationJobBuilder struct {
	Resolver *DatasetReferenceResolver
}

func (b *EvaluationJobBuilder)
	Build(
		pkg packages.ExtractedPackage,
		manifest validation.EvaluationManifest,
	) (*EvaluationJob, error) {

	modelPath :=
		fmt.Sprintf(
			"%s/%s",
			pkg.ExtractionRoot,
			manifest.ModelPath,
		)

	datasetPath, err :=
		b.Resolver.Resolve(
			pkg.ExtractionRoot,
			manifest.DatasetPath,
		)

	if err != nil {
		return nil, err
	}

	job := &EvaluationJob{
		PackageID:
			pkg.PackageID,

		ModelPath:
			modelPath,

		DatasetPath:
			datasetPath,

		Metric:
			manifest.Metric,
	}

	return job, nil
}

func (b *EvaluationJobBuilder)
	ValidateInputs(
		job *EvaluationJob,
	) error {

	if job.ModelPath == "" {
		return fmt.Errorf(
			"missing model path",
		)
	}

	if job.DatasetPath == "" {
		return fmt.Errorf(
			"missing dataset path",
		)
	}

	return nil
}
