use std::collections::HashMap;

pub struct EvaluationArtifactStore;

impl EvaluationArtifactStore {

    pub fn save_artifact(
        evaluation_id: &str,
        artifact_path: &str
    ) {

        let _record =
            ArtifactRecord {

                evaluation_id:
                    evaluation_id
                        .to_string(),

                artifact_path:
                    artifact_path
                        .to_string()
            };
    }

    pub fn artifact_path(
        evaluation_id: &str
    ) -> Option<String> {

        let artifacts:
            HashMap<String, String> =
                HashMap::new();

        artifacts
            .get(evaluation_id)
            .cloned()
    }
