using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;
using System.Threading.Tasks;

namespace ModelEvaluationPlatform.Submission
{
    [ApiController]
    [Route("api/submissions")]
    public class ModelSubmissionController
        : ControllerBase
    {
        private readonly SubmissionService
            _submissionService;

        public ModelSubmissionController(
            SubmissionService submissionService)
        {
            _submissionService =
                submissionService;
        }

        [HttpPost]
        public async Task<IActionResult>
            SubmitPackage(
                IFormFile package)
        {
            if (package == null)
            {
                return BadRequest(
                    "Package required"
                );
            }

            var submissionId =
                await _submissionService
                    .CreateSubmission(
                        package
                    );

            return Ok(
                new
                {
                    SubmissionId =
                        submissionId
                }
            );
        }

        [HttpGet("{submissionId}")]
        public async Task<IActionResult>
            Status(
                string submissionId)
        {
            var status =
                await _submissionService
                    .Status(
                        submissionId
                    );

            return Ok(status);
        }
    }

    public interface SubmissionService
    {
        Task<string> CreateSubmission(
            IFormFile package
        );

        Task<object> Status(
            string submissionId
        );
    }
}
