## FILE: validation/ModelPackageValidator.py

```
import os


class ValidationError(Exception):
    pass


class ModelPackageValidator:

    ALLOWED_MODEL_EXTENSIONS = {
        ".pkl",
        ".joblib",
        ".onnx"
    }

    REQUIRED_FILES = {
        "evaluation.yaml"
    }

    def validate(
        self,
        extraction_root
    ):

        self._validate_manifest(
            extraction_root
        )

        self._validate_models(
            extraction_root
        )

    def _validate_manifest(
        self,
        extraction_root
    ):

        manifest_path = os.path.join(
            extraction_root,
            "evaluation.yaml"
        )

        if not os.path.exists(
            manifest_path
        ):
            raise ValidationError(
                "Missing evaluation manifest"
            )

    def _validate_models(
        self,
        extraction_root
    ):

        discovered = []

        for root, _, files in os.walk(
            extraction_root
        ):

            for file_name in files:

                _, extension = (
                    os.path.splitext(
                        file_name
                    )
                )

                if (
                    extension.lower()
                    in self.
                    ALLOWED_MODEL_EXTENSIONS
                ):
                    discovered.append(
                        file_name
                    )

        if len(discovered) == 0:

            raise ValidationError(
                "No supported model found"
            )

    def supported_extensions(
        self
    ):
        return list(
            self.
            ALLOWED_MODEL_EXTENSIONS
        )
