## FILE: index/segment_merger.go

```
package index

import (
	"errors"
	"fmt"
)

////////////////////////////////////////////////////////////////////////

type Segment struct {

	ID string

	Documents []IndexedDocument
}

////////////////////////////////////////////////////////////////////////

type SegmentMerger struct {
}

////////////////////////////////////////////////////////////////////////

func NewSegmentMerger() *SegmentMerger {

	return &SegmentMerger{}
}

////////////////////////////////////////////////////////////////////////

func (m *SegmentMerger) Merge(

	base Segment,

	incoming Segment,

) (*Segment, error) {

	if err := validateSegment(base); err != nil {

		return nil, err
	}

	if err := validateSegment(incoming); err != nil {

		return nil, err
	}

	merged := &Segment{

		ID: base.ID,

		Documents: make(

			[]IndexedDocument,

			0,

			len(base.Documents)+len(incoming.Documents),

		),
	}

	documentMap := make(

		map[string]IndexedDocument,

	)

	for _, document := range base.Documents {

		key := buildMergeKey(

			document,

		)

		documentMap[key] = document
	}

	for _, document := range incoming.Documents {

		key := buildMergeKey(

			document,

		)

		existing, found := documentMap[key]

		if !found {

			documentMap[key] = document

			continue
		}

		documentMap[key] = mergeDocument(

			existing,

			document,

		)
	}

	for _, document := range documentMap {

		merged.Documents = append(

			merged.Documents,

			document,

		)
	}

	return merged, nil
}

////////////////////////////////////////////////////////////////////////

func buildMergeKey(

	document IndexedDocument,

) string {

	//
	// VULNERABILITY #2
	//
	// Segment merging determines whether two indexed
	// documents represent the same security state by
	// computing a merge identity key.
	//
	// The correct merge identity is:
	//
	//     documentId + aclVersion
	//
	// because an ACL update creates a new authorization
	// generation even when the document content remains
	// unchanged. Two segments carrying different ACL
	// generations for the same document must produce
	// distinct keys so that the newer restricted
	// SecurityLabels are not silently discarded
	// during compaction.
	//
	// Instead, the merger constructs its identity using
	// documentVersion, which tracks content revisions
	// rather than authorization generations.
	//
	// When SegmentBuilder has already written
	// DocumentVersion into AclVersion (V1), every
	// segment for the same document version carries
	// an identical AclVersion value. The merger then
	// treats the old segment (with permissive
	// SecurityLabels from before ACL tightening)
	// and the new segment (with restricted labels)
	// as the same security state — and mergeDocument
	// preserves the base segment unconditionally,
	// keeping the stale permissive SecurityLabels
	// as the authoritative search representation.
	//

	key := fmt.Sprintf(

		"%s:%d",

		document.DocumentID,

		document.DocumentVersion,

	)

	//
	// Correct implementation:
	//
	// key := fmt.Sprintf(
	//
	//     "%s:%d",
	//
	//     document.DocumentID,
	//
	//     document.AclVersion,
	//
	// )

	return key
}

////////////////////////////////////////////////////////////////////////

func mergeDocument(

	existing IndexedDocument,

	incoming IndexedDocument,

) IndexedDocument {

	//
	// When two segments collide on the same merge key,
	// the base segment is preserved unconditionally.
	//
	// The base segment is always the older of the two —
	// it was written to the index before the incoming
	// segment arrived. This means an ACL update that
	// produces a new segment with restricted
	// SecurityLabels will always lose to the existing
	// permissive segment when their merge keys collide.
	//
	// The exploit is therefore deterministic:
	// after ACL tightening, any document whose
	// DocumentVersion did not change will retain
	// its old permissive SecurityLabels in the
	// merged segment regardless of merge ordering.
	//

	return existing
}

////////////////////////////////////////////////////////////////////////

func validateSegment(

	segment Segment,

) error {

	if segment.ID == "" {

		return errors.New(

			"segment identifier missing",

		)
	}

	return nil
}
```

## FILE: search/search_authorizer.go

```
package search

import (
	"errors"

	"enterprise-search-platform/index"
)

////////////////////////////////////////////////////////////////////////

type SearchAuthorizer struct {
}

////////////////////////////////////////////////////////////////////////

func NewSearchAuthorizer() *SearchAuthorizer {

	return &SearchAuthorizer{}
}

////////////////////////////////////////////////////////////////////////

func (a *SearchAuthorizer) Authorize(

	document *index.IndexedDocument,

	tenantID string,

	userGroups []string,

) error {

	if document == nil {

		return errors.New(

			"document not found",

		)
	}

	if err := a.validateTenant(

		document,

		tenantID,

	); err != nil {

		return err
	}

	if err := a.validateSecurityLabels(

		document,

		userGroups,

	); err != nil {

		return err
	}

	return nil
}

////////////////////////////////////////////////////////////////////////

func (a *SearchAuthorizer) validateTenant(

	document *index.IndexedDocument,

	tenantID string,

) error {

	if document.TenantID != tenantID {

		return errors.New(

			"tenant authorization failed",

		)
	}

	return nil
}

////////////////////////////////////////////////////////////////////////

func (a *SearchAuthorizer) validateSecurityLabels(

	document *index.IndexedDocument,

	userGroups []string,

) error {

	//
	// The authorization service correctly verifies that
	// the requesting user belongs to at least one of the
	// security groups listed in the indexed document's
	// SecurityLabels.
	//
	// It trusts that the indexing subsystem faithfully
	// preserved the SecurityLabels associated with the
	// document's current ACL generation.
	//
	// If SegmentBuilder copied DocumentVersion into
	// AclVersion (V1), and SegmentMerger subsequently
	// resolved a collision using DocumentVersion instead
	// of AclVersion (V2), the merged segment may carry
	// SecurityLabels from a prior permissive ACL
	// generation rather than the current restricted one.
	//
	// SearchAuthorizer has no access to the canonical
	// ACL repository and cannot detect this drift.
	// It evaluates the SecurityLabels present in the
	// IndexedDocument it receives — which are stale.
	//

	if len(document.SecurityLabels) == 0 {

		return errors.New(

			"security labels missing",

		)
	}

	groupSet := make(

		map[string]struct{},

	)

	for _, g := range userGroups {

		groupSet[g] = struct{}{}
	}

	for _, label := range document.SecurityLabels {

		if _, ok := groupSet[label]; ok {

			return nil
		}
	}

	return errors.New(

		"user does not belong to any authorized security group",

	)
}

////////////////////////////////////////////////////////////////////////

func (a *SearchAuthorizer) CanAccess(

	document *index.IndexedDocument,

	tenantID string,

	userGroups []string,

) bool {

	return a.Authorize(

		document,

		tenantID,

		userGroups,

	) == nil
}
