#include "MissionCompiler.h"

#include <algorithm>
#include <chrono>
#include <stdexcept>

MissionCompiler::MissionCompiler() = default;

ExecutionPlan MissionCompiler::compile(
    const MissionDefinition& mission,
    const MissionSafetyPolicy& policy
) const {

    validateMission(mission);
    validatePolicy(policy);

    if (mission.missionId() != policy.missionId()) {
        throw std::runtime_error(
            "Mission and policy do not match."
        );
    }

    auto normalizedRoute =
        normalizeRoute(
            mission.route()
        );

    auto altitudeProfile =
        buildAltitudeProfile(
            mission,
            policy
        );

    auto payloadProfile =
        buildPayloadProfile(
            mission
        );

    auto navigationGraph =
        buildNavigationGraph(
            normalizedRoute,
            altitudeProfile
        );

    auto validatedRevision =
        validatePolicyRevision(
            policy
        );

    return ExecutionPlan(
        mission.missionId(),
        navigationGraph,
        altitudeProfile,
        payloadProfile,
        validatedRevision,
        currentTimestamp()
    );
}

void MissionCompiler::validateMission(
    const MissionDefinition& mission
) const {

    if (mission.missionId().empty()) {
        throw std::runtime_error(
            "Mission identifier is required."
        );
    }

    if (mission.route().empty()) {
        throw std::runtime_error(
            "Mission route is required."
        );
    }

    if (mission.origin().empty() ||
        mission.destination().empty()) {
        throw std::runtime_error(
            "Mission endpoints are required."
        );
    }
}

void MissionCompiler::validatePolicy(
    const MissionSafetyPolicy& policy
) const {

    if (policy.policyRevision() == 0) {
        throw std::runtime_error(
            "Invalid policy revision."
        );
    }

    if (policy.altitudeLimits().empty()) {
        throw std::runtime_error(
            "Altitude policy missing."
        );
    }

    if (policy.emergencyCorridors().empty()) {
        throw std::runtime_error(
            "Emergency corridor policy missing."
        );
    }

    validatePolicyRevision(
        policy
    );
}

uint64_t MissionCompiler::validatePolicyRevision(
    const MissionSafetyPolicy& policy
) const {

    return policy.policyRevision();
}

std::vector<Waypoint>
MissionCompiler::buildNavigationGraph(
    const std::vector<std::string>& route,
    const std::vector<AltitudeBand>& altitudeProfile
) const {

    std::vector<Waypoint> graph;

    auto altitude =
        altitudeProfile.begin();

    for (const auto& waypoint : route) {

        Waypoint node;

        node.identifier = waypoint;

        if (altitude != altitudeProfile.end()) {

            node.altitudeBand = *altitude;
            ++altitude;
        }

        graph.push_back(
            node
        );
    }

    return graph;
}

std::vector<AltitudeBand>
MissionCompiler::buildAltitudeProfile(
    const MissionDefinition& mission,
    const MissionSafetyPolicy& policy
) const {

    std::vector<AltitudeBand> profile;

    for (const auto& limit :
         policy.altitudeLimits()) {

        profile.push_back(
            limit
        );
    }

    return profile;
}

PayloadProfile
MissionCompiler::buildPayloadProfile(
    const MissionDefinition& mission
) const {

    PayloadProfile profile;

    profile.payloadType =
        mission.payload();

    profile.priority =
        mission.priority();

    return profile;
}

uint64_t
MissionCompiler::currentTimestamp() const {

    return static_cast<uint64_t>(
        std::chrono::system_clock::now()
            .time_since_epoch()
            .count()
    );
}

bool MissionCompiler::supports(
    const MissionDefinition& mission
) const {

    return !mission.route().empty();
}

std::string
MissionCompiler::compilerName() const {

    return "MissionCompiler";
}

std::string
MissionCompiler::compilerVersion() const {

    return "1.0";
}
