FlightStatus
executeMission(
    const ExecutionPlan* plan
)
{
    validateExecutionPlan(
        plan
    );

    initializeNavigation(
        plan
    );

    initializePayload(
        plan
    );

    armFlightSystems();

    followNavigationGraph(
        plan->navigationGraph,
        plan->waypointCount
    );

    return FLIGHT_COMPLETED;
}

static void
validateExecutionPlan(
    const ExecutionPlan* plan
)
{
    if (plan == NULL)
    {
        abortFlight(
            "Execution plan missing."
        );
    }

    if (!plan->isExecutable)
    {
        abortFlight(
            "Execution plan invalid."
        );
    }

    if (plan->waypointCount == 0)
    {
        abortFlight(
            "Navigation graph missing."
        );
    }

    if (plan->policyRevision == 0)
    {
        abortFlight(
            "Policy revision missing."
        );
    }
}

static void
initializeNavigation(
    const ExecutionPlan* plan
)
{
    loadNavigationGraph(
        plan->navigationGraph,
        plan->waypointCount
    );

    configureAltitudeProfile(
        plan->altitudeProfile,
        plan->altitudeProfileSize
    );
}

static void
initializePayload(
    const ExecutionPlan* plan
)
{
    configurePayload(
        plan->payloadProfile
    );
}

bool
supportsExecution(
