```
package com.idp.provisioning.workflow

import com.idp.provisioning.model.RuntimeSecretResponse
import com.idp.provisioning.model.SecretMaterializationCommand
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

/**
 * Coordinates the runtime secret materialization workflow.
 *
 * Responsibilities
 * ----------------
 * - Validate workload authorization.
 * - Build the materialization job.
 * - Dispatch the request to the materialization engine.
 *
 * The coordinator never performs alias resolution itself.
 */
@Service
class SecretMaterializationCoordinator(
    private val authorizationService: WorkloadAuthorizationService,
    private val materializationClient: SecretMaterializationClient
) {

    private val logger =
        LoggerFactory.getLogger(SecretMaterializationCoordinator::class.java)

    fun materialize(
        command: SecretMaterializationCommand
    ): RuntimeSecretResponse {

        logger.info(
            "Starting runtime secret materialization. workload={}, alias={}, scope={}",
            command.workloadId,
            command.secretAlias,
            command.workloadScope
        )

        authorizationService.verifyAccess(command)

        val request = SecretMaterializationJob(
            correlationId = command.correlationId,
            workloadId = command.workloadId,
            applicationName = command.applicationName,
            namespace = command.namespace,
            environment = command.environment,
            secretAlias = command.secretAlias,
            workloadScope = command.workloadScope
        )

        logger.debug(
            "Dispatching secret materialization job for alias {}.",
            request.secretAlias
        )

        return materializationClient.materialize(request)
    }
}

/**
 * Internal RPC client responsible for communicating with
 * the Scala materialization engine.
 */
interface SecretMaterializationClient {

    fun materialize(
        request: SecretMaterializationJob
    ): RuntimeSecretResponse
}

/**
 * Immutable job forwarded to the materialization engine.
 */
data class SecretMaterializationJob(

    val correlationId: String,

    val workloadId: String,

    val applicationName: String,

    val namespace: String,

    val environment: String,

    val secretAlias: String,

    val workloadScope: String
)
