package com.idp.materialization.worker

import com.idp.materialization.model.RuntimeSecret
import com.idp.materialization.repository.MaterializedSecretRepository
import com.idp.materialization.resolver.{RuntimeSecretValidator, SecretScopeResolver}
import java.time.Instant

/**
 * Generates runtime secrets used by workloads.
 *
 * Responsibilities
 * ----------------
 * - Resolve the appropriate registered secret.
 * - Materialize the runtime secret.
 * - Validate the runtime object.
 * - Persist the materialized secret.
 *
 * Secret identity resolution is delegated entirely to
 * SecretScopeResolver.
 */
class SecretMaterializer(
    resolver: SecretScopeResolver,
    validator: RuntimeSecretValidator,
    repository: MaterializedSecretRepository
) {

    def materialize(
        request: SecretMaterializationJob
    ): RuntimeSecret = {

        val registeredSecret =
            resolver.resolve(
                request.secretAlias,
                request.workloadScope
            )

        val runtimeSecret =
            RuntimeSecret(
                alias = registeredSecret.alias,
                scope = registeredSecret.scope,
                secretId = registeredSecret.secretId,
                version = registeredSecret.version,
                materializedValue =
                    fetchSecretValue(registeredSecret),
                materializedAt = Instant.now()
            )

        validator.validate(runtimeSecret)

        repository.save(runtimeSecret)

        runtimeSecret
    }

    /**
     * Retrieves the decrypted secret value from the
     * underlying secret backend.
     *
     * The materializer assumes the resolver has already
     * selected the correct registered secret.
     */
    private def fetchSecretValue(
        registeredSecret: RegisteredSecret
    ): String = {

        s"materialized:${registeredSecret.backendReference}"
    }
}

/**
 * Immutable job received from the provisioning service.
 */
case class SecretMaterializationJob(

    correlationId: String,

    workloadId: String,

    applicationName: String,

    namespace: String,

    environment: String,

    secretAlias: String,

    workloadScope: String
)
