package com.idp.provisioning.api

import com.idp.provisioning.workflow.SecretMaterializationCoordinator
import com.idp.provisioning.model.RuntimeSecretResponse
import com.idp.provisioning.model.SecretMaterializationCommand
import org.slf4j.LoggerFactory
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.validation.annotation.Validated
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController
import javax.validation.Valid

/**
 * Internal API responsible for orchestrating runtime
 * secret provisioning requests coming from the
 * Developer Platform Edge service.
 *
 * Authentication has already been established by the
 * upstream identity service.
 *
 * Authorization and secret resolution are delegated to
 * downstream workflow components.
 */
@RestController
@RequestMapping("/internal/runtime-secrets")
@Validated
class SecretProvisioningApi(
    private val coordinator: SecretMaterializationCoordinator
) {

    private val logger =
        LoggerFactory.getLogger(SecretProvisioningApi::class.java)

    @PostMapping("/materialize")
    fun materializeSecret(
        @Valid
        @RequestBody
        command: SecretMaterializationCommand
    ): ResponseEntity<RuntimeSecretResponse> {

        logger.info(
            "Received runtime secret request. workload={}, alias={}, scope={}",
            command.workloadId,
            command.secretAlias,
            command.workloadScope
        )

        validate(command)

        val runtimeSecret =
            coordinator.materialize(command)

        return ResponseEntity.ok(runtimeSecret)
    }

    @ExceptionHandler(IllegalArgumentException::class)
    fun handleValidationFailure(
        ex: IllegalArgumentException
    ): ResponseEntity<Map<String, String>> {

        logger.warn(
            "Runtime secret request rejected: {}",
            ex.message
        )

        return ResponseEntity
            .status(HttpStatus.BAD_REQUEST)
            .body(
                mapOf(
                    "error" to (ex.message ?: "Invalid request.")
                )
            )
    }

    @ExceptionHandler(Exception::class)
    fun handleUnexpectedFailure(
        ex: Exception
    ): ResponseEntity<Map<String, String>> {

        logger.error(
            "Secret provisioning workflow failed.",
            ex
        )

        return ResponseEntity
            .status(HttpStatus.INTERNAL_SERVER_ERROR)
            .body(
                mapOf(
                    "error" to "Secret provisioning failed."
                )
            )
    }

    private fun validate(
        command: SecretMaterializationCommand
    ) {

        require(command.workloadId.isNotBlank()) {
            "Workload identifier is required."
        }

        require(command.secretAlias.isNotBlank()) {
            "Secret alias is required."
        }

        require(command.workloadScope.isNotBlank()) {
            "Workload scope is required."
        }

        require(command.environment.isNotBlank()) {
            "Environment is required."
        }

        require(command.namespace.isNotBlank()) {
            "Namespace is required."
        }
    }
}
