using System;
using System.ComponentModel.DataAnnotations;

namespace DeveloperPlatform.Contracts
{
    /// <summary>
    /// Request submitted by an authenticated workload to
    /// materialize a runtime secret.
    ///
    /// The request identifies the logical secret required by the
    /// workload rather than a concrete secret version.
    ///
    /// Secret resolution and authorization are performed by the
    /// downstream provisioning workflow.
    /// </summary>
    public sealed class SecretMaterializationRequest
    {
        /// <summary>
        /// Unique workload requesting the secret.
        /// </summary>
        [Required]
        [MinLength(3)]
        public string WorkloadId { get; init; } = string.Empty;

        /// <summary>
        /// Service or application name.
        /// </summary>
        [Required]
        public string ApplicationName { get; init; } = string.Empty;

        /// <summary>
        /// Logical secret alias.
        ///
        /// Example:
        /// billing/postgres
        /// </summary>
        [Required]
        public string SecretAlias { get; init; } = string.Empty;

        /// <summary>
        /// Business scope owning the secret.
        ///
        /// Example:
        /// payments
        /// analytics
        /// platform
        /// </summary>
        [Required]
        public string WorkloadScope { get; init; } = string.Empty;

        /// <summary>
        /// Deployment environment.
        /// </summary>
        [Required]
        public string Environment { get; init; } = string.Empty;

        /// <summary>
        /// Namespace in which the workload executes.
        /// </summary>
        [Required]
        public string Namespace { get; init; } = string.Empty;

        /// <summary>
        /// Internal correlation identifier used for
        /// distributed tracing.
        /// </summary>
        public Guid CorrelationId { get; init; } =
            Guid.NewGuid();

        /// <summary>
        /// UTC request timestamp.
        /// </summary>
        public DateTime RequestedAtUtc { get; init; } =
            DateTime.UtcNow;

        public void Validate()
        {
            if (string.IsNullOrWhiteSpace(WorkloadId))
                throw new ValidationException(
                    "Workload identifier is required.");

            if (string.IsNullOrWhiteSpace(ApplicationName))
                throw new ValidationException(
                    "Application name is required.");

            if (string.IsNullOrWhiteSpace(SecretAlias))
                throw new ValidationException(
                    "Secret alias is required.");

            if (string.IsNullOrWhiteSpace(WorkloadScope))
                throw new ValidationException(
                    "Workload scope is required.");

            if (string.IsNullOrWhiteSpace(Environment))
                throw new ValidationException(
                    "Environment is required.");

            if (string.IsNullOrWhiteSpace(Namespace))
                throw new ValidationException(
                    "Namespace is required.");
        }

        public override string ToString()
        {
            return $"{ApplicationName} | " +
                   $"{SecretAlias} | " +
                   $"{WorkloadScope} | " +
                   $"{Environment}";
        }
    }
}
