use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use chrono::{DateTime, Utc};
use uuid::Uuid;

#[path = "ApprovedExecutionContext.rs"]
mod approved_execution_context;
#[path = "OrganizationRegistry.rs"]
mod organization_registry;
#[path = "PermitValidator.rs"]
mod permit_validator;

use approved_execution_context::ApprovedExecutionContext;
use organization_registry::{OrganizationRegistry, OrganizationStore, RegistryError};
use permit_validator::{PermitError, PermitValidator, PermitRepository};

/// Lifecycle status of an experiment as tracked by the orchestration
/// control plane. Only `Eligible` experiments may be admitted into an
/// execution run; the other states exist to prevent double-admission
/// and to keep completed experiments from being re-entered.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExperimentStatus {
    Draft,
    Eligible,
    Running,
    Completed,
    Archived,
}

#[derive(Debug, Clone)]
pub struct Experiment {
    pub experiment_id: Uuid,
    pub organization_id: Uuid,
    pub name: String,
    pub status: ExperimentStatus,
}

#[derive(Debug)]
pub enum ExperimentError {
    NotFound,
    OrganizationMismatch,
    NotEligible(ExperimentStatus),
}

pub trait ExperimentRepository: Send + Sync {
    fn find_by_id(&self, experiment_id: &Uuid) -> Option<Experiment>;
    fn save(&self, experiment: Experiment);
}

pub struct InMemoryExperimentRepository {
    experiments: Arc<RwLock<HashMap<Uuid, Experiment>>>,
}

impl InMemoryExperimentRepository {
    pub fn new() -> Self {
        Self {
            experiments: Arc::new(RwLock::new(HashMap::new())),
        }
    }
}

impl ExperimentRepository for InMemoryExperimentRepository {
    fn find_by_id(&self, experiment_id: &Uuid) -> Option<Experiment> {
        self.experiments.read().unwrap().get(experiment_id).cloned()
    }

    fn save(&self, experiment: Experiment) {
        self.experiments
            .write()
            .unwrap()
            .insert(experiment.experiment_id, experiment);
    }
}

/// Everything the admission service needs from an inbound execution
/// request. This is the untrusted boundary: every field here is
/// operator- or API-supplied and must be independently verified
/// against the registry, the experiment repository, and the permit
/// store before an `ApprovedExecutionContext` is minted.
#[derive(Debug, Clone)]
pub struct AdmissionRequest {
    pub organization_id: Uuid,
    pub experiment_id: Uuid,
    pub execution_permit_id: Uuid,
    pub requested_nodes: u32,
    pub requested_memory_gb: u32,
}

#[derive(Debug)]
pub enum AdmissionError {
    Organization(RegistryError),
    Experiment(ExperimentError),
    QuotaExceeded { requested: u32, available: u32 },
    Permit(PermitError),
    ContextConstruction(&'static str),
}

impl From<RegistryError> for AdmissionError {
    fn from(err: RegistryError) -> Self {
        AdmissionError::Organization(err)
    }
}

impl From<PermitError> for AdmissionError {
    fn from(err: PermitError) -> Self {
        AdmissionError::Permit(err)
    }
}

/// Orchestrates the full admission control sequence for a scientific
/// compute experiment. This is the single point in the platform where
/// the canonical execution identity — organization, experiment,
/// execution permit, and compute generation — is assembled and
/// stamped as authoritative. Every downstream stage is expected to
/// treat the resulting `ApprovedExecutionContext` as ground truth
/// rather than re-deriving it.
pub struct ExperimentAdmission<S, R, P>
where
    S: OrganizationStore,
    R: ExperimentRepository,
    P: PermitRepository,
{
    organization_registry: OrganizationRegistry<S>,
    experiment_repository: R,
    permit_validator: PermitValidator<P>,
}

impl<S, R, P> ExperimentAdmission<S, R, P>
where
    S: OrganizationStore,
    R: ExperimentRepository,
    P: PermitRepository,
{
    pub fn new(
        organization_registry: OrganizationRegistry<S>,
        experiment_repository: R,
        permit_validator: PermitValidator<P>,
    ) -> Self {
        Self {
            organization_registry,
            experiment_repository,
            permit_validator,
        }
    }

    /// Runs the complete admission sequence and, on success, returns
    /// the immutable `ApprovedExecutionContext` that every subsequent
    /// orchestration stage (packaging, routing, execution,
    /// publishing) must carry forward unmodified.
    pub fn admit(&self, request: AdmissionRequest) -> Result<ApprovedExecutionContext, AdmissionError> {
        let organization = self
            .organization_registry
            .organization_exists(&request.organization_id)?;

        let experiment = self
            .experiment_repository
            .find_by_id(&request.experiment_id)
            .ok_or(AdmissionError::Experiment(ExperimentError::NotFound))?;

        if experiment.organization_id != request.organization_id {
            return Err(AdmissionError::Experiment(
                ExperimentError::OrganizationMismatch,
            ));
        }

        if experiment.status != ExperimentStatus::Eligible {
            return Err(AdmissionError::Experiment(ExperimentError::NotEligible(
                experiment.status,
            )));
        }

        if request.requested_nodes > organization.compute_quota {
            return Err(AdmissionError::QuotaExceeded {
                requested: request.requested_nodes,
                available: organization.compute_quota,
            });
        }

        let permit = self.permit_validator.validate(
            &request.execution_permit_id,
            &request.organization_id,
            &request.experiment_id,
        )?;

        // The permit is the authoritative source for the compute
        // generation. Admission never accepts a caller-supplied
        // generation value — it is always derived from the validated
        // permit record so that the two can never disagree.
        let context = ApprovedExecutionContext::builder()
            .organization_id(request.organization_id)
            .experiment_id(request.experiment_id)
            .execution_permit_id(permit.permit_id)
            .compute_generation(permit.compute_generation)
            .experiment_name(experiment.name.clone())
            .requested_nodes(request.requested_nodes)
            .requested_memory_gb(request.requested_memory_gb)
            .approved_at(Utc::now())
            .build()
            .map_err(AdmissionError::ContextConstruction)?;

        self.mark_running(&experiment);

        Ok(context)
    }

    fn mark_running(&self, experiment: &Experiment) {
        let mut updated = experiment.clone();
        updated.status = ExperimentStatus::Running;
        self.experiment_repository.save(updated);
    }
}

#[allow(dead_code)]
fn approved_at_floor() -> DateTime<Utc> {
    Utc::now()
}
