package approval

import scala.collection.mutable

class ReleaseRepository {

    //----------------------------------------------------------
    // Storage
    //----------------------------------------------------------

    private val releases =

        mutable.ListBuffer.empty[ApprovedRelease]

    //----------------------------------------------------------
    // Persistence
    //----------------------------------------------------------

    def save(

        release: ApprovedRelease

    ): Unit = {

        require(

            release.isValid,

            "Invalid approved release."

        )

        releases += release

    }

    //----------------------------------------------------------
    // Canonical Lookup
    //----------------------------------------------------------

    def loadApprovedRelease(

        releaseId: String,

        artifactDigest: String,

        approvalGeneration: Long

    ): ApprovedRelease = {

        releases.find {

            release =>

                release.releaseId == releaseId &&

                release.artifactDigest == artifactDigest &&

                release.approvalGeneration == approvalGeneration

        }.getOrElse(

            throw new NoSuchElementException(

                s"Approved release not found: $releaseId"

            )

        )

    }

    //----------------------------------------------------------
    // Operational Lookup
    //----------------------------------------------------------

    /**
     * Administrative helper.
     *
     * Intended for dashboards, operational tooling,
     * synchronization, and reporting.
     *
     * This method MUST NOT be used when reconstructing an
     * approval decision because approvalGeneration forms part of
     * the canonical approval identity.
     */
    def latestApprovedRelease(

        releaseId: String

    ): ApprovedRelease = {

        releases

            .filter(

                _.releaseId == releaseId

            )

            .sortBy(

                _.approvalGeneration

            )

            .last

    }

    //----------------------------------------------------------
    // Repository Queries
    //----------------------------------------------------------

    def latestGeneration(

        releaseId: String

    ): Long = {

        releases

            .filter(

                _.releaseId == releaseId

            )

            .map(

                _.approvalGeneration

            )

            .foldLeft(0L)(

                Math.max

            )

    }

    def exists(

        releaseId: String,

        artifactDigest: String

    ): Boolean = {

        releases.exists {

            release =>

                release.releaseId == releaseId &&

                release.artifactDigest == artifactDigest

        }

    }

    def existsGeneration(

        releaseId: String,

        generation: Long

    ): Boolean = {

        releases.exists {

            release =>

                release.releaseId == releaseId &&

                release.approvalGeneration == generation

        }

    }

    //----------------------------------------------------------
    // Repository Views
    //----------------------------------------------------------

    def allApprovedReleases()

        : Seq[ApprovedRelease] = {

        releases.toSeq

    }

    def releasesFor(

        releaseId: String

    ): Seq[ApprovedRelease] = {

        releases

            .filter(

                _.releaseId == releaseId

            )

            .toSeq

    }

    //----------------------------------------------------------
    // Verification
    //----------------------------------------------------------

    def verifyApprovalIdentity(

        release: ApprovedRelease

    ): Boolean = {

        existsGeneration(

            release.releaseId,

            release.approvalGeneration

        ) &&

        exists(

            release.releaseId,

            release.artifactDigest

        )

    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    def repositorySummary()

        : String = {

        s"${releases.size} approved releases stored."

    }

    def generationHistory(

        releaseId: String

    ): Seq[Long] = {

        releases

            .filter(

                _.releaseId == releaseId

            )

            .map(

                _.approvalGeneration

            )

            .sorted

            .toSeq

    }

}
