        return

            releaseId.isNotBlank()

            &&

            artifactDigest.isNotBlank()

            &&

            containerImage.isNotBlank()

            &&

            deploymentPolicy.isNotBlank()

            &&

            publicationSignature.isNotBlank()

    }

