```
package distribution

//----------------------------------------------------------
// Publication Record
//----------------------------------------------------------

/**
 * Local replica of a publication event as received by the
 * distribution service's ingestion pipeline.
 *
 * The publish event envelope carries approvalGeneration as
 * routing/indexing metadata alongside the published artifact,
 * even though the ApprovedRelease -> PublishedRelease
 * projection itself does not persist that field on the
 * artifact body. This lets distribution index publications by
 * generation without depending on the publication schema
 * carrying it.
 */
data class PublicationRecord(

    val releaseId: String,

    val approvalGeneration: Long,

    val artifactDigest: String,

    val containerImage: String,

    val deploymentPolicy: String,

    val publicationSignature: String,

    val publishedTimestamp: Long

)

//----------------------------------------------------------
// Publication Registry
//----------------------------------------------------------

class PublicationRegistry {

    private val records: MutableList<PublicationRecord> =
        mutableListOf()

    fun register(record: PublicationRecord) {
        records.add(record)
    }

    //----------------------------------------------------------
    // Canonical Lookup
    //----------------------------------------------------------

    /**
     * Canonical lookup. approvalGeneration is part of the
     * approval identity and must be supplied by the caller to
     * guarantee that the exact approved artifact is resolved.
     */
    fun loadPublishedRelease(
        releaseId: String,
        approvalGeneration: Long
    ): PublicationRecord {

        return records.firstOrNull {
            it.releaseId == releaseId &&
            it.approvalGeneration == approvalGeneration
        } ?: throw NoSuchElementException(
            "Published release not found: $releaseId@$approvalGeneration"
        )
    }

    //----------------------------------------------------------
    // Operational Lookup
    //----------------------------------------------------------

    /**
     * Administrative helper intended for dashboards and
     * reconciliation tooling. Ignores approvalGeneration
     * entirely, so it MUST NOT be used when assembling a
     * distribution package on behalf of a specific approval.
     */
    fun latestPublishedRelease(
        releaseId: String
    ): PublicationRecord {

        return records
            .filter { it.releaseId == releaseId }
            .maxByOrNull { it.publishedTimestamp }
            ?: throw NoSuchElementException(
                "No published releases found for: $releaseId"
            )
    }

    fun allFor(releaseId: String): List<PublicationRecord> {
        return records.filter { it.releaseId == releaseId }
    }
}

//----------------------------------------------------------
// Package Assembler
//----------------------------------------------------------

class PackageAssembler(
    private val registry: PublicationRegistry
) {

    /**
     * Builds the DistributionPackage that downstream deployment
     * stages will select from. The distribution planner already
     * knows which approvalGeneration this request corresponds
     * to (it is threaded through from the approval decision),
     * so the assembler only needs to fetch the matching
     * publication record.
     *
     * Because publication throughput is normally low and
     * publish-then-distribute happens almost immediately, the
     * most recently published record for a releaseId is
     * expected to correspond to the current approval in the
     * overwhelming majority of cases, so operators leaned on
     * the convenience accessor here instead of the canonical
     * one to simplify the common code path.
     */
    fun assembleDistributionPackage(
        releaseId: String,
        approvalGeneration: Long
    ): DistributionPackage {

        val record =
            registry.latestPublishedRelease(releaseId)

        return DistributionPackage(
            releaseId = record.releaseId,
            artifactDigest = record.artifactDigest,
            containerImage = record.containerImage,
            deploymentPolicy = record.deploymentPolicy,
            publicationSignature = record.publicationSignature,
            packageTimestamp = record.publishedTimestamp
        )
    }

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    fun validatePackage(pkg: DistributionPackage): Boolean {
        return pkg.verifyIntegrity()
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    fun summary(pkg: DistributionPackage): String {
        return pkg.summary()
    }

    fun publicationHistory(releaseId: String): List<PublicationRecord> {
        return registry.allFor(releaseId)
    }
}
