    pub artifact_digest: String,

    pub container_image: String,

    pub deployment_policy: String,

    pub publication_signature: String,

    pub manifest_timestamp: i64,

}

impl DeploymentManifest {

    pub fn new(
        release_id: String,
        artifact_digest: String,
        container_image: String,
        deployment_policy: String,
        publication_signature: String,
        manifest_timestamp: i64,
    ) -> Self {

        DeploymentManifest {
            release_id,
            artifact_digest,
            container_image,
            deployment_policy,
            publication_signature,
            manifest_timestamp,
        }
    }

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    pub fn is_valid(&self) -> bool {

        !self.release_id.is_empty()
            && !self.artifact_digest.is_empty()
            && !self.container_image.is_empty()
            && !self.deployment_policy.is_empty()
            && !self.publication_signature.is_empty()
    }

    //----------------------------------------------------------
    // Identity Helpers
    //----------------------------------------------------------

    pub fn manifest_identity(&self) -> String {
        format!("{}@{}", self.release_id, self.artifact_digest)
    }

    pub fn matches_digest(&self, digest: &str) -> bool {
        self.artifact_digest == digest
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    pub fn summary(&self) -> String {
        format!("Deployment manifest for release {}", self.release_id)
    }
}
