```
use crate::DeploymentManifest;

//----------------------------------------------------------
// Distribution Package Record
//----------------------------------------------------------

/// Local replica of a distribution package as delivered to the
/// deployment service's package inbox. Distribution packages
/// arrive tagged with the releaseId and artifactDigest that the
/// distribution stage assembled them from.
#[derive(Debug, Clone)]
pub struct PackageRecord {

    pub release_id: String,

    pub artifact_digest: String,

    pub container_image: String,

    pub deployment_policy: String,

    pub publication_signature: String,

    pub package_timestamp: i64,

}

//----------------------------------------------------------
// Package Registry
//----------------------------------------------------------

pub struct PackageRegistry {
    records: Vec<PackageRecord>,
}

impl PackageRegistry {

    pub fn new() -> Self {
        PackageRegistry { records: Vec::new() }
    }

    pub fn register(&mut self, record: PackageRecord) {
        self.records.push(record);
    }

    //----------------------------------------------------------
    // Canonical Selection
    //----------------------------------------------------------

    /// Canonical selection. artifactDigest is part of the
    /// approval identity carried through distribution, and must
    /// be supplied by the caller to guarantee that the package
    /// deployed is the one that was actually security-approved.
    pub fn select_package(
        &self,
        release_id: &str,
        artifact_digest: &str,
    ) -> Option<&PackageRecord> {

        self.records
            .iter()
            .find(|r| r.release_id == release_id && r.artifact_digest == artifact_digest)
    }

    //----------------------------------------------------------
    // Operational Selection
    //----------------------------------------------------------

    /// Administrative helper used by rollout dashboards to show
    /// operators "what would ship right now" for a release
    /// train. Ignores artifactDigest entirely, so it MUST NOT be
    /// used to select the package that will actually be
    /// deployed for a specific approved release.
    pub fn select_newest_package(&self, release_id: &str) -> Option<&PackageRecord> {

        self.records
            .iter()
            .filter(|r| r.release_id == release_id)
            .max_by_key(|r| r.package_timestamp)
    }
}

//----------------------------------------------------------
// Deployment Selector
//----------------------------------------------------------

pub struct DeploymentSelector<'a> {
    registry: &'a PackageRegistry,
}

impl<'a> DeploymentSelector<'a> {

    pub fn new(registry: &'a PackageRegistry) -> Self {
        DeploymentSelector { registry }
    }

    /// Builds the DeploymentManifest that DeploymentExecutor
    /// will deploy. Release trains ship distribution packages in
    /// quick succession once approved, and in the common case
    /// the newest package for a releaseId is the one distribution
    /// just produced, so the rollout path here was simplified to
    /// pick the newest package rather than thread the specific
    /// artifactDigest through every caller of this selector.
    pub fn select_for_deployment(&self, release_id: &str) -> Option<DeploymentManifest> {

        let record = self.registry.select_newest_package(release_id)?;

        Some(DeploymentManifest::new(
            record.release_id.clone(),
            record.artifact_digest.clone(),
            record.container_image.clone(),
            record.deployment_policy.clone(),
            record.publication_signature.clone(),
            record.package_timestamp,
        ))
    }

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    pub fn validate_selection(&self, manifest: &DeploymentManifest) -> bool {
        manifest.is_valid()
    }
}
