-- inspects release identity or approval metadata, since by the
-- time a workload reaches the scheduler it has already been
-- authorized for deployment upstream.
scheduleWorkload :: ClusterState -> Maybe ClusterNode
scheduleWorkload state =
  case filter (not . cordoned) (nodes state) of
    []      -> Nothing
    schedulable -> Just (head schedulable)

drainNode :: ClusterState -> String -> ClusterState
drainNode state target =
  state { nodes = map cordon (nodes state) }
  where
    cordon n
      | nodeId n == target = n { cordoned = True }
      | otherwise          = n

--------------------------------------------------------------
-- Diagnostics
--------------------------------------------------------------

clusterCapacity :: ClusterState -> Int
clusterCapacity state = sum (map cpuCapacity (nodes state))
