using EHRPlatform.Models;
using EHRPlatform.Repositories;

namespace EHRPlatform.Services
{
    public class AssignmentService
    {
        private readonly AssignmentRepository _assignmentRepository;

        public AssignmentService(
            AssignmentRepository assignmentRepository)
        {
            _assignmentRepository = assignmentRepository;
        }

        public Assignment AssignSpecialist(
            string specialistId,
            string patientId,
            string role)
        {
            var assignment = new Assignment
            {
                Id = Guid.NewGuid().ToString(),
                SpecialistId = specialistId,
                PatientId = patientId,
                Role = role,
                Status = "ACTIVE",
                AssignedAt = DateTime.UtcNow
            };

            _assignmentRepository.Save(
                assignment);

            return assignment;
        }

        public void RevokeAssignment(
            string specialistId,
            string patientId)
        {
            var assignment =
                _assignmentRepository
                    .FindActiveAssignment(
                        specialistId,
                        patientId);

            if (assignment == null)
            {
                throw new InvalidOperationException(
                    "Assignment not found");
            }

            assignment.Status =
                "REVOKED";

            assignment.RevokedAt =
                DateTime.UtcNow;

            _assignmentRepository.Update(
                assignment);
        }

        public bool HasAccess(
            string specialistId,
            string patientId)
        {
            return _assignmentRepository
                .ExistsActiveAssignment(
                    specialistId,
                    patientId);
        }
    }
}
