using EHRPlatform.Models;

namespace EHRPlatform.Repositories
{
    public class AssignmentRepository
    {
        private readonly Database _database;

        public AssignmentRepository(
            Database database)
        {
            _database = database;
        }

        public void Save(
            Assignment assignment)
        {
            _database.Execute(
                @"
                INSERT INTO assignments
                (
                    id,
                    specialist_id,
                    patient_id,
                    role,
                    status,
                    assigned_at
                )
                VALUES
                (
                    @Id,
                    @SpecialistId,
                    @PatientId,
                    @Role,
                    @Status,
                    @AssignedAt
                )",
                assignment);
        }

        public Assignment FindActiveAssignment(
            string specialistId,
            string patientId)
        {
            return _database.QuerySingle<Assignment>(
                @"
                SELECT *
                FROM assignments
                WHERE specialist_id = @specialistId
                  AND patient_id = @patientId
                  AND status = 'ACTIVE'
                ",
                new
                {
                    specialistId,
                    patientId
                });
        }

        public bool ExistsActiveAssignment(
            string specialistId,
            string patientId)
        {
            return _database.Exists(
                @"
                SELECT 1
                FROM assignments
                WHERE specialist_id = @specialistId
                  AND patient_id = @patientId
                  AND status = 'ACTIVE'
                ",
                new
                {
                    specialistId,
                    patientId
                });
        }

        public List<Assignment> ActiveAssignmentsForSpecialist(
            string specialistId)
        {
            return _database.Query<Assignment>(
                @"
                SELECT *
                FROM assignments
                WHERE specialist_id = @specialistId
                  AND status = 'ACTIVE'
                ",
                new
                {
                    specialistId
                });
        }
    }
}
