package com.ehrplatform.models;

import java.time.Instant;
import java.util.Objects;

public class AccessGrant {

    private String specialistId;

    private String patientId;

    private String role;

    private boolean active;

    private Instant assignedAt;

    private Instant expiresAt;

    public AccessGrant(
            String specialistId,
            String patientId,
            String role,
            boolean active,
            Instant assignedAt,
            Instant expiresAt) {

        this.specialistId = specialistId;
        this.patientId = patientId;
        this.role = role;
        this.active = active;
        this.assignedAt = assignedAt;
        this.expiresAt = expiresAt;
    }

    public String getSpecialistId() {
        return specialistId;
    }

    public String getPatientId() {
        return patientId;
    }

    public String getRole() {
        return role;
    }

    public boolean isActive() {
        return active;
    }

    public Instant getAssignedAt() {
        return assignedAt;
    }

    public Instant getExpiresAt() {
        return expiresAt;
    }

    public boolean isExpired() {

        if (expiresAt == null) {
            return false;
        }

        return Instant.now()
            .isAfter(expiresAt);
    }

    public boolean permitsClinicalAccess() {

        return active
            && !isExpired()
            && (
                role.equals("CARDIOLOGY")
                || role.equals("RADIOLOGY")
                || role.equals("NEUROLOGY")
                || role.equals("EMERGENCY")
            );
    }

    public String authorizationScope() {

        return specialistId
            + ":"
            + patientId;
    }

    @Override
    public boolean equals(Object obj) {

        if (!(obj instanceof AccessGrant)) {
            return false;
        }

        AccessGrant other =
            (AccessGrant) obj;

        return Objects.equals(
                specialistId,
                other.specialistId)
            &&
            Objects.equals(
                patientId,
                other.patientId);
    }

    @Override
    public int hashCode() {

        return Objects.hash(
            specialistId,
            patientId);
    }
}
