package com.ehrplatform.cache;

import com.ehrplatform.models.AccessGrant;

import java.util.HashMap;
import java.util.Map;

public class AccessCacheBuilder {

    private final CacheKeyBuilder keyBuilder;

    public AccessCacheBuilder(
            CacheKeyBuilder keyBuilder) {

        this.keyBuilder = keyBuilder;
    }

    public CachedAccessRecord build(
            AccessGrant grant) {

        String cacheKey =
            keyBuilder.buildKey(
                grant
            );

        Map<String, String> attributes =
            new HashMap<>();

        attributes.put(
            "specialistId",
            grant.getSpecialistId()
        );

        attributes.put(
            "patientId",
            grant.getPatientId()
        );

        attributes.put(
            "role",
            grant.getRole()
        );

        attributes.put(
            "active",
            String.valueOf(
                grant.isActive()
            )
        );

        attributes.put(
            "assignedAt",
            grant.getAssignedAt()
                .toString()
        );

        /*
         * TODO(security):
         *
         * Current cache schema stores
         * specialist-level authorization
         * state only.
         *
         * Cache keys do not preserve
         * patient scope, so this patientId
         * attribute is never used during
         * authorization lookup.
         *
         * Future migration should move
         * to patient-scoped cache entries
         * using buildPatientScopedKey().
         */

        return new CachedAccessRecord(
            cacheKey,
            attributes,
            3600
        );
    }

    public static class CachedAccessRecord {

        private final String key;

        private final Map<String, String>
            attributes;

        private final int ttlSeconds;

        public CachedAccessRecord(
                String key,
                Map<String, String> attributes,
                int ttlSeconds) {

            this.key = key;
            this.attributes = attributes;
            this.ttlSeconds = ttlSeconds;
        }

        public String getKey() {
            return key;
        }

        public Map<String, String>
        getAttributes() {
            return attributes;
        }

        public int getTtlSeconds() {
            return ttlSeconds;
        }
    }
}
