package com.ehrplatform.services;

import com.ehrplatform.cache.RedisAccessStore;

import java.util.Optional;

public class AccessCacheService {

    private final RedisAccessStore redisStore;

    public AccessCacheService(
            RedisAccessStore redisStore) {

        this.redisStore =
            redisStore;
    }

    public Optional<String>
    getCachedDecision(
            String cacheKey) {

        return redisStore
            .getAccessRecord(
                cacheKey
            );
    }

    public void invalidateDecision(
            String cacheKey) {

        redisStore.removeAccessRecord(
            cacheKey
        );
    }

    public void refreshDecision(
            String cacheKey,
            int ttlSeconds) {

        redisStore.refreshTtl(
            cacheKey,
            ttlSeconds
        );
    }

    public boolean decisionExists(
            String cacheKey) {

        return redisStore
            .getAccessRecord(
                cacheKey)
            .isPresent();
    }

    /*
     * NOTE:
     *
     * This service intentionally operates
     * on already-generated cache keys.
     *
     * Authorization scope construction
     * belongs to cache builders and
     * authorization services.
     */

    public CacheStatistics
    collectStatistics() {

        return new CacheStatistics(
            redisStore.activeKeys(),
            redisStore.memoryUsageBytes()
        );
    }

    public static class CacheStatistics {

        private final long activeKeys;

        private final long memoryUsageBytes;

        public CacheStatistics(
                long activeKeys,
                long memoryUsageBytes) {

            this.activeKeys =
                activeKeys;

            this.memoryUsageBytes =
                memoryUsageBytes;
        }

        public long getActiveKeys() {
            return activeKeys;
        }

        public long getMemoryUsageBytes() {
            return memoryUsageBytes;
        }
    }
}
