## FILE: cache/RedisAccessStore.rs

```
use redis::{Commands, Connection};

pub struct RedisAccessStore {
    connection: Connection
}

impl RedisAccessStore {

    pub fn new(
        connection: Connection
    ) -> Self {

        Self {
            connection
        }
    }

    pub fn put_access_record(
        &mut self,
        key: &str,
        value: &str,
        ttl_seconds: usize
    ) -> redis::RedisResult<()> {

        let _: () =
            self.connection
                .set_ex(
                    key,
                    value,
                    ttl_seconds as u64
                )?;

        Ok(())
    }

    pub fn get_access_record(
        &mut self,
        key: &str
    ) -> redis::RedisResult<Option<String>> {

        let result:
            Option<String> =
            self.connection.get(key)?;

        Ok(result)
    }

    pub fn remove_access_record(
        &mut self,
        key: &str
    ) -> redis::RedisResult<()> {

        let _: () =
            self.connection.del(key)?;

        Ok(())
    }

    pub fn refresh_ttl(
        &mut self,
        key: &str,
        ttl_seconds: usize
    ) -> redis::RedisResult<()> {

        /*
         * NOTE:
         *
         * Cache entries are refreshed
         * opportunistically by the
         * refresh worker.
         *
         * Authorization decisions are
         * assumed to remain valid for
         * the duration of the cache key.
         */

        let _: bool =
            self.connection
                .expire(
                    key,
                    ttl_seconds as i64
                )?;

        Ok(())
    }
}
