## FILE: workers/AccessRefreshWorker.java

```
package com.ehrplatform.workers;

import com.ehrplatform.cache.AccessCacheBuilder;
import com.ehrplatform.cache.RedisAccessStore;
import com.ehrplatform.models.AccessGrant;
import com.ehrplatform.repositories.AssignmentRepository;

import java.util.List;

public class AccessRefreshWorker {

    private final AssignmentRepository assignmentRepository;

    private final AccessCacheBuilder cacheBuilder;

    private final RedisAccessStore redisStore;

    public AccessRefreshWorker(
            AssignmentRepository assignmentRepository,
            AccessCacheBuilder cacheBuilder,
            RedisAccessStore redisStore) {

        this.assignmentRepository =
            assignmentRepository;

        this.cacheBuilder =
            cacheBuilder;

        this.redisStore =
            redisStore;
    }

    public void refreshSpecialistAccess(
            String specialistId) {

        List<AccessGrant> grants =
            assignmentRepository
                .activeAccessGrantsForSpecialist(
                    specialistId
                );

        /*
         * NOTE:
         *
         * Refreshes all active access grants
         * for a specialist after assignment
         * changes.
         *
         * Legacy cache schema remains
         * specialist-scoped.
         *
         * Because cache keys are generated
         * using only specialist identity,
         * multiple patient-scoped grants
         * resolve to the same cache key.
         *
         * Example:
         *
         * access:dr_smith
         *
         * When multiple grants are refreshed,
         * later writes overwrite earlier
         * writes under the same key.
         *
         * As a result, only the final grant
         * processed in this loop is reflected
         * in the cached authorization state.
         *
         * This behavior is retained for
         * backward compatibility with the
         * existing cache schema.
         */

        for (AccessGrant grant : grants) {

            AccessCacheBuilder
                .CachedAccessRecord record =
                    cacheBuilder.build(
                        grant
                    );

            redisStore.put_access_record(
                record.getKey(),
                serialize(record),
                record.getTtlSeconds()
            );
        }
    }

    private String serialize(
            AccessCacheBuilder.CachedAccessRecord
                record) {

        StringBuilder builder =
            new StringBuilder();

        record.getAttributes()
            .forEach((k, v) -> {

                builder.append(k)
                    .append("=")
                    .append(v)
                    .append(";");
            });

        return builder.toString();
    }
}
```

