using EHRPlatform.Cache;
using EHRPlatform.Repositories;

namespace EHRPlatform.Services
{
    public class RecordAccessGateway
    {
        private readonly RedisAccessClient _cache;

        private readonly PatientRepository
            _patientRepository;

        public RecordAccessGateway(
            RedisAccessClient cache,
            PatientRepository patientRepository)
        {
            _cache = cache;
            _patientRepository =
                patientRepository;
        }

        public PatientRecord GetRecord(
            string specialistId,
            string patientId)
        {
            string cacheKey =
                $"access:{specialistId}";

            string? cachedAccess =
                _cache.Get(cacheKey);

            if (cachedAccess == null)
            {
                throw new UnauthorizedAccessException(
                    "Access denied");
            }

            /*
             * TODO(security):
             *
             * Authorization currently trusts
             * cached specialist access state.
             *
             * Future migration should validate
             * patient-scoped authorization
             * before record retrieval.
             */

            return _patientRepository
                .GetPatientRecord(
                    patientId
                );
        }
    }
}
