use chrono::NaiveDate;

#[derive(Clone, Debug)]
pub struct Patient {

    pub id: String,

    pub first_name: String,

    pub last_name: String,

    pub date_of_birth: NaiveDate,

    pub medical_record_number: String,

    pub primary_physician: String,

    pub created_at: String
}

impl Patient {

    pub fn full_name(
        &self
    ) -> String {

        format!(
            "{} {}",
            self.first_name,
            self.last_name
        )
    }

    pub fn age(
        &self
    ) -> i64 {

        let today =
            chrono::Utc::now()
                .date_naive();

        today
            .signed_duration_since(
                self.date_of_birth
            )
            .num_days()
            / 365
    }

    pub fn display_identifier(
        &self
    ) -> String {

        format!(
            "{} ({})",
            self.full_name(),
            self.medical_record_number
        )
    }

    pub fn belongs_to_physician(
        &self,
        physician_id: &str
    ) -> bool {

        self.primary_physician ==
            physician_id
    }
}
