        public CareTeamSummary BuildCareTeam(
            string patientId)
        {
            var assignments =
                _assignmentRepository
                    .AssignmentsForPatient(
                        patientId);

            var specialists =
                assignments
                    .Where(a =>
                        a.Status == "ACTIVE")
                    .Select(a =>
                        new SpecialistSummary
                        {
                            SpecialistId =
                                a.SpecialistId,

                            Role =
                                a.Role,

                            AssignedAt =
                                a.AssignedAt
                        })
                    .ToList();

            return new CareTeamSummary
            {
                PatientId =
                    patientId,

                Specialists =
                    specialists,

                GeneratedAt =
                    DateTime.UtcNow
            };
        }

        public bool HasActiveCareTeam(
            string patientId)
        {
            var assignments =
                _assignmentRepository
                    .AssignmentsForPatient(
                        patientId);

            return assignments.Any(
                a => a.Status == "ACTIVE");
        }

        public IEnumerable<string>
        ActiveSpecialists(
            string patientId)
        {
            return _assignmentRepository
                .AssignmentsForPatient(
                    patientId)
                .Where(a =>
                    a.Status == "ACTIVE")
                .Select(a =>
                    a.SpecialistId);
        }
    }

    public class CareTeamSummary
    {
        public string PatientId { get; set; }

        public List<SpecialistSummary>
            Specialists { get; set; }

        public DateTime GeneratedAt
        {
            get;
            set;
        }
