package snapshot

import repository.KnowledgeDocument

class SnapshotBuilder {

  def build(
      document: KnowledgeDocument
  ): PublishedSnapshot = {

    val validatedDocument =
      validateDocument(document)

    val normalizedLabels =
      normalizeSecurityLabels(
        validatedDocument
      )

    val normalizedDepartment =
      normalizeDepartment(
        validatedDocument
      )

    val normalizedTitle =
      normalizeTitle(
        validatedDocument
      )

    val normalizedBody =
      normalizeBody(
        validatedDocument
      )

    val validatedPolicyVersion =
      validatePolicyVersion(
        validatedDocument
      )

    PublishedSnapshot(

      documentId =
        validatedDocument.documentId(),

      securityLabels =
        normalizedLabels,

      department =
        normalizedDepartment,

      title =
        normalizedTitle,

      body =
        normalizedBody,

      publishedAt =
        currentPublicationTime()
    )
  }

  private def validateDocument(
      document: KnowledgeDocument
  ): KnowledgeDocument = {

    require(
      document.documentId().nonEmpty,
      "Document identifier is required."
    )

    require(
      document.title().nonEmpty,
      "Document title is required."
    )

    require(
      document.body().nonEmpty,
      "Document body is required."
    )

    require(
      document.department().nonEmpty,
      "Department is required."
    )

    validatePolicyVersion(
      document
    )

    document
  }

  private def validatePolicyVersion(
      document: KnowledgeDocument
  ): Long = {

    val version =
      document.policyVersion()

    require(
      version > 0,
      "Invalid policy version."
    )

    version
  }

  private def normalizeSecurityLabels(
      document: KnowledgeDocument
  ): Seq[String] = {

    document
      .securityLabels()
      .toSeq
      .map(_.trim)
      .filter(_.nonEmpty)
      .distinct
      .sorted
  }

  private def normalizeDepartment(
      document: KnowledgeDocument
  ): String = {

    document
      .department()
      .trim
      .toUpperCase
  }

  private def normalizeTitle(
      document: KnowledgeDocument
  ): String = {

    document
      .title()
      .trim
  }

  private def normalizeBody(
      document: KnowledgeDocument
  ): String = {

    document
      .body()
      .trim
  }
    private def currentPublicationTime(): Long = {

    System.currentTimeMillis()
  }

  def supports(
      document: KnowledgeDocument
  ): Boolean = {

    document.isSearchable()
  }

  def canPublish(
      document: KnowledgeDocument
  ): Boolean = {

    validatePolicyVersion(
      document
    )

    supports(
      document
    )
  }

  def snapshotIdentity(
      document: KnowledgeDocument
  ): String = {

    document.documentId()
  }

  def preview(
      document: KnowledgeDocument
  ): PublishedSnapshot = {

    build(
      document
    )
  }

  def builderName(): String = {

    "SnapshotBuilder"
  }

  def builderVersion(): String = {

    "1.0"
  }

  def health(): Boolean = {

    true
  }
}
