package snapshot

case class PublishedSnapshot(

    documentId: String,

    securityLabels: Seq[String],

    department: String,

    title: String,

    body: String,

    publishedAt: Long
) {

  def snapshotId(): String = {

    documentId
  }

  def searchableText(): String = {

    Seq(
      title,
      body
    ).mkString(" ")
  }

  def belongsTo(
      value: String
  ): Boolean = {

    department == value
  }

  def hasLabel(
      label: String
  ): Boolean = {

    securityLabels.contains(label)
  }

  def publicationAge(
      now: Long
  ): Long = {

    now - publishedAt
  }

  def summary(): String = {

    s"$title [$department]"
  }

  def nonEmpty(): Boolean = {

    documentId.nonEmpty &&
    title.nonEmpty &&
    body.nonEmpty
  }

  def searchIdentity(): String = {

    documentId
  }
}
