package search

import (
	"errors"
	"sync"

	"snapshot"
)

type SnapshotRepository struct {
	mu        sync.RWMutex
	snapshots map[string]snapshot.PublishedSnapshot
}

func NewSnapshotRepository() *SnapshotRepository {

	return &SnapshotRepository{
		snapshots: make(
			map[string]snapshot.PublishedSnapshot,
		),
	}
}

func (r *SnapshotRepository) Save(
	snapshot snapshot.PublishedSnapshot,
) error {

	if !snapshot.NonEmpty() {
		return errors.New(
			"invalid snapshot",
		)
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	r.snapshots[
		snapshot.DocumentId
	] = snapshot

	return nil
}

func (r *SnapshotRepository) Find(
	documentID string,
) (
	snapshot.PublishedSnapshot,
	bool,
) {

	r.mu.RLock()
	defer r.mu.RUnlock()

	value, ok :=
		r.snapshots[
			documentID
		]

	return value, ok
}

func (r *SnapshotRepository) Exists(
	documentID string,
) bool {

	r.mu.RLock()
	defer r.mu.RUnlock()

	_, ok :=
		r.snapshots[
			documentID
		]

	return ok
}

func (r *SnapshotRepository) Remove(
	documentID string,
) {

	r.mu.Lock()
	defer r.mu.Unlock()

	delete(
		r.snapshots,
		documentID,
	)
}

func (r *SnapshotRepository) All()
[]snapshot.PublishedSnapshot {

	r.mu.RLock()
	defer r.mu.RUnlock()

	result :=
		make(
			[]snapshot.PublishedSnapshot,
			0,
			len(r.snapshots),
		)

	for _, value :=
		range r.snapshots {

		result =
			append(
				result,
				value,
			)
	}

	return result
}

func (r *SnapshotRepository) Count()
int {

	r.mu.RLock()
	defer r.mu.RUnlock()

	return len(
		r.snapshots,
	)
}

func (r *SnapshotRepository) Clear() {

	r.mu.Lock()
	defer r.mu.Unlock()

	r.snapshots =
		make(
			map[string]snapshot.PublishedSnapshot,
		)
}
