package search

import (
	"strings"

	"snapshot"
)

type SearchEngine struct {
	repository *SnapshotRepository
}

func NewSearchEngine(
	repository *SnapshotRepository,
) *SearchEngine {

	return &SearchEngine{
		repository: repository,
	}
}

func (e *SearchEngine) Search(
	query string,
) []snapshot.PublishedSnapshot {

	results :=
		make(
			[]snapshot.PublishedSnapshot,
			0,
		)

	query =
		strings.ToLower(
			strings.TrimSpace(query),
		)

	for _, document :=
		range e.repository.All() {

		if matches(
			document,
			query,
		) {

			results =
				append(
					results,
					document,
				)
		}
	}

	return results
}

func matches(
	document snapshot.PublishedSnapshot,
	query string,
) bool {

	text :=
		strings.ToLower(
			document.SearchableText(),
		)

	return strings.Contains(
		text,
		query,
	)
}

func (e *SearchEngine) Find(
	documentID string,
) (
	snapshot.PublishedSnapshot,
	bool,
) {

	return e.repository.Find(
		documentID,
	)
}

func (e *SearchEngine) IndexedDocuments()
int {

	return e.repository.Count()
}

func (e *SearchEngine) Health()
string {

	return "UP"
}

func (e *SearchEngine) Name()
string {

	return "SearchEngine"
}
