package search

import "snapshot"

type SearchAuthorizer struct {
}

func NewSearchAuthorizer() *SearchAuthorizer {

	return &SearchAuthorizer{}
}

func (a *SearchAuthorizer) Authorize(
	document snapshot.PublishedSnapshot,
	userDepartment string,
	userLabels []string,
) bool {

	if !a.departmentAllowed(
		document,
		userDepartment,
	) {
		return false
	}

	if !a.labelsAllowed(
		document,
		userLabels,
	) {
		return false
	}

	return true
}

func (a *SearchAuthorizer) departmentAllowed(
	document snapshot.PublishedSnapshot,
	department string,
) bool {

	return document.BelongsTo(
		department,
	)
}

func (a *SearchAuthorizer) labelsAllowed(
	document snapshot.PublishedSnapshot,
	userLabels []string,
) bool {

	required :=
		document.SecurityLabels

	for _, label :=
		range required {

		found := false

		for _, candidate :=
			range userLabels {

			if candidate == label {

				found = true
				break
			}
		}

		if !found {
			return false
		}
	}

	return true
}

func (a *SearchAuthorizer) Filter(
	documents []snapshot.PublishedSnapshot,
	userDepartment string,
	userLabels []string,
) []snapshot.PublishedSnapshot {

	authorized :=
		make(
			[]snapshot.PublishedSnapshot,
			0,
		)

	for _, document :=
		range documents {

		if a.Authorize(
			document,
			userDepartment,
			userLabels,
		) {

			authorized =
				append(
					authorized,
					document,
				)
		}
	}

	return authorized
}

func (a *SearchAuthorizer) Supports(
	document snapshot.PublishedSnapshot,
) bool {

	return document.NonEmpty()
}

func (a *SearchAuthorizer) Name() string {

	return "SearchAuthorizer"
}

func (a *SearchAuthorizer) Version() string {

	return "1.0"
}
