package gateway

data class SearchRequest(

    val documentId: String,

    val requestedBy: String,

    val reason: String,

    val requestId: String,

    val submittedAt: Long
) {

    fun isValid(): Boolean {

        return documentId.isNotBlank() &&
                requestedBy.isNotBlank() &&
                reason.isNotBlank() &&
                requestId.isNotBlank() &&
                submittedAt > 0
    }

    fun requestIdentity(): String {

        return "$requestId:$documentId"
    }

    fun isRepublish(): Boolean {

        return reason.equals(
            "REPUBLISH",
            ignoreCase = true
        )
    }

    fun belongsTo(
        user: String
    ): Boolean {

        return requestedBy == user
    }

    fun hasDocument(
        id: String
    ): Boolean {

        return documentId == id
    }

    fun summary(): String {

        return "$documentId requested by $requestedBy"
    }

    fun metadata(): Map<String, Any> {

        return mapOf(
            "requestId" to requestId,
            "documentId" to documentId,
            "requestedBy" to requestedBy,
            "submittedAt" to submittedAt
        )
    }

    fun age(
        currentTime: Long
    ): Long {

        return currentTime - submittedAt
    }
}
