package snapshot

import repository.KnowledgeDocument

class SnapshotPublisher(
    builder: SnapshotBuilder
) {

  def publish(
      document: KnowledgeDocument
  ): PublishedSnapshot = {

    val snapshot =
      builder.build(
        document
      )

    validateSnapshot(
      snapshot
    )

    snapshot
  }

  def publishBatch(
      documents: Seq[KnowledgeDocument]
  ): Seq[PublishedSnapshot] = {

    documents.map(
      publish
    )
  }

  private def validateSnapshot(
      snapshot: PublishedSnapshot
  ): Unit = {

    require(
      snapshot.documentId.nonEmpty,
      "Document identifier missing."
    )

    require(
      snapshot.title.nonEmpty,
      "Document title missing."
    )

    require(
      snapshot.body.nonEmpty,
      "Document body missing."
    )

    require(
      snapshot.department.nonEmpty,
      "Department missing."
    )

    require(
      snapshot.securityLabels.nonEmpty,
      "Security labels missing."
    )
  }

  def supports(
      document: KnowledgeDocument
  ): Boolean = {

    builder.supports(
      document
    )
  }

  def republish(
      document: KnowledgeDocument
  ): PublishedSnapshot = {

    publish(
      document
    )
  }

  def publisherName(): String = {

    "SnapshotPublisher"
  }

  def publisherVersion(): String = {

    "1.0"
  }

  def health(): Boolean = {

    true
  }
}
