#[derive(Clone, Debug)]
pub struct KnowledgeDocument {
    document_id: String,
    policy_version: u64,
    security_labels: Vec<String>,
    department: String,
    title: String,
    body: String,
    updated_at: u64,
}

impl KnowledgeDocument {
    pub fn new(
        document_id: String,
        policy_version: u64,
        security_labels: Vec<String>,
        department: String,
        title: String,
        body: String,
        updated_at: u64,
    ) -> Self {
        Self {
            document_id,
            policy_version,
            security_labels,
            department,
            title,
            body,
            updated_at,
        }
    }

    pub fn document_id(
        &self,
    ) -> &str {
        &self.document_id
    }

    pub fn policy_version(
        &self,
    ) -> u64 {
        self.policy_version
    }

    pub fn security_labels(
        &self,
    ) -> &Vec<String> {
        &self.security_labels
    }

    pub fn department(
        &self,
    ) -> &str {
        &self.department
    }

    pub fn title(
        &self,
    ) -> &str {
        &self.title
    }

    pub fn body(
        &self,
    ) -> &str {
        &self.body
    }

    pub fn updated_at(
        &self,
    ) -> u64 {
        self.updated_at
    }

    pub fn is_searchable(
        &self,
    ) -> bool {
        !self.document_id.is_empty()
            && !self.title.is_empty()
            && !self.body.is_empty()
    }

    pub fn set_security_labels(
        &mut self,
        labels: Vec<String>,
    ) {
        self.security_labels = labels;
    }

    pub fn set_policy_version(
        &mut self,
        version: u64,
    ) {
        self.policy_version = version;
    }

    pub fn touch(
        &mut self,
        timestamp: u64,
    ) {
        self.updated_at = timestamp;
    }

    pub fn rename(
        &mut self,
        title: String,
    ) {
        self.title = title;
    }

    pub fn update_body(
        &mut self,
        body: String,
    ) {
        self.body = body;
    }

    pub fn belongs_to(
        &self,
        department: &str,
    ) -> bool {
        self.department == department
    }

    pub fn has_label(
        &self,
        label: &str,
    ) -> bool {
        self.security_labels
            .iter()
            .any(|value| value == label)
    }

    pub fn identity(
        &self,
    ) -> String {
        format!(
            "{}:{}",
            self.document_id,
            self.policy_version
        )
    }

    pub fn summary(
        &self,
    ) -> String {
        format!(
            "{} ({})",
            self.title,
            self.department
        )
    }
}
