package gateway

import repository.KnowledgeDocument
import repository.DocumentRepository
import snapshot.SnapshotPublisher

data class SearchApi(
    private val repository: DocumentRepository,
    private val publisher: SnapshotPublisher
) {

    fun publishDocument(
        request: SearchRequest
    ): Boolean {

        validateRequest(request)

        val document =
            repository.findDocument(
                request.documentId
            ) ?: throw IllegalArgumentException(
                "Document not found."
            )

        if (!document.isSearchable()) {
            throw IllegalStateException(
                "Document is not eligible for publication."
            )
        }

        publisher.publish(document)

        return true
    }

    fun republishDocument(
        documentId: String
    ): Boolean {

        val document =
            repository.findDocument(
                documentId
            ) ?: throw IllegalArgumentException(
                "Document not found."
            )

        publisher.publish(document)

        return true
    }

    fun publishBatch(
        requests: List<SearchRequest>
    ): Int {

        var published = 0

        for (request in requests) {

            if (publishDocument(request)) {
                published++
            }
        }

        return published
    }

    fun validateRequest(
        request: SearchRequest
    ) {

        require(
            request.documentId.isNotBlank()
        ) {
            "Missing document identifier."
        }

        require(
            request.requestedBy.isNotBlank()
        ) {
            "Missing requester."
        }

        require(
            request.reason.isNotBlank()
        ) {
            "Missing publication reason."
        }
    }

    fun preview(
        documentId: String
    ): KnowledgeDocument? {

        return repository.findDocument(
            documentId
        )
    }

    fun documentExists(
        documentId: String
    ): Boolean {

        return repository.exists(
            documentId
        )
    }

    fun publicationCount(): Int {

        return repository.totalDocuments()
    }

    fun health(): String {

        return "UP"
    }
}
