use std::collections::HashMap;

use crate::repository::KnowledgeDocument;

pub struct DocumentRepository {
    documents: HashMap<String, KnowledgeDocument>,
}

impl DocumentRepository {
    pub fn new() -> Self {
        Self {
            documents: HashMap::new(),
        }
    }

    pub fn save_document(
        &mut self,
        document: KnowledgeDocument,
    ) {
        self.documents.insert(
            document.document_id().to_string(),
            document,
        );
    }

    pub fn find_document(
        &self,
        document_id: &str,
    ) -> Option<KnowledgeDocument> {
        self.documents
            .get(document_id)
            .cloned()
    }

    pub fn exists(
        &self,
        document_id: &str,
    ) -> bool {
        self.documents.contains_key(
            document_id,
        )
    }

    pub fn remove_document(
        &mut self,
        document_id: &str,
    ) -> Option<KnowledgeDocument> {
        self.documents.remove(
            document_id,
        )
    }

    pub fn all_documents(
        &self,
    ) -> Vec<KnowledgeDocument> {
        self.documents
            .values()
            .cloned()
            .collect()
    }

    pub fn searchable_documents(
        &self,
    ) -> Vec<KnowledgeDocument> {
        self.documents
            .values()
            .filter(|document| {
                document.is_searchable()
            })
            .cloned()
            .collect()
    }

    pub fn documents_for_department(
        &self,
        department: &str,
    ) -> Vec<KnowledgeDocument> {
        self.documents
            .values()
            .filter(|document| {
                document.department()
                    == department
            })
            .cloned()
            .collect()
    }

    pub fn total_documents(
        &self,
    ) -> usize {
        self.documents.len()
    }

    pub fn clear(
        &mut self,
    ) {
        self.documents.clear();
    }

    pub fn replace_document(
        &mut self,
        document: KnowledgeDocument,
    ) {
        self.documents.insert(
            document.document_id().to_string(),
            document,
        );
    }

    pub fn latest_document(
        &self,
        document_id: &str,
    ) -> Option<KnowledgeDocument> {
        self.find_document(
            document_id,
        )
    }

    pub fn update_security_labels(
        &mut self,
        document_id: &str,
        labels: Vec<String>,
    ) -> bool {
        if let Some(document) =
            self.documents.get_mut(document_id)
        {
            document.set_security_labels(
                labels,
            );

            return true;
        }

        false
    }

    pub fn update_policy_version(
        &mut self,
        document_id: &str,
        policy_version: u64,
    ) -> bool {
        if let Some(document) =
            self.documents.get_mut(document_id)
        {
            document.set_policy_version(
                policy_version,
            );

            return true;
        }

        false
    }
}
