namespace Catalog

open System
open System.Collections.Generic

type StudyCatalog
(
    archive : ImageArchive,
    partitionRegistry : PartitionRegistry
) =

    //------------------------------------------------------------------

    member _.ResolveStudy
    (
        studyInstanceUid : string
    ) : CatalogStudy =

        if String.IsNullOrWhiteSpace(studyInstanceUid) then
            invalidArg "studyInstanceUid" "Study UID required."

        let study =
            archive.LoadStudy(studyInstanceUid)

        partitionRegistry.ValidatePartition(
            study.HospitalPartitionId
        )

        _.ValidateStudy(study)

        study

    //------------------------------------------------------------------

    member _.BuildCatalogEntry
    (
        study : CatalogStudy
    ) : CatalogEntry =

        _.ValidateStudy(study)

        CatalogEntry(

            studyInstanceUid = study.StudyInstanceUid,

            accessionNumber = study.AccessionNumber,

            patientId = study.PatientId,

            modality = study.Modality,

            hospitalPartitionId = study.HospitalPartitionId,

            studyDate = study.StudyDate,

            seriesCount = study.SeriesCount,

            imageCount = study.ImageCount,

            visibility = study.Visibility,

            version = study.Version

        )

    //------------------------------------------------------------------

    member _.Exists
    (
        studyInstanceUid : string
    ) : bool =

        archive.Exists(studyInstanceUid)

    //------------------------------------------------------------------

    member private _.ValidateStudy
    (
        study : CatalogStudy
    ) =

        if String.IsNullOrWhiteSpace(study.StudyInstanceUid) then
            raise (InvalidOperationException("Study identifier missing."))

        if String.IsNullOrWhiteSpace(study.HospitalPartitionId) then
            raise (InvalidOperationException("Hospital partition missing."))

        if study.SeriesCount <= 0 then
            raise (InvalidOperationException("Invalid series count."))

        if study.ImageCount <= 0 then
            raise (InvalidOperationException("Invalid image count."))

        if String.IsNullOrWhiteSpace(study.Visibility) then
            raise (InvalidOperationException("Visibility metadata missing."))

        ()
