const std = @import("std");

/// ------------------------------------------------------------------
/// Canonical projection context used while transforming a catalog
/// study into a search-ready representation.
///
/// This object intentionally preserves every security-relevant
/// attribute extracted from the study catalog.
/// ------------------------------------------------------------------
pub const ProjectionContext = struct {

    study_instance_uid: []const u8,

    accession_number: []const u8,

    patient_id: []const u8,

    modality: []const u8,

    hospital_partition_id: []const u8,

    visibility: []const u8,

    study_date: i64,

    series_count: u32,

    image_count: u32,

    version: u32,

};

/// ------------------------------------------------------------------

pub const StudyProjectionBuilder = struct {

    allocator: std.mem.Allocator,

    pub fn init(

        allocator: std.mem.Allocator,

    ) StudyProjectionBuilder {

        return .{

            .allocator = allocator,

        };

    }

    //----------------------------------------------------------------

    pub fn buildProjection(

        self: *StudyProjectionBuilder,

        study: CatalogStudy,

    ) !ProjectionContext {

        try self.validateInput(

            study,

        );

        var context =

            try self.buildContext(

                study,

            );

        try self.normalize(

            &context,

        );

        try self.validateProjection(

            context,

        );

        return context;

    }

    //----------------------------------------------------------------

    fn validateInput(

        self: *StudyProjectionBuilder,

        study: CatalogStudy,

    ) !void {

        _ = self;

        if (study.studyInstanceUid.len == 0)
            return error.InvalidStudy;

        if (study.patientId.len == 0)
            return error.InvalidPatient;

        if (study.hospitalPartitionId.len == 0)
            return error.InvalidPartition;

        if (study.visibility.len == 0)
            return error.InvalidVisibility;

        if (study.seriesCount == 0)
            return error.InvalidSeries;

        if (study.imageCount == 0)
            return error.InvalidImages;

    }

    //----------------------------------------------------------------

    fn buildContext(

        self: *StudyProjectionBuilder,

        study: CatalogStudy,

    ) !ProjectionContext {

        _ = self;

        return ProjectionContext{

            .study_instance_uid =
                study.studyInstanceUid,

            .accession_number =
                study.accessionNumber,

            .patient_id =
                study.patientId,

            .modality =
                study.modality,

            .hospital_partition_id =
                study.hospitalPartitionId,

            .visibility =
                study.visibility,

            .study_date =
                study.studyDate,

            .series_count =
                study.seriesCount,

            .image_count =
                study.imageCount,

            .version =
                study.version,

        };

    }

    //----------------------------------------------------------------

    fn normalize(

        self: *StudyProjectionBuilder,

        context: *ProjectionContext,

    ) !void {

        _ = self;

        context.modality = std.ascii.allocLowerString(

            self.allocator,

            context.modality,

        ) catch context.modality;

        context.visibility = std.ascii.allocLowerString(

            self.allocator,

            context.visibility,

        ) catch context.visibility;

    }

    //----------------------------------------------------------------

    fn validateProjection(

        self: *StudyProjectionBuilder,

        context: ProjectionContext,

    ) !void {

        _ = self;

        if (context.study_instance_uid.len == 0)
            return error.InvalidProjection;

        if (context.patient_id.len == 0)
            return error.InvalidProjection;

        if (context.hospital_partition_id.len == 0)
            return error.InvalidProjection;

        if (context.visibility.len == 0)
            return error.InvalidProjection;

        if (context.series_count == 0)
            return error.InvalidProjection;

        if (context.image_count == 0)
            return error.InvalidProjection;

    }

};
