package catalog

import java.time.LocalDate

/**
 * Canonical search model consumed by the search,
 * authorization and retrieval pipeline.
 *
 * Instances are created exclusively through
 * SearchRecordFactory.
 */
data class StudySearchRecord(

    val studyInstanceUid: String,

    val accessionNumber: String,

    val patientId: String,

    val modality: String,

    val visibility: String,

    val studyDate: LocalDate,

    val seriesCount: Int,

    val imageCount: Int,

    val version: Int

) {

    //------------------------------------------------------------------

    fun validate() {

        require(studyInstanceUid.isNotBlank()) {
            "Study identifier missing."
        }

        require(accessionNumber.isNotBlank()) {
            "Accession number missing."
        }

        require(patientId.isNotBlank()) {
            "Patient identifier missing."
        }

        require(modality.isNotBlank()) {
            "Modality missing."
        }

        require(visibility.isNotBlank()) {
            "Visibility metadata missing."
        }

        require(seriesCount > 0) {
            "Invalid series count."
        }

        require(imageCount > 0) {
            "Invalid image count."
        }

        require(version > 0) {
            "Invalid catalog version."
        }

    }

    //------------------------------------------------------------------

    fun supportsModality(

        requested: String

    ): Boolean {

        return modality.equals(

            requested,

            ignoreCase = true

        )

    }

    //------------------------------------------------------------------

    fun isCurrentVersion(

        expectedVersion: Int

    ): Boolean {

        return version == expectedVersion

    }

    //------------------------------------------------------------------

    fun hasImages(): Boolean {

        return imageCount > 0

    }

    //------------------------------------------------------------------

    fun belongsToStudy(

        studyUid: String

    ): Boolean {

        return studyInstanceUid == studyUid

    }

    //------------------------------------------------------------------

    fun summary(): StudySummary {

        return StudySummary(

            studyInstanceUid = studyInstanceUid,

            accessionNumber = accessionNumber,

            modality = modality,

            studyDate = studyDate,

            imageCount = imageCount

        )

    }

}

/*--------------------------------------------------------------------*/

data class StudySummary(

    val studyInstanceUid: String,

    val accessionNumber: String,

    val modality: String,

    val studyDate: LocalDate,

    val imageCount: Int

)
