module StudyIndexer = struct

  type search_record =
  {
    study_instance_uid : string;
    accession_number : string;
    patient_id : string;
    modality : string;
    hospital_partition_id : string;
    visibility : string;
    study_date : float;
    series_count : int;
    image_count : int;
    version : int;
  }

  type index_document =
  {
    document_id : string;
    partition_key : string;
    visibility : string;
    modality : string;
    searchable_text : string;
    version : int;
  }

  (************************************************************)

  let build_index_document record =

    validate_record record;

    let document =
    {
      document_id = record.study_instance_uid;

      partition_key = record.hospital_partition_id;

      visibility = record.visibility;

      modality = normalize_modality record.modality;

      searchable_text =

        build_searchable_text record;

      version = record.version;
    }
    in

    validate_document document;

    document

  (************************************************************)

  and validate_record record =

    if record.study_instance_uid = "" then
      failwith "Missing study identifier.";

    if record.hospital_partition_id = "" then
      failwith "Missing hospital partition.";

    if record.visibility = "" then
      failwith "Missing visibility.";

    if record.version <= 0 then
      failwith "Invalid version."

  (************************************************************)

  and validate_document document =

    if document.partition_key = "" then
      failwith "Partition key missing.";

    if document.visibility = "" then
      failwith "Visibility missing."

  (************************************************************)

  and normalize_modality modality =

    String.uppercase_ascii modality

  (************************************************************)

  and build_searchable_text record =

    String.concat " "

    [

      record.accession_number;

      record.patient_id;

      record.modality

    ]

end
