  [plan]

  (assoc

    plan

    :parallel-search true

    :prefetch-metadata true))

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

(defn supports-study?

  [plan study]

  (and

    (=

      (:partition plan)

      (:hospital-partition study))

    (=

      (:visibility plan)

      (:visibility study))))
