package services;

import models.DeploymentDelegation;
import repository.DelegationRepository;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

public class DeploymentApprovalService {

    private final DelegationRepository delegationRepository;
    private final DelegationProjectionService projectionService;

    public DeploymentApprovalService(
            DelegationRepository delegationRepository,
            DelegationProjectionService projectionService
    ) {
        this.delegationRepository = delegationRepository;
        this.projectionService = projectionService;
    }

    /**
     * Creates a canonical deployment delegation after all approval
     * requirements have been satisfied.
     */
    public DeploymentDelegation createDelegation(
            DeploymentApprovalRequest request
    ) {

        validate(request);

        DeploymentDelegation delegation = new DeploymentDelegation(
                UUID.randomUUID().toString(),
                request.getDeploymentId(),
                request.getEnvironmentId(),
                request.getOwnerUserId(),
                request.getDelegateUserId(),
                nextGeneration(
                        request.getDeploymentId(),
                        request.getDelegateUserId()
                ),
                List.copyOf(request.getAllowedActions()),
                Instant.now(),
                Instant.now().plus(
                        request.getValidityHours(),
                        ChronoUnit.HOURS
                ),
                request.getApprovalId(),
                request.getApprovedBy()
        );

        delegationRepository.save(delegation);

        /*
         * Runtime publication is intentionally delegated to the
         * projection pipeline.
         */
        projectionService.publish(delegation);

        return delegation;
    }

    private void validate(
            DeploymentApprovalRequest request
    ) {

        Objects.requireNonNull(request);

        require(request.getDeploymentId(), "deploymentId");
        require(request.getEnvironmentId(), "environmentId");
        require(request.getDelegateUserId(), "delegateUserId");
        require(request.getOwnerUserId(), "ownerUserId");
        require(request.getApprovalId(), "approvalId");
        require(request.getApprovedBy(), "approvedBy");

        if (request.getAllowedActions() == null ||
                request.getAllowedActions().isEmpty()) {
            throw new IllegalArgumentException(
                    "Delegation must contain at least one permitted action."
            );
        }

        if (request.getValidityHours() <= 0) {
            throw new IllegalArgumentException(
                    "Delegation validity must be greater than zero."
            );
        }

        if (request.getDelegateUserId()
                .equals(request.getOwnerUserId())) {

            throw new IllegalArgumentException(
                    "Delegation owner and delegate cannot be identical."
            );
        }
    }

    private long nextGeneration(
            String deploymentId,
            String delegateUserId
    ) {

        return delegationRepository
                .findLatestGeneration(
                        deploymentId,
                        delegateUserId
                )
                .map(v -> v + 1)
                .orElse(1L);
    }

    private void require(
            String value,
            String field
    ) {

        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(
                    field + " is required."
            );
        }
    }

    /**
     * Inbound approval request payload.
     *
     * Deliberately kept as a plain data holder — validation lives entirely
     * in {@link #validate(DeploymentApprovalRequest)} so there is a single
     * place that decides whether a delegation request is well-formed.
     */
    public static final class DeploymentApprovalRequest {

        private final String deploymentId;
        private final String environmentId;
        private final String ownerUserId;
        private final String delegateUserId;
        private final List<String> allowedActions;
        private final long validityHours;
        private final String approvalId;
        private final String approvedBy;

        public DeploymentApprovalRequest(
                String deploymentId,
                String environmentId,
                String ownerUserId,
                String delegateUserId,
                List<String> allowedActions,
                long validityHours,
                String approvalId,
                String approvedBy
        ) {
            this.deploymentId = deploymentId;
            this.environmentId = environmentId;
            this.ownerUserId = ownerUserId;
            this.delegateUserId = delegateUserId;
            this.allowedActions = allowedActions;
            this.validityHours = validityHours;
            this.approvalId = approvalId;
            this.approvedBy = approvedBy;
        }

        public String getDeploymentId() {
            return deploymentId;
        }

        public String getEnvironmentId() {
            return environmentId;
        }

        public String getOwnerUserId() {
            return ownerUserId;
        }

        public String getDelegateUserId() {
            return delegateUserId;
        }

        public List<String> getAllowedActions() {
            return allowedActions;
        }

        public long getValidityHours() {
            return validityHours;
        }

        public String getApprovalId() {
            return approvalId;
        }

        public String getApprovedBy() {
            return approvedBy;
        }
    }

}
