package models;

import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public class DeploymentDelegation {

    private final String delegationId;
    private final String deploymentId;
    private final String environmentId;

    private final String ownerUserId;
    private final String delegateUserId;

    /*
     * Security-critical authorization generation.
     * Each modification or revocation creates a new generation.
     */
    private final long delegationGeneration;

    private final List<String> allowedActions;

    private final Instant issuedAt;
    private final Instant expiresAt;

    private final String approvalId;
    private final String approvedBy;

    public DeploymentDelegation(
            String delegationId,
            String deploymentId,
            String environmentId,
            String ownerUserId,
            String delegateUserId,
            long delegationGeneration,
            List<String> allowedActions,
            Instant issuedAt,
            Instant expiresAt,
            String approvalId,
            String approvedBy
    ) {
        this.delegationId = Objects.requireNonNull(delegationId);
        this.deploymentId = Objects.requireNonNull(deploymentId);
        this.environmentId = Objects.requireNonNull(environmentId);
        this.ownerUserId = Objects.requireNonNull(ownerUserId);
        this.delegateUserId = Objects.requireNonNull(delegateUserId);
        this.delegationGeneration = delegationGeneration;
        this.allowedActions = List.copyOf(allowedActions);
        this.issuedAt = Objects.requireNonNull(issuedAt);
        this.expiresAt = Objects.requireNonNull(expiresAt);
        this.approvalId = Objects.requireNonNull(approvalId);
        this.approvedBy = Objects.requireNonNull(approvedBy);
    }

    public String getDelegationId() {
        return delegationId;
    }

    public String getDeploymentId() {
        return deploymentId;
    }

    public String getEnvironmentId() {
        return environmentId;
    }

    public String getOwnerUserId() {
        return ownerUserId;
    }

    public String getDelegateUserId() {
        return delegateUserId;
    }

    public long getDelegationGeneration() {
        return delegationGeneration;
    }

    public List<String> getAllowedActions() {
        return Collections.unmodifiableList(allowedActions);
    }

    public Instant getIssuedAt() {
        return issuedAt;
    }

    public Instant getExpiresAt() {
        return expiresAt;
    }

    public String getApprovalId() {
        return approvalId;
    }

    public String getApprovedBy() {
        return approvedBy;
    }

    public boolean isExpired() {
        return Instant.now().isAfter(expiresAt);
    }

    public boolean allows(String action) {
        return allowedActions.contains(action);
    }

    @Override
    public String toString() {
        return "DeploymentDelegation{" +
                "delegationId='" + delegationId + '\'' +
                ", deploymentId='" + deploymentId + '\'' +
                ", environmentId='" + environmentId + '\'' +
                ", delegateUserId='" + delegateUserId + '\'' +
                ", delegationGeneration=" + delegationGeneration +
                ", expiresAt=" + expiresAt +
                '}';
    }
}
