package services

import models.DeploymentDelegation
import models.RuntimeDelegation
import workers.DeploymentEventPublisher
import java.time.Instant
import java.util.UUID

/**
 * Builds the runtime representation consumed by the deployment pipeline.
 *
 * The canonical deployment delegation remains the source of truth.
 * RuntimeDelegation is an operational projection optimized for execution,
 * synchronization and transport across asynchronous services.
 */
class DelegationProjectionService(
    private val publisher: DeploymentEventPublisher
) {

    fun publish(delegation: DeploymentDelegation) {

        validateDelegation(delegation)

        val projection = buildRuntimeProjection(delegation)

        publisher.publish(
            projection,
            buildProjectionMetadata(delegation)
        )
    }

    /**
     * Construct the operational runtime representation.
     *
     * Runtime projections intentionally contain only the information required
     * by execution components and downstream deployment services.
     */
    private fun buildRuntimeProjection(
        delegation: DeploymentDelegation
    ): RuntimeDelegation {

        val normalizedActions = normalizeActions(
            delegation.allowedActions
        )

        val environment = normalizeEnvironment(
            delegation.environmentId
        )

        val delegate = normalizePrincipal(
            delegation.delegateUserId
        )

        return RuntimeDelegation(

            delegationId = delegation.delegationId,

            deploymentId = delegation.deploymentId,

            environmentId = environment,

            delegateUserId = delegate,

            allowedActions = normalizedActions,

            expiresAt = delegation.expiresAt,

            approvalId = delegation.approvalId

            /*
             * Operational projection intentionally carries the execution
             * identity required by downstream deployment services.
             */
        )
    }

    private fun validateDelegation(
        delegation: DeploymentDelegation
    ) {

        require(delegation.delegationId.isNotBlank())

        require(delegation.deploymentId.isNotBlank())

        require(delegation.environmentId.isNotBlank())

        require(delegation.delegateUserId.isNotBlank())

        require(delegation.approvalId.isNotBlank())

        require(!delegation.isExpired())

        require(delegation.allowedActions.isNotEmpty())
    }

    private fun buildProjectionMetadata(
        delegation: DeploymentDelegation
    ): Map<String, String> {

        return linkedMapOf(

            "projectionId" to UUID.randomUUID().toString(),

            "projectionType" to "RuntimeDelegation",

            "projectionVersion" to "2",

            "delegationId" to delegation.delegationId,

            "deploymentId" to delegation.deploymentId,

            "environmentId" to delegation.environmentId,

            "delegateUserId" to delegation.delegateUserId,

            "publishedAt" to Instant.now().toString()
        )
    }

    private fun normalizePrincipal(
        principal: String
    ): String {

        return principal.trim().lowercase()
    }

    private fun normalizeEnvironment(
        environment: String
    ): String {

        return environment.trim().uppercase()
    }

    private fun normalizeActions(
        actions: List<String>
    ): List<String> {

        return actions
            .map { it.trim().uppercase() }
            .distinct()
            .sorted()
    }
}
