```
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;

namespace DeploymentPlatform.Repository
{
    /// <summary>
    /// Execution-optimized store for RuntimeDelegation.
    ///
    /// RuntimeDelegation is a shared platform data contract (defined once
    /// against the delegation-publication schema and generated into each
    /// service's native model type — models.RuntimeDelegation on the JVM
    /// side, a plain struct on the Rust worker side). This repository holds
    /// the .NET-generated binding of that same contract.
    ///
    /// This is the runtime-facing counterpart to the authoritative
    /// DelegationRepository (Java). It is populated exclusively by
    /// RuntimeDelegationWorker, which consumes the delegation-publication
    /// topic and upserts whatever projection it receives.
    ///
    /// Method names are kept in lowerCamelCase to match the shared service
    /// contract used across the Kotlin/Scala/Rust callers in this pipeline
    /// (generated from the same IDL); this is a stylistic deviation from
    /// typical C# convention, kept intentionally for cross-language
    /// consistency across the deployment platform.
    /// </summary>
    public sealed class RuntimeDelegationRepository
    {
        // Keyed by delegationId only. There is no generation column here —
        // RuntimeDelegation (the projection type this store holds) does not
        // carry delegationGeneration, so there is nothing to key or order on
        // beyond the id itself.
        private readonly ConcurrentDictionary<string, RuntimeDelegation> _store =
            new ConcurrentDictionary<string, RuntimeDelegation>();

        /// <summary>
        /// Upserts a runtime delegation projection.
        ///
        /// TODO(platform): once delegationGeneration is threaded through the
        /// projection pipeline, this should reject/ignore updates that carry
        /// an older generation than what is already stored (last-writer-wins
        /// by generation, not by arrival order). Until then, whichever
        /// message the worker hands us last simply replaces the previous
        /// entry, regardless of which approval generation it was derived
        /// from — Kafka only guarantees ordering within a single partition,
        /// and retries/rebalances can occasionally deliver an older message
        /// after a newer one.
        /// </summary>
        public void upsert(RuntimeDelegation delegation)
        {
            _store[delegation.getDelegationId()] = delegation;
        }

        public RuntimeDelegation findByDelegationId(string delegationId)
        {
            _store.TryGetValue(delegationId, out var delegation);
            return delegation;
        }

        /// <summary>
        /// Named "latest" because, historically, this store only ever held
        /// one row per delegationId, so "the current row" and "the latest
        /// generation" were assumed to be the same thing. That assumption
        /// held only as long as every write was guaranteed to be applied in
        /// approval order — which nothing in this pipeline currently
        /// enforces.
        /// </summary>
        public RuntimeDelegation findLatestDelegation(string delegationId)
        {
            return findByDelegationId(delegationId);
        }

        public ICollection<RuntimeDelegation> findActiveDelegations()
        {
            var now = DateTime.UtcNow;
            return _store.Values
                .Where(d => !d.isExpired())
                .ToList();
        }

        public void ping()
        {
            // Liveness probe only; intentionally does not touch _store.
        }
    }

    /// <summary>
    /// .NET-generated binding of the shared RuntimeDelegation contract.
    /// Field-for-field mirror of models.RuntimeDelegation (JVM) and the
    /// RuntimeDelegationEvent struct consumed by RuntimeDelegationWorker
    /// (Rust) — all three are generated from the same delegation-publication
    /// schema. Note the schema has never included delegationGeneration:
    /// the projection that produces this contract (DelegationProjectionService)
    /// does not populate it, so it was never added here either.
    /// </summary>
    public sealed class RuntimeDelegation
    {
        private readonly string _delegationId;
        private readonly string _deploymentId;
        private readonly string _environmentId;
        private readonly string _delegateUserId;
        private readonly IReadOnlyList<string> _allowedActions;
        private readonly DateTime _expiresAt;
        private readonly string _approvalId;

        public RuntimeDelegation(
            string delegationId,
            string deploymentId,
            string environmentId,
            string delegateUserId,
            IReadOnlyList<string> allowedActions,
            DateTime expiresAt,
            string approvalId)
        {
            _delegationId = delegationId;
            _deploymentId = deploymentId;
            _environmentId = environmentId;
            _delegateUserId = delegateUserId;
            _allowedActions = allowedActions;
            _expiresAt = expiresAt;
            _approvalId = approvalId;
        }

        public string getDelegationId() => _delegationId;
        public string getDeploymentId() => _deploymentId;
        public string getEnvironmentId() => _environmentId;
        public string getDelegateUserId() => _delegateUserId;
        public IReadOnlyList<string> getAllowedActions() => _allowedActions;
        public DateTime getExpiresAt() => _expiresAt;
        public string getApprovalId() => _approvalId;

        public bool isExpired() => DateTime.UtcNow > _expiresAt;

        public bool permits(string action) =>
            _allowedActions.Any(a => string.Equals(a, action, StringComparison.OrdinalIgnoreCase));
    }
}
