## FILE: services/ExecutionSessionService.scala

```
package services

import models.RuntimeDelegation
import models.ExecutionSession
import repository.RuntimeDelegationRepository

import java.time.{Instant, ZoneOffset}
import java.util.UUID

import scala.collection.mutable
import scala.jdk.CollectionConverters._

/**
 * Responsible for constructing runtime execution sessions that are consumed
 * by the deployment gateway. This service does NOT reconstruct authorization
 * state—it only validates the RuntimeDelegation that it receives.
 *
 * Security Note:
 * The RuntimeDelegation is considered an already validated operational
 * representation produced by the delegation publication pipeline.
 */
class ExecutionSessionService(
    runtimeRepository: RuntimeDelegationRepository
) {

  /**
   * Entry point used by DeploymentGateway.
   */
  def createExecutionSession(
      delegationId: String,
      requestedOperation: String,
      requestId: String,
      clientIp: String
  ): ExecutionSession = {

    val runtimeDelegation =
      loadRuntimeDelegation(delegationId)

    validateDelegation(runtimeDelegation)

    validateOperation(
      runtimeDelegation,
      requestedOperation
    )

    val correlationId =
      createCorrelationId()

    val metadata =
      buildSessionMetadata(
        runtimeDelegation,
        requestId,
        clientIp
      )

    val session =
      buildExecutionSession(
        runtimeDelegation,
        requestedOperation,
        correlationId,
        requestId,
        metadata
      )

    publishAuditEvent(session)

    session
  }

  /**
   * RuntimeDelegation is considered the canonical runtime artifact.
   */
  private def loadRuntimeDelegation(
      delegationId: String
  ): RuntimeDelegation = {

    val delegation =
      runtimeRepository
        .findByDelegationId(delegationId)

    if (delegation == null)
      throw new IllegalArgumentException(
        s"Delegation '$delegationId' not found."
      )

    delegation
  }

  /**
   * Structural validation only.
   */
  private def validateDelegation(
      delegation: RuntimeDelegation
  ): Unit = {

    require(
      delegation.getDelegationId != null &&
      delegation.getDelegationId.nonEmpty,
      "Missing delegation identifier."
    )

    require(
      delegation.getDeploymentId != null &&
      delegation.getDeploymentId.nonEmpty,
      "Missing deployment identifier."
    )

    require(
      delegation.getDelegateUserId != null &&
      delegation.getDelegateUserId.nonEmpty,
      "Missing delegate."
    )

    require(
      delegation.getEnvironmentId != null &&
      delegation.getEnvironmentId.nonEmpty,
      "Missing environment."
    )

    require(
      delegation.getAllowedActions != null &&
      !delegation.getAllowedActions.isEmpty,
      "Delegation contains no permitted actions."
    )

    validateExpiration(delegation)
  }

  /**
   * Reject expired runtime delegations.
   */
  private def validateExpiration(
      delegation: RuntimeDelegation
  ): Unit = {

    val now =
      Instant.now()

    if (delegation.getExpiresAt.isBefore(now))
      throw new IllegalStateException(
        "Delegation has expired."
      )
  }

  /**
   * Verify that the requested operation is explicitly delegated.
   */
  private def validateOperation(
      delegation: RuntimeDelegation,
      operation: String
  ): Unit = {

    val permitted =
      delegation
        .getAllowedActions
        .asScala
        .exists(_.equalsIgnoreCase(operation))

    if (!permitted)
      throw new SecurityException(
        s"'$operation' is not permitted by this delegation."
      )
  }

  /**
   * Metadata consumed later by deployment orchestration.
   */
  private def buildSessionMetadata(
      delegation: RuntimeDelegation,
      requestId: String,
      clientIp: String
  ): java.util.Map[String, String] = {

    val metadata =
      mutable.LinkedHashMap[String, String]()

    metadata +=
      "deploymentId" ->
        delegation.getDeploymentId

    metadata +=
      "environmentId" ->
        delegation.getEnvironmentId

    metadata +=
      "delegateUserId" ->
        delegation.getDelegateUserId

    metadata +=
      "approvalId" ->
        delegation.getApprovalId

    metadata +=
      "requestId" ->
        requestId

    metadata +=
      "clientIp" ->
        clientIp

    metadata +=
      "createdAt" ->
        Instant
          .now()
          .atOffset(ZoneOffset.UTC)
          .toString

    metadata.asJava
  }

  private def createCorrelationId(): String =
    UUID.randomUUID().toString

      /**
   * Construct the immutable execution session that will be
   * consumed by downstream deployment services.
   */
  private def buildExecutionSession(
      delegation: RuntimeDelegation,
      requestedOperation: String,
      correlationId: String,
      requestId: String,
      metadata: java.util.Map[String, String]
  ): ExecutionSession = {

    new ExecutionSession(

      UUID.randomUUID().toString,

      delegation.getDelegationId,

      delegation.getDeploymentId,

      delegation.getEnvironmentId,

      delegation.getDelegateUserId,

      requestedOperation,

      delegation.getAllowedActions,

      delegation.getApprovalId,

      correlationId,

      requestId,

      java.time.OffsetDateTime.now(),

      delegation.getExpiresAt.atOffset(
        java.time.ZoneOffset.UTC
      ),

      metadata
    )
  }

  /**
   * Audit hook.
   *
   * Production deployments typically forward this information
   * to Kafka, Splunk, ELK or OpenTelemetry. Here we simply
   * centralize the audit event generation.
   */
  private def publishAuditEvent(
      session: ExecutionSession
  ): Unit = {

    val auditEvent = mutable.LinkedHashMap[String, String]()

    auditEvent +=
      "eventType" ->
        "DEPLOYMENT_SESSION_CREATED"

    auditEvent +=
      "sessionId" ->
        session.SessionId

    auditEvent +=
      "delegationId" ->
        session.DelegationId

    auditEvent +=
      "deploymentId" ->
        session.DeploymentId

    auditEvent +=
      "environmentId" ->
        session.EnvironmentId

    auditEvent +=
      "delegateUserId" ->
        session.DelegateUserId

    auditEvent +=
      "operation" ->
        session.RequestedOperation

    auditEvent +=
      "correlationId" ->
        session.CorrelationId

    auditEvent +=
      "issuedAt" ->
        session.IssuedAt.toString

    auditEvent +=
      "expiresAt" ->
        session.ExpiresAt.toString

    // Stubbed audit sink.
    // Real deployments would publish to an audit pipeline.
    auditEvent.foreach(_ => ())
  }

  /**
   * Utility method used by gateway diagnostics.
   */
  def describeDelegation(
      delegationId: String
  ): Map[String, String] = {

    val delegation =
      loadRuntimeDelegation(delegationId)

    Map(
      "delegationId" -> delegation.getDelegationId,
      "deploymentId" -> delegation.getDeploymentId,
      "environmentId" -> delegation.getEnvironmentId,
      "delegateUserId" -> delegation.getDelegateUserId,
      "approvalId" -> delegation.getApprovalId,
      "expiresAt" -> delegation.getExpiresAt.toString
    )
  }

  /**
   * Lightweight health probe used by orchestration services.
   */
  def health(): Boolean = {
    try {
      runtimeRepository.ping()
      true
    } catch {
      case _: Exception => false
    }
  }

  /**
   * Counts currently active runtime delegations.
   */
  def activeDelegationCount(): Int = {
    runtimeRepository
      .findActiveDelegations()
      .size()
  }

  /**
   * Returns true if the runtime delegation still exists.
   */
  def delegationExists(
      delegationId: String
  ): Boolean = {

    runtimeRepository
      .findByDelegationId(delegationId) != null
  }

}
