// ExecutionSessionService is implemented in Scala (services/ExecutionSessionService.scala)
// and reached here through a generated client stub sharing the same method
// name/signature. ExecutionSession below is the TypeScript binding of the
// shared models.ExecutionSession contract (see models/ExecutionSession.cs).
import { ExecutionSessionService } from "./ExecutionSessionService";

export interface ExecutionSession {
    sessionId: string;
    delegationId: string;
    deploymentId: string;
    environmentId: string;
    delegateUserId: string;
    requestedOperation: string;
    allowedOperations: string[];
    approvalId: string;
}

// Native addon compiled from runtime/ExecutionContextAssembler.cpp.
// Exposes assemble(session) -> AuthorizedExecutionContext, throwing on
// authorization failure.
// eslint-disable-next-line @typescript-eslint/no-var-requires
const nativeExecutionContextAssembler = require("../../build/Release/execution_context_assembler.node");

// Generated RPC client for services/DeploymentAgent.py, exposed over the
// internal service mesh (gRPC).
// eslint-disable-next-line @typescript-eslint/no-var-requires
const deploymentAgentRpc = require("../../build/rpc-clients/deployment_agent_client");

export interface ExecuteRequestBody {
    delegationId: string;
    operation: string;
    requestId: string;
}

export interface DeploymentExecutionResult {
    deploymentId: string;
    operation: string;
    status: "completed" | "failed";
    sessionId: string;
}

interface AuthorizedExecutionContext {
    sessionId: string;
    delegationId: string;
    deploymentId: string;
    operation: string;
    delegateUserId: string;
}

/**
 * Thin binding onto the native ExecutionContextAssembler module
 * (runtime/ExecutionContextAssembler.cpp), loaded once per process.
 *
 * This is the final authorization gate for a deployment operation. It is
 * invoked with the session built by ExecutionSessionService and either
 * returns an AuthorizedExecutionContext or rejects with an authorization
 * error — it does not perform any authorization logic itself in this
 * process, it delegates entirely to the native module.
 */
class ExecutionContextAssemblerClient {
    // In production this is:
    //   require("../../build/Release/execution_context_assembler.node")
    // Declared as a method here so the orchestration logic in
    // DeploymentGateway reads the same regardless of binding mechanism.
    async assemble(session: ExecutionSession): Promise<AuthorizedExecutionContext> {
        return nativeExecutionContextAssembler.assemble(session);
    }
}

interface AgentOperationRequest {
    deploymentId: string;
    operation: string;
    delegateUserId: string;
    sessionId: string;
}

interface AgentOperationResult {
    success: boolean;
}

/**
 * Client onto DeploymentAgent (services/DeploymentAgent.py), reached over
 * the platform's internal service mesh. DeploymentAgent trusts that any
 * request it receives from the gateway has already cleared authorization —
 * it focuses purely on carrying out the requested infrastructure action.
 */
class DeploymentAgentClient {
    async executeOperation(request: AgentOperationRequest): Promise<AgentOperationResult> {
        return deploymentAgentRpc.executeOperation(request);
    }
}

/**
 * Public entry point for executing a deployment operation on behalf of a
 * delegate. This class does not make authorization decisions itself — it
 * coordinates the two components that do:
 *
 *   1. ExecutionSessionService — builds a session shell describing what is
 *      being requested and by whom, based on the current runtime
 *      delegation projection.
 *   2. ExecutionContextAssembler — the final authorization gate, invoked
 *      immediately before dispatch, which confirms the session is backed
 *      by a delegation that still permits the requested operation.
 *
 * Only after both steps succeed does this gateway hand the operation to
 * DeploymentAgent for execution.
 */
export class DeploymentGateway {
    private readonly contextAssembler = new ExecutionContextAssemblerClient();
    private readonly agent = new DeploymentAgentClient();

    constructor(private readonly executionSessionService: ExecutionSessionService) {}

    async execute(
        deploymentId: string,
        body: ExecuteRequestBody
    ): Promise<DeploymentExecutionResult> {
        if (!body.delegationId || !body.operation) {
            throw new Error("delegationId and operation are required.");
        }

        const clientIp = "internal"; // populated from req context in production

        const session = await this.executionSessionService.createExecutionSession(
            body.delegationId,
            body.operation,
            body.requestId,
            clientIp
        );

        if (session.deploymentId !== deploymentId) {
            throw new Error(
                `Session was built for deployment ${session.deploymentId}, not ${deploymentId}.`
            );
        }

        // Final authorization gate — throws/rejects if the delegation
        // backing this session no longer permits the operation.
        const context = await this.contextAssembler.assemble(session);

        const agentResult = await this.agent.executeOperation({
            deploymentId: context.deploymentId,
            operation: context.operation,
            delegateUserId: context.delegateUserId,
            sessionId: context.sessionId,
        });

        return {
            deploymentId,
            operation: body.operation,
            status: agentResult.success ? "completed" : "failed",
            sessionId: session.sessionId,
        };
    }
}
