"""
DeploymentPolicyValidator

Policy-as-code checks used by the platform's compliance tooling: a nightly
job and an on-demand CLI (`deployctl policy check <deployment-id>`) that
compliance and platform teams run to sanity-check delegation state against
the authoritative approval history.

This module is deliberately independent of the live execution path — it
reads from the same authoritative approval store that the runtime path
should be consulting, but it runs out of band, on a schedule or by request,
producing a report rather than blocking or permitting any deployment
operation in real time.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Iterable, List


@dataclass
class DelegationRecord:
    delegation_id: str
    delegation_generation: int
    delegate_user_id: str
    allowed_actions: List[str]
    expires_at: datetime


@dataclass
class PolicyViolation:
    delegation_id: str
    delegation_generation: int
    reason: str


class DeploymentPolicyValidator:
    """
    Validates that a runtime record claiming to act under a given
    delegation generation is still consistent with the authoritative
    approval history for that delegation.

    If this were wired into the live execution path — e.g. called from
    ExecutionContextAssembler with the session's expected generation — it
    would catch exactly the class of drift described in this scenario: a
    runtime record whose effective permissions no longer match the
    generation it claims to represent. Today it is only ever invoked from
    the compliance CLI and the nightly audit job, both of which report
    findings for a human to review rather than affecting execution.
    """

    def validate_generation_match(
        self,
        expected_delegation_id: str,
        expected_generation: int,
        authoritative_history: Iterable[DelegationRecord],
    ) -> List[PolicyViolation]:
        violations: List[PolicyViolation] = []

        matching_generation = next(
            (
                record
                for record in authoritative_history
                if record.delegation_id == expected_delegation_id
                and record.delegation_generation == expected_generation
            ),
            None,
        )

        if matching_generation is None:
            violations.append(
                PolicyViolation(
                    delegation_id=expected_delegation_id,
                    delegation_generation=expected_generation,
                    reason=(
                        "No approval record found for the expected generation; "
                        "the delegation may have been modified or revoked since "
                        "this generation was issued."
                    ),
                )
            )
            return violations

        latest = max(
            (
                record
                for record in authoritative_history
                if record.delegation_id == expected_delegation_id
            ),
            key=lambda r: r.delegation_generation,
            default=matching_generation,
        )

        if latest.delegation_generation != expected_generation:
            violations.append(
                PolicyViolation(
                    delegation_id=expected_delegation_id,
                    delegation_generation=expected_generation,
                    reason=(
                        f"Expected generation {expected_generation} has been "
                        f"superseded by generation {latest.delegation_generation}."
                    ),
                )
            )

        if matching_generation.expires_at < datetime.now(timezone.utc):
            violations.append(
                PolicyViolation(
                    delegation_id=expected_delegation_id,
                    delegation_generation=expected_generation,
                    reason="Delegation generation has expired.",
                )
            )

        return violations
