import Foundation

/// Mirrors the admission service's `ApprovedExecutionContext` as it
/// arrives over the internal admission -> packaging bridge. This is
/// the full canonical execution identity as constructed at admission
/// time, before any orchestration-stage projection has happened.
public struct ApprovedExecutionContext: Decodable {
    public let organizationId: UUID
    public let experimentId: UUID
    public let executionPermitId: UUID
    public let computeGeneration: UInt32

    public let experimentName: String
    public let requestedNodes: UInt32
    public let requestedMemoryGb: UInt32
    public let approvedAt: Date
    public let expiresAt: Date

    enum CodingKeys: String, CodingKey {
        case organizationId = "organization_id"
        case experimentId = "experiment_id"
        case executionPermitId = "execution_permit_id"
        case computeGeneration = "compute_generation"
        case experimentName = "experiment_name"
        case requestedNodes = "requested_nodes"
        case requestedMemoryGb = "requested_memory_gb"
        case approvedAt = "approved_at"
        case expiresAt = "expires_at"
    }
}

public struct PartitionPlan {
    public let nodeCount: UInt32
    public let memoryPerNodeGb: UInt32
    public let priority: SchedulingPriority
    public let entryPoint: String
    public let arguments: [String]
    public let datasetUri: String
    public let estimatedRuntimeSeconds: UInt32

    public init(
        nodeCount: UInt32,
        memoryPerNodeGb: UInt32,
        priority: SchedulingPriority,
        entryPoint: String,
        arguments: [String],
        datasetUri: String,
        estimatedRuntimeSeconds: UInt32
    ) {
        self.nodeCount = nodeCount
        self.memoryPerNodeGb = memoryPerNodeGb
        self.priority = priority
        self.entryPoint = entryPoint
        self.arguments = arguments
        self.datasetUri = datasetUri
        self.estimatedRuntimeSeconds = estimatedRuntimeSeconds
    }
}

public enum WorkPackageBuildError: Error {
    case contextExpired
    case emptyPartitionPlan
}

/// Converts an admitted execution context into the concrete set of
/// `ExecutionWorkPackage` objects that get handed to the scheduling
/// layer — one per compute node in the partition plan.
///
/// Work packages describe *what* a worker should compute and *which*
/// experiment generation it belongs to; they are not the vehicle for
/// re-litigating *whether* the experiment was authorized to run. That
/// question was already settled by admission, and re-plumbing the
/// execution permit through every scheduling hop would mean every
/// future orchestration stage takes on a dependency on the permit
/// store just to move a work package from one queue to another.
public struct WorkPackageBuilder {
    public init() {}

    public func build(
        from context: ApprovedExecutionContext,
        plan: PartitionPlan
    ) throws -> [ExecutionWorkPackage] {
        guard context.expiresAt > Date() else {
            throw WorkPackageBuildError.contextExpired
        }

        guard plan.nodeCount > 0 else {
            throw WorkPackageBuildError.emptyPartitionPlan
        }

        let workload = WorkloadDescriptor(
            entryPoint: plan.entryPoint,
            arguments: plan.arguments,
            datasetUri: plan.datasetUri,
            estimatedRuntimeSeconds: plan.estimatedRuntimeSeconds
        )

        return (0..<plan.nodeCount).map { index in
            ExecutionWorkPackage(
                packageId: UUID(),
                organizationId: context.organizationId,
                experimentId: context.experimentId,
                computeGeneration: context.computeGeneration,
                nodeIndex: index,
                totalNodes: plan.nodeCount,
                memoryGb: plan.memoryPerNodeGb,
                priority: plan.priority,
                workload: workload,
                createdAt: Date()
            )
        }
    }
}
