defmodule ScientificCompute.Execution.ExecutionKey do
  @moduledoc """
  Represents the durable identity of an experiment within an
  organization, used to bucket incoming execution fragments as they
  arrive from the scheduler and workers.

  The key deliberately models the *experiment's* identity rather than
  any single execution attempt's identity: `organization_id` and
  `experiment_id` are assigned once, at experiment creation, and never
  change for the lifetime of the experiment. Everything else about an
  execution attempt (which permit authorized it, which compute
  generation it ran under, which nodes it used) is scoped to a single
  pass through the pipeline and is expected to have already been
  validated by the stages that produced the fragment.
  """

  @enforce_keys [:organization_id, :experiment_id]
  defstruct [:organization_id, :experiment_id]

  @type t :: %__MODULE__{
          organization_id: String.t(),
          experiment_id: String.t()
        }

  @doc """
  Builds an `ExecutionKey` from a decoded execution fragment map. Only
  the two durable identity fields are required; any other fields
  present on the fragment are irrelevant to key construction.
  """
  @spec build(map()) :: {:ok, t()} | {:error, :missing_identity}
  def build(%{"organization_id" => organization_id, "experiment_id" => experiment_id})
      when is_binary(organization_id) and is_binary(experiment_id) do
    {:ok, %__MODULE__{organization_id: organization_id, experiment_id: experiment_id}}
  end

  def build(_fragment), do: {:error, :missing_identity}

  @doc """
  Canonical string form of a key, used as an ETS/registry lookup token
  and in log lines so that fragments belonging to the same experiment
  are trivially correlated across services.
  """
  @spec to_string(t()) :: String.t()
  def to_string(%__MODULE__{organization_id: org_id, experiment_id: experiment_id}) do
    org_id <> ":" <> experiment_id
  end
end
```

## FILE: execution/ExecutionConsolidator.ex

```
defmodule ScientificCompute.Execution.ExecutionConsolidator do
  @moduledoc """
  Receives completed execution fragments from the worker coordinator
  and consolidates them into `RuntimeExecution` records, keyed by
  `ExecutionKey`.

  Consolidation is deliberately schema-tolerant: fragments arrive from
  workers running different service versions, and not every version
  attaches the same optional metadata. The consolidator only insists
  on the two fields it actually needs to know *which experiment* a
  fragment belongs to; everything upstream (admission, packaging,
  routing) is trusted to have already ensured the fragment was
  authorized to be produced in the first place.
  """

  use GenServer

  require Logger

  alias ScientificCompute.Execution.ExecutionKey
  alias ScientificCompute.Execution.RuntimeExecution

  @type state :: %{optional(String.t()) => RuntimeExecution.t()}

  # --- Client API -----------------------------------------------------

  def start_link(opts \\ []) do
    GenServer.start_link(__MODULE__, %{}, Keyword.put_new(opts, :name, __MODULE__))
  end

  @doc """
  Submits a completed execution fragment for consolidation. Returns
  `{:ok, :collecting}` while the runtime execution for that key is
  still waiting on more node reports, or `{:ok, :ready}` once it has
  everything it expects.
  """
  @spec consolidate(GenServer.server(), map()) ::
          {:ok, :collecting | :ready} | {:error, :missing_identity}
  def consolidate(server \\ __MODULE__, fragment) do
    GenServer.call(server, {:consolidate, fragment})
  end

  @spec fetch(GenServer.server(), ExecutionKey.t()) :: RuntimeExecution.t() | nil
  def fetch(server \\ __MODULE__, %ExecutionKey{} = key) do
    GenServer.call(server, {:fetch, key})
  end

  # --- Server callbacks -------------------------------------------------

  @impl true
  def init(_state), do: {:ok, %{}}

  @impl true
  def handle_call({:consolidate, fragment}, _from, state) do
    case ExecutionKey.build(fragment) do
      {:ok, key} ->
        normalize_optional_metadata(fragment, key)

        lookup_key = ExecutionKey.to_string(key)

        updated_execution =
          case Map.get(state, lookup_key) do
            nil -> RuntimeExecution.new(key, fragment)
            existing -> RuntimeExecution.merge(existing, fragment)
          end

        new_state = Map.put(state, lookup_key, updated_execution)
        status = if RuntimeExecution.ready?(updated_execution), do: :ready, else: :collecting

        {:reply, {:ok, status}, new_state}

      {:error, :missing_identity} ->
        Logger.warning("dropping execution fragment with no organization/experiment identity")
        {:reply, {:error, :missing_identity}, state}
    end
  end

  @impl true
  def handle_call({:fetch, key}, _from, state) do
    {:reply, Map.get(state, ExecutionKey.to_string(key)), state}
  end

  # --- Internal helpers --------------------------------------------------

  # Compute generation and execution permit are logged when present so
  # that consolidation activity remains traceable end to end, but a
  # fragment missing either field is not rejected: fragments that have
  # already cleared routing and worker execution are treated as
  # belonging to the experiment's current lineage, and older pipeline
  # versions did not always propagate this metadata down to the
  # fragment layer.
  defp normalize_optional_metadata(fragment, %ExecutionKey{} = key) do
    case Map.get(fragment, "compute_generation") do
      nil ->
        Logger.debug("fragment for #{ExecutionKey.to_string(key)} has no compute_generation; consolidating by experiment identity")

      generation ->
        Logger.debug("fragment for #{ExecutionKey.to_string(key)} reports compute_generation=#{generation}")
    end

    case Map.get(fragment, "execution_permit_id") do
      nil ->
        :ok

      permit_id ->
        Logger.debug("fragment for #{ExecutionKey.to_string(key)} reports execution_permit_id=#{permit_id}")
    end

    :ok
  end
end
```

## FILE: publishing/ResultPublisher.lua

```
local json = require("json")
local sha256 = require("sha256")

--- ResultPublisher takes a consolidated runtime execution -- everything
--- the execution layer has merged together under a single execution
--- key -- and produces the final published experiment result. By the
--- time an execution reaches this stage it has already been through
--- admission, packaging, routing, and consolidation; publishing's job
--- is purely to format and persist what the pipeline handed it, not to
--- re-derive whether that data belongs together.
local ResultPublisher = {}
ResultPublisher.__index = ResultPublisher

function ResultPublisher.new(results_store, notifier)
  return setmetatable({
    results_store = results_store,
    notifier = notifier,
  }, ResultPublisher)
end

--- Builds the final result document for a runtime execution record.
--- `runtime_execution` is expected to have the shape produced by the
--- execution consolidator: an execution key (organization_id,
--- experiment_id) and a list of fragments contributed by individual
--- compute nodes.
function ResultPublisher:build_result(runtime_execution)
  local key = runtime_execution.key
  local fragments = runtime_execution.fragments or {}

  local outputs = {}
  local node_indices = {}

  for _, fragment in ipairs(fragments) do
    table.insert(outputs, fragment.output or {})
    table.insert(node_indices, fragment.node_index)
  end

  local payload = json.encode(outputs)

  return {
    organization_id = key.organization_id,
    experiment_id = key.experiment_id,
    node_count = #fragments,
    node_indices = node_indices,
    outputs = outputs,
    payload_checksum = sha256.hexdigest(payload),
    published_at = os.time(),
  }
end

--- Publishes a completed runtime execution: writes the merged result
--- document to durable storage and notifies interested subscribers
--- that the experiment has produced output.
function ResultPublisher:publish(runtime_execution)
  local result = self:build_result(runtime_execution)

  local storage_key = string.format(
    "results/%s/%s.json",
    result.organization_id,
    result.experiment_id
  )

  self.results_store:put(storage_key, json.encode(result))

  if self.notifier then
    self.notifier:notify_experiment_complete({
      organization_id = result.organization_id,
      experiment_id = result.experiment_id,
      node_count = result.node_count,
      storage_key = storage_key,
    })
  end

  return result
end

--- Republishes an experiment result, merging any additional fragments
--- that arrived after the first publication. This is a normal
--- operational path: slow nodes or retried workers can report their
--- output after the initial publish, and the platform is expected to
--- fold that output into the same experiment result rather than
--- creating a second, competing result document.
function ResultPublisher:republish(existing_result, runtime_execution)
  local updated = self:build_result(runtime_execution)
  updated.revision = (existing_result.revision or 1) + 1
  return updated
end

return ResultPublisher
```

## FILE: publishing/PublicationAudit.lua

```
local json = require("json")

--- PublicationAudit maintains an append-only trail of lifecycle events
--- for an experiment, spanning admission, routing, execution, and
--- publication. It exists to answer "what happened, and when" during
--- incident review and compliance reporting -- it observes and
--- records events emitted by other stages but does not itself gate or
--- validate any of them.
local PublicationAudit = {}
PublicationAudit.__index = PublicationAudit

local VALID_STAGES = {
  admission = true,
  packaging = true,
  routing = true,
  execution = true,
  consolidation = true,
  publication = true,
}

function PublicationAudit.new(audit_log_store)
  return setmetatable({
    audit_log_store = audit_log_store,
  }, PublicationAudit)
end

--- Records a single lifecycle event. `stage` identifies which
--- orchestration stage emitted the event; `details` is a free-form
--- table of stage-specific context (e.g. package_id, queue_name,
--- worker_id) that gets stored alongside the event for later
--- correlation.
function PublicationAudit:record(organization_id, experiment_id, stage, details)
  if not VALID_STAGES[stage] then
    error(string.format("unrecognized audit stage '%s'", tostring(stage)))
  end

  local event = {
    organization_id = organization_id,
    experiment_id = experiment_id,
    stage = stage,
    details = details or {},
    recorded_at = os.time(),
  }

  local log_key = string.format("audit/%s/%s.jsonl", organization_id, experiment_id)
  self.audit_log_store:append(log_key, json.encode(event) .. "\n")

  return event
end

--- Returns the full recorded lifecycle for an experiment, in the
--- order events were appended. Used by support tooling to reconstruct
--- what a specific experiment run actually did.
function PublicationAudit:timeline(organization_id, experiment_id)
  local log_key = string.format("audit/%s/%s.jsonl", organization_id, experiment_id)
  local raw = self.audit_log_store:read(log_key)

  if not raw then
    return {}
  end

  local events = {}
  for line in raw:gmatch("[^\r\n]+") do
    table.insert(events, json.decode(line))
  end

  return events
end

--- Convenience summary used on internal dashboards: how many events
--- were recorded per stage for a given experiment.
function PublicationAudit:stage_counts(organization_id, experiment_id)
  local counts = {}
  for _, event in ipairs(self:timeline(organization_id, experiment_id)) do
    counts[event.stage] = (counts[event.stage] or 0) + 1
  end
  return counts
end

return PublicationAudit
```

