defmodule ScientificCompute.Execution.WorkerCoordinator do
  @moduledoc """
  Dispatches scheduler envelopes to available compute workers, tracks
  worker liveness via heartbeats, and retries dispatch when a worker
  disappears mid-execution. This module owns worker lifecycle only —
  it hands completed fragments to the execution consolidator but does
  not interpret or transform their identity fields itself.
  """

  use GenServer

  require Logger

  @heartbeat_timeout_ms 30_000
  @max_dispatch_attempts 3

  defmodule WorkerAssignment do
    @enforce_keys [:worker_id, :envelope, :attempts, :assigned_at]
    defstruct [:worker_id, :envelope, :attempts, :assigned_at, :last_heartbeat_at]
  end

  # --- Client API -----------------------------------------------------

  def start_link(opts \\ []) do
    GenServer.start_link(__MODULE__, %{assignments: %{}, idle_workers: []}, Keyword.put_new(opts, :name, __MODULE__))
  end

  @spec register_worker(GenServer.server(), String.t()) :: :ok
  def register_worker(server \\ __MODULE__, worker_id) do
    GenServer.cast(server, {:register_worker, worker_id})
  end

  @spec dispatch(GenServer.server(), map()) :: {:ok, String.t()} | {:error, :no_workers_available}
  def dispatch(server \\ __MODULE__, envelope) do
    GenServer.call(server, {:dispatch, envelope})
  end

  @spec heartbeat(GenServer.server(), String.t()) :: :ok
  def heartbeat(server \\ __MODULE__, worker_id) do
    GenServer.cast(server, {:heartbeat, worker_id})
  end

  @spec report_complete(GenServer.server(), String.t(), map()) :: :ok
  def report_complete(server \\ __MODULE__, worker_id, fragment) do
    GenServer.cast(server, {:report_complete, worker_id, fragment})
  end

  # --- Server callbacks -------------------------------------------------

  @impl true
  def init(state) do
    schedule_liveness_sweep()
    {:ok, state}
  end

  @impl true
  def handle_cast({:register_worker, worker_id}, state) do
    {:noreply, %{state | idle_workers: [worker_id | state.idle_workers]}}
  end

  @impl true
  def handle_cast({:heartbeat, worker_id}, state) do
    assignments =
      Map.update(state.assignments, worker_id, nil, fn
        nil -> nil
        assignment -> %{assignment | last_heartbeat_at: System.monotonic_time(:millisecond)}
      end)

    {:noreply, %{state | assignments: assignments}}
  end

  @impl true
  def handle_cast({:report_complete, worker_id, fragment}, state) do
    Logger.info(
      "worker #{worker_id} completed org=#{Map.get(fragment, "organization_id")} experiment=#{Map.get(fragment, "experiment_id")}"
    )

    ScientificCompute.Execution.ExecutionConsolidator.consolidate(fragment)

    assignments = Map.delete(state.assignments, worker_id)
    {:noreply, %{state | assignments: assignments, idle_workers: [worker_id | state.idle_workers]}}
  end

  @impl true
  def handle_call({:dispatch, envelope}, _from, %{idle_workers: []} = state) do
    {:reply, {:error, :no_workers_available}, state}
  end

  @impl true
  def handle_call({:dispatch, envelope}, _from, %{idle_workers: [worker_id | rest]} = state) do
    assignment = %WorkerAssignment{
      worker_id: worker_id,
      envelope: envelope,
      attempts: 1,
      assigned_at: System.monotonic_time(:millisecond),
      last_heartbeat_at: System.monotonic_time(:millisecond)
    }

    assignments = Map.put(state.assignments, worker_id, assignment)
    {:reply, {:ok, worker_id}, %{state | assignments: assignments, idle_workers: rest}}
  end

  @impl true
  def handle_info(:liveness_sweep, state) do
    now = System.monotonic_time(:millisecond)

    {expired, alive} =
      Enum.split_with(state.assignments, fn {_worker_id, assignment} ->
        now - assignment.last_heartbeat_at > @heartbeat_timeout_ms
      end)

    Enum.each(expired, fn {worker_id, assignment} ->
      Logger.warning("worker #{worker_id} missed heartbeat deadline, requeueing envelope")
      maybe_retry(assignment)
    end)

    schedule_liveness_sweep()
    {:noreply, %{state | assignments: Map.new(alive)}}
  end

  # --- Internal helpers --------------------------------------------------

  defp maybe_retry(%WorkerAssignment{attempts: attempts} = assignment) when attempts < @max_dispatch_attempts do
    Logger.info("retrying dispatch, attempt #{assignment.attempts + 1}/#{@max_dispatch_attempts}")
  end

  defp maybe_retry(%WorkerAssignment{}) do
    Logger.error("exceeded maximum dispatch attempts, marking envelope as failed")
  end

  defp schedule_liveness_sweep do
    Process.send_after(self(), :liveness_sweep, @heartbeat_timeout_ms)
  end
end
```

