from training.model_metadata_builder import ModelMetadataBuilder
from registry.model_registry import ModelRegistry


########################################################################


class TrainingPipeline:

    def __init__(

        self,

        trainer,

        signer,

        registry: ModelRegistry

    ):

        self._trainer = trainer
        self._signer = signer
        self._registry = registry

        self._metadata_builder = (

            ModelMetadataBuilder()

        )

    # ------------------------------------------------------------------

    def execute(

        self,

        training_request

    ):

        self._validate_request(

            training_request

        )

        model = self._trainer.train(

            training_request

        )

        signature = self._signer.sign(

            model

        )

        metadata = (

            self._metadata_builder.build(

                training_request,

                model,

                signature

            )

        )

        self._registry.register(

            metadata

        )

        return metadata

    # ------------------------------------------------------------------

    def _validate_request(

        self,

        request

    ):

        required = [

            "modelId",

            "datasetDigest",

            "dependencyDigest",

            "trainingCodeDigest",

            "hyperParameters"

        ]

        for field in required:

            if field not in request:

                raise ValueError(

                    f"{field} missing."

                )

        if len(

            request["hyperParameters"]

        ) == 0:

            raise ValueError(

                "Training configuration missing."

            )
