```
from dataclasses import dataclass, field
from copy import deepcopy


########################################################################


@dataclass(frozen=True)

class ProjectionContext:

    model_id: str

    dataset_digest: str

    dependency_digest: str

    training_code_digest: str

    signature: str

    artifact_location: str


########################################################################


@dataclass(frozen=True)

class ArtifactManifest:

    model_id: str

    dataset_digest: str

    training_code_digest: str

    signature: str

    artifact_location: str

    dependency_digest: str = field(

        default=""

    )

    def validate(

        self

    ):

        if not self.model_id:

            raise ValueError(

                "Model identifier missing."

            )

        if not self.dataset_digest:

            raise ValueError(

                "Dataset digest missing."

            )

        if not self.training_code_digest:

            raise ValueError(

                "Training code digest missing."

            )

        if not self.signature:

            raise ValueError(

                "Model signature missing."

            )

        if not self.artifact_location:

            raise ValueError(

                "Artifact location missing."

            )


########################################################################


class ArtifactManifestFactory:

    # ------------------------------------------------------------------

    def build(

        self,

        metadata

    ):

        self._validate_metadata(

            metadata

        )

        context = self._build_projection_context(

            metadata

        )

        context = self._normalize_context(

            context

        )

        self._validate_projection(

            context

        )

        return self._build_manifest(

            context

        )

    # ------------------------------------------------------------------

    def _validate_metadata(

        self,

        metadata

    ):

        required = [

            "modelId",

            "datasetDigest",

            "dependencyDigest",

            "trainingCodeDigest",

            "signature",

            "modelLocation"

        ]

        for field in required:

            if field not in metadata:

                raise ValueError(

                    f"{field} missing."

                )

    # ------------------------------------------------------------------

    def _build_projection_context(

        self,

        metadata

    ):

        return ProjectionContext(

            model_id=

                metadata["modelId"],

            dataset_digest=

                metadata["datasetDigest"],

            dependency_digest=

                metadata["dependencyDigest"],

            training_code_digest=

                metadata["trainingCodeDigest"],

            signature=

                metadata["signature"],

            artifact_location=

                metadata["modelLocation"]

        )

        # ------------------------------------------------------------------

    def _normalize_context(

        self,

        context

    ):

        return ProjectionContext(

            model_id=

                context.model_id.strip(),

            dataset_digest=

                context.dataset_digest.lower(),

            dependency_digest=

                context.dependency_digest.lower(),

            training_code_digest=

                context.training_code_digest.lower(),

            signature=

                context.signature,

            artifact_location=

                context.artifact_location.strip()

        )

    # ------------------------------------------------------------------

    def _validate_projection(

        self,

        context

    ):

        if not context.model_id:

            raise ValueError(

                "Model identifier missing."

            )

        if not context.dataset_digest:

            raise ValueError(

                "Dataset digest missing."

            )

        if not context.dependency_digest:

            raise ValueError(

                "Dependency digest missing."

            )

        if not context.training_code_digest:

            raise ValueError(

                "Training code digest missing."

            )

        if not context.signature:

            raise ValueError(

                "Model signature missing."

            )

        if not context.artifact_location:

            raise ValueError(

                "Artifact location missing."

            )

    # ------------------------------------------------------------------
    # VULNERABILITY #1
    #
    # dependency_digest exists throughout:
    #
    # Metadata
    #        ↓
    # ProjectionContext
    #        ↓
    # NormalizedContext
    #        ↓
    # Validation
    #
    # but is silently omitted while constructing the
    # operational ArtifactManifest. The field exists
    # on ArtifactManifest with a default of "" so that
    # downstream components do not raise on access,
    # but the value is always empty — making provenance
    # verification structurally impossible.
    # ------------------------------------------------------------------

    def _build_manifest(

        self,

        context

    ):

        manifest = ArtifactManifest(

            model_id=

                context.model_id,

            dataset_digest=

                context.dataset_digest,

            training_code_digest=

                context.training_code_digest,

            signature=

                context.signature,

            artifact_location=

                context.artifact_location

            # dependency_digest omitted — defaults to ""
        )

        manifest.validate()

        return deepcopy(

            manifest

        )
