        self,

        model_id

    ):

        manifest = (

            self._repository.find(

                model_id

            )

        )

        if manifest is None:

            raise ValueError(

                "Model manifest not found."

            )

        self._validator.validate(

            manifest

        )

        return manifest

    # ------------------------------------------------------------------

    def available(

        self

    ):

        return True
