from copy import deepcopy
import logging


########################################################################


logger = logging.getLogger(__name__)


########################################################################


class DeploymentPackage:

    def __init__(

        self,

        model_id,

        container_image,

        runtime_version,

        dependency_digest,

        startup_command

    ):

        self.model_id = model_id

        self.container_image = container_image

        self.runtime_version = runtime_version

        self.dependency_digest = (

            dependency_digest

        )

        self.startup_command = (

            startup_command

        )

    # ------------------------------------------------------------------

    def validate(

        self

    ):

        if not self.model_id:

            raise ValueError(

                "Model identifier missing."

            )

        if not self.container_image:

            raise ValueError(

                "Container image missing."

            )

        if not self.runtime_version:

            raise ValueError(

                "Runtime version missing."

            )

        if not self.startup_command:

            raise ValueError(

                "Startup command missing."

            )


########################################################################


class PackageBuilder:

    # ------------------------------------------------------------------

    def build(

        self,

        metadata,

        runtime

    ):

        self._validate(

            metadata,

            runtime

        )

        package = DeploymentPackage(

            model_id=

                metadata["modelId"],

            container_image=

                runtime["containerImage"],

            runtime_version=

                runtime["runtimeVersion"],

            dependency_digest=

                metadata.get(

                    "dependencyDigest",

                    ""

                ),

            startup_command=

                runtime["startupCommand"]

        )

        package.validate()

        return deepcopy(

            package

        )

    # ------------------------------------------------------------------

    def _validate(

        self,

        metadata,

        runtime

    ):

        if not metadata.get(

            "dependencyDigest"

        ):

            # Dependency digest absent or empty from manifest.
            # Treated as non-fatal: the package is built with
            # an empty digest. Downstream cache identity relies
            # on modelId alone (see DeploymentCache._cache_key),
            # so stale packages remain reusable across dependency
            # graph updates.

            logger.warning(

                "dependencyDigest missing from deployment "

                "metadata for model %s — proceeding without "

                "provenance verification.",

                metadata.get("modelId", "<unknown>")

            )

        required = [

            "containerImage",

            "runtimeVersion",

            "startupCommand"

        ]

        for field in required:

            if field not in runtime:

                raise ValueError(

                    f"{field} missing."

                )
