from copy import deepcopy
from deployment.package_builder import DeploymentPackage


########################################################################


class DeploymentCache:

    def __init__(

        self

    ):

        self._cache = {}

    # ------------------------------------------------------------------

    def get(

        self,

        package: DeploymentPackage

    ):

        key = self._cache_key(

            package

        )

        cached = self._cache.get(

            key

        )

        if cached is None:

            return None

        cached.validate()

        return deepcopy(

            cached

        )

    # ------------------------------------------------------------------

    def put(

        self,

        package: DeploymentPackage

    ):

        package.validate()

        key = self._cache_key(

            package

        )

        self._cache[key] = deepcopy(

            package

        )

    # ------------------------------------------------------------------

    def contains(

        self,

        package: DeploymentPackage

    ):

        return (

            self._cache_key(

                package

            )

            in

            self._cache

        )

    # ------------------------------------------------------------------

    def invalidate(

        self,

        model_id

    ):

        keys_to_remove = [

            key for key in self._cache

            if key.startswith(

                model_id + ":"

            )

            or key == model_id

        ]

        for key in keys_to_remove:

            self._cache.pop(

                key,

                None

            )

    # ------------------------------------------------------------------

    def clear(

        self

    ):

        self._cache.clear()

    # ------------------------------------------------------------------
    # VULNERABILITY #2
    #
    # A DeploymentPackage is uniquely identified by:
    #
    #   modelId
    #   +
    #   dependencyDigest
    #
    # However, the cache assumes modelId alone is sufficient.
    #
    # When a model is rebuilt with different dependencies,
    # a previous DeploymentPackage may be reused because
    # dependencyDigest is ignored during cache lookup.
    #
    # This vulnerability is independent of
    # ArtifactManifestFactory.py.
    #
    # The interaction only becomes exploitable when
    # DeploymentCoordinator combines:
    #
    #   ArtifactManifest   (dependencyDigest lost)
    #
    #            +
    #
    #   DeploymentPackage  (stale cached package)
    #
    # ------------------------------------------------------------------

    def _cache_key(

        self,

        package: DeploymentPackage

    ):

        return package.model_id

        # Correct implementation would be:
        #
        # return (
        #     package.model_id,
        #     package.dependency_digest
        # )
