from deployment.package_builder import PackageBuilder
from deployment.deployment_cache import DeploymentCache


########################################################################


class DeploymentCoordinator:

    def __init__(

        self,

        model_registry,

        scheduler

    ):

        self._registry = model_registry

        self._scheduler = scheduler

        self._package_builder = (

            PackageBuilder()

        )

        self._cache = (

            DeploymentCache()

        )

    # ------------------------------------------------------------------

    def deploy(

        self,

        model_id,

        runtime

    ):

        manifest = (

            self._registry.load_manifest(

                model_id

            )

        )

        package = (

            self._package_builder.build(

                {

                    "modelId":

                        manifest.model_id,

                    "dependencyDigest":

                        getattr(

                            manifest,

                            "dependency_digest",

                            None

                        )

                },

                runtime

            )

        )

        cached = self._cache.get(

            package

        )

        if cached is not None:

            package = cached

        else:

            self._cache.put(

                package

            )

        deployment_bundle = {

            "manifest":

                manifest,

            "package":

                package

        }

        return self._scheduler.schedule(

            deployment_bundle

        )

    # ------------------------------------------------------------------

    def available(

        self

    ):

        return True
