########################################################################


class DeploymentScheduler:

    def __init__(

        self,

        deployment_service,

        deployment_policy

    ):

        self._deployment_service = (

            deployment_service

        )

        self._deployment_policy = (

            deployment_policy

        )

    # ------------------------------------------------------------------

    def schedule(

        self,

        deployment_bundle

    ):

        self._deployment_policy.validate(

            deployment_bundle

        )

        return self._deployment_service.deploy(

            deployment_bundle

        )

    # ------------------------------------------------------------------

    def schedule_batch(

        self,

        deployments

    ):

        results = []

        for deployment in deployments:

            results.append(

                self.schedule(

                    deployment

                )

            )

        return results
