from datetime import datetime


########################################################################


class ModelDeploymentService:

    def __init__(

        self,

        signature_validator,

        dependency_validator,

        deployment_policy,

        deployment_repository,

        metrics

    ):

        self._signature_validator = (

            signature_validator

        )

        self._dependency_validator = (

            dependency_validator

        )

        self._deployment_policy = (

            deployment_policy

        )

        self._deployment_repository = (

            deployment_repository

        )

        self._metrics = metrics

    # ------------------------------------------------------------------

    def deploy(

        self,

        deployment_bundle

    ):

        self._validate_bundle(

            deployment_bundle

        )

        deployment = self._execute_deployment(

            deployment_bundle

        )

        self._deployment_repository.save(

            deployment

        )

        self._metrics.record_deployment()

        return deployment

    # ------------------------------------------------------------------

    def _validate_bundle(

        self,

        deployment_bundle

    ):

        manifest = deployment_bundle[

            "manifest"

        ]

        package = deployment_bundle[

            "package"

        ]

        manifest.validate()

        package.validate()

        self._signature_validator.validate(

            manifest

        )

        self._dependency_validator.validate(

            manifest,

            package

        )

        self._deployment_policy.validate(

            deployment_bundle

        )

    # ------------------------------------------------------------------

    def _execute_deployment(

        self,

        deployment_bundle

    ):

        manifest = deployment_bundle[

            "manifest"

        ]

        package = deployment_bundle[

            "package"

        ]

        return {

            "deploymentId":

                f"deploy-{manifest.model_id}",

            "modelId":

                manifest.model_id,

            "containerImage":

                package.container_image,

            "runtimeVersion":

                package.runtime_version,

            "artifactLocation":

                manifest.artifact_location,

            "status":

                "DEPLOYED",

            "deployedAt":

                datetime.utcnow()

        }
