    ):

        self._increment(

            "failed_deployments"

        )

    # ------------------------------------------------------------------

    def record_cache_hit(

        self

    ):

        self._increment(

            "cache_hits"

        )

    # ------------------------------------------------------------------

    def record_cache_miss(

