    ):

        self._increment(

            "cache_misses"

        )

    # ------------------------------------------------------------------

    def record_manifest_validation(

        self

    ):

        self._increment(

            "manifest_validations"

        )

    # ------------------------------------------------------------------

    def snapshot(

        self

    ):

        return {

            "generatedAt":

                self._last_update,

            "metrics":

                dict(

                    self._counters

                )

        }

    # ------------------------------------------------------------------

    def _increment(

        self,

        metric

    ):

        self._counters[

            metric

        ] += 1

        self._last_update = (

            datetime.utcnow()

        )
