import express from "express";

////////////////////////////////////////////////////////////////////////

export function trainingRoutes(

    trainingPipeline: any

): express.Router {

    const router = express.Router();

    //------------------------------------------------------------------

    router.post(

        "/train",

        async (req, res) => {

            try {

                validateRequest(

                    req.body

                );

                const metadata =

                    trainingPipeline.execute(

                        req.body

                    );

                res.status(201).json({

                    status: "SUCCESS",

                    metadata

                });

            }

            catch (error: any) {

                res.status(400).json({

                    status: "FAILED",

                    message: error.message

                });

            }

        }

    );

    //------------------------------------------------------------------

    router.get(

        "/health",

        (_, res) => {

            res.json({

                status: "UP"

            });

        }

    );

    return router;

}

////////////////////////////////////////////////////////////////////////

function validateRequest(

    body: any

): void {

    const required = [

        "modelId",

        "datasetDigest",

        "dependencyDigest",

        "trainingCodeDigest",

        "hyperParameters"

    ];

    for (const field of required) {

        if (!(field in body)) {

            throw new Error(

                `${field} missing.`

            );

        }

    }

}
