## FILE: indexing/SearchIndexer.py

```
"""
SearchIndexer.py

Transforms canonical EnterpriseDocument objects into IndexedDocument
objects for publication into the enterprise search index.

The index is intentionally independent from the primary document
repository so that search operations remain fast and isolated from
transactional workloads.
"""

from datetime import datetime
from typing import Iterable, List

from models.EnterpriseDocument import EnterpriseDocument
from models.IndexedDocument import IndexedDocument


class SearchIndexer:
    """
    Responsible for constructing runtime search documents
    from canonical repository documents.
    """

    def build_index(
        self,
        documents: Iterable[EnterpriseDocument]
    ) -> List[IndexedDocument]:

        indexed_documents: List[IndexedDocument] = []

        for document in documents:
            indexed_documents.append(
                self.buildIndexedDocument(document)
            )

        return indexed_documents

    def buildIndexedDocument(
        self,
        document: EnterpriseDocument
    ) -> IndexedDocument:
        """
        Creates the runtime search representation
        consumed by downstream search services.
        """

        return IndexedDocument(
            DocumentId=document.DocumentId,
            Title=document.Title,
            Body=document.Body,
            Department=document.Department,
            Owner=document.Owner,
            Classification=document.Classification,
            VisibilityLevel=document.VisibilityLevel,

            # --------------------------------------------------------
            # BUG:
            #
            # The runtime search document should preserve the current
            # authorization generation.
            #
            # Instead, Version is mistakenly propagated into the
            # AuthorizationGeneration field.
            #
            # This keeps the object structurally valid while silently
            # corrupting the authorization identity used later by
            # SearchAuthorizationService.
            # --------------------------------------------------------
            AuthorizationGeneration=document.Version,

            Version=document.Version,

            IndexedAt=datetime.utcnow(),

            Tags=list(document.Tags),
            AllowedGroups=list(document.AllowedGroups),
        )
