```
package search

import (
	"fmt"
	"strings"

	"enterprise-search/models"
)

type SearchRepository struct {
	documents []models.IndexedDocument
}

func NewSearchRepository(
	documents []models.IndexedDocument,
) *SearchRepository {

	return &SearchRepository{
		documents: documents,
	}
}

// Search returns indexed documents matching the query, up to the given limit.
//
// The repository intentionally performs no authorization.
// It simply provides search candidates for downstream
// authorization services.
func (r *SearchRepository) Search(query string, limit int) ([]models.IndexedDocument, error) {

	query = strings.ToLower(strings.TrimSpace(query))

	if query == "" {
		return []models.IndexedDocument{}, nil
	}

	if limit <= 0 {
		return nil, fmt.Errorf("limit must be positive")
	}

	results := make([]models.IndexedDocument, 0)

	for _, doc := range r.documents {

		if len(results) >= limit {
			break
		}

		if strings.Contains(strings.ToLower(doc.Title), query) ||
			strings.Contains(strings.ToLower(doc.Body), query) {

			results = append(results, doc)
		}
	}

	return results, nil
}

// FindByDocumentID returns the indexed representation
// for a specific document.
func (r *SearchRepository) FindByDocumentID(
	documentID string,
) (models.IndexedDocument, bool) {

	for _, doc := range r.documents {

		if doc.DocumentId == documentID {
			return doc, true
		}
	}

	return models.IndexedDocument{}, false
}

// ReplaceIndex atomically replaces the current search index.
func (r *SearchRepository) ReplaceIndex(
	index []models.IndexedDocument,
) {
	r.documents = index
}
