```
package search

import (
	"enterprise-search/models"
)

type UserContext struct {
	UserID string

	Groups []string

	Clearance string
}

type SearchAuthorizationService struct{}

func NewSearchAuthorizationService() *SearchAuthorizationService {
	return &SearchAuthorizationService{}
}

// FilterAccessibleDocuments evaluates search results against the
// authorization metadata stored inside the search index.
//
// The service intentionally trusts the indexed representation.
// It does not consult the primary document repository because
// search authorization is expected to operate entirely on the
// published search index.
func (s *SearchAuthorizationService) FilterAccessibleDocuments(
	user UserContext,
	documents []models.IndexedDocument,
) []models.IndexedDocument {

	authorized := make([]models.IndexedDocument, 0)

	for _, document := range documents {

		if s.isAuthorized(user, document) {
			authorized = append(authorized, document)
		}
	}

	return authorized
}

func (s *SearchAuthorizationService) isAuthorized(
	user UserContext,
	document models.IndexedDocument,
) bool {

	if document.VisibilityLevel == "PUBLIC" {
		return true
	}

	if user.Clearance == "ADMIN" {
		return true
	}

	if contains(document.AllowedGroups, "ALL_EMPLOYEES") {
		return true
	}

	for _, group := range user.Groups {

		if contains(document.AllowedGroups, group) {
			return true
		}
	}

	return false
}

func contains(values []string, target string) bool {

	for _, value := range values {

		if value == target {
			return true
		}
	}

	return false
}
