package publishing

import indexing.SearchIndexer
import models.EnterpriseDocument
import models.IndexedDocument
import repository.DocumentRepository

/**
 * Coordinates publication of canonical enterprise documents into the
 * enterprise search index.
 *
 * This class is responsible only for orchestration:
 *
 * Repository
 *      ↓
 * SearchIndexer
 *      ↓
 * SearchRepository
 *
 * It does not modify security metadata or perform authorization.
 */
class DocumentPublisher(
    private val documentRepository: DocumentRepository,
    private val searchIndexer: SearchIndexer
) {

    /**
     * Publishes every active document into the search index.
     */
    fun publishAll() {
        val documents = documentRepository.listPublishableDocuments()

        for (document in documents) {
            publish(document)
        }
    }

    /**
     * Publishes a single document.
     */
    fun publish(document: EnterpriseDocument): IndexedDocument {
        validate(document)

        return searchIndexer.buildIndexedDocument(document)
    }

    /**
     * Republishes an existing document after modification.
     */
    fun republish(documentId: String): IndexedDocument {
        val document = documentRepository.findById(documentId)
            ?: throw IllegalArgumentException("Document not found: $documentId")

        return publish(document)
    }

    /**
     * Republishes every document belonging to a department.
     */
    fun publishDepartment(department: String) {
        val documents = documentRepository.findByDepartment(department)

        documents.forEach {
            publish(it)
        }
    }

    /**
     * Performs lightweight publication validation.
     *
     * Security validation and authorization are handled elsewhere.
     */
    private fun validate(document: EnterpriseDocument) {
        require(document.documentId.isNotBlank()) {
            "Document identifier is required."
        }

        require(document.title.isNotBlank()) {
            "Document title is required."
        }

        require(document.body.isNotBlank()) {
            "Document body is required."
        }

        require(document.department.isNotBlank()) {
            "Department is required."
        }

        require(document.owner.isNotBlank()) {
            "Owner is required."
        }

        require(document.classification.isNotBlank()) {
            "Classification is required."
        }

        require(document.visibilityLevel.isNotBlank()) {
            "Visibility level is required."
        }

        require(document.isActive) {
            "Inactive documents cannot be published."
        }
    }
}
