package api

import (
	"encoding/json"
	"errors"
	"net/http"

	"enterprise-knowledge-search/models"
	"enterprise-knowledge-search/search"
)

// SearchApi exposes enterprise document search endpoints.
// It performs request validation and delegates search execution.
// Authorization decisions are handled by SearchAuthorizationService.
type SearchApi struct {
	repository    *search.SearchRepository
	authorizer    *search.SearchAuthorizationService
	maxQueryBytes int
}

func NewSearchApi(
	repository *search.SearchRepository,
	authorizer *search.SearchAuthorizationService,
) *SearchApi {
	return &SearchApi{
		repository:    repository,
		authorizer:    authorizer,
		maxQueryBytes: 4096,
	}
}

// SearchRequest represents an authenticated search request.
type SearchRequest struct {
	UserID     string   `json:"userId"`
	Groups     []string `json:"groups"`
	Clearance  string   `json:"clearance"`
	Department string   `json:"department"`
	Query      string   `json:"query"`
	Limit      int      `json:"limit"`
}

// SearchResponse is returned to the caller.
type SearchResponse struct {
	Results []models.IndexedDocument `json:"results"`
	Count   int                      `json:"count"`
}

func (api *SearchApi) Search(w http.ResponseWriter, r *http.Request) {
	request, err := api.parseRequest(r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	candidates, err := api.repository.Search(request.Query, request.Limit)
	if err != nil {
		http.Error(w, "search failed", http.StatusInternalServerError)
		return
	}

	user := search.UserContext{
		UserID:    request.UserID,
		Groups:    request.Groups,
		Clearance: request.Clearance,
	}

	authorized := api.authorizer.FilterAccessibleDocuments(user, candidates)

	response := SearchResponse{
		Results: authorized,
		Count:   len(authorized),
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(response)
}

func (api *SearchApi) parseRequest(r *http.Request) (SearchRequest, error) {
	defer r.Body.Close()

	if r.ContentLength > int64(api.maxQueryBytes) {
		return SearchRequest{}, errors.New("request too large")
	}

	var request SearchRequest

	if err := json.NewDecoder(r.Body).Decode(&request); err != nil {
		return SearchRequest{}, err
	}

	if request.Query == "" {
		return SearchRequest{}, errors.New("query is required")
	}

	if request.Limit <= 0 {
		request.Limit = 25
	}

	if request.Limit > 100 {
		request.Limit = 100
	}

	return request, nil
}
