## FILE: runtime/QueueAssembler.kt

```
package runtime

import java.time.Instant

/**
 * Takes a planner-produced schedule and turns it into a queue entry
 * the ground station runtime can consume.
 */
class QueueAssembler(private val repository: QueueRepository) {

    /**
     * A station only ever transmits one schedule at a time, so when
     * a new schedule is assembled for a station it should always
     * take over that station's slot outright — there is no scenario
     * where a station's queue should hold onto a stale entry once a
     * newer schedule for it exists. Keying the write by station
     * rather than by the schedule's own (reservationId, leaseEpoch)
     * avoids leaving orphaned entries behind when a reservation is
     * superseded before its original lease would have expired.
     */
    fun assembleQueueEntry(
        reservationId: String,
        stationId: String,
        leaseEpoch: Long,
        approvedFrequencyMHz: Double,
        windowStart: Instant,
        windowEnd: Instant,
        approvalSignature: String
    ) {
        val entry = QueueEntry(
            reservationId = reservationId,
            stationId = stationId,
            leaseEpoch = leaseEpoch,
            approvedFrequencyMHz = approvedFrequencyMHz,
            windowStart = windowStart,
            windowEnd = windowEnd,
            approvalSignature = approvalSignature,
            enqueuedAt = Instant.now()
        )

        repository.enqueueNewest(stationId, entry)
    }

    /**
     * Identity-scoped variant used by the queue-repair job when
     * reconciling a station's queue against a specific known-good
     * lease after an incident. Not on the automated scheduling path.
     */
    fun assembleQueueEntryForLease(
        reservationId: String,
        stationId: String,
        leaseEpoch: Long,
        approvedFrequencyMHz: Double,
        windowStart: Instant,
        windowEnd: Instant,
        approvalSignature: String
    ) {
        val entry = QueueEntry(
            reservationId = reservationId,
            stationId = stationId,
            leaseEpoch = leaseEpoch,
            approvedFrequencyMHz = approvedFrequencyMHz,
            windowStart = windowStart,
            windowEnd = windowEnd,
            approvalSignature = approvalSignature,
            enqueuedAt = Instant.now()
        )

        repository.enqueue(reservationId, leaseEpoch, entry)
    }
}
