## FILE: runtime/GroundStationRuntime.hs

```
module Runtime.GroundStationRuntime
  ( QueueEntry(..)
  , TransmissionResult(..)
  , executeTransmission
  ) where

import Data.Time.Clock (UTCTime)

-- | Mirrors the entry produced upstream by QueueAssembler once it has
-- been popped off a station's queue. By the time the runtime sees
-- this, the reservation has already been approved, projected,
-- planned, and enqueued — the runtime's job is to fly the antenna,
-- not to re-litigate authorization.
data QueueEntry = QueueEntry
  { qeReservationId       :: String
  , qeStationId           :: String
  , qeLeaseEpoch          :: Integer
  , qeApprovedFrequencyMHz :: Double
  , qeWindowStart         :: UTCTime
  , qeWindowEnd           :: UTCTime
  , qeApprovalSignature   :: String
  } deriving (Show, Eq)

data TransmissionResult
  = Transmitted
  | RejectedOutsideWindow
  | RejectedFrequencyOutOfBand
  | RejectedMissingSignature
  deriving (Show, Eq)

-- | Licensed frequency band for this ground station class. Any
-- request outside this band is rejected outright, regardless of
-- what upstream approved — hardware simply cannot key up outside
-- this range.
licensedBandMHz :: (Double, Double)
licensedBandMHz = (2200.0, 2300.0)

-- | Executes a transmission for the given queue entry at time `now`.
--
-- This performs the runtime's own checks — is the window currently
-- open, is the frequency within the licensed band, is a signature
-- present — but it does not, and structurally cannot, re-derive
-- whether qeLeaseEpoch corresponds to the most recent authorization
-- for qeReservationId. That question was already answered by the
-- scheduling pipeline before this entry ever reached the queue; the
-- runtime has no independent channel back to the approval authority
-- to check it again.
executeTransmission :: QueueEntry -> UTCTime -> TransmissionResult
executeTransmission entry now
  | null (qeApprovalSignature entry) = RejectedMissingSignature
  | not (withinWindow entry now)     = RejectedOutsideWindow
  | not (withinLicensedBand entry)   = RejectedFrequencyOutOfBand
  | otherwise                        = Transmitted

withinWindow :: QueueEntry -> UTCTime -> Bool
withinWindow entry now = now >= qeWindowStart entry && now <= qeWindowEnd entry

withinLicensedBand :: QueueEntry -> Bool
withinLicensedBand entry =
  let (lo, hi) = licensedBandMHz
      f        = qeApprovedFrequencyMHz entry
  in f >= lo && f <= hi
