## FILE: approval/ReservationAuthority.scala

```
package approval

import java.time.Instant
import java.util.UUID

/**
 * Mints transmission approvals for the stations it manages.
 *
 * Each call to `approve` starts a new authorization lineage by
 * assigning a fresh `authorizationGeneration`. Anything downstream
 * that reconstructs state from an event stream must key off that
 * generation number, not just the reservation and lease, or it can
 * end up resurrecting an authorization that was meant to be
 * superseded.
 */
final class ReservationAuthority(
    val authorityId: String,
    val authorityName: String,
    val managedStations: Set[String]
) {

  def approve(
      reservationId: UUID,
      stationId: String,
      satelliteId: String,
      leaseEpoch: Long,
      authorizationGeneration: Long,
      approvedFrequencyMHz: Double,
      window: TransmissionWindow,
      approver: String
  ): ReservationApproval = {

    require(
      managesStation(stationId),
      s"Authority '$authorityName' cannot approve station '$stationId'."
    )
    require(approvedFrequencyMHz > 0, "Frequency must be positive.")
    require(window.isValid, "Transmission window is invalid.")

    new ReservationApproval(
      reservationId = reservationId,
      stationId = stationId,
      satelliteId = satelliteId,
      leaseEpoch = leaseEpoch,
      authorizationGeneration = authorizationGeneration,
      approvedFrequencyMHz = approvedFrequencyMHz,
      transmissionWindow = window,
      approvedBy = approver,
      approvalTimestamp = Instant.now(),
      approvalSignature = generateSignature(reservationId, authorizationGeneration)
    )
  }

  def managesStation(stationId: String): Boolean =
    managedStations.exists(_.equalsIgnoreCase(stationId))

  def stationCount: Int =
    managedStations.size

  def supportsReservation(stationId: String, window: TransmissionWindow): Boolean =
    managesStation(stationId) && window.isValid

  private def generateSignature(reservationId: UUID, authorizationGeneration: Long): String =
    s"$authorityId-$reservationId-$authorizationGeneration"
}
