import Foundation

/// Inbound request submitted by a satellite operator asking for a
/// communication window on a specific ground station. This is the
/// entry point of the reservation workflow — nothing here has been
/// authorized yet. Authorization is minted downstream by
/// `ReservationAuthority` once the request clears scheduling checks.
public struct ReservationRequest: Codable {
    public let reservationId: UUID
    public let stationId: String
    public let satelliteId: String
    public let requestedFrequencyMHz: Double
    public let startTime: Date
    public let endTime: Date
    public let requestedBy: String

    public init(
        reservationId: UUID = UUID(),
        stationId: String,
        satelliteId: String,
        requestedFrequencyMHz: Double,
        startTime: Date,
        endTime: Date,
        requestedBy: String
    ) {
        self.reservationId = reservationId
        self.stationId = stationId
        self.satelliteId = satelliteId
        self.requestedFrequencyMHz = requestedFrequencyMHz
        self.startTime = startTime
        self.endTime = endTime
        self.requestedBy = requestedBy
    }

    public var duration: TimeInterval {
        endTime.timeIntervalSince(startTime)
    }

    /// Basic shape validation. Business-rule validation (frequency
    /// licensing, station capability, scheduling conflicts) happens
    /// in the approval authority, not here.
    public var isWellFormed: Bool {
        !stationId.isEmpty
            && !satelliteId.isEmpty
            && requestedFrequencyMHz > 0
            && endTime > startTime
    }
}
