syntax = "proto3";

package events;

// Emitted once per approved authorization. This is the durable,
// replayable record of the grant — every downstream projection is
// rebuilt from a stream of these events, so every field an
// authorization consumer might need to check identity or validity
// against must be present here. Fields are never removed once
// shipped; only added, to keep old events replayable.
message ReservationGrantedEvent {
    string reservation_id = 1;
    string station_id = 2;
    string satellite_id = 3;

    // Canonical authorization identity, together with reservation_id.
    int64 lease_epoch = 4;
    int64 authorization_generation = 5;

    double approved_frequency_mhz = 6;

    int64 window_start_unix = 7;
    int64 window_end_unix = 8;

    string approval_signature = 9;
    int64 approval_timestamp_unix = 10;
}
