## FILE: events/EventPublisher.go

```
package events

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// ApprovedReservation is the local Go representation of an approval
// grant, as handed off by the approval service at the process
// boundary. It intentionally carries every field of the canonical
// authorization identity (ReservationId, LeaseEpoch,
// AuthorizationGeneration) so that the event this publisher emits
// is a complete, replayable record.
type ApprovedReservation struct {
	ReservationId           string
	StationId               string
	SatelliteId             string
	LeaseEpoch              int64
	AuthorizationGeneration int64
	ApprovedFrequencyMhz    float64
	WindowStartUnix         int64
	WindowEndUnix           int64
	ApprovalSignature       string
	ApprovalTimestampUnix   int64
}

func (a ApprovedReservation) IsValid() bool {
	return a.ReservationId != "" &&
		a.StationId != "" &&
		a.SatelliteId != "" &&
		a.ApprovedFrequencyMhz > 0 &&
		a.WindowEndUnix > a.WindowStartUnix &&
		a.ApprovalSignature != ""
}

type EventBus interface {
	Publish(topic string, event *ReservationGrantedEvent) error
}

type EventPublisher struct {
	bus            EventBus
	topic          string
	mu             sync.RWMutex
	publishedCount uint64
	lastPublished  time.Time
}

func NewEventPublisher(bus EventBus, topic string) *EventPublisher {
	return &EventPublisher{
		bus:   bus,
		topic: topic,
	}
}

// PublishApproval converts a freshly granted approval into a
// ReservationGrantedEvent and puts it on the bus. Every projection
// downstream is rebuilt from this event, so nothing here is
// optional — in particular AuthorizationGeneration must always be
// carried through, since it is what lets a projection distinguish
// this grant from a later one for the same reservation and lease.
func (p *EventPublisher) PublishApproval(approved ApprovedReservation) error {
	if !approved.IsValid() {
		return errors.New("invalid reservation approval")
	}

	event := p.buildGrantedEvent(approved)

	if err := p.bus.Publish(p.topic, event); err != nil {
		return fmt.Errorf("unable to publish reservation event: %w", err)
	}

	p.recordPublication()
	return nil
}

func (p *EventPublisher) buildGrantedEvent(approved ApprovedReservation) *ReservationGrantedEvent {
	return &ReservationGrantedEvent{
		ReservationId:           approved.ReservationId,
		StationId:               approved.StationId,
		SatelliteId:             approved.SatelliteId,
		LeaseEpoch:              approved.LeaseEpoch,
		AuthorizationGeneration: approved.AuthorizationGeneration,
		ApprovedFrequencyMhz:    approved.ApprovedFrequencyMhz,
		WindowStartUnix:         approved.WindowStartUnix,
		WindowEndUnix:           approved.WindowEndUnix,
		ApprovalSignature:       approved.ApprovalSignature,
		ApprovalTimestampUnix:   approved.ApprovalTimestampUnix,
	}
}

func (p *EventPublisher) PublishedCount() uint64 {
	p.mu.RLock()
	defer p.mu.RUnlock()
	return p.publishedCount
}

func (p *EventPublisher) LastPublished() time.Time {
	p.mu.RLock()
	defer p.mu.RUnlock()
	return p.lastPublished
}

func (p *EventPublisher) HealthCheck() bool {
	return p.bus != nil && p.topic != ""
}

func (p *EventPublisher) recordPublication() {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.publishedCount++
	p.lastPublished = time.Now().UTC()
}

func (p *EventPublisher) Topic() string {
	return p.topic
}

func (p *EventPublisher) ResetMetrics() {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.publishedCount = 0
	p.lastPublished = time.Time{}
}
