type UploadHandler struct {
	uploadService *services.UploadService
}

func NewUploadHandler(
	uploadService *services.UploadService,
) *UploadHandler {

	return &UploadHandler{
		uploadService: uploadService,
	}
}

func (h *UploadHandler) UploadEvidence(
	ctx *gin.Context,
) {

	userID := ctx.GetString(
		"userId",
	)

	caseID := ctx.PostForm(
		"caseId",
	)

	fileHeader, err := ctx.FormFile(
		"archive",
	)

	if err != nil {

		ctx.JSON(
			http.StatusBadRequest,
			gin.H{
				"error":
					"archive missing",
			},
		)

		return
	}

	if caseID == "" {

		ctx.JSON(
			http.StatusBadRequest,
			gin.H{
				"error":
					"caseId missing",
			},
		)

		return
	}

	result, err :=
		h.uploadService.
			ProcessEvidenceUpload(
				userID,
				caseID,
				fileHeader,
			)

	if err != nil {

		ctx.JSON(
			http.StatusBadRequest,
			gin.H{
				"error":
					err.Error(),
			},
		)

		return
	}

	ctx.JSON(
		http.StatusCreated,
		gin.H{
			"evidenceId":
				result.EvidenceID,

			"status":
				result.Status,
		},
	)
}
