use std::fs;
use std::io::Read;
use zip::read::ZipFile;

pub struct SymlinkHandler;

impl SymlinkHandler {

    pub fn new() -> Self {

        Self {}
    }

    pub fn is_symlink(
        &self,
        file: &ZipFile
    ) -> bool {

        match file.unix_mode() {

            Some(mode) => {

                (mode & 0o170000)
                    == 0o120000
            }

            None => false
        }
    }

    pub fn extract_symlink(
        &self,
        file: &mut ZipFile,
        destination: &std::path::Path
    ) -> Result<(), String> {

        let mut target =
            String::new();

        file.read_to_string(
            &mut target
        ).map_err(
            |_| "failed reading symlink"
                .to_string()
        )?;

        #[cfg(unix)]
        {

            std::os::unix::fs::symlink(
                &target,
                destination
            ).map_err(
                |_| "symlink creation failed"
                    .to_string()
            )?;
        }

        Ok(())
    }
}
