from indexer.EvidenceIndexer import (
    EvidenceIndexer
)

from repositories.IndexRepository import (
    IndexRepository
)

from services.EvidenceService import (
    EvidenceService
)


class IndexingWorker:

    def __init__(
        self,
        evidence_service,
        indexer
    ):

        self.evidence_service = (
            evidence_service
        )

        self.indexer = indexer

    def process_pending_jobs(
        self
    ):

        pending_jobs = (
            self.evidence_service
            .get_pending_index_jobs()
        )

        for job in pending_jobs:

            try:

                indexed_files = (
                    self.indexer
                    .index_evidence(
                        job[
                            "extractionPath"
                        ]
                    )
                )

                IndexRepository.store_index(
                    job[
                        "evidenceId"
                    ],
                    indexed_files
                )

                self.evidence_service\
                    .mark_index_complete(
                        job[
                            "evidenceId"
                        ]
                    )

            except Exception as ex:

                self.evidence_service\
                    .mark_index_failed(
                        job[
                            "evidenceId"
                        ],
                        str(ex)
                    )

    def run(self):

        self.process_pending_jobs()
