import os

from storage.FileLocator import (
    FileLocator
)

from indexer.MetadataCollector import (
    MetadataCollector
)


class EvidenceIndexer:

    def __init__(self):

        self.collector = (
            MetadataCollector()
        )

    def index_evidence(
        self,
        extraction_root
    ):

        indexed_files = []

        for root, dirs, files in os.walk(
            extraction_root
        ):

            for file_name in files:

                full_path = os.path.join(
                    root,
                    file_name
                )

                metadata = (
                    self.collector
                    .collect(
                        full_path
                    )
                )

                indexed_files.append(
                    {
                        "path":
                            FileLocator
                            .normalize(
                                full_path
                            ),

                        "size":
                            metadata[
                                "size"
                            ],

                        "sha256":
                            metadata[
                                "sha256"
                            ],

                        "mimeType":
                            metadata[
                                "mimeType"
                            ]
                    }
                )

        return indexed_files
