import os


class FileLocator:

    @staticmethod
    def normalize(
        path
    ):

        return os.path.abspath(
            path
        )

    @staticmethod
    def resolve(
        indexed_path
    ):

        if not os.path.exists(
            indexed_path
        ):
            raise Exception(
                "File not found"
            )

        return os.path.realpath(
            indexed_path
        )

    @staticmethod
    def get_file_size(
        indexed_path
    ):

        resolved = (
            FileLocator.resolve(
                indexed_path
            )
        )

        return os.path.getsize(
            resolved
        )

    @staticmethod
    def open_file(
        indexed_path
    ):

        resolved = (
            FileLocator.resolve(
                indexed_path
            )
        )

        return open(
            resolved,
            "rb"
        )
