package services

import (
	"io"

	"evidence-platform/storage"
	"evidence-platform/repositories"
)

type EvidenceService struct {
	indexRepo repositories.IndexRepository
}

func (s *EvidenceService)
DownloadIndexedFile(
	fileID string,
) (
	io.ReadCloser,
	error,
) {

	record, err :=
		s.indexRepo.
			GetIndexedFile(
				fileID,
			)

	if err != nil {

		return nil, err
	}

	reader, err :=
		storage.
			OpenIndexedFile(
				record.Path,
			)

	if err != nil {

		return nil, err
	}

	return reader, nil
}
