```
package approval;

import capability.CapabilityRepository;
import capability.model.ApprovedToolCapability;
import models.AuthenticatedUser;
import models.ToolExecutionRequest;

import java.time.Instant;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Responsible for determining whether an authenticated user
 * may execute a logical tool within a given environment.
 *
 * This service only produces canonical ApprovedToolCapability
 * objects. Runtime transformations happen later.
 */
public class PolicyApprovalService {

    private final CapabilityRepository capabilityRepository;

    public PolicyApprovalService(
            CapabilityRepository capabilityRepository
    ) {
        this.capabilityRepository = capabilityRepository;
    }

    public ApprovedToolCapability authorizeExecution(
            AuthenticatedUser user,
            ToolExecutionRequest request
    ) {

        validateUser(user);

        validateRequest(request);

        ApprovedToolCapability capability =
                capabilityRepository.findApprovedCapability(
                        request.getToolId(),
                        request.getEnvironment(),
                        user.getDepartment()
                );

        if (capability == null) {
            throw new IllegalStateException(
                    "No approved capability exists."
            );
        }

        validateCapabilityState(capability);

        verifyEnvironment(
                capability,
                request.getEnvironment()
        );

        verifyParameterSchema(
                capability,
                request
        );

        verifyDepartmentAccess(
                capability,
                user
        );

        verifyExpiration(capability);

        return capability;

    }

    private void validateUser(
            AuthenticatedUser user
    ) {

        require(
                user.getUserId(),
                "User id missing."
        );

        require(
                user.getDepartment(),
                "Department missing."
        );

        require(
                user.getRole(),
                "Role missing."
        );

    }

    private void validateRequest(
            ToolExecutionRequest request
    ) {

        require(
                request.getToolId(),
                "Tool id missing."
        );

        require(
                request.getEnvironment(),
                "Environment missing."
        );

        require(
                request.getJustification(),
                "Business justification required."
        );

        if (request.getParameters() == null) {
            throw new IllegalArgumentException(
                    "Parameters missing."
            );
        }

    }

    private void verifyEnvironment(
            ApprovedToolCapability capability,
            String environment
    ) {

        if (!capability
                .getEnvironment()
                .equalsIgnoreCase(environment)) {

            throw new SecurityException(
                    "Environment mismatch."
            );

        }

    }

    private void verifyDepartmentAccess(
            ApprovedToolCapability capability,
            AuthenticatedUser user
    ) {

        if (!capability
                .getDepartments()
                .contains(user.getDepartment())) {

            throw new SecurityException(
                    "Department not authorized."
            );

        }

    }

    private void verifyExpiration(
            ApprovedToolCapability capability
    ) {

        if (capability
                .getExpiresAt()
                .isBefore(Instant.now())) {

            throw new SecurityException(
                    "Capability expired."
            );

        }

    }

    private void validateCapabilityState(
            ApprovedToolCapability capability
    ) {

        if (!capability.isApproved()) {

            throw new SecurityException(
                    "Capability has not been approved."
            );

        }

        if (capability.isRevoked()) {

            throw new SecurityException(
                    "Capability revoked."
            );

        }

    }

    /**
     * Ensures supplied parameters match the
     * approved parameter schema.
     */
    private void verifyParameterSchema(
            ApprovedToolCapability capability,
            ToolExecutionRequest request
    ) {

        Set<String> approvedNames =
                capability.getAllowedParameters()
                        .stream()
                        .map(ParameterDefinition::getName)
                        .collect(Collectors.toSet());

        Set<String> suppliedNames =
                request.getParameters()
                        .stream()
                        .map(Parameter::getName)
                        .collect(Collectors.toSet());

        if (!approvedNames.equals(suppliedNames)) {

            throw new SecurityException(
                    "Parameter schema mismatch."
            );

        }

        for (ParameterDefinition definition :
                capability.getAllowedParameters()) {

            Parameter supplied =
                    request.findParameter(
                            definition.getName()
                    );

            if (supplied == null) {

                throw new SecurityException(
                        "Missing parameter: "
                                + definition.getName()
                );

            }

            validateParameterValue(
                    definition,
                    supplied.getValue()
            );

        }

    }

    private void validateParameterValue(
            ParameterDefinition definition,
            String value
    ) {

        if (value == null || value.isBlank()) {

            throw new IllegalArgumentException(
                    "Parameter value missing."
            );

        }

        if (value.length() >
                definition.getMaximumLength()) {

            throw new IllegalArgumentException(
                    "Parameter too long."
            );

        }

    }

    private void require(
            String value,
            String message
    ) {

        if (value == null ||
                value.isBlank()) {

            throw new IllegalArgumentException(
                    message
            );

        }

    }

    public List<String> supportedTools() {

        return capabilityRepository
                .listApprovedTools();

    }

    public Map<String, Object> diagnostics() {

        Map<String, Object> diagnostics =
                new LinkedHashMap<>();

        diagnostics.put(
                "approvedTools",
                capabilityRepository.count()
        );

        diagnostics.put(
                "generatedAt",
                Instant.now()
        );

        diagnostics.put(
                "service",
                "PolicyApprovalService"
        );

        return diagnostics;

    }

}
```

