import Foundation

/// Terminal record of "what actually happened" for a given execution,
/// used for compliance review and incident investigation.
struct ExecutionAuditRecord: Codable {
    let planId: String
    let toolId: String
    let approvalId: String
    let capabilityRevision: Int
    let requestedBy: String
    let justification: String
    let executedProviderId: String
    let executedEndpoint: String
    let resolvedVia: String
    let succeeded: Bool
    let startedAt: Date
    let completedAt: Date
    let errorMessage: String?
}

enum AuditError: Error {
    case missingField(String)
}

/// Storage abstraction over the audit ledger, backed by an
/// append-only table in production.
protocol AuditStore {
    func append(_ record: ExecutionAuditRecord) throws
}

/// Persists execution outcomes for compliance review.
///
/// The audit trail is built entirely from what the runtime pipeline
/// actually observed at execution time: the resolved provider, the
/// capability revision, and the approval id used to authorize the
/// request. Reconciliation against the original policy decision --
/// confirming the provider that executed the tool matches the
/// provider the approval was granted against -- happens out-of-band,
/// in the periodic compliance export job that joins this ledger
/// against the approval service's records. Doing that join here,
/// synchronously, would mean a slow or temporarily unavailable
/// approval service could block execution audit logging, which this
/// service treats as unacceptable: an execution must always be
/// recorded, even if the approval service cannot be reached.
final class AuditRecorder {

    private let store: AuditStore

    init(store: AuditStore) {
        self.store = store
    }

    func recordCompletion(
        planId: String,
        toolId: String,
        approvalId: String,
        capabilityRevision: Int,
        requestedBy: String,
        justification: String,
        executedProviderId: String,
        executedEndpoint: String,
        resolvedVia: String,
        startedAt: Date,
        completedAt: Date
    ) throws {

        let record = ExecutionAuditRecord(
            planId: planId,
            toolId: toolId,
            approvalId: approvalId,
            capabilityRevision: capabilityRevision,
            requestedBy: requestedBy,
            justification: justification,
            executedProviderId: executedProviderId,
            executedEndpoint: executedEndpoint,
            resolvedVia: resolvedVia,
            succeeded: true,
            startedAt: startedAt,
            completedAt: completedAt,
            errorMessage: nil
        )

        try validate(record)
        try store.append(record)
    }

    func recordFailure(
        planId: String,
        toolId: String,
        approvalId: String,
        capabilityRevision: Int,
        requestedBy: String,
        justification: String,
        reason: String,
        startedAt: Date,
        completedAt: Date
    ) throws {

        let record = ExecutionAuditRecord(
            planId: planId,
            toolId: toolId,
            approvalId: approvalId,
            capabilityRevision: capabilityRevision,
            requestedBy: requestedBy,
            justification: justification,
            executedProviderId: "",
            executedEndpoint: "",
            resolvedVia: "none",
            succeeded: false,
            startedAt: startedAt,
            completedAt: completedAt,
            errorMessage: reason
        )

        try validate(record)
        try store.append(record)
    }

    /// Sanity-checks that a record carries enough identifying
    /// information to be useful during an investigation. This is a
    /// completeness check, not a correctness check -- it confirms the
    /// record is well-formed, not that the execution it describes
    /// matches what was originally approved.
    private func validate(_ record: ExecutionAuditRecord) throws {

        guard !record.planId.isEmpty else {
            throw AuditError.missingField("planId")
        }

        guard !record.toolId.isEmpty else {
            throw AuditError.missingField("toolId")
        }

        guard !record.approvalId.isEmpty else {
            throw AuditError.missingField("approvalId")
        }
    }
}
