```
package gateway

import (
	"net/http"
	"strings"
	"time"

	"aiops-platform/approval"
	"aiops-platform/models"
	"aiops-platform/planner"

	"github.com/gin-gonic/gin"
)

type AgentGateway struct {
	approvalService *approval.PolicyApprovalService
	planner         *planner.ExecutionPlanner
}

func NewAgentGateway(
	approvalService *approval.PolicyApprovalService,
	planner *planner.ExecutionPlanner,
) *AgentGateway {

	return &AgentGateway{
		approvalService: approvalService,
		planner:         planner,
	}

}

func (g *AgentGateway) ExecuteTool(
	ctx *gin.Context,
) {

	var request models.ToolExecutionRequest

	if err := ctx.ShouldBindJSON(&request); err != nil {

		ctx.JSON(
			http.StatusBadRequest,
			gin.H{
				"error": "invalid request body",
			},
		)

		return

	}

	if err := g.validateRequest(&request); err != nil {

		ctx.JSON(
			http.StatusBadRequest,
			gin.H{
				"error": err.Error(),
			},
		)

		return

	}

	user := g.extractUser(ctx)

	approvedCapability, err :=
		g.approvalService.AuthorizeExecution(
			ctx.Request.Context(),
			user,
			request,
		)

	if err != nil {

		ctx.JSON(
			http.StatusForbidden,
			gin.H{
				"error": err.Error(),
			},
		)

		return

	}

	execution, err :=
		g.planner.CreateExecution(
			ctx.Request.Context(),
			approvedCapability,
			request,
		)

	if err != nil {

		ctx.JSON(
			http.StatusInternalServerError,
			gin.H{
				"error": err.Error(),
			},
		)

		return

	}

	ctx.JSON(
		http.StatusAccepted,
		gin.H{
			"executionId": execution.ExecutionID,
			"status":      execution.Status,
			"submittedAt": execution.CreatedAt,
		},
	)

}

func (g *AgentGateway) Health(
	ctx *gin.Context,
) {

	ctx.JSON(
		http.StatusOK,
		gin.H{
			"status":    "UP",
			"service":   "agent-gateway",
			"timestamp": time.Now().UTC(),
		},
	)

}

func (g *AgentGateway) validateRequest(
	request *models.ToolExecutionRequest,
) error {

	if strings.TrimSpace(request.ToolID) == "" {
		return models.NewValidationError(
			"toolId is required",
		)
	}

	if strings.TrimSpace(request.Environment) == "" {
		return models.NewValidationError(
			"environment is required",
		)
	}

	if strings.TrimSpace(request.Justification) == "" {
		return models.NewValidationError(
			"justification is required",
		)
	}

	if len(request.Parameters) == 0 {
		return models.NewValidationError(
			"at least one parameter is required",
		)
	}

	if len(request.Parameters) > 25 {
		return models.NewValidationError(
			"parameter limit exceeded",
		)
	}

	for _, parameter := range request.Parameters {

		if strings.TrimSpace(parameter.Name) == "" {
			return models.NewValidationError(
				"parameter name cannot be empty",
			)
		}

		if strings.TrimSpace(parameter.Value) == "" {
			return models.NewValidationError(
				"parameter value cannot be empty",
			)
		}

	}

	return nil

}

func (g *AgentGateway) extractUser(
	ctx *gin.Context,
) models.AuthenticatedUser {

	claims, exists := ctx.Get("principal")

	if !exists {

		return models.AuthenticatedUser{}

	}

	user, ok :=
		claims.(models.AuthenticatedUser)

	if !ok {

		return models.AuthenticatedUser{}

	}

	return user

}
```


