from flask import Blueprint, request, jsonify

from services.ReservationService import ReservationService
from services.InventoryService import InventoryService
from services.AuditService import AuditService
from security.JwtValidator import JwtValidator
from utils.RequestValidator import RequestValidator

reservation_bp = Blueprint("reservation", __name__)


class ReservationController:

    @staticmethod
    @reservation_bp.route("/api/reservations", methods=["POST"])
    def create_reservation():

        user = JwtValidator.validate(
            request.headers.get("Authorization")
        )

        payload = request.get_json()

        RequestValidator.require_fields(
            payload,
            [
                "productId",
                "quantity"
            ]
        )

        product_id = payload["productId"]
        quantity = payload["quantity"]

        if quantity <= 0:
            return jsonify({
                "error": "Quantity must be greater than zero"
            }), 400

        inventory = InventoryService.get_inventory(
            product_id
        )

        if inventory is None:
            return jsonify({
                "error": "Product not found"
            }), 404

        if inventory["availableQuantity"] < quantity:
            return jsonify({
                "error": "Insufficient inventory"
            }), 409

        reservation = ReservationService.create_reservation(
            user_id=user["userId"],
            product_id=product_id,
            quantity=quantity
        )

        AuditService.record_event(
            event_type="inventory_reserved",
            actor=user["userId"],
            resource_id=product_id,
            metadata={
                "reservationId":
                    reservation["reservationId"],
                "quantity":
                    quantity
            }
        )

        return jsonify({
            "reservationId":
                reservation["reservationId"],
            "productId":
                reservation["productId"],
            "reservedQuantity":
                reservation["quantity"],
            "status":
                reservation["status"]
        }), 201

    @staticmethod
    @reservation_bp.route(
        "/api/reservations/<reservation_id>",
        methods=["GET"]
    )
    def get_reservation(reservation_id):

        user = JwtValidator.validate(
            request.headers.get("Authorization")
        )

        reservation = ReservationService.get_reservation(
            reservation_id
        )

        if reservation is None:
            return jsonify({
                "error": "Reservation not found"
            }), 404

        if reservation["userId"] != user["userId"]:
            return jsonify({
                "error": "Access denied"
            }), 403

        return jsonify(reservation), 200
