from datetime import datetime, timedelta

from repositories.ReservationRepository import ReservationRepository
from repositories.InventoryRepository import InventoryRepository


class ReservationService:

    RESERVATION_EXPIRY_HOURS = 24

    @staticmethod
    def create_reservation(
        user_id,
        product_id,
        quantity
    ):

        inventory = InventoryRepository.get_by_product_id(
            product_id
        )

        if inventory is None:
            raise Exception(
                "Inventory record not found"
            )

        remaining_stock = (
            inventory["availableQuantity"]
            - quantity
        )

        InventoryRepository.update_available_quantity(
            product_id,
            remaining_stock
        )

        reservation = {
            "userId": user_id,
            "productId": product_id,
            "quantity": quantity,
            "reservedQuantity": quantity,
            "status": "ACTIVE",
            "createdAt": datetime.utcnow(),
            "expiresAt": (
                datetime.utcnow()
                + timedelta(
                    hours=ReservationService.
                    RESERVATION_EXPIRY_HOURS
                )
            )
        }

        reservation_id = (
            ReservationRepository.create(
                reservation
            )
        )

        return ReservationRepository.get_by_id(
            reservation_id
        )

    @staticmethod
    def get_reservation(
        reservation_id
    ):

        return (
            ReservationRepository.get_by_id(
                reservation_id
            )
        )

    @staticmethod
    def mark_partially_fulfilled(
        reservation_id,
        shipped_quantity
    ):

        reservation = (
            ReservationRepository.get_by_id(
                reservation_id
            )
        )

        if reservation is None:
            raise Exception(
                "Reservation not found"
            )

        remaining_quantity = (
            reservation["reservedQuantity"]
            - shipped_quantity
        )

        if remaining_quantity < 0:
            raise Exception(
                "Shipment exceeds reservation"
            )

        ReservationRepository.update_reserved_quantity(
            reservation_id,
            remaining_quantity
        )

        if remaining_quantity == 0:

            ReservationRepository.update_status(
                reservation_id,
                "FULFILLED"
            )

    @staticmethod
    def cancel_reservation(
        reservation_id
    ):

        reservation = (
            ReservationRepository.get_by_id(
                reservation_id
            )
        )

        if reservation is None:
            raise Exception(
                "Reservation not found"
            )

        if reservation["status"] not in [
            "ACTIVE",
            "PARTIALLY_FULFILLED"
        ]:
            raise Exception(
                "Reservation cannot be cancelled"
            )

        ReservationRepository.update_status(
            reservation_id,
            "CANCELLED"
        )
