from datetime import datetime

from repositories.ShipmentRepository import ShipmentRepository
from repositories.ReservationRepository import ReservationRepository
from services.ReservationService import ReservationService


class ShipmentService:

    @staticmethod
    def create_shipment(
        reservation_id,
        shipped_quantity,
        warehouse_id
    ):

        reservation = (
            ReservationRepository.get_by_id(
                reservation_id
            )
        )

        if reservation is None:
            raise Exception(
                "Reservation not found"
            )

        if reservation["status"] not in [
            "ACTIVE",
            "PARTIALLY_FULFILLED"
        ]:
            raise Exception(
                "Reservation cannot be shipped"
            )

        remaining_reserved = (
            reservation["reservedQuantity"]
        )

        if shipped_quantity <= 0:
            raise Exception(
                "Invalid shipment quantity"
            )

        if shipped_quantity > remaining_reserved:
            raise Exception(
                "Shipment exceeds reserved quantity"
            )

        shipment = {
            "reservationId": reservation_id,
            "productId": reservation["productId"],
            "quantity": shipped_quantity,
            "warehouseId": warehouse_id,
            "createdAt": datetime.utcnow()
        }

        shipment_id = (
            ShipmentRepository.create(
                shipment
            )
        )

        ReservationService.mark_partially_fulfilled(
            reservation_id,
            shipped_quantity
        )

        updated_reservation = (
            ReservationRepository.get_by_id(
                reservation_id
            )
        )

        if (
            updated_reservation["reservedQuantity"]
            > 0
        ):
            ReservationRepository.update_status(
                reservation_id,
                "PARTIALLY_FULFILLED"
            )

        return ShipmentRepository.get_by_id(
            shipment_id
        )

    @staticmethod
    def get_total_shipped_quantity(
        reservation_id
    ):

        shipments = (
            ShipmentRepository.find_by_reservation(
                reservation_id
            )
        )

        total = 0

        for shipment in shipments:
            total += shipment["quantity"]

        return total

    @staticmethod
    def get_remaining_quantity(
        reservation_id
    ):

        reservation = (
            ReservationRepository.get_by_id(
                reservation_id
            )
        )

        if reservation is None:
            raise Exception(
                "Reservation not found"
            )

        return reservation[
            "reservedQuantity"
        ]
