from datetime import datetime

from repositories.ReservationRepository import ReservationRepository
from repositories.CancellationRepository import CancellationRepository

from services.NotificationService import NotificationService
from services.AuditService import AuditService


class CancellationService:

    CANCELLABLE_STATES = [
        "ACTIVE",
        "PARTIALLY_FULFILLED"
    ]

    @staticmethod
    def cancel_reservation(
        reservation_id,
        user_id,
        reason=None
    ):

        reservation = (
            ReservationRepository.get_by_id(
                reservation_id
            )
        )

        if reservation is None:
            raise Exception(
                "Reservation not found"
            )

        if reservation["userId"] != user_id:
            raise Exception(
                "User does not own reservation"
            )

        if (
            reservation["status"]
            not in CancellationService.
            CANCELLABLE_STATES
        ):
            raise Exception(
                "Reservation cannot be cancelled"
            )

        existing_cancellation = (
            CancellationRepository
            .find_by_reservation(
                reservation_id
            )
        )

        if existing_cancellation:
            raise Exception(
                "Reservation already cancelled"
            )

        cancellation_record = {
            "reservationId":
                reservation_id,

            "productId":
                reservation["productId"],

            "userId":
                reservation["userId"],

            "originalQuantity":
                reservation["quantity"],

            "remainingQuantity":
                reservation[
                    "reservedQuantity"
                ],

            "status":
                "PENDING_RECONCILIATION",

            "reason":
                reason,

            "createdAt":
                datetime.utcnow()
        }

        cancellation_id = (
            CancellationRepository.create(
                cancellation_record
            )
        )

        ReservationRepository.update_status(
            reservation_id,
            "CANCELLED"
        )

        AuditService.record_event(
            event_type=
                "reservation_cancelled",
            actor=user_id,
            resource_id=reservation_id,
            metadata={
                "productId":
                    reservation["productId"],
                "remainingQuantity":
                    reservation[
                        "reservedQuantity"
                    ]
            }
        )

        NotificationService.send_cancellation_email(
            reservation["userId"],
            reservation_id
        )

        return (
            CancellationRepository.get_by_id(
                cancellation_id
            )
        )

    @staticmethod
    def get_pending_reconciliations():

        return (
            CancellationRepository
            .find_by_status(
                "PENDING_RECONCILIATION"
            )
        )
