class ReservationRepository:

    @staticmethod
    def create(reservation):

        query = """
        INSERT INTO reservations
        (
            user_id,
            product_id,
            quantity,
            reserved_quantity,
            status,
            created_at,
            expires_at
        )
        VALUES
        (
            %s,%s,%s,%s,%s,%s,%s
        )
        RETURNING reservation_id
        """

        result = db.execute(
            query,
            [
                reservation["userId"],
                reservation["productId"],
                reservation["quantity"],
                reservation["reservedQuantity"],
                reservation["status"],
                reservation["createdAt"],
                reservation["expiresAt"]
            ]
        )

        return result[0]["reservation_id"]

    @staticmethod
    def get_by_id(
        reservation_id
    ):

        query = """
        SELECT
            reservation_id,
            user_id,
            product_id,
            quantity,
            reserved_quantity,
            status,
            created_at,
            expires_at
        FROM reservations
        WHERE reservation_id = %s
        """

        result = db.execute(
            query,
            [reservation_id]
        )

        if len(result) == 0:
            return None

        row = result[0]

        return {
            "reservationId":
                row["reservation_id"],

            "userId":
                row["user_id"],

            "productId":
                row["product_id"],

            "quantity":
                row["quantity"],

            "reservedQuantity":
                row["reserved_quantity"],

            "status":
                row["status"],

            "createdAt":
                row["created_at"],

            "expiresAt":
                row["expires_at"]
        }

    @staticmethod
    def update_reserved_quantity(
        reservation_id,
        quantity
    ):

        query = """
        UPDATE reservations
        SET reserved_quantity = %s
        WHERE reservation_id = %s
        """

        db.execute(
            query,
            [
                quantity,
                reservation_id
            ]
        )

    @staticmethod
    def update_status(
        reservation_id,
        status
    ):

        query = """
        UPDATE reservations
        SET status = %s
        WHERE reservation_id = %s
        """

        db.execute(
            query,
            [
                status,
                reservation_id
            ]
        )

    @staticmethod
    def get_cancelled_reservations_pending_reconciliation():

        query = """
        SELECT
            reservation_id,
            product_id,
            quantity,
            reserved_quantity
        FROM reservations
        WHERE status = 'CANCELLED'
        """

        rows = db.execute(query)

        results = []

        for row in rows:

            results.append({
                "reservationId":
                    row["reservation_id"],

                "productId":
                    row["product_id"],

                "quantity":
                    row["quantity"],

                "reservedQuantity":
                    row["reserved_quantity"]
            })

        return results
