from database import db


class ShipmentRepository:

    @staticmethod
    def create(shipment):

        query = """
        INSERT INTO shipments
        (
            reservation_id,
            product_id,
            quantity,
            warehouse_id,
            created_at
        )
        VALUES
        (
            %s,%s,%s,%s,%s
        )
        RETURNING shipment_id
        """

        result = db.execute(
            query,
            [
                shipment["reservationId"],
                shipment["productId"],
                shipment["quantity"],
                shipment["warehouseId"],
                shipment["createdAt"]
            ]
        )

        return result[0]["shipment_id"]

    @staticmethod
    def get_by_id(shipment_id):

        query = """
        SELECT
            shipment_id,
            reservation_id,
            product_id,
            quantity,
            warehouse_id,
            created_at
        FROM shipments
        WHERE shipment_id = %s
        """

        result = db.execute(
            query,
            [shipment_id]
        )

        if not result:
            return None

        row = result[0]

        return {
            "shipmentId":
                row["shipment_id"],
            "reservationId":
                row["reservation_id"],
            "productId":
                row["product_id"],
            "quantity":
                row["quantity"],
            "warehouseId":
                row["warehouse_id"],
            "createdAt":
                row["created_at"]
        }

    @staticmethod
    def find_by_reservation(
        reservation_id
    ):

        query = """
        SELECT
            shipment_id,
            reservation_id,
            quantity,
            created_at
        FROM shipments
        WHERE reservation_id = %s
        ORDER BY created_at ASC
        """

        rows = db.execute(
            query,
            [reservation_id]
        )

        shipments = []

        for row in rows:

            shipments.append({
                "shipmentId":
                    row["shipment_id"],
                "reservationId":
                    row["reservation_id"],
                "quantity":
                    row["quantity"],
                "createdAt":
                    row["created_at"]
            })

        return shipments

    @staticmethod
    def get_total_shipped_quantity(
        reservation_id
    ):

        query = """
        SELECT
            COALESCE(
                SUM(quantity),
                0
            ) AS total_shipped
        FROM shipments
        WHERE reservation_id = %s
        """

        result = db.execute(
            query,
            [reservation_id]
        )

        return result[0][
            "total_shipped"
        ]
