from services.ReconciliationService import (
    ReconciliationService
)

from services.AuditService import (
    AuditService
)

from repositories.CancellationRepository import (
    CancellationRepository
)


class ReconciliationWorker:

    BATCH_SIZE = 100

    @staticmethod
    def process_pending_cancellations():

        pending = (
            CancellationRepository
            .find_by_status(
                "PENDING_RECONCILIATION"
            )
        )

        processed = 0

        for cancellation in pending:

            try:

                ReconciliationService.reconcile(
                    cancellation[
                        "reservationId"
                    ]
                )

                CancellationRepository.update_status(
                    cancellation["id"],
                    "RECONCILED"
                )

                AuditService.record_event(
                    event_type=
                        "inventory_reconciled",
                    actor=
                        "system",
                    resource_id=
                        cancellation[
                            "reservationId"
                        ]
                )

                processed += 1

                if (
                    processed >=
                    ReconciliationWorker
                    .BATCH_SIZE
                ):
                    break

            except Exception as ex:

                AuditService.record_event(
                    event_type=
                        "reconciliation_failed",
                    actor=
                        "system",
                    resource_id=
                        cancellation[
                            "reservationId"
                        ],
                    metadata={
                        "error":
                            str(ex)
                    }
                )

    @staticmethod
    def run():

        ReconciliationWorker\
            .process_pending_cancellations()
