from repositories.ReservationRepository import (
    ReservationRepository
)

from repositories.CancellationRepository import (
    CancellationRepository
)

from services.InventoryAdjustmentService import (
    InventoryAdjustmentService
)

from services.AuditService import (
    AuditService
)


class ReconciliationService:

    @staticmethod
    def reconcile(
        reservation_id
    ):

        reservation = (
            ReservationRepository.get_by_id(
                reservation_id
            )
        )

        if reservation is None:
            raise Exception(
                "Reservation not found"
            )

        cancellation = (
            CancellationRepository
            .find_by_reservation(
                reservation_id
            )
        )

        if cancellation is None:
            raise Exception(
                "Cancellation record not found"
            )

        if cancellation["status"] == "RECONCILED":
            raise Exception(
                "Reservation already reconciled"
            )

        if reservation["status"] != "CANCELLED":
            raise Exception(
                "Reservation must be cancelled"
            )

        adjustment = {
            "productId":
                reservation["productId"],

            # BUG: uses original reservation quantity
            # instead of remaining unshipped quantity.
            # Should be reservation["reservedQuantity"].
            "quantity":
                reservation["quantity"],

            "reason":
                "RESERVATION_CANCELLATION",

            "referenceId":
                reservation_id
        }

        InventoryAdjustmentService.apply_adjustment(
            adjustment
        )

        AuditService.record_event(
            event_type=
                "inventory_restored",

            actor=
                "system",

            resource_id=
                reservation_id,

            metadata={
                "productId":
                    reservation["productId"],

                "restoredQuantity":
                    reservation["quantity"]
            }
        )

        return True
