from datetime import datetime

from repositories.InventoryRepository import (
    InventoryRepository
)

from repositories.AdjustmentRepository import (
    AdjustmentRepository
)

from services.AuditService import (
    AuditService
)


class InventoryAdjustmentService:

    VALID_REASONS = [
        "PURCHASE_ORDER",
        "MANUAL_CORRECTION",
        "RESERVATION_CANCELLATION",
        "WAREHOUSE_TRANSFER"
    ]

    @staticmethod
    def apply_adjustment(
        adjustment
    ):

        if (
            adjustment["reason"]
            not in
            InventoryAdjustmentService
            .VALID_REASONS
        ):
            raise Exception(
                "Invalid adjustment reason"
            )

        inventory = (
            InventoryRepository
            .get_by_product_id(
                adjustment["productId"]
            )
        )

        if inventory is None:
            raise Exception(
                "Inventory not found"
            )

        previous_quantity = (
            inventory[
                "availableQuantity"
            ]
        )

        updated_quantity = (
            previous_quantity
            +
            adjustment["quantity"]
        )

        InventoryRepository.update_available_quantity(
            adjustment["productId"],
            updated_quantity
        )

        AdjustmentRepository.create(
            {
                "productId":
                    adjustment["productId"],

                "quantity":
                    adjustment["quantity"],

                "reason":
                    adjustment["reason"],

                "referenceId":
                    adjustment["referenceId"],

                "createdAt":
                    datetime.utcnow()
            }
        )

        AuditService.record_event(
            event_type=
                "inventory_adjusted",

            actor=
                "system",

            resource_id=
                adjustment["productId"],

            metadata={
                "oldQuantity":
                    previous_quantity,

                "newQuantity":
                    updated_quantity,

                "change":
                    adjustment["quantity"]
            }
        )

        return {
            "productId":
                adjustment["productId"],

            "previousQuantity":
                previous_quantity,

            "currentQuantity":
                updated_quantity
        }
