from repositories.InventoryRepository import (
    InventoryRepository
)

from repositories.ShipmentRepository import (
    ShipmentRepository
)


class ForecastService:

    FORECAST_DAYS = 30

    @staticmethod
    def forecast_inventory(
        product_id
    ):

        inventory = (
            InventoryRepository
            .get_by_product_id(
                product_id
            )
        )

        if inventory is None:
            return None

        shipped = (
            ShipmentRepository
            .get_total_shipped_last_n_days(
                product_id,
                ForecastService
                .FORECAST_DAYS
            )
        )

        average_daily_usage = (
            shipped /
            ForecastService
            .FORECAST_DAYS
        )

        projected_days_remaining = 0

        if average_daily_usage > 0:

            projected_days_remaining = (
                inventory[
                    "availableQuantity"
                ]
                /
                average_daily_usage
            )

        return {
            "productId":
                product_id,

            "averageDailyUsage":
                round(
                    average_daily_usage,
                    2
                ),

            "daysRemaining":
                round(
                    projected_days_remaining,
                    2
                )
        }
