using System;
using System.Collections.Generic;
using System.Linq;

namespace capability
{
    /// <summary>
    /// .NET-side representation of the runtime capability contract
    /// emitted by the capability projection service. This mirrors the
    /// wire schema field-for-field; see CapabilityProjectionService
    /// for the authoritative field list and the rationale behind what
    /// was excluded from the canonical approval record.
    ///
    /// Deliberately absent from this type: capability id, approval
    /// status, revocation status, department scoping, and expiration.
    /// Those are policy-time concerns already enforced before a
    /// capability is ever projected, and re-checking them here would
    /// require this service to stay in lockstep with every change to
    /// the approval schema.
    /// </summary>
    public sealed class RuntimeCapability
    {
        public string ToolId { get; init; } = string.Empty;
        public int CapabilityRevision { get; init; }
        public string ApprovalId { get; init; } = string.Empty;
        public IReadOnlyList<string> AllowedArguments { get; init; } = Array.Empty<string>();
        public string Environment { get; init; } = string.Empty;
        public DateTimeOffset ProjectedAt { get; init; }

        public bool AllowsArgument(string name) =>
            AllowedArguments.Contains(name, StringComparer.OrdinalIgnoreCase);

        public static RuntimeCapability FromWireContract(RuntimeCapabilityWireModel wire)
        {
            if (wire is null)
            {
                throw new ArgumentNullException(nameof(wire));
            }

            return new RuntimeCapability
            {
                ToolId = wire.ToolId,
                CapabilityRevision = wire.CapabilityRevision,
                ApprovalId = wire.ApprovalId,
                AllowedArguments = wire.AllowedArguments ?? Array.Empty<string>(),
                Environment = wire.Environment,
                ProjectedAt = string.IsNullOrEmpty(wire.ProjectedAt)
                    ? DateTimeOffset.UtcNow
                    : DateTimeOffset.Parse(wire.ProjectedAt)
            };
        }
    }

    /// <summary>
    /// Raw deserialization shape for the JSON payload received from
    /// the capability projection service. Kept separate from
    /// <see cref="RuntimeCapability"/> so that wire-format quirks
    /// (nullable lists, string timestamps) don't leak into the type
    /// the rest of the scheduler works with.
    /// </summary>
    public sealed class RuntimeCapabilityWireModel
    {
        public string ToolId { get; set; } = string.Empty;
        public int CapabilityRevision { get; set; }
        public string ApprovalId { get; set; } = string.Empty;
        public List<string>? AllowedArguments { get; set; }
        public string Environment { get; set; } = string.Empty;
        public string ProjectedAt { get; set; } = string.Empty;
    }
}
