"""
ExecutionPlanner
----------------
Compiles an approved capability and the caller's tool execution
request into an ExecutionPlan, then hands the compiled plan to the
runtime scheduler for asynchronous execution.

This service sits between policy approval and runtime execution. It
does not make authorization decisions -- that already happened in
PolicyApprovalService -- its job is purely to shape approved intent
into the execution contract the scheduler understands.
"""

from __future__ import annotations

import time
import uuid
from dataclasses import dataclass, field
from typing import Any, Protocol


@dataclass(frozen=True)
class RuntimeCapability:
    """
    Python-side mirror of the runtime capability contract produced by
    the capability projection service. The projection service is
    implemented natively for performance and is reached through a
    thin binding; this dataclass is simply the local, idiomatic view
    of the payload it returns.
    """

    tool_id: str
    capability_revision: int
    approval_id: str
    allowed_arguments: list[str]
    environment: str
    projected_at: str


class CapabilityProjectionService(Protocol):
    """Dependency boundary onto the capability projection service."""

    def project(self, approved_capability: dict[str, Any]) -> RuntimeCapability: ...


class ExecutionSchedulerClient(Protocol):
    """Dependency boundary onto the runtime scheduler."""

    def enqueue(self, plan: "ExecutionPlan") -> str: ...


class PlanCompilationError(Exception):
    pass


@dataclass(frozen=True)
class ToolExecutionRequest:
    tool_id: str
    environment: str
    justification: str
    parameters: list[dict[str, str]]
    requested_by: str


@dataclass(frozen=True)
class ExecutionPlan:
    plan_id: str
    tool_id: str
    environment: str
    requested_by: str
    justification: str
    arguments: dict[str, str]
    runtime_capability: RuntimeCapability
    created_at: float = field(default_factory=time.time)


@dataclass(frozen=True)
class Execution:
    execution_id: str
    status: str
    created_at: float


class ExecutionPlanner:
    """
    Coordinates the compile -> validate -> enqueue pipeline that turns
    an approved capability into a scheduled execution.
    """

    def __init__(
        self,
        projection_service: CapabilityProjectionService,
        scheduler_client: ExecutionSchedulerClient,
    ) -> None:
        self._projection_service = projection_service
        self._scheduler_client = scheduler_client

    def create_execution(
        self,
        approved_capability: dict[str, Any],
        request: ToolExecutionRequest,
    ) -> Execution:

        runtime_capability = self._compile_runtime_capability(approved_capability)

        plan = self._build_plan(runtime_capability, request)

        self._validate_plan(plan)

        execution_id = self._scheduler_client.enqueue(plan)

        return Execution(
            execution_id=execution_id,
            status="QUEUED",
            created_at=time.time(),
        )

    def _compile_runtime_capability(
        self,
        approved_capability: dict[str, Any],
    ) -> RuntimeCapability:
        """
        Delegates projection of the canonical approval record into the
        reduced runtime contract. The planner never inspects
        policy-time fields (approval status, department scoping,
        expiry) directly -- those concerns belong to the approval and
        projection services, and duplicating those checks here would
        risk the two services drifting out of sync as policy evolves.
        """
        return self._projection_service.project(approved_capability)

    def _build_plan(
        self,
        runtime_capability: RuntimeCapability,
        request: ToolExecutionRequest,
    ) -> ExecutionPlan:

        arguments = {
            parameter["name"]: parameter["value"] for parameter in request.parameters
        }

        return ExecutionPlan(
            plan_id=str(uuid.uuid4()),
            tool_id=runtime_capability.tool_id,
            environment=runtime_capability.environment,
            requested_by=request.requested_by,
            justification=request.justification,
            arguments=arguments,
            runtime_capability=runtime_capability,
        )

    def _validate_plan(self, plan: ExecutionPlan) -> None:
        """
        Confirms the compiled plan only references arguments the
        runtime capability actually allows, and that the plan's tool
        id agrees with the capability it was compiled from. This
        protects against a caller supplying extra parameters that were
        never part of the approved schema; it is not a re-check of
        authorization, which is out of scope for this stage.
        """

        allowed = set(plan.runtime_capability.allowed_arguments)
        supplied = set(plan.arguments.keys())

        unexpected = supplied - allowed

        if unexpected:
            raise PlanCompilationError(
                f"plan references arguments outside the approved schema: {sorted(unexpected)}"
            )

        if plan.tool_id != plan.runtime_capability.tool_id:
            raise PlanCompilationError(
                "plan tool_id does not match the compiled runtime capability"
            )

        if plan.environment != plan.runtime_capability.environment:
            raise PlanCompilationError(
                "plan environment does not match the compiled runtime capability"
            )
