using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

using capability;
using runtime;
using audit;

namespace scheduler
{
    /// <summary>
    /// A compiled unit of work handed off by ExecutionPlanner. This is
    /// the runtime scheduler's own view of a plan -- it carries the
    /// projected RuntimeCapability plus the request-scoped fields
    /// needed for dispatch and audit.
    /// </summary>
    public sealed class ExecutionPlan
    {
        public string PlanId { get; init; } = string.Empty;
        public string ToolId { get; init; } = string.Empty;
        public string Environment { get; init; } = string.Empty;
        public string RequestedBy { get; init; } = string.Empty;
        public string Justification { get; init; } = string.Empty;
        public IReadOnlyDictionary<string, string> Arguments { get; init; } =
            new Dictionary<string, string>();
        public RuntimeCapability RuntimeCapability { get; init; } = default!;
        public DateTimeOffset CreatedAt { get; init; }
    }

    /// <summary>
    /// Orchestrates the second half of the execution pipeline: pulling
    /// compiled plans off the internal queue, resolving which provider
    /// should service the tool, dispatching the invocation, and
    /// recording the outcome.
    ///
    /// This service is intentionally decoupled from the approval and
    /// projection stages -- it operates purely on the runtime contract
    /// it receives and does not re-derive anything the earlier stages
    /// already decided. Provider selection, in particular, is entirely
    /// delegated to ProviderResolver; the scheduler treats whatever
    /// provider comes back as authoritative.
    /// </summary>
    public sealed class ExecutionScheduler
    {
        private readonly BlockingCollection<ExecutionPlan> _queue = new();
        private readonly ProviderResolver _providerResolver;
        private readonly ExecutionDispatcher _dispatcher;
        private readonly AuditRecorder _auditRecorder;

        public ExecutionScheduler(
            ProviderResolver providerResolver,
            ExecutionDispatcher dispatcher,
            AuditRecorder auditRecorder)
        {
            _providerResolver = providerResolver;
            _dispatcher = dispatcher;
            _auditRecorder = auditRecorder;
        }

        /// <summary>
        /// Accepts a compiled plan from ExecutionPlanner and queues it
        /// for asynchronous processing. Returns immediately so the
        /// gateway can respond to the caller without waiting on
        /// provider resolution or dispatch.
        /// </summary>
        public string Enqueue(ExecutionPlan plan)
        {
            ValidatePlanShape(plan);
            _queue.Add(plan);
            return plan.PlanId;
        }

        public async Task RunAsync(CancellationToken cancellationToken)
        {
            foreach (var plan in _queue.GetConsumingEnumerable(cancellationToken))
            {
                await ProcessAsync(plan, cancellationToken);
            }
        }

        private async Task ProcessAsync(ExecutionPlan plan, CancellationToken cancellationToken)
        {
            var startedAt = DateTimeOffset.UtcNow;

            ResolvedProvider provider;

            try
            {
                provider = _providerResolver.ResolveProvider(plan.RuntimeCapability);
            }
            catch (ProviderResolutionException ex)
            {
                _auditRecorder.RecordFailure(
                    planId: plan.PlanId,
                    toolId: plan.ToolId,
                    approvalId: plan.RuntimeCapability.ApprovalId,
                    capabilityRevision: plan.RuntimeCapability.CapabilityRevision,
                    requestedBy: plan.RequestedBy,
                    justification: plan.Justification,
                    reason: ex.Message,
                    startedAt: startedAt,
                    completedAt: DateTimeOffset.UtcNow);
                return;
            }

            var outcome = await _dispatcher.DispatchAsync(plan, provider, cancellationToken);

            if (outcome.Success)
            {
                _auditRecorder.RecordCompletion(
                    planId: plan.PlanId,
                    toolId: plan.ToolId,
                    approvalId: plan.RuntimeCapability.ApprovalId,
                    capabilityRevision: plan.RuntimeCapability.CapabilityRevision,
                    requestedBy: plan.RequestedBy,
                    justification: plan.Justification,
                    executedProviderId: provider.ProviderId,
                    executedEndpoint: provider.Endpoint,
                    resolvedVia: provider.ResolvedVia,
                    startedAt: startedAt,
                    completedAt: DateTimeOffset.UtcNow);
            }
            else
            {
                _auditRecorder.RecordFailure(
                    planId: plan.PlanId,
                    toolId: plan.ToolId,
                    approvalId: plan.RuntimeCapability.ApprovalId,
                    capabilityRevision: plan.RuntimeCapability.CapabilityRevision,
                    requestedBy: plan.RequestedBy,
                    justification: plan.Justification,
                    reason: outcome.ErrorMessage,
                    startedAt: startedAt,
                    completedAt: DateTimeOffset.UtcNow);
            }
        }

        /// <summary>
        /// Basic shape validation before a plan enters the queue. This
        /// mirrors the planner's own validation as a safety net in
        /// case this scheduler is ever invoked from a path other than
        /// ExecutionPlanner, such as a manual replay tool used during
        /// incident response.
        /// </summary>
        private static void ValidatePlanShape(ExecutionPlan plan)
        {
            if (string.IsNullOrWhiteSpace(plan.PlanId))
                throw new ArgumentException("plan is missing an identifier.");

            if (plan.RuntimeCapability is null)
                throw new ArgumentException("plan is missing its runtime capability.");

            if (string.IsNullOrWhiteSpace(plan.RuntimeCapability.ToolId))
                throw new ArgumentException("runtime capability is missing a tool id.");

            if (string.IsNullOrWhiteSpace(plan.RuntimeCapability.ApprovalId))
                throw new ArgumentException("runtime capability is missing an approval id.");

            if (plan.RuntimeCapability.CapabilityRevision <= 0)
                throw new ArgumentException("runtime capability has an invalid revision.");
        }
    }
}
