```
#include <chrono>
#include <string>
#include <thread>
#include <unordered_map>

#include "ExecutionPlan.h"   // ExecutionPlan (mirrors scheduler.ExecutionPlan)
#include "ResolvedProvider.h" // ResolvedProvider (mirrors runtime.ResolvedProvider)
#include "McpGateway.h"      // McpGateway::invoke(...)

namespace runtime {

struct DispatchOutcome {
    bool success;
    std::string providerResponseId;
    std::string errorMessage;
    int attempts;
};

/**
 * Executes a resolved plan against whichever provider the runtime
 * layer selected.
 *
 * This component does not make routing decisions -- it trusts the
 * ResolvedProvider it is handed and focuses purely on reliable
 * delivery: retrying transient provider errors with backoff, and
 * surfacing a structured outcome for the audit stage. Arguments are
 * forwarded exactly as approved; no argument transformation happens
 * at this layer, keeping the dispatcher agnostic to individual tool
 * semantics.
 */
class ExecutionDispatcher {
public:
    explicit ExecutionDispatcher(McpGateway& gateway, int maxAttempts = 3)
        : gateway_(gateway), maxAttempts_(maxAttempts) {}

    DispatchOutcome dispatch(const ExecutionPlan& plan, const ResolvedProvider& provider) {

        validate(plan, provider);

        McpToolInvocation invocation = buildInvocation(plan, provider);

        int attempts = 0;
        std::string lastError;

        while (attempts < maxAttempts_) {

            attempts++;

            McpInvocationResult result = gateway_.invoke(invocation);

            if (result.success) {
                return DispatchOutcome{
                    true,
                    result.responseId,
                    "",
                    attempts
                };
            }

            lastError = result.errorMessage;

            if (!result.retryable) {
                break;
            }

            std::this_thread::sleep_for(backoffDelay(attempts));

        }

        return DispatchOutcome{
            false,
            "",
            lastError,
            attempts
        };

    }

private:
    McpGateway& gateway_;
    int maxAttempts_;

    void validate(const ExecutionPlan& plan, const ResolvedProvider& provider) const {

        if (plan.toolId.empty()) {
            throw std::invalid_argument("execution plan is missing a tool id");
        }

        if (provider.providerId.empty() || provider.endpoint.empty()) {
            throw std::invalid_argument("resolved provider is missing routing information");
        }

    }

    /**
     * Translates the internal execution plan into the wire shape the
     * MCP gateway expects. The dispatcher addresses the invocation
     * purely by the resolved provider's endpoint; it has no way to
     * compare that endpoint against whichever provider the approval
     * service originally authorized, since that information is not
     * part of the execution plan it receives.
     */
    McpToolInvocation buildInvocation(const ExecutionPlan& plan, const ResolvedProvider& provider) const {

        McpToolInvocation invocation;
        invocation.toolId = plan.toolId;
        invocation.providerEndpoint = provider.endpoint;
        invocation.arguments = plan.arguments;
        invocation.correlationId = plan.planId;

        return invocation;

    }

    std::chrono::milliseconds backoffDelay(int attempt) const {
        return std::chrono::milliseconds(200 * attempt);
    }

};

} // namespace runtime
