package runtime

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"time"
)

// ToolInvocation is the payload sent to a provider's MCP endpoint.
type ToolInvocation struct {
	ToolID           string            `json:"toolId"`
	CorrelationID    string            `json:"correlationId"`
	Arguments        map[string]string `json:"arguments"`
	ProviderEndpoint string            `json:"-"`
}

// InvocationResult describes the outcome reported by a provider.
type InvocationResult struct {
	Success      bool   `json:"success"`
	ResponseID   string `json:"responseId"`
	ErrorMessage string `json:"errorMessage"`
	Retryable    bool   `json:"retryable"`
}

// McpGateway is the transport layer between the platform and every
// MCP-compatible provider (AWS, Azure, Kubernetes, Disaster Recovery,
// and any future provider onboarded to the tool catalog).
//
// This gateway has no knowledge of which provider was approved versus
// which provider was resolved by the runtime routing layer -- it
// simply delivers the invocation to whichever endpoint it is given.
// That separation is intentional: the gateway's job is uniform,
// reliable MCP transport, not policy enforcement.
type McpGateway struct {
	client *http.Client
}

func NewMcpGateway() *McpGateway {
	return &McpGateway{
		client: &http.Client{
			Timeout: 15 * time.Second,
		},
	}
}

func (g *McpGateway) Invoke(
	ctx context.Context,
	invocation ToolInvocation,
) (InvocationResult, error) {

	body, err := json.Marshal(invocation)
	if err != nil {
		return InvocationResult{}, fmt.Errorf("encoding invocation: %w", err)
	}

	url := fmt.Sprintf("%s/mcp/v1/tools/invoke", invocation.ProviderEndpoint)

	req, err := http.NewRequestWithContext(
		ctx,
		http.MethodPost,
		url,
		bytes.NewReader(body),
	)
	if err != nil {
		return InvocationResult{}, fmt.Errorf("building request: %w", err)
	}

	req.Header.Set("Content-Type", "application/json")

	resp, err := g.client.Do(req)
	if err != nil {
		return InvocationResult{
			Success:      false,
			ErrorMessage: err.Error(),
			Retryable:    true,
		}, nil
	}
	defer resp.Body.Close()

	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		return InvocationResult{}, fmt.Errorf("reading response: %w", err)
	}

	if resp.StatusCode >= http.StatusInternalServerError {
		return InvocationResult{
			Success:      false,
			ErrorMessage: string(raw),
			Retryable:    true,
		}, nil
	}

	if resp.StatusCode >= http.StatusBadRequest {
		return InvocationResult{
			Success:      false,
			ErrorMessage: string(raw),
			Retryable:    false,
		}, nil
	}

	var result InvocationResult
	if err := json.Unmarshal(raw, &result); err != nil {
		return InvocationResult{}, fmt.Errorf("decoding provider response: %w", err)
	}

	return result, nil

}
