import React, { useMemo, useState } from "react";

interface ToolParameter {
    name: string;
    value: string;
}

interface ToolExecutionRequest {
    toolId: string;
    environment: string;
    justification: string;
    parameters: ToolParameter[];
}

const AVAILABLE_TOOLS = [
    "restart-service",
    "scale-deployment",
    "restart-pod",
    "run-backup",
    "invalidate-cache",
    "flush-queue"
];

const ENVIRONMENTS = [
    "development",
    "staging",
    "production"
];

export default function UserRequest() {

    const [toolId, setToolId] =
        useState("restart-service");

    const [environment, setEnvironment] =
        useState("staging");

    const [justification, setJustification] =
        useState("");

    const [parameters, setParameters] =
        useState<ToolParameter[]>([
            {
                name: "service",
                value: ""
            }
        ]);

    const [loading, setLoading] =
        useState(false);

    const [response, setResponse] =
        useState<string | null>(null);

    const requestPayload = useMemo<ToolExecutionRequest>(() => {

        return {
            toolId,
            environment,
            justification,
            parameters
        };

    }, [
        toolId,
        environment,
        justification,
        parameters
    ]);

    const updateParameter = (
        index: number,
        key: keyof ToolParameter,
        value: string
    ) => {

        const copy = [...parameters];

        copy[index] = {
            ...copy[index],
            [key]: value
        };

        setParameters(copy);

    };

    const addParameter = () => {

        setParameters(previous => [

            ...previous,

            {
                name: "",
                value: ""
            }

        ]);

    };

    const removeParameter = (
        index: number
    ) => {

        if (parameters.length == 1)
            return;

        setParameters(previous =>
            previous.filter((_, i) => i !== index)
        );

    };

    const submitRequest = async () => {

        setLoading(true);

        setResponse(null);

        try {

            const res = await fetch(
                "/api/v1/tools/execute",
                {
                    method: "POST",
                    headers: {
                        "Content-Type":
                            "application/json"
                    },
                    body: JSON.stringify(
                        requestPayload
                    )
                }
            );

            const body = await res.json();

            if (!res.ok)
                throw new Error(
                    body.error ??
                    "Execution failed."
                );

            setResponse(
                body.executionId
            );

        } catch (err: any) {

            setResponse(
                err.message
            );

        } finally {

            setLoading(false);

        }

    };

    return (

        <div
            style={{
                maxWidth: "900px",
                margin: "40px auto",
                fontFamily: "sans-serif"
            }}
        >

            <h2>

                AI Operations Platform

            </h2>

            <p>

                Submit an approved tool request
                for autonomous execution.

            </p>

            <div>

                <label>

                    Tool

                </label>

                <br />

                <select
                    value={toolId}
                    onChange={e =>
                        setToolId(
                            e.target.value
                        )
                    }
                >

                    {

                        AVAILABLE_TOOLS.map(tool => (

                            <option
                                key={tool}
                                value={tool}
                            >

                                {tool}

                            </option>

                        ))

                    }

                </select>

            </div>

            <br />

            <div>

                <label>

                    Environment

                </label>

                <br />

                <select
                    value={environment}
                    onChange={e =>
                        setEnvironment(
                            e.target.value
                        )
                    }
                >

                    {

                        ENVIRONMENTS.map(env => (

                            <option
                                key={env}
                                value={env}
                            >

                                {env}

                            </option>

                        ))

                    }

                </select>

            </div>

            <br />

            <div>

                <label>

                    Business Justification

                </label>

                <br />

                <textarea
                    rows={4}
                    style={{
                        width: "100%"
                    }}
                    value={justification}
                    onChange={e =>
                        setJustification(
                            e.target.value
                        )
                    }
                />

            </div>

            <br />

            <h3>

                Parameters

            </h3>

            {

                parameters.map(
                    (
                        parameter,
                        index
                    ) => (

                        <div
                            key={index}
                            style={{
                                display: "flex",
                                gap: "12px",
                                marginBottom: "12px"
                            }}
                        >

                            <input
                                placeholder="Parameter"
                                value={parameter.name}
                                onChange={e =>
                                    updateParameter(
                                        index,
                                        "name",
                                        e.target.value
                                    )
                                }
                            />

                            <input
                                placeholder="Value"
                                value={parameter.value}
                                onChange={e =>
                                    updateParameter(
                                        index,
                                        "value",
                                        e.target.value
                                    )
                                }
                            />

                            <button
                                onClick={() =>
                                    removeParameter(
                                        index
                                    )
                                }
                            >

                                Remove

                            </button>

                        </div>

                    )

                )

            }

            <button
                onClick={addParameter}
            >

                Add Parameter

            </button>

            <br />
            <br />

            <button
                disabled={loading}
                onClick={submitRequest}
            >

                {

                    loading
                        ? "Submitting..."
                        : "Submit Request"

                }

            </button>

            {

                response &&

                <>

                    <hr />

                    <strong>

                        Response

                    </strong>

                    <pre>

                        {response}

                    </pre>

                </>

            }

        </div>

    );

}
