package policy

import authorization.AuthorizationDecision

class RuntimePolicyBuilder {

    fun build(
        decision: AuthorizationDecision
    ): RuntimePolicy {

        val runtimePolicy = RuntimePolicy()

        runtimePolicy.policyId =
            decision.policyId

        runtimePolicy.policyGeneration =
            decision.policyGeneration

        runtimePolicy.resourceScope =
            decision.resourceScope

        runtimePolicy.allowedCapabilities =
            decision.capabilitySet

        runtimePolicy.runtimePolicyKey =
            runtimePolicy.policyId

        runtimePolicy.createdBy = "policy-service"

        runtimePolicy.active = true

        runtimePolicy.version = 1

        return runtimePolicy
    }
}
