package policy

class RuntimePolicy {

    var policyId: String = ""

    var policyGeneration: Long = 0

    var resourceScope: String = ""

    var allowedCapabilities: Set<String> = emptySet()

    var runtimePolicyKey: String = ""

    var createdBy: String = ""

    var version: Int = 1

    var active: Boolean = true

    fun allows(capability: String): Boolean {
        return allowedCapabilities.contains(capability)
    }

    override fun toString(): String {
        return "RuntimePolicy(" +
                "policyId='$policyId', " +
                "policyGeneration=$policyGeneration, " +
                "resourceScope='$resourceScope', " +
                "runtimePolicyKey='$runtimePolicyKey', " +
                "allowedCapabilities=$allowedCapabilities" +
