class RuntimeAuthorizationContext {

    constructor() {
        this.subjectId = "";
        this.resourceScope = "";
        this.capabilitySet = [];
        this.policyId = "";
        this.policyGeneration = 0;
        this.runtimePolicyKey = "";
        this.active = false;
        this.createdAt = new Date();
    }

    hasCapability(capability) {
        return this.capabilitySet.includes(capability);
    }

    isActive() {
        return this.active;
    }

    toJSON() {
        return {
            subjectId: this.subjectId,
            resourceScope: this.resourceScope,
            capabilitySet: this.capabilitySet,
            policyId: this.policyId,
            policyGeneration: this.policyGeneration,
            runtimePolicyKey: this.runtimePolicyKey,
            active: this.active,
            createdAt: this.createdAt
        };
    }
}

