class InvoiceService {

    constructor(invoiceRepository) {
        this.invoiceRepository = invoiceRepository;
    }

    async listInvoices(context) {
        this.ensureCapability(context, "invoice.read");
        return await this.invoiceRepository.findByScope(context.resourceScope);
    }

    async getInvoice(context, invoiceId) {
        this.ensureCapability(context, "invoice.read");
        return await this.invoiceRepository.findOne(invoiceId, context.resourceScope);
    }

    async createInvoice(context, body) {
        this.ensureCapability(context, "invoice.write");
        const invoice = {
            invoiceId: body.invoiceId,
            customerId: body.customerId,
            amount: body.amount,
            currency: body.currency,
            resourceScope: context.resourceScope,
            createdBy: context.subjectId,
            createdAt: new Date()
        };
        return await this.invoiceRepository.save(invoice);
    }

    async updateInvoice(context, body) {
        this.ensureCapability(context, "invoice.write");
        return await this.invoiceRepository.update(body.invoiceId, context.resourceScope, body);
    }

    async deleteInvoice(context, invoiceId) {
        this.ensureCapability(context, "invoice.delete");
        return await this.invoiceRepository.delete(invoiceId, context.resourceScope);
    }

    ensureCapability(context, capability) {
        if (!context) {
            throw new Error("Missing authorization context.");
        }
        if (!context.active) {
            throw new Error("Inactive authorization context.");
        }
        if (!context.hasCapability(capability)) {
            throw new Error("Missing capability: " + capability);
        }
    }
}

module.exports = InvoiceService;
