package gateway

import (
	"errors"
	"net/http"

	"enterprise-api-platform/runtime"
	"enterprise-api-platform/services"
)

// RequestRouter dispatches already-authorized requests
// to downstream business services.
//
// Responsibilities:
//   - Route requests
//   - Invoke business services
//
// It intentionally performs NO authentication,
// authorization or permission checks.
type RequestRouter struct {
	invoiceService *services.InvoiceService
}

func NewRequestRouter(
	invoiceService *services.InvoiceService,
) *RequestRouter {

	return &RequestRouter{
		invoiceService: invoiceService,
	}
}

func (r *RequestRouter) Route(
	ctx *runtime.RuntimeAuthorizationContext,
	req *http.Request,
) (interface{}, error) {

	switch req.URL.Path {

	case "/api/invoices":

		switch req.Method {

		case http.MethodGet:
			return r.invoiceService.ListInvoices(ctx)

		case http.MethodPost:
			return r.invoiceService.CreateInvoice(ctx, req.Body)

		case http.MethodPut:
			return r.invoiceService.UpdateInvoice(ctx, req.Body)

		case http.MethodDelete:
			return r.invoiceService.DeleteInvoice(ctx)

		default:
			return nil, errors.New("unsupported HTTP method")
		}

	default:
		return nil, errors.New("unknown endpoint")
	}
}
