package security

import authorization.AuthorizationRecord

class PolicyValidator {

    fun validate(record: AuthorizationRecord?) {

        require(record != null) { "Authorization policy not found." }

        require(record.subjectId.isNotBlank()) { "Subject identifier is missing." }

        require(record.resourceScope.isNotBlank()) { "Resource scope is missing." }

        require(record.policyId.isNotBlank()) { "Policy identifier is missing." }

        require(record.policyGeneration > 0) { "Invalid policy generation." }

        require(record.allowed) { "Authorization denied." }

        require(record.capabilitySet.isNotEmpty()) { "Capability set cannot be empty." }
    }
}
