// runtime/AuthorizationDispatcher.js

/**
 * AuthorizationDispatcher
 *
 * ------------------------------------------------------------------
 * Responsibilities
 * ------------------------------------------------------------------
 * - Receive a fully constructed RuntimeAuthorizationContext.
 * - Perform basic runtime validation.
 * - Forward authorized requests to the appropriate business service.
 *
 * IMPORTANT
 * ------------------------------------------------------------------
 * This component performs NO authorization decisions.
 *
 * Authorization has already been completed by:
 *
 *      PolicyEngine
 *              ↓
 *      CapabilityProjectionService
 *              +
 *      RuntimePolicyBuilder
 *              ↓
 *      GatewayMergeService
 *
 * This dispatcher simply trusts the RuntimeAuthorizationContext.
 *
 * There is NO vulnerability in this file.
 */

class AuthorizationDispatcher {

    constructor(requestRouter) {
        this.requestRouter = requestRouter;
    }

    /**
     * Dispatch an already-authorized request.
     */
    dispatch(context, request) {

        if (!context) {
            throw new Error("Missing authorization context.");
        }

        if (!context.isActive()) {
            throw new Error("Authorization context is inactive.");
        }

        if (!request) {
            throw new Error("Missing request.");
        }

        return this.requestRouter.route(
            context,
            request
        );
    }

    /**
     * Convenience wrapper for forwarding
     * multiple requests using the same
     * RuntimeAuthorizationContext.
     */
    dispatchBatch(context, requests) {

        if (!Array.isArray(requests)) {
            throw new Error("Request batch expected.");
        }

        return requests.map(request =>
            this.dispatch(context, request)
        );
    }
}

module.exports = AuthorizationDispatcher;
```

