    let mut token = CapabilityToken::new();
    token.set_subject_id(decision.get_subject_id().to_string());
    token.set_capability_set(decision.get_capability_set().clone());
    token.set_policy_id(decision.get_policy_id().to_string());
    token.set_policy_generation(decision.get_policy_generation());
