package com.acme.logplatform.worker;

import java.util.List;

import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import com.acme.logplatform.model.DiagnosticJob;
import com.acme.logplatform.repository.JobRepository;
import com.acme.logplatform.util.CommandBuilder;

@Component
public class DiagnosticWorker {

    private final JobRepository repository;

    private final CommandBuilder builder;

    public DiagnosticWorker(
        JobRepository repository,
        CommandBuilder builder
    ) {
        this.repository = repository;
        this.builder = builder;
    }

    @Scheduled(fixedDelay = 10000)
    public void processJobs() throws Exception {

        List<DiagnosticJob> jobs =
            repository.findPending();

        for (DiagnosticJob job : jobs) {

            String command =
                builder.build(
                    job.getHostname()
                );

            new ProcessBuilder(
                "/bin/sh",
                "-c",
                command
            ).start();

            job.setStatus("COMPLETED");
            repository.save(job);
        }
    }
}
