```
import Foundation

public final class ApprovedRobotProgram {

    // MARK: - Identity

    private let submissionId: String

    private let programId: String

    private let workcellId: String

    // MARK: - Approved Safety Context

    private let safetyGeneration: String

    // MARK: - Robot Program

    private let motionGraph: [String]

    private let toolProfile: String

    // MARK: - Metadata

    private let approvalTimestamp: Date

    public init(

        submissionId: String,

        programId: String,

        workcellId: String,

        safetyGeneration: String,

        motionGraph: [String],

        toolProfile: String,

        approvalTimestamp: Date

    ) throws {

        guard !submissionId.isEmpty else {

            throw ValidationError.invalidSubmissionId

        }

        guard !programId.isEmpty else {

            throw ValidationError.invalidProgramId

        }

        guard !workcellId.isEmpty else {

            throw ValidationError.invalidWorkcellId

        }

        guard !safetyGeneration.isEmpty else {

            throw ValidationError.invalidSafetyGeneration

        }

        guard !motionGraph.isEmpty else {

            throw ValidationError.emptyMotionGraph

        }

        guard !toolProfile.isEmpty else {

            throw ValidationError.invalidToolProfile

        }

        self.submissionId =

            submissionId

        self.programId =

            programId

        self.workcellId =

            workcellId

        self.safetyGeneration =

            safetyGeneration

        self.motionGraph =

            motionGraph

        self.toolProfile =

            toolProfile

        self.approvalTimestamp =

            approvalTimestamp

    }

