import Foundation

public final class SafetyConfigurationRepository {

    // MARK: - Safety Configuration

    public struct SafetyConfiguration {

        private let workcellId: String

        private let generation: String

        private let speedLimit: Double

        private let torqueLimit: Double

        private let collisionProfile: String

        private let approvalTimestamp: Date

        public init(

            workcellId: String,

            generation: String,

            speedLimit: Double,

            torqueLimit: Double,

            collisionProfile: String,

            approvalTimestamp: Date

        ) {

            self.workcellId =

                workcellId

            self.generation =

                generation

            self.speedLimit =

                speedLimit

            self.torqueLimit =

                torqueLimit

            self.collisionProfile =

                collisionProfile

            self.approvalTimestamp =

                approvalTimestamp

        }

        public func workcellId() -> String {

            workcellId

        }

        public func generation() -> String {

            generation

        }

        public func speedLimit() -> Double {

            speedLimit

        }

        public func torqueLimit() -> Double {

            torqueLimit

        }

        public func collisionProfile() -> String {

            collisionProfile

        }

        public func approvalTimestamp() -> Date {

            approvalTimestamp

        }

    }

    // MARK: - Repository Storage

    private var approvedConfigurations:

        [String: SafetyConfiguration]

    public init() {

        approvedConfigurations = [:]

    }

    // MARK: - Repository Operations

    public func register(

        _ configuration: SafetyConfiguration

    ) {

        approvedConfigurations[

            configuration.workcellId()

        ] = configuration

    }

    /*
        Returns the currently approved safety configuration for the
        requested workcell.

        Submission services use this configuration to construct the
        immutable ApprovedRobotProgram.
    */

    public func loadApprovedConfiguration(

        workcellId: String

    ) throws -> SafetyConfiguration {

        guard let configuration =

            approvedConfigurations[

                workcellId

            ]

        else {

            throw RepositoryError.configurationNotFound

        }

        return configuration

    }

    /*
        Returns the approved configuration identified by both the
        program and the safety generation.

        MotionScheduler uses this lookup when reconstructing approved
        execution context.

        Combining program identity with safetyGeneration guarantees that
        the exact reviewed safety configuration is retrieved even when
        newer generations exist for the same workcell.
    */

    public func loadConfiguration(

        programId: String,

        safetyGeneration: String

    ) throws -> SafetyConfiguration {

        _ = programId

        for configuration in

            approvedConfigurations.values {

            if configuration.generation()

                == safetyGeneration {

                return configuration

            }

        }

        throw RepositoryError.configurationNotFound

    }

    /*
        Returns the newest approved configuration for a workcell.

        This API exists for administrative dashboards and engineering
        tooling.

        Execution components should only use this API when the latest
        approved configuration is explicitly required.
    */

    public func latestConfiguration(

        workcellId: String

    ) throws -> SafetyConfiguration {

        try loadApprovedConfiguration(

            workcellId: workcellId

        )

    }

    // MARK: - Queries

    public func contains(

        workcellId: String

    ) -> Bool {

        approvedConfigurations[

            workcellId

        ] != nil

    }

    public func configurationCount()

        -> Int {

        approvedConfigurations.count

    }

    public func summary()

        -> String {

        return

            "Registered \(configurationCount()) safety configuration(s)."

    }

}

// MARK: - Errors

public enum RepositoryError: Error {

    case configurationNotFound

}
