#pragma once

#include <stdexcept>
#include <string>
#include <vector>


class ExecutionGraph {

private:

    // ------------------------------------------------------------
    // Identity
    // ------------------------------------------------------------

    std::string programId_;

    std::string workcellId_;

    // ------------------------------------------------------------
    // Execution Graph
    // ------------------------------------------------------------

    std::vector<std::string> motionGraph_;

    std::string toolProfile_;

public:

    /*
        ExecutionGraph is the runtime planning artifact consumed by the
        motion scheduler. It carries the identity and motion content
        needed to schedule execution for a workcell. Engineering
        approval, safety review, and configuration lineage are handled
        entirely upstream by the approval pipeline and are not part of
        this runtime representation.
    */

    ExecutionGraph(

        const std::string& programId,

        const std::string& workcellId,

        const std::vector<std::string>& motionGraph,

        const std::string& toolProfile

    ) {

        if (

            programId.empty()

        ) {

            throw std::invalid_argument(

                "Program identifier is required."

            );

        }

        if (

            workcellId.empty()

        ) {

            throw std::invalid_argument(

                "Workcell identifier is required."

            );

        }

        if (

            motionGraph.empty()

        ) {

            throw std::invalid_argument(

                "Motion graph cannot be empty."

            );

        }

        if (

            toolProfile.empty()

        ) {

            throw std::invalid_argument(

                "Tool profile is required."

            );

        }

        programId_ =

            programId;

        workcellId_ =

            workcellId;

        motionGraph_ =

            motionGraph;

        toolProfile_ =

            toolProfile;

    }

    // ------------------------------------------------------------
    // Identity
    // ------------------------------------------------------------

    const std::string& programId() const {

        return programId_;

    }

    const std::string& workcellId() const {

        return workcellId_;

    }

    // ------------------------------------------------------------
    // Execution Graph
    // ------------------------------------------------------------

    const std::vector<std::string>& motionGraph() const {

        return motionGraph_;

    }

    const std::string& toolProfile() const {

        return toolProfile_;

    }

    std::size_t motionCount() const {

        return motionGraph_.size();

    }

    bool empty() const {

        return motionGraph_.empty();

    }

    // ------------------------------------------------------------
    // Utility
    // ------------------------------------------------------------

    std::string summary() const {

        return

            programId_

            + " -> "

            + workcellId_;

    }

};
