```
#include "ExecutionGraph.cpp"

#include "../safety/ApprovedRobotProgram.swift"

#include <algorithm>
#include <stdexcept>
#include <string>
#include <vector>

class ExecutionGraphBuilder {

public:

    //------------------------------------------------------------------
    // Build Execution Graph
    //------------------------------------------------------------------

    ExecutionGraph buildExecutionGraph(

        const ApprovedRobotProgram& approvedProgram

    ) {

        validateApprovedProgram(

            approvedProgram

        );

        std::vector<std::string> graph =

            projectMotionGraph(

                approvedProgram

            );

        std::string toolProfile =

            projectToolProfile(

                approvedProgram

            );

        /*
            ExecutionGraph is a lightweight planning artifact scoped to
            program identity, workcell identity, motion content, and
            tool profile. Engineering approval and safety review are
            authoritative in ApprovedRobotProgram and are re-validated
            above before projection ever runs, so the execution graph
            does not need to carry that context forward for the
            scheduler to operate correctly.
        */

        ExecutionGraph executionGraph(

            approvedProgram.programId(),

            approvedProgram.workcellId(),

            graph,

            toolProfile

        );

        return executionGraph;

    }

    //------------------------------------------------------------------
    // Summary
    //------------------------------------------------------------------

    std::string summarize(

        const ExecutionGraph& graph

    ) const {

        return

            graph.programId()

            + " -> "

            + std::to_string(

                graph.motionCount()

            )

            + " motion step(s)";

    }

    //------------------------------------------------------------------
    // Graph Validation
    //------------------------------------------------------------------

    void validateGraph(

        const ExecutionGraph& graph

    ) const {

        if (

            graph.empty()

        ) {

            throw std::runtime_error(

                "Execution graph contains no motion steps."

            );

        }

        if (

            graph.toolProfile().empty()

        ) {

            throw std::runtime_error(

                "Execution graph is missing tool profile."

            );

        }

        /*
            Duplicate motion identifiers are not treated as a security
            issue here. They may legitimately occur in repetitive
            manufacturing sequences and are handled during production
            optimization rather than execution graph construction.
        */

    }

private:

    //------------------------------------------------------------------
    // Motion Graph Projection
    //------------------------------------------------------------------

    std::vector<std::string> projectMotionGraph(

        const ApprovedRobotProgram& approvedProgram

    ) {

        std::vector<std::string> projected;

        projected.reserve(

            approvedProgram.motionGraph().size()

        );

        for (

            const auto& motion :

            approvedProgram.motionGraph()

        ) {

            projected.push_back(

                motion

            );

        }

        return projected;

    }

    //------------------------------------------------------------------
    // Tool Profile Projection
    //------------------------------------------------------------------

    std::string projectToolProfile(

        const ApprovedRobotProgram& approvedProgram

    ) {

        return

            approvedProgram.toolProfile();

    }

    //------------------------------------------------------------------
    // Validation
    //------------------------------------------------------------------

    void validateApprovedProgram(

        const ApprovedRobotProgram& approvedProgram

    ) {

        if (

            approvedProgram.programId().empty()

        ) {

            throw std::invalid_argument(

                "Program identifier is required."

            );

        }

        if (

            approvedProgram.workcellId().empty()

        ) {

            throw std::invalid_argument(

                "Workcell identifier is required."

            );

        }

        if (

            approvedProgram.safetyGeneration().empty()

        ) {

            throw std::invalid_argument(

                "Safety generation is required."

            );

        }

        if (

            approvedProgram.motionGraph().empty()

        ) {

            throw std::invalid_argument(

                "Motion graph cannot be empty."

            );

        }

        if (

            approvedProgram.toolProfile().empty()

        ) {

            throw std::invalid_argument(

                "Tool profile is required."

            );

        }

    }

    //------------------------------------------------------------------
    // Graph Inspection
    //------------------------------------------------------------------

    bool containsDuplicateSteps(

        const std::vector<std::string>& graph

    ) {

        std::vector<std::string> copy =

            graph;

        std::sort(

            copy.begin(),

            copy.end()

        );

        return std::adjacent_find(

            copy.begin(),

            copy.end()

        ) != copy.end();

    }

};
