## FILE: planning/MotionScheduler.rs

```
use std::collections::VecDeque;

use crate::execution::ExecutionGraph;
use crate::planning::MotionSchedule;
use crate::safety::{
    SafetyConfiguration,
    SafetyConfigurationRepository,
};

/*
    MotionScheduler

    Produces the immutable MotionSchedule consumed by the robot
    controller.

    The scheduler converts an ExecutionGraph into a time-ordered motion
    schedule after validating the approved safety configuration.

    It is the final planning stage before robot execution.
*/

pub struct MotionScheduler<'a> {

    repository:

        &'a SafetyConfigurationRepository

}

impl<'a> MotionScheduler<'a> {

    pub fn new(

        repository:

            &'a SafetyConfigurationRepository

    ) -> Self {

        Self {

            repository

        }

    }

    //------------------------------------------------------------------
    // Build Motion Schedule
    //------------------------------------------------------------------

    pub fn build_motion_schedule(

        &self,

        execution_graph: &ExecutionGraph,

        schedule_id: String

    ) -> Result<MotionSchedule, String> {

        self.validate_execution_graph(

            execution_graph

        )?;

        /*
            ExecutionGraph is scoped to program identity, workcell
            identity, motion content, and tool profile. Safety
            configuration review happens upstream in the approval
            pipeline, so the scheduler resolves the safety configuration
            currently registered for the target workcell rather than
            re-deriving approval state that ExecutionGraph does not
            carry.
        */

        let safety_configuration =

            self.repository

                .latest_configuration(

                    execution_graph.workcell_id()

                )?;

        let commands =

            self.build_motion_commands(

                execution_graph,

                &safety_configuration

            );

        let execution_steps =

            execution_graph

                .motion_graph()

                .clone();

        MotionSchedule::new(

            schedule_id,

            execution_graph

                .workcell_id()

                .to_string(),

            safety_configuration

                .generation()

                .to_string(),

            execution_steps,

            commands

        )

    }

    //------------------------------------------------------------------
    // Motion Command Construction
    //------------------------------------------------------------------

    fn build_motion_commands(

        &self,

        execution_graph: &ExecutionGraph,

        safety_configuration: &SafetyConfiguration

    ) -> VecDeque<String> {

        let mut commands =

            VecDeque::new();

        /*
            The motion scheduler converts the validated execution graph
            into controller-ready motion commands.

            The supplied safety configuration may influence future
            scheduling decisions such as speed limits, acceleration
            profiles, collision zones, or workspace restrictions.
        */

        let _ = safety_configuration;

        for motion in

            execution_graph.motion_graph()

        {

            commands.push_back(

                format!(

                    "EXECUTE:{}",

                    motion

                )

            );

        }

        commands

    }

    //------------------------------------------------------------------
    // Validation
    //------------------------------------------------------------------

    fn validate_execution_graph(

        &self,

        execution_graph: &ExecutionGraph

    ) -> Result<(), String> {

        if

            execution_graph.program_id()

                .trim()

                .is_empty()

        {

            return Err(

                "Program identifier is required."

                    .into()

            );

        }

        if

            execution_graph.workcell_id()

                .trim()

                .is_empty()

        {

            return Err(

                "Workcell identifier is required."

                    .into()

            );

        }

        if

            execution_graph.motion_graph()

                .is_empty()

        {

            return Err(

                "Execution graph contains no motion steps."

                    .into()

            );

        }

        if

            execution_graph.tool_profile()

                .trim()

                .is_empty()

        {

            return Err(

                "Tool profile is required."

                    .into()

            );

        }

        Ok(())

    }

    //------------------------------------------------------------------
    // Statistics
    //------------------------------------------------------------------

    pub fn estimated_duration(

        &self,

        schedule: &MotionSchedule

    ) -> usize {

        /*
            Simple estimation used by engineering dashboards.

            Real production systems derive execution time from robot
            kinematics and controller capabilities.
        */

        schedule.motion_count() * 2

    }

    //------------------------------------------------------------------
    // Summary
    //------------------------------------------------------------------

    pub fn summary(

        &self,

        schedule: &MotionSchedule

    ) -> String {

        format!(

            "{} scheduled with {} motion command(s)",

            schedule.workcell_id(),

            schedule.motion_count()

        )

    }

}
