## FILE: controller/RobotController.kt

```
package controller

import hardware.IndustrialRobotAdapter

/*
 * RobotController
 *
 * Final execution stage before commands are sent to the industrial
 * robot.
 *
 * The controller intentionally trusts MotionSchedule as the
 * authoritative runtime artifact produced by the planning pipeline.
 * It never reconstructs engineering approval or safety lineage.
 */

class RobotController(

    private val adapter:

        IndustrialRobotAdapter

) {

    //------------------------------------------------------------------
    // Execution
    //------------------------------------------------------------------

    fun executeSchedule(

        envelope: ExecutionEnvelope

    ): Boolean {

        validate(

            envelope

        )

        val schedule =

            envelope.schedule

        /*
            MotionSchedule is considered immutable and already validated
            by upstream planning components.

            The controller therefore focuses solely on deterministic
            execution and does not attempt to resolve or verify safety
            configuration lineage.
        */

        adapter.execute(

            schedule.motion_commands()

        )

        return true

    }

    //------------------------------------------------------------------
    // Validation
    //------------------------------------------------------------------

    private fun validate(

        envelope: ExecutionEnvelope

    ) {

        require(

            envelope.motionCount() > 0

        ) {

            "Motion schedule cannot be empty."

        }

    }

    //------------------------------------------------------------------
    // Diagnostics
    //------------------------------------------------------------------

    fun estimateCompletion(

        envelope: ExecutionEnvelope

    ): Int {

        return

            envelope.motionCount() * 2

    }

    fun summary(

        envelope: ExecutionEnvelope

    ): String {

        return

            "Executing ${envelope.workcellId()} " +

            "(${envelope.motionCount()} motion(s))"

    }

}
