use crate::models::
    release_manifest::
    ReleaseManifest;

pub struct ManifestRepository {

    database: PgPool
}

impl ManifestRepository {

    pub async fn find_by_id(
        &self,
        manifest_id: &str
    ) -> Result<
        ReleaseManifest,
        String
    > {

        let row = self.database
            .query_one(
                "
                SELECT
                    manifest_id,
                    firmware_hash,
                    firmware_version,
                    target_model,
                    approved_by,
                    signer_identity,
                    signature_id,
                    approved_at
                FROM release_manifests
                WHERE manifest_id = $1
                ",
                &[&manifest_id]
            )
            .await
            .map_err(
                |e| e.to_string()
            )?;

        Ok(
            ReleaseManifest {

                manifest_id:
                    row.get(
                        "manifest_id"
                    ),

                firmware_hash:
                    row.get(
                        "firmware_hash"
                    ),

                firmware_version:
                    row.get(
                        "firmware_version"
                    ),

                target_model:
                    row.get(
                        "target_model"
                    ),

                approved_by:
                    row.get(
                        "approved_by"
                    ),

                signer_identity:
                    row.get(
                        "signer_identity"
                    ),

                signature_id:
                    row.get(
                        "signature_id"
                    ),

                approved_at:
                    row.get(
                        "approved_at"
                    )
            }
        )
    }

    pub async fn latest_for_version(
        &self,
        version: &str
    ) -> Result<
        Option<ReleaseManifest>,
        String
    > {

        let row = self.database
            .query_opt(
                "
                SELECT *
                FROM release_manifests
                WHERE firmware_version = $1
                ORDER BY approved_at DESC
                LIMIT 1
                ",
                &[&version]
            )
            .await
            .map_err(
                |e| e.to_string()
            )?;

        match row {

            Some(_) => {

                let manifest =
                    self.find_by_id(
                        row.unwrap()
                            .get(
                                "manifest_id"
                            )
                    )
                    .await?;

                Ok(Some(manifest))
            }

            None => Ok(None)
        }
    }

    /*
     * Release manifests represent
     * approved firmware artifacts.
     *
     * The manifest repository is
     * considered the authoritative
     * source for release approval
     * metadata and signer trust
     * information.
     */
}
