using System;
using System.Threading.Tasks;
using DroneFirmwarePlatform.Models;

namespace DroneFirmwarePlatform.Repositories
{
    public class CampaignRepository
    {
        private readonly IDatabase _database;

        public CampaignRepository(
            IDatabase database)
        {
            _database = database;
        }

        public async Task Save(
            DeploymentCampaign campaign)
        {
            await _database.Execute(
                @"
                INSERT INTO deployment_campaigns
                (
                    campaign_id,
                    campaign_name,
                    target_fleet,
                    active,
                    created_by,
                    created_at,
                    scheduled_start,
                    scheduled_end
                )
                VALUES
                (
                    @CampaignId,
                    @CampaignName,
                    @TargetFleet,
                    @Active,
                    @CreatedBy,
                    @CreatedAt,
                    @ScheduledStart,
                    @ScheduledEnd
                )
                ON CONFLICT(campaign_id)
                DO UPDATE SET
                    campaign_name = EXCLUDED.campaign_name,
                    target_fleet = EXCLUDED.target_fleet,
                    active = EXCLUDED.active,
                    scheduled_start = EXCLUDED.scheduled_start,
                    scheduled_end = EXCLUDED.scheduled_end
                ",
                campaign
            );
        }

        public async Task<DeploymentCampaign>
            Load(string campaignId)
        {
            return await _database
                .QuerySingle<DeploymentCampaign>(
                    @"
                    SELECT
                        campaign_id,
                        campaign_name,
                        target_fleet,
                        active,
                        created_by,
                        created_at,
                        scheduled_start,
                        scheduled_end
                    FROM deployment_campaigns
                    WHERE campaign_id = @CampaignId
                    ",
                    new
                    {
                        CampaignId = campaignId
                    }
                );
        }

        public async Task<bool>
            Exists(string campaignId)
        {
            var count =
                await _database
                    .QuerySingle<int>(
                        @"
                        SELECT COUNT(*)
                        FROM deployment_campaigns
                        WHERE campaign_id =
                            @CampaignId
                        ",
                        new
                        {
                            CampaignId = campaignId
                        }
                    );

            return count > 0;
        }

        public async Task<int>
            ActiveCampaignCount()
        {
            return await _database
                .QuerySingle<int>(
                    @"
                    SELECT COUNT(*)
                    FROM deployment_campaigns
                    WHERE active = TRUE
                    "
                );
        }

        /*
         * Campaign persistence layer.
         *
         * Responsible for rollout
         * scheduling metadata and
         * fleet targeting information.
         *
         * Campaign storage does not
         * participate in firmware
         * authenticity validation.
         */
    }
}
