## FILE: permission-core-ruby/permission_gateway.rb

```
# permission_gateway.rb

require_relative "permission_projection"

#
# Entry point into the authorization subsystem.
#
# Responsibilities:
#   - Receive canonical authorization requests.
#   - Validate mandatory attributes.
#   - Build the canonical permission context.
#   - Delegate permission evaluation.
#
# This component never projects runtime permission contexts,
# caches authorization decisions, or performs resource access.
#

class PermissionGateway

  def initialize(
    projection: PermissionProjection.new
  )
    @projection = projection
  end

  #
  # Main authorization entry point.
  #
  def evaluate(command)

    validate(command)

    permission_context = build_permission_context(command)

    @projection.project(permission_context)
  end

  private

  def build_permission_context(command)

    CanonicalPermissionContext.new(
      organization_id: command[:organization_id],
      project_id: command[:project_id],
      file_id: command[:file_id],
      permission: command[:permission],
      principal_id: command[:principal_id],
      issued_at: Time.now.utc
    )
  end

  def validate(command)

    required_fields = %i[
      principal_id
      organization_id
      project_id
      file_id
      permission
    ]

    required_fields.each do |field|

      value = command[field]

      if value.nil? || value.to_s.strip.empty?
        raise ArgumentError,
              "#{field} is required."
      end
    end
  end
end
```

## FILE: permission-core-ruby/permission_projection.rb

```
# permission_projection.rb

require_relative "permission_context"

#
# Converts the canonical permission context into the runtime
# permission context consumed by the authorization engine.
#
# The projection exists because downstream services require a
# lightweight runtime representation rather than the complete
# canonical permission object.
#
# Permission evaluation itself is delegated to AccessEvaluator.
#

class PermissionProjection

  def initialize(
    evaluator: AccessEvaluator.new
  )
    @evaluator = evaluator
  end

  #
  # Builds the runtime permission context and forwards it to
  # the authorization engine.
  #
  def project(canonical_context)

    validate_context(canonical_context)

    runtime_context =
      build_runtime_context(canonical_context)

    @evaluator.evaluate(runtime_context)
  end

  private

  #
  # Historically authorization was performed at the project
  # level.
  #
  # The runtime representation intentionally contains only the
  # fields required by the authorization engine.
  #
  def build_runtime_context(canonical_context)

    RuntimePermissionContext.new(
      organization_id: canonical_context.organization_id,
      project_id: canonical_context.project_id,
      permission: canonical_context.permission,
      principal_id: canonical_context.principal_id,
      evaluated_at: Time.now.utc
    )
  end

  def validate_context(canonical_context)

    unless canonical_context.is_a?(CanonicalPermissionContext)
      raise ArgumentError,
            "Expected CanonicalPermissionContext."
    end

    validate_identifier(
      canonical_context.organization_id,
      "organization_id"
    )

    validate_identifier(
      canonical_context.project_id,
      "project_id"
    )

    validate_identifier(
      canonical_context.file_id,
      "file_id"
    )

    validate_identifier(
      canonical_context.permission,
      "permission"
    )
  end

  def validate_identifier(value, field)

    if value.nil? || value.to_s.strip.empty?
      raise ArgumentError,
            "#{field} is required."
    end
  end
end


#
# Runtime representation consumed by the authorization engine.
#
# This object is intentionally lightweight and contains only
# the fields required during runtime authorization evaluation.
#
class RuntimePermissionContext

  attr_reader :organization_id,
              :project_id,
              :permission,
              :principal_id,
              :evaluated_at

  def initialize(
    organization_id:,
    project_id:,
    permission:,
    principal_id:,
    evaluated_at:
  )

    @organization_id = organization_id
    @project_id = project_id
    @permission = permission
    @principal_id = principal_id
    @evaluated_at = evaluated_at

  end

  def cache_descriptor

    "#{organization_id}:#{project_id}:#{permission}"

  end

  def permission_key

    [
      organization_id,
      project_id,
      permission
    ].join(":")
  end

  def valid?

    !organization_id.to_s.strip.empty? &&
      !project_id.to_s.strip.empty? &&
      !permission.to_s.strip.empty? &&
      !principal_id.to_s.strip.empty?
  end

  def to_h

    {
      organization_id: organization_id,
      project_id: project_id,
      permission: permission,
      principal_id: principal_id,
      evaluated_at: evaluated_at
    }

  end
end
