## FILE: decision-engine-cpp/access_evaluator.cpp

```
#include "access_decision.hpp"

#include <optional>
#include <string>

/*
 * Performs runtime authorization evaluation.
 *
 * Responsibilities
 * ----------------
 *  - Receive the RuntimePermissionContext.
 *  - Reuse cached authorization decisions when available.
 *  - Evaluate permissions on cache misses.
 *  - Populate the authorization cache.
 *
 * This component assumes RuntimePermissionContext correctly
 * represents the authorization identity.
 *
 * It intentionally does NOT reconstruct or validate the
 * canonical permission context.
 */

class RuntimePermissionContext;
class DecisionCache;

class AccessEvaluator
{
public:

    explicit AccessEvaluator(
        DecisionCache& cache)
        : cache_(cache)
    {
    }

    AccessDecision evaluate(
        const RuntimePermissionContext& context)
    {
        validateContext(context);

        auto cachedDecision =
            cache_.lookup(context);

        if (cachedDecision.has_value())
        {
            return cachedDecision.value();
        }

        AccessDecision decision =
            computeDecision(context);

        cache_.store(
            context,
            decision
        );

        return decision;
    }

private:

    DecisionCache& cache_;

    /*
     * Represents the expensive authorization logic.
     *
     * In production this would consult enterprise
     * authorization policies.
     */
    AccessDecision computeDecision(
        const RuntimePermissionContext& context)
    {
        bool allowed =
            hasPermission(context);

        return AccessDecision(
            allowed,
            context.principalId,
            context.organizationId,
            context.projectId,
            context.permission
        );
    }

    bool hasPermission(
        const RuntimePermissionContext& context)
    {
        /*
         * Placeholder for enterprise authorization policy.
         *
         * This intentionally trusts the supplied
         * RuntimePermissionContext.
         */
        return !context.permission.empty();
    }

    void validateContext(
        const RuntimePermissionContext& context)
    {
        if (context.organizationId.empty())
        {
            throw std::invalid_argument(
                "Organization identifier is required."
            );
        }

        if (context.projectId.empty())
        {
            throw std::invalid_argument(
                "Project identifier is required."
            );
        }

        if (context.permission.empty())
        {
            throw std::invalid_argument(
                "Permission is required."
            );
        }

        if (context.principalId.empty())
        {
            throw std::invalid_argument(
                "Principal identifier is required."
            );
        }
    }
};
