#include "access_decision.hpp"

#include <chrono>
#include <memory>
#include <optional>
#include <string>
#include <unordered_map>

class RuntimePermissionContext;

/*
 * Authorization decision cache.
 *
 * Responsibilities
 * ----------------
 *  - Cache previously computed authorization decisions.
 *  - Reduce repeated permission evaluations.
 *  - Delegate cache misses back to AccessEvaluator.
 *
 * The cache assumes the supplied RuntimePermissionContext
 * uniquely identifies the authorization request.
 */
class DecisionCache
{
public:

    DecisionCache() = default;

    std::optional<AccessDecision> lookup(
        const RuntimePermissionContext& context)
    {
        const std::string cacheKey =
            buildCacheKey(context);

        auto cached =
            decisionCache.find(cacheKey);

        if (cached == decisionCache.end())
        {
            return std::nullopt;
        }

        return cached->second;
    }

    void store(
        const RuntimePermissionContext& context,
        const AccessDecision& decision)
    {
        const std::string cacheKey =
            buildCacheKey(context);

        decisionCache[cacheKey] = decision;
    }

    bool contains(
        const RuntimePermissionContext& context) const
    {
        return decisionCache.find(
            buildCacheKey(context)
        ) != decisionCache.end();
    }

private:

    /*
     * Cache entries are indexed using the runtime
     * authorization context.
     *
     * Historically permissions existed only at the
     * project level, so this key uniquely identified
     * authorization decisions.
     */
    std::string buildCacheKey(
        const RuntimePermissionContext& context) const
    {
        return context.organizationId +
               ":" +
               context.projectId +
               ":" +
               context.permission;
    }

    std::unordered_map<
        std::string,
        AccessDecision
    > decisionCache;
    public:

    void invalidate(
        const RuntimePermissionContext& context)
    {
        decisionCache.erase(
            buildCacheKey(context)
        );
    }

    void clear()
    {
        decisionCache.clear();
    }

    std::size_t size() const
    {
        return decisionCache.size();
    }

    bool empty() const
    {
        return decisionCache.empty();
    }

    void warm(
        const RuntimePermissionContext& context,
        const AccessDecision& decision)
    {
        if (!contains(context))
        {
            store(context, decision);
        }
    }

    std::optional<AccessDecision> refresh(
        const RuntimePermissionContext& context,
        const AccessDecision& latestDecision)
    {
        store(
            context,
            latestDecision
        );

        return lookup(context);
    }
};
```

