# permission_store.rb

#
# Canonical permission repository.
#
# Stores the enterprise permission assignments that originate
# from the administration system.
#
# This repository is intentionally correct and always resolves
# permissions using the complete canonical identity.
#

class PermissionStore

  def initialize
    @permissions = []
  end

  #
  # Returns the canonical permission associated with the
  # supplied identity.
  #
  def find_permission(
    organization_id:,
    project_id:,
    file_id:,
    principal_id:
  )

    @permissions.find do |permission|

      permission.organization_id == organization_id &&
        permission.project_id == project_id &&
        permission.file_id == file_id &&
        permission.principal_id == principal_id

    end
  end

  def save(permission)

    @permissions << permission

    permission
  end

  def update(permission)

    existing =
      find_permission(
        organization_id: permission.organization_id,
        project_id: permission.project_id,
        file_id: permission.file_id,
        principal_id: permission.principal_id
      )

    if existing
      @permissions.delete(existing)
    end

    @permissions << permission
  end

  def exists?(permission)

    !find_permission(
      organization_id: permission.organization_id,
      project_id: permission.project_id,
      file_id: permission.file_id,
      principal_id: permission.principal_id
    ).nil?
  end

  def count

    @permissions.length

  end
end
