defmodule DesignCloud.IdentityContext do
  @moduledoc """
  Builds the authenticated execution context used by the
  permission subsystem.

  Responsibilities:
    * Verify request identity.
    * Construct the authorization request.
    * Delegate permission evaluation.

  This module never transforms permission contexts and never
  evaluates authorization rules.
  """

  alias DesignCloud.AccessRequest
  alias PermissionCore.PermissionGateway

  require Logger

  @spec authorize(AccessRequest.t()) ::
          {:ok, map()} | {:error, map()}
  def authorize(%AccessRequest{} = request) do
    with :ok <- validate_identity(request) do

      Logger.debug(
        "Creating authorization context for #{request.user_id}."
      )

      command = %{
        principal_id: request.user_id,
        organization_id: request.organization_id,
        project_id: request.project_id,
        file_id: request.file_id,
        permission: request.permission
      }

      PermissionGateway.evaluate(command)
    end
  end

  defp validate_identity(%AccessRequest{} = request) do
    cond do
      blank?(request.user_id) ->
        {:error, %{message: "Unauthenticated request."}}

      blank?(request.organization_id) ->
        {:error, %{message: "Organization context missing."}}

      true ->
        :ok
    end
  end

  defp blank?(value) do
    value == nil or String.trim(to_string(value)) == ""
  end
end
