class CanonicalPermissionContext

  attr_reader :organization_id,
              :project_id,
              :file_id,
              :permission,
              :principal_id,
              :issued_at

  def initialize(
    organization_id:,
    project_id:,
    file_id:,
    permission:,
    principal_id:,
    issued_at:
  )

    @organization_id = organization_id
    @project_id = project_id
    @file_id = file_id
    @permission = permission
    @principal_id = principal_id
    @issued_at = issued_at

  end

  def descriptor

    [
      organization_id,
      project_id,
      file_id,
      permission
    ].join(":")

  end

  def valid?

    !organization_id.to_s.strip.empty? &&
      !project_id.to_s.strip.empty? &&
      !file_id.to_s.strip.empty? &&
      !permission.to_s.strip.empty? &&
      !principal_id.to_s.strip.empty?

  end

