defmodule DesignCloud.AccessRouter do
  @moduledoc """
  Entry point for all design file access requests.

  Responsibilities:
    * Validate incoming requests.
    * Forward authenticated requests into the authorization pipeline.
    * Never evaluate permissions directly.

  Authentication is assumed to have already been completed by the
  API gateway. Authorization is delegated to IdentityContext.
  """

  alias DesignCloud.IdentityContext
  alias DesignCloud.AccessRequest

  require Logger

  @spec open_file(map()) :: {:ok, map()} | {:error, map()}
  def open_file(params) when is_map(params) do
    with {:ok, request} <- build_request(params),
         :ok <- validate_request(request) do

      Logger.info(
        "Processing file access request for user=#{request.user_id}, file=#{request.file_id}"
      )

      IdentityContext.authorize(request)

    else
      {:error, reason} ->
        {:error, %{message: reason}}
    end
  end

  defp build_request(params) do
    request = %AccessRequest{
      user_id: Map.get(params, "user_id"),
      organization_id: Map.get(params, "organization_id"),
      project_id: Map.get(params, "project_id"),
      file_id: Map.get(params, "file_id"),
      permission: Map.get(params, "permission")
    }

    {:ok, request}
  end

  defp validate_request(%AccessRequest{} = request) do
    cond do
      blank?(request.user_id) ->
        {:error, "User identifier is required."}

      blank?(request.organization_id) ->
        {:error, "Organization identifier is required."}

      blank?(request.project_id) ->
        {:error, "Project identifier is required."}

      blank?(request.file_id) ->
        {:error, "File identifier is required."}

      blank?(request.permission) ->
        {:error, "Permission is required."}

      true ->
        :ok
    end
  end

  defp blank?(value) do
    value == nil or String.trim(to_string(value)) == ""
  end
end
