from __future__ import annotations

from collections import defaultdict
from datetime import timedelta
from typing import Dict, List

from ExecutionProfile import (
    ExecutionProfile,
    ExecutionProfileFactory,
    ResourceLimit,
    ToolCapability,
)


class ProfileRegistry:
    """
    Registry responsible for managing execution profiles.

    This component owns profile registration, lookup and lifecycle
    management.

    It does NOT compose runtime contexts or schedule workloads.
    """

    def __init__(self) -> None:

        self._profiles: Dict[str, ExecutionProfile] = {}

        self._policy_index: Dict[str, List[str]] = defaultdict(list)

    # ---------------------------------------------------------
    # Registration
    # ---------------------------------------------------------

    def register(
        self,
        profile: ExecutionProfile,
    ) -> None:

        self._profiles[
            profile.execution_profile_id
        ] = profile

        self._policy_index[
            profile.sandbox_policy
        ].append(
            profile.execution_profile_id
        )

    # ---------------------------------------------------------
    # Lookup
    # ---------------------------------------------------------

    def profile(
        self,
        profile_id: str,
    ) -> ExecutionProfile:

        try:
            return self._profiles[profile_id]
        except KeyError:
            raise LookupError(
                f"Unknown execution profile '{profile_id}'."
            )

    def exists(
        self,
        profile_id: str,
    ) -> bool:

        return profile_id in self._profiles

    def profiles_for_policy(
        self,
        sandbox_policy: str,
    ) -> List[ExecutionProfile]:

        return [

            self._profiles[profile_id]

            for profile_id in

            self._policy_index.get(
                sandbox_policy,
                [],
            )

        ]

    # ---------------------------------------------------------
    # Operational Helper
    # ---------------------------------------------------------

    def default_profile(
        self,
        sandbox_policy: str,
    ) -> ExecutionProfile:
        """
        Returns the most recently registered execution profile for a
        given sandbox policy.

        Used by operational tooling, bootstrap environments, and
        administrative workflows that need a ready-to-use profile for a
        policy family without tracking a specific execution_profile_id.
        """

        candidates = self.profiles_for_policy(
            sandbox_policy
        )

        if not candidates:
            raise LookupError(
                f"No execution profile for '{sandbox_policy}'."
            )

        candidates.sort(
            key=lambda profile: profile.created_at,
            reverse=True,
        )

        return candidates[0]

    # ---------------------------------------------------------
    # Lifecycle
    # ---------------------------------------------------------

    def extend_profile(
        self,
        profile_id: str,
        duration: timedelta,
    ) -> None:

        self.profile(
            profile_id
        ).extend(duration)

    def remove(
        self,
        profile_id: str,
    ) -> None:

        profile = self.profile(profile_id)

        self._policy_index[
            profile.sandbox_policy
        ].remove(profile_id)

        del self._profiles[profile_id]

    # ---------------------------------------------------------
    # Validation
    # ---------------------------------------------------------

    def validate(
        self,
        profile_id: str,
    ) -> bool:

        if not self.exists(profile_id):
            return False

        return self.profile(
            profile_id
        ).validate()

    # ---------------------------------------------------------
    # Statistics
    # ---------------------------------------------------------

    def profile_count(self) -> int:

        return len(self._profiles)

    def active_profiles(self) -> List[ExecutionProfile]:

        return [

            profile

            for profile in self._profiles.values()

            if not profile.expired()

        ]

    def sandbox_policies(self) -> List[str]:

        return sorted(
            self._policy_index.keys()
        )

    # ---------------------------------------------------------
    # Bootstrap Helper
    # ---------------------------------------------------------

    @staticmethod
    def bootstrap_profile() -> ExecutionProfile:

        profile = ExecutionProfileFactory.create(

            sandbox_policy="standard",

            tool_profile="default",

            cpu_policy="shared",

            resource_limits=ResourceLimit(

                cpu_limit=2,

                memory_mb=4096,

                max_processes=64,

            ),

        )

        profile.register_capability(
            ToolCapability(
                name="shell",
                version="1.0",
                enabled=True,
            )
        )

        return profile
