package network

import java.time.Duration
import java.util.concurrent.ConcurrentHashMap

class NetworkController {

    private val activeBindings =
        ConcurrentHashMap<String, NetworkBinding>()

    fun provisionNetwork(
        networkZone: String,
        egressPolicy: String,
        tenantId: String,
        leaseDuration: Duration
    ): NetworkBinding {

        require(networkZone.isNotBlank()) {
            "Network zone is required."
        }

        require(egressPolicy.isNotBlank()) {
            "Egress policy is required."
        }

        require(tenantId.isNotBlank()) {
            "Tenant identifier is required."
        }

        val binding = NetworkBinding.create(
            networkZone = networkZone,
            egressPolicy = egressPolicy,
            tenantId = tenantId,
            leaseSeconds = leaseDuration.seconds
        )

        activeBindings[binding.networkBindingId] = binding

        return binding
    }

    fun binding(
        bindingId: String
    ): NetworkBinding {

        return activeBindings[bindingId]
            ?: throw IllegalArgumentException(
                "Unknown network binding: $bindingId"
            )
    }

    fun bindingExists(
        bindingId: String
    ): Boolean {

        return activeBindings.containsKey(bindingId)

    }

    fun validateBinding(
        bindingId: String
    ): Boolean {

        if (!bindingExists(bindingId)) {
            return false
        }

        return binding(bindingId).validate()
    }

    fun renewBinding(
        bindingId: String,
        extension: Duration
    ) {

        binding(bindingId)
            .renewLease(extension.seconds)

    }

    fun releaseBinding(
        bindingId: String
    ) {

        activeBindings.remove(bindingId)

    }

    fun activeBindings(): List<NetworkBinding> {

        return activeBindings
            .values
            .filter { !it.isExpired() }

    }

    fun bindingsForTenant(
        tenantId: String
    ): List<NetworkBinding> {

        return activeBindings()
            .filter {
                it.belongsToTenant(tenantId)
            }

    }

    fun bindingsInZone(
        networkZone: String
    ): List<NetworkBinding> {

        return activeBindings()
            .filter {

                it.networkZone.equals(
                    networkZone,
                    ignoreCase = true
                )

            }

    }

    fun activeBindingCount(): Int {

        return activeBindings()
            .size

    }

    fun cleanupExpiredBindings() {

        val iterator =
            activeBindings.entries.iterator()

        while (iterator.hasNext()) {

            val entry = iterator.next()

            if (entry.value.isExpired()) {
                iterator.remove()
            }

        }

    }

    fun registerFirewallRule(
        bindingId: String,
        rule: FirewallRule
    ) {

        binding(bindingId)
            .addFirewallRule(rule)

    }

    fun registerRoute(
        bindingId: String,
        route: NetworkRoute
    ) {

        binding(bindingId)
            .addRoute(route)

    }

    fun summary(
        bindingId: String
    ): Map<String, Any> {

        val binding = binding(bindingId)

        return mapOf(

            "bindingId" to binding.networkBindingId,

            "tenant" to binding.tenantId,

            "zone" to binding.networkZone,

            "policy" to binding.egressPolicy,

            "routes" to binding.routeCount(),

            "firewallRules" to binding.firewallRuleCount(),

            "expired" to binding.isExpired()

        )

    }

}
