export interface ExecutionRequest {
    requestId: string;
    tenantId: string;

    workloadName: string;
    workloadVersion: string;

    volumeProfile: string;
    networkProfile: string;
    executionProfile: string;

    requestedCpu: number;
    requestedMemoryMb: number;

    submittedBy: string;
    submittedAt: Date;
}

export class ExecutionRequestValidator {

    static validate(
        request: ExecutionRequest
    ): void {

        if (!request.requestId.trim()) {
            throw new Error("Request identifier is required.");
        }

        if (!request.tenantId.trim()) {
            throw new Error("Tenant identifier is required.");
        }

        if (!request.workloadName.trim()) {
            throw new Error("Workload name is required.");
        }

        if (!request.workloadVersion.trim()) {
            throw new Error("Workload version is required.");
        }

        if (!request.volumeProfile.trim()) {
            throw new Error("Volume profile is required.");
        }

        if (!request.networkProfile.trim()) {
            throw new Error("Network profile is required.");
        }

        if (!request.executionProfile.trim()) {
            throw new Error("Execution profile is required.");
        }

        if (request.requestedCpu <= 0) {
            throw new Error("Requested CPU must be positive.");
        }

        if (request.requestedMemoryMb <= 0) {
            throw new Error("Requested memory must be positive.");
        }

        if (!request.submittedBy.trim()) {
            throw new Error("Submitting user is required.");
        }
    }

    static resourceFingerprint(
        request: ExecutionRequest
    ): string {

        return [
            request.volumeProfile,
            request.networkProfile,
            request.executionProfile
        ].join(":");

    }

    static workloadIdentity(
        request: ExecutionRequest
    ): string {

        return `${request.workloadName}:${request.workloadVersion}`;

    }

    static requestedResources(
        request: ExecutionRequest
    ): { cpu: number; memoryMb: number } {

        return {
            cpu: request.requestedCpu,
            memoryMb: request.requestedMemoryMb
        };

    }

    static belongsToTenant(
        request: ExecutionRequest,
        tenantId: string
    ): boolean {

        return request.tenantId === tenantId;

    }
}
