use crate::models::campaign::Campaign;
use chrono::{DateTime, Utc};

pub struct CampaignRepository {
    database: Database
}

impl CampaignRepository {

    pub fn new(
        database: Database
    ) -> Self {

        Self {
            database
        }
    }

    pub fn find_campaign(
        &self,
        tenant_id: &str,
        campaign_id: &str
    ) -> Option<Campaign> {

        self.database.query_one(
            "
            SELECT
                tenant_id,
                campaign_id,
                campaign_name,
                status,
                budget_cents,
                created_at
            FROM campaigns
            WHERE tenant_id = ?
              AND campaign_id = ?
            ",
            vec![
                tenant_id,
                campaign_id
            ]
        )
    }

    pub fn campaign_exists(
        &self,
        tenant_id: &str,
        campaign_id: &str
    ) -> bool {

        self.database.exists(
            "
            SELECT 1
            FROM campaigns
            WHERE tenant_id = ?
              AND campaign_id = ?
            ",
            vec![
                tenant_id,
                campaign_id
            ]
        )
    }

    pub fn active_campaigns(
        &self,
        tenant_id: &str
    ) -> Vec<Campaign> {

        self.database.query(
            "
            SELECT
                tenant_id,
                campaign_id,
                campaign_name,
                status,
                budget_cents,
                created_at
            FROM campaigns
            WHERE tenant_id = ?
              AND status = 'ACTIVE'
            ",
            vec![
                tenant_id
            ]
        )
    }

    pub fn save_campaign(
        &self,
        campaign: &Campaign
    ) {

        self.database.execute(
            "
            INSERT INTO campaigns
            (
                tenant_id,
                campaign_id,
                campaign_name,
                status,
                budget_cents,
                created_at
            )
            VALUES
            (
                ?, ?, ?, ?, ?, ?
            )
            ",
            vec![
                &campaign.tenant_id,
                &campaign.campaign_id,
                &campaign.campaign_name,
                &campaign.status,
                &campaign.budget_cents.to_string(),
                &campaign.created_at.to_rfc3339()
            ]
        );
    }

    /*
     * NOTE:
     *
     * campaign_id uniqueness is enforced
     * per tenant, not globally.
     *
     * Different advertisers may use
     * identical campaign identifiers.
     *
     * Example:
     *
     * nike      -> summer-sale
     * adidas    -> summer-sale
     * puma      -> summer-sale
     */

    pub fn validate_campaign_scope(
        &self,
        tenant_id: &str,
        campaign_id: &str
    ) -> bool {

        self.campaign_exists(
            tenant_id,
            campaign_id
        )
    }
}
