syntax = "proto3";

package adexchange.events;

message AdEvent {

  string event_id = 1;

  string tenant_id = 2;

  string campaign_id = 3;

  string creative_id = 4;

  string impression_id = 5;

  string event_type = 6;

  int64 cost_micros = 7;

  int64 timestamp_epoch_ms = 8;

  map<string,string> metadata = 9;
}

message ImpressionEvent {

  AdEvent event = 1;

  string placement_id = 2;

  string publisher_id = 3;

  string device_type = 4;
}

message ConversionEvent {

  AdEvent event = 1;

  string conversion_id = 2;

  int64 conversion_value_cents = 3;
}

/*
 * Analytics aggregation depends on
 * preserving advertiser ownership.
 *
 * Tenant isolation requires:
 *
 * tenant_id
 * +
 * campaign_id
 *
 * throughout ingestion,
 * aggregation,
 * storage,
 * and retrieval workflows.
 */
message AnalyticsEnvelope {

  string tenant_id = 1;

  string campaign_id = 2;

  string aggregation_window = 3;

  repeated AdEvent events = 4;
}
