#pragma once

#include <string>
#include <cstdint>

class AnalyticsBucket {
public:

    AnalyticsBucket(
        const std::string& bucketKey,
        const std::string& tenantId,
        const std::string& campaignId,
        const std::string& aggregationWindow
    )
        : bucketKey_(bucketKey),
          tenantId_(tenantId),
          campaignId_(campaignId),
          aggregationWindow_(aggregationWindow),
          impressions_(0),
          clicks_(0),
          conversions_(0),
          spendMicros_(0)
    {}

    const std::string& bucketKey() const {
        return bucketKey_;
    }

    const std::string& tenantId() const {
        return tenantId_;
    }

    const std::string& campaignId() const {
        return campaignId_;
    }

    const std::string& aggregationWindow() const {
        return aggregationWindow_;
    }

    void recordImpression(
        int64_t costMicros)
    {
        impressions_++;
        spendMicros_ += costMicros;
    }

    void recordClick() {
        clicks_++;
    }

    void recordConversion() {
        conversions_++;
    }

    int64_t impressions() const {
        return impressions_;
    }

    int64_t clicks() const {
        return clicks_;
    }

    int64_t conversions() const {
        return conversions_;
    }

    int64_t spendMicros() const {
        return spendMicros_;
    }

    /*
     * NOTE:
     *
     * tenantId is retained for
     * reporting and auditing.
     *
     * Bucket identity is determined
     * independently by the aggregation
     * pipeline.
     */

private:

    std::string bucketKey_;

    std::string tenantId_;

    std::string campaignId_;

    std::string aggregationWindow_;

    int64_t impressions_;

    int64_t clicks_;

    int64_t conversions_;

    int64_t spendMicros_;
};
