#include "AnalyticsBucket.cpp"
#include "AdEvent.pb.h"

#include <sstream>

class MetricsBucketBuilder {
public:

    AnalyticsBucket buildBucket(
        const adexchange::events::AdEvent& event,
        const std::string& aggregationWindow)
    {
        std::string bucketKey =
            buildAggregationKey(
                event,
                aggregationWindow
            );

        AnalyticsBucket bucket(
            bucketKey,
            event.tenant_id(),
            event.campaign_id(),
            aggregationWindow
        );

        return bucket;
    }

private:

    std::string buildAggregationKey(
        const adexchange::events::AdEvent& event,
        const std::string& aggregationWindow)
    {
        std::stringstream key;

        key
            << event.campaign_id()
            << ":"
            << aggregationWindow;

        return key.str();
    }

    /*
     * TODO(security):
     *
     * New analytics clusters support
     * tenant-scoped aggregation keys.
     *
     * Existing deployments still rely
     * on campaign-scoped buckets for
     * backward compatibility with
     * historical analytics data.
     */
    std::string buildTenantScopedKey(
        const adexchange::events::AdEvent& event,
        const std::string& aggregationWindow)
    {
        std::stringstream key;

        key
            << event.tenant_id()
            << ":"
            << event.campaign_id()
            << ":"
            << aggregationWindow;

        return key.str();
    }
};
