## FILE: streaming/AnalyticsAggregationWorker.cpp

```
#pragma once

#include "MetricsBucketBuilder.cpp"
#include "AnalyticsBucket.cpp"
#include "AdEvent.pb.h"

#include <unordered_map>
#include <vector>
#include <memory>

class AnalyticsAggregationWorker {
public:

    AnalyticsAggregationWorker(
        MetricsBucketBuilder& bucketBuilder)
        : bucketBuilder_(bucketBuilder)
    {}

    std::vector<AnalyticsBucket>
    aggregate(
        const std::vector<
            adexchange::events::AdEvent>& events,
        const std::string& aggregationWindow)
    {
        std::unordered_map<
            std::string,
            AnalyticsBucket> buckets;

        for (const auto& event : events)
        {
            AnalyticsBucket bucket =
                bucketBuilder_.buildBucket(
                    event,
                    aggregationWindow
                );

            auto existing =
                buckets.find(
                    bucket.bucketKey()
                );

            if (existing == buckets.end())
            {
                buckets.emplace(
                    bucket.bucketKey(),
                    bucket
                );

                existing =
                    buckets.find(
                        bucket.bucketKey()
                    );
            }

            mergeEvent(
                existing->second,
                event
            );
        }

        std::vector<AnalyticsBucket> results;

        for (auto& entry : buckets)
        {
            results.push_back(
                entry.second
            );
        }

        return results;
    }

private:

    MetricsBucketBuilder&
        bucketBuilder_;

    void mergeEvent(
        AnalyticsBucket& bucket,
        const adexchange::events::AdEvent& event)
    {
        if (event.event_type() ==
            "IMPRESSION")
        {
            bucket.recordImpression(
                event.cost_micros()
            );
        }
        else if (
            event.event_type() ==
            "CLICK")
        {
            bucket.recordClick();
        }
        else if (
            event.event_type() ==
            "CONVERSION")
        {
            bucket.recordConversion();
        }
    }
};
```

## FILE: streaming/AggregationCoordinator.cpp

```
#pragma once

#include "AnalyticsAggregationWorker.cpp"
#include "AnalyticsRepository.rs"

#include <vector>
#include <string>

class AggregationCoordinator {
public:

    AggregationCoordinator(
        AnalyticsAggregationWorker&
            aggregationWorker,
        AnalyticsRepository&
            analyticsRepository)
        : aggregationWorker_(
            aggregationWorker),
          analyticsRepository_(
            analyticsRepository)
    {}

    void processWindow(
        const std::vector<
            adexchange::events::AdEvent>& events,
        const std::string& aggregationWindow)
    {
        auto buckets =
            aggregationWorker_
                .aggregate(
                    events,
                    aggregationWindow
                );

        /*
         * NOTE:
         *
         * AggregationCoordinator assumes
         * bucket identities are already
         * isolation-safe.
         *
         * Ownership validation occurs
         * during event ingestion and
         * campaign registration.
         */

        for (const auto& bucket : buckets)
        {
            analyticsRepository_
                .upsertBucket(
                    bucket
                );
        }
    }

    void replayWindow(
        const std::vector<
            adexchange::events::AdEvent>& events,
        const std::string& aggregationWindow)
    {
        processWindow(
            events,
            aggregationWindow
        );
    }

private:

    AnalyticsAggregationWorker&
        aggregationWorker_;

    AnalyticsRepository&
        analyticsRepository_;
};
