                aggregation_window,
                impressions,
                clicks,
                conversions,
                spend_micros
            )
            VALUES
            (
                ?, ?, ?, ?, ?, ?, ?, ?
            )
            ",
            vec![
                bucket.bucket_key(),
                bucket.tenant_id(),
                bucket.campaign_id(),
                bucket.aggregation_window(),
                bucket.impressions(),
                bucket.clicks(),
                bucket.conversions(),
                bucket.spend_micros()
            ]
        );
    }

    pub fn find_bucket(
        &self,
