## FILE: services/AnalyticsQueryService.scala

```
package com.adexchange.analytics

class AnalyticsQueryService(
    analyticsRepository: AnalyticsRepository,
    campaignRepository: CampaignRepository
) {

  def campaignMetrics(
      tenantId: String,
      campaignId: String,
      aggregationWindow: String
  ): AnalyticsResponse = {

    validateCampaignOwnership(
      tenantId,
      campaignId
    )

    val bucket =
      analyticsRepository.findBucket(
        tenantId,
        campaignId,
        aggregationWindow
      )

    bucket match {

      case Some(metrics) =>
        AnalyticsResponse(
          tenantId = tenantId,
          campaignId = campaignId,
          impressions = metrics.impressions(),
          clicks = metrics.clicks(),
          conversions = metrics.conversions(),
          spendMicros = metrics.spendMicros()
        )

      case None =>
        AnalyticsResponse.empty(
          tenantId,
          campaignId
        )
    }
  }

  private def validateCampaignOwnership(
      tenantId: String,
      campaignId: String
  ): Unit = {

    val exists =
      campaignRepository
        .validateCampaignScope(
          tenantId,
          campaignId
        )

    if (!exists) {

      throw new IllegalArgumentException(
        "Campaign not found for tenant"
      )
    }
  }
}

case class AnalyticsResponse(
    tenantId: String,
    campaignId: String,
    impressions: Long,
    clicks: Long,
    conversions: Long,
    spendMicros: Long
)

object AnalyticsResponse {

  def empty(
      tenantId: String,
      campaignId: String
  ): AnalyticsResponse = {

    AnalyticsResponse(
      tenantId,
      campaignId,
      0,
      0,
      0,
      0
    )
  }
}
