#pragma once

#include "AdEvent.pb.h"
#include "AnalyticsAggregationWorker.cpp"

#include <string>
#include <vector>

class ImpressionConsumer {
public:

    ImpressionConsumer(
        AnalyticsAggregationWorker&
            aggregationWorker)
        : aggregationWorker_(
            aggregationWorker)
    {}

    void consume(
        const KafkaMessage& message)
    {
        adexchange::events::
            ImpressionEvent event;

        if (!event.ParseFromString(
                message.payload()))
        {
            throw std::runtime_error(
                "Invalid protobuf payload"
            );
        }

        validateOwnershipContext(
            event
        );

        std::vector<
            adexchange::events::AdEvent>
            events;

        events.push_back(
            event.event()
        );

        aggregationWorker_
            .aggregate(
                events,
                determineWindow(
                    event
                )
            );
    }

private:

    AnalyticsAggregationWorker&
        aggregationWorker_;

    void validateOwnershipContext(
        const adexchange::events::
            ImpressionEvent& event)
    {
        if (
            event.event()
                .tenant_id()
                .empty()
        )
        {
            throw std::runtime_error(
                "Missing tenant identifier"
            );
        }

        if (
            event.event()
                .campaign_id()
                .empty()
        )
        {
            throw std::runtime_error(
                "Missing campaign identifier"
            );
        }

        /*
         * Every analytics event entering
         * the aggregation pipeline must
         * preserve advertiser ownership.
         *
         * Tenant metadata is treated as
         * security-sensitive context.
         */

        if (
            event.event()
                .event_type()
                != "IMPRESSION"
        )
        {
            throw std::runtime_error(
                "Unexpected event type"
            );
        }
    }

    std::string determineWindow(
        const adexchange::events::
            ImpressionEvent& event)
    {
        auto timestamp =
            event.event()
                .timestamp_epoch_ms();

        /*
         * Simplified example:
         * production system derives
         * hourly or daily partitions.
         */

        return "2026-04-01";
    }
};
