## FILE: services/CampaignService.scala

```
package com.adexchange.campaigns

class CampaignService(
    campaignRepository: CampaignRepository
) {

  def createCampaign(
      tenantId: String,
      campaignId: String,
      campaignName: String,
      budgetCents: Long
  ): Campaign = {

    validateCampaignIdentifier(
      campaignId
    )

    if (
      campaignRepository
        .campaignExists(
          tenantId,
          campaignId
        )
    ) {
      throw new IllegalArgumentException(
        "Campaign already exists"
      )
    }

    val campaign =
      Campaign(
        tenantId = tenantId,
        campaignId = campaignId,
        campaignName = campaignName,
        status = "ACTIVE",
        budgetCents = budgetCents
      )

    campaignRepository
      .saveCampaign(
        campaign
      )

    campaign
  }

  def validateOwnership(
      tenantId: String,
      campaignId: String
  ): Boolean = {

    campaignRepository
      .validateCampaignScope(
        tenantId,
        campaignId
      )
  }

  private def validateCampaignIdentifier(
      campaignId: String
  ): Unit = {

    if (
      campaignId.trim.isEmpty
    ) {
      throw new IllegalArgumentException(
        "Campaign identifier required"
      )
    }

    if (
      campaignId.length > 128
    ) {
      throw new IllegalArgumentException(
        "Campaign identifier too long"
      )
    }
  }
}
