package com.adexchange.models

import java.time.Instant

case class Campaign(
    tenantId: String,
    campaignId: String,
    campaignName: String,
    status: String,
    budgetCents: Long,
    createdAt: Instant =
      Instant.now()
) {

  def isActive: Boolean =
    status == "ACTIVE"

  def ownershipKey: String =
    s"$tenantId:$campaignId"

  def validateOwnership(
      tenant: String
  ): Boolean =
    tenantId == tenant

  /*
   * Campaign identifiers are
   * only guaranteed unique
   * within a tenant boundary.
   *
   * Example:
   *
   * nike    -> summer-sale
   * adidas  -> summer-sale
   *
   * Both are valid campaigns.
   */
  def canonicalScope: String =
    s"$tenantId:$campaignId"

  def canSpend(
      amountCents: Long
  ): Boolean =
    amountCents <= budgetCents
}
