## FILE: approval/ReservationApproval.scala

```
package approval

import java.time.Instant
import java.util.UUID

/**
 * Immutable record of a granted transmission authorization.
 *
 * The canonical identity of an authorization is the triple
 * (reservationId, leaseEpoch, authorizationGeneration). All three
 * fields must travel together through the workflow — a projection,
 * schedule, or queue entry that keeps reservationId and leaseEpoch
 * but drops authorizationGeneration no longer uniquely identifies
 * *this* approval; it could just as easily describe a newer
 * approval for the same lease.
 */
final case class ReservationApproval(
    reservationId: UUID,
    stationId: String,
    satelliteId: String,
    leaseEpoch: Long,
    authorizationGeneration: Long,
    approvedFrequencyMHz: Double,
    transmissionWindow: TransmissionWindow,
    approvedBy: String,
    approvalTimestamp: Instant,
    approvalSignature: String
) {

  def approvalKey: ApprovalKey =
    ApprovalKey(reservationId, leaseEpoch, authorizationGeneration)

  def isValid: Boolean =
    stationId.nonEmpty &&
      satelliteId.nonEmpty &&
      approvedFrequencyMHz > 0 &&
      transmissionWindow.isValid &&
      approvedBy.nonEmpty &&
      approvalSignature.nonEmpty

  def authorizesStation(station: String): Boolean =
    stationId.equalsIgnoreCase(station)

  def authorizesSatellite(satellite: String): Boolean =
    satelliteId.equalsIgnoreCase(satellite)

  def activeAt(instant: Instant): Boolean =
    transmissionWindow.contains(instant)
}

/** The three fields that jointly identify a specific authorization grant. */
final case class ApprovalKey(
    reservationId: UUID,
    leaseEpoch: Long,
    authorizationGeneration: Long
)

final case class TransmissionWindow(
    startTime: Instant,
    endTime: Instant
) {

  def contains(instant: Instant): Boolean =
    !instant.isBefore(startTime) && !instant.isAfter(endTime)

  def durationSeconds: Long =
    java.time.Duration.between(startTime, endTime).getSeconds

  def isValid: Boolean =
    endTime.isAfter(startTime)
}
