## FILE: projections/OperationalReservation.cpp

```
#pragma once

#include <chrono>
#include <string>

// Read model produced by ReservationProjection from the granted-event
// stream. Everything downstream (SchedulingPlanner, QueueAssembler,
// GroundStationRuntime) treats this as ground truth for "what was
// approved" — none of them go back to the original event or the
// approval authority to double-check.
class OperationalReservation
{
public:

    OperationalReservation(
        std::string reservationId,
        std::string stationId,
        std::string satelliteId,
        long leaseEpoch,
        long authorizationGeneration,
        double approvedFrequencyMHz,
        std::chrono::system_clock::time_point windowStart,
        std::chrono::system_clock::time_point windowEnd,
        std::string approvalSignature
    ) :
        reservationId_(std::move(reservationId)),
        stationId_(std::move(stationId)),
        satelliteId_(std::move(satelliteId)),
        leaseEpoch_(leaseEpoch),
        authorizationGeneration_(authorizationGeneration),
        approvedFrequencyMHz_(approvedFrequencyMHz),
        windowStart_(windowStart),
        windowEnd_(windowEnd),
        approvalSignature_(std::move(approvalSignature))
    {}

    // --------------------------------------------------------
    // Canonical Authorization Identity
    // --------------------------------------------------------

    const std::string& reservationId() const { return reservationId_; }
    long leaseEpoch() const { return leaseEpoch_; }
    long authorizationGeneration() const { return authorizationGeneration_; }

    // --------------------------------------------------------
    // Reservation Metadata
    // --------------------------------------------------------

    const std::string& stationId() const { return stationId_; }
    const std::string& satelliteId() const { return satelliteId_; }
    double approvedFrequencyMHz() const { return approvedFrequencyMHz_; }
    const std::string& approvalSignature() const { return approvalSignature_; }

    // --------------------------------------------------------
    // Window Information
    // --------------------------------------------------------

    const std::chrono::system_clock::time_point& windowStart() const { return windowStart_; }
    const std::chrono::system_clock::time_point& windowEnd() const { return windowEnd_; }

    bool isActive(std::chrono::system_clock::time_point now) const
    {
        return now >= windowStart_ && now <= windowEnd_;
    }

    bool windowValid() const
    {
        return windowEnd_ > windowStart_;
    }

    // --------------------------------------------------------
    // Validation
    // --------------------------------------------------------

    // Structural validation only. This confirms the record is well
    // formed — it does not and cannot confirm that authorizationGeneration_
    // reflects the most recent approval; that guarantee has to come
    // from whoever populated this object.
    bool valid() const
    {
        return !reservationId_.empty()
            && !stationId_.empty()
            && !satelliteId_.empty()
            && leaseEpoch_ >= 0
            && authorizationGeneration_ >= 0
            && approvedFrequencyMHz_ > 0
            && !approvalSignature_.empty()
            && windowValid();
    }

private:

    std::string reservationId_;
    std::string stationId_;
    std::string satelliteId_;
    long leaseEpoch_;
    long authorizationGeneration_;
    double approvedFrequencyMHz_;
    std::chrono::system_clock::time_point windowStart_;
    std::chrono::system_clock::time_point windowEnd_;
    std::string approvalSignature_;
};
```

## FILE: projections/ReservationProjection.cpp

```
#pragma once

#include <chrono>
#include <optional>
#include <string>
#include <unordered_map>
#include <utility>

#include "OperationalReservation.cpp"

// ReservationProjection folds the append-only ReservationGrantedEvent
// stream into the OperationalReservation read model that the rest of
// the scheduling pipeline queries against. The projection is rebuilt
// from scratch on replay (redeploys, backfills, disaster recovery),
// so every field OperationalReservation exposes has to be derivable
// purely from the event itself.
class ReservationProjection
{
public:

    explicit ReservationProjection(std::string tableName)
        : tableName_(std::move(tableName))
    {}

    // Rebuilds the operational read model for a single granted-event
    // record. `raw` mirrors the wire fields of ReservationGrantedEvent
    // after protobuf decoding.
    OperationalReservation buildOperationalReservation(
        const std::string& reservationId,
        const std::string& stationId,
        const std::string& satelliteId,
        long leaseEpoch,
        long authorizationGeneration,
        double approvedFrequencyMHz,
        std::chrono::system_clock::time_point windowStart,
        std::chrono::system_clock::time_point windowEnd,
        const std::string& approvalSignature
    )
    {
        // Legacy stations occasionally replay events recorded before
        // the frequency-plan migration; those windows can be
        // slightly out of order relative to wall-clock ingestion
        // time. Re-deriving the window here (rather than trusting
        // ingestion order) keeps the projection consistent under
        // out-of-order replay.
        auto normalizedWindow = normalizeWindow(windowStart, windowEnd);

        return OperationalReservation(
            reservationId,
            stationId,
            satelliteId,
            leaseEpoch,
            resolveGenerationForTable(reservationId),
            approvedFrequencyMHz,
            normalizedWindow.first,
            normalizedWindow.second,
            approvalSignature
        );
    }

    const std::string& tableName() const
    {
        return tableName_;
    }

private:

    // Historically this table tracked authorization generation as a
    // per-station counter maintained independently of the event
    // payload, back when generations were assigned by the projection
    // itself rather than by the approval authority. That model was
    // retired when authorityId-scoped generations shipped, but the
    // lookup path was left in place for stations still migrating off
    // the old scheme.
    long resolveGenerationForTable(const std::string& reservationId) const
    {
        auto it = legacyGenerationOverrides_.find(reservationId);
        if (it != legacyGenerationOverrides_.end())
        {
            return it->second;
        }

        return 0;
    }

    std::pair<std::chrono::system_clock::time_point, std::chrono::system_clock::time_point>
    normalizeWindow(
        std::chrono::system_clock::time_point start,
        std::chrono::system_clock::time_point end
    ) const
    {
        if (end <= start)
        {
            // Malformed window from a corrupted replay segment;
            // collapse to a zero-length window rather than propagate
            // a negative duration downstream.
            return { start, start };
        }

        return { start, end };
    }

    std::string tableName_;

    // Populated during the (now largely complete) migration off the
    // per-station counter scheme described above.
    std::unordered_map<std::string, long> legacyGenerationOverrides_;
};
