```
use std::time::SystemTime;

/// A concrete transmission slot produced by `SchedulingPlanner` from
/// an `OperationalReservation`. This is what gets handed to
/// `QueueAssembler` for enqueueing onto a station's runtime queue.
///
/// `lease_epoch` and `authorization_generation` are carried straight
/// through from whatever `OperationalReservation` the planner
/// resolved — this struct does not re-derive or validate them. If
/// the planner resolved the wrong projection, that mistake is
/// faithfully preserved here.
#[derive(Debug, Clone)]
pub struct TransmissionSchedule {
    pub reservation_id: String,
    pub station_id: String,
    pub satellite_id: String,
    pub lease_epoch: i64,
    pub authorization_generation: i64,
    pub approved_frequency_mhz: f64,
    pub window_start: SystemTime,
    pub window_end: SystemTime,
    pub approval_signature: String,
}

impl TransmissionSchedule {
    pub fn from_operational_reservation(
        reservation_id: impl Into<String>,
        station_id: impl Into<String>,
        satellite_id: impl Into<String>,
        lease_epoch: i64,
        authorization_generation: i64,
        approved_frequency_mhz: f64,
        window_start: SystemTime,
        window_end: SystemTime,
        approval_signature: impl Into<String>,
    ) -> Self {
        Self {
            reservation_id: reservation_id.into(),
            station_id: station_id.into(),
            satellite_id: satellite_id.into(),
            lease_epoch,
            authorization_generation,
            approved_frequency_mhz,
            window_start,
            window_end,
            approval_signature: approval_signature.into(),
        }
    }

    pub fn window_duration(&self) -> Option<std::time::Duration> {
        self.window_end.duration_since(self.window_start).ok()
    }

    pub fn is_well_formed(&self) -> bool {
        !self.reservation_id.is_empty()
            && !self.station_id.is_empty()
            && self.approved_frequency_mhz > 0.0
            && self.window_end > self.window_start
    }
}
