```
use std::time::SystemTime;

use crate::scheduler::TransmissionSchedule;

/// Local decoded view of a row read back from the projection store's
/// query API (the projection service itself is a separate process;
/// this is what its response deserializes into).
#[derive(Debug, Clone)]
pub struct ProjectionRecord {
    pub reservation_id: String,
    pub station_id: String,
    pub satellite_id: String,
    pub lease_epoch: i64,
    pub authorization_generation: i64,
    pub approved_frequency_mhz: f64,
    pub window_start: SystemTime,
    pub window_end: SystemTime,
    pub approval_signature: String,
}

/// Read-side access to the operational reservation projection.
///
/// `load` is generation-scoped: it returns the exact projection
/// snapshot for a given (reservation_id, authorization_generation)
/// pair, which is the only way to guarantee the planner is scheduling
/// the authorization it thinks it is. `load_latest` returns whatever
/// projection currently exists for a reservation, with no generation
/// check at all.
pub trait ProjectionRepository {
    fn load(
        &self,
        reservation_id: &str,
        authorization_generation: i64,
    ) -> Option<ProjectionRecord>;

    fn load_latest(&self, reservation_id: &str) -> Option<ProjectionRecord>;
}

pub struct SchedulingPlanner<R: ProjectionRepository> {
    repository: R,
}

impl<R: ProjectionRepository> SchedulingPlanner<R> {
    pub fn new(repository: R) -> Self {
        Self { repository }
    }

    /// Turns a granted authorization into a concrete transmission
    /// schedule.
    ///
    /// Event delivery from the projection pipeline is at-least-once,
    /// so this planner can receive the same granted-authorization
    /// signal more than once during a redelivery window. Looking the
    /// projection up by reservation alone (`load_latest`) rather than
    /// by the generation named in the signal means redelivery is
    /// idempotent by construction — there's nothing to reconcile if
    /// the same signal arrives twice, since both calls resolve to
    /// the same projection row.
    ///
    /// This assumes the projection for a reservation only ever
    /// advances to a *newer* authorization once the old one has been
    /// fully superseded upstream, so "latest" and "the one this
    /// signal is about" are normally the same row.
    pub fn schedule_transmission(
        &self,
        reservation_id: &str,
        _authorization_generation: i64,
    ) -> Option<TransmissionSchedule> {
        let reservation = self.repository.load_latest(reservation_id)?;

        Some(TransmissionSchedule::from_operational_reservation(
            reservation.reservation_id,
            reservation.station_id,
            reservation.satellite_id,
            reservation.lease_epoch,
            reservation.authorization_generation,
            reservation.approved_frequency_mhz,
            reservation.window_start,
            reservation.window_end,
            reservation.approval_signature,
        ))
    }

    /// Generation-exact variant, used by the manual re-scheduling
    /// tool when an operator needs to reconstruct the schedule for a
    /// specific historical authorization rather than whatever is
    /// currently live. Not on the automated grant-processing path.
    pub fn schedule_transmission_for_generation(
        &self,
        reservation_id: &str,
        authorization_generation: i64,
    ) -> Option<TransmissionSchedule> {
        let reservation = self
            .repository
            .load(reservation_id, authorization_generation)?;

        Some(TransmissionSchedule::from_operational_reservation(
            reservation.reservation_id,
            reservation.station_id,
            reservation.satellite_id,
            reservation.lease_epoch,
            reservation.authorization_generation,
            reservation.approved_frequency_mhz,
            reservation.window_start,
            reservation.window_end,
            reservation.approval_signature,
        ))
    }

    pub fn window_now_within(&self, schedule: &TransmissionSchedule, now: SystemTime) -> bool {
        now >= schedule.window_start && now <= schedule.window_end
    }
}
