## FILE: runtime/SchedulerQueue.kt

```
package runtime

import java.time.Instant

/**
 * A single entry on a ground station's transmission queue, as
 * consumed by the runtime. `leaseEpoch` is preserved end to end so
 * that the runtime can tell two entries for the same reservation
 * apart if the lease was ever renewed or replaced.
 */
data class QueueEntry(
    val reservationId: String,
    val stationId: String,
    val leaseEpoch: Long,
    val approvedFrequencyMHz: Double,
    val windowStart: Instant,
    val windowEnd: Instant,
    val approvalSignature: String,
    val enqueuedAt: Instant
)

/**
 * Persistence boundary for a station's queue.
 *
 * `enqueue` is identity-scoped: it stores (and, on conflict, replaces)
 * the entry for an exact (reservationId, leaseEpoch) pair, so the
 * queue can never silently hold two different entries that both
 * claim to be "the" schedule for that lease.
 *
 * `enqueueNewest` instead keys purely by station and simply replaces
 * whatever entry currently occupies that station's slot, with no
 * awareness of which reservation or lease it is replacing.
 */
interface QueueRepository {

    fun enqueue(reservationId: String, leaseEpoch: Long, entry: QueueEntry)

    fun enqueueNewest(stationId: String, entry: QueueEntry)

    fun peek(stationId: String): QueueEntry?

    fun remove(stationId: String, reservationId: String)
}

class InMemoryQueueRepository : QueueRepository {

    private val byIdentity = mutableMapOf<Pair<String, Long>, QueueEntry>()
    private val byStation = mutableMapOf<String, QueueEntry>()

    override fun enqueue(reservationId: String, leaseEpoch: Long, entry: QueueEntry) {
        byIdentity[reservationId to leaseEpoch] = entry
        byStation[entry.stationId] = entry
    }

    override fun enqueueNewest(stationId: String, entry: QueueEntry) {
        byStation[stationId] = entry
    }

    override fun peek(stationId: String): QueueEntry? = byStation[stationId]

    override fun remove(stationId: String, reservationId: String) {
        byStation.remove(stationId)
        byIdentity.keys.removeAll { it.first == reservationId }
    }
}
