using System;
using System.Collections.Generic;

namespace EnterpriseAgent.Approval
{

    public sealed class ApprovedToolInvocation
    {
        public string ToolId { get; }

        public string EndpointId { get; }

        public string ApprovalGeneration { get; }

        public IReadOnlyDictionary<string, string> AllowedArguments { get; }

        public TimeSpan Timeout { get; }

        public DateTime ApprovalTimestamp { get; }

        public ApprovedToolInvocation(

            string toolId,

            string endpointId,

            string approvalGeneration,

            IReadOnlyDictionary<string, string> allowedArguments,

            TimeSpan timeout,

            DateTime approvalTimestamp

        )
        {
            if (string.IsNullOrWhiteSpace(toolId))
                throw new ArgumentException(
                    "Tool identifier is required."
                );

            if (string.IsNullOrWhiteSpace(endpointId))
                throw new ArgumentException(
                    "Endpoint identifier is required."
                );

            if (string.IsNullOrWhiteSpace(approvalGeneration))
                throw new ArgumentException(
                    "Approval generation is required."
                );

            ToolId = toolId;

            EndpointId = endpointId;

            ApprovalGeneration = approvalGeneration;

            AllowedArguments =

                new Dictionary<string, string>(

                    allowedArguments

                );

            Timeout = timeout;

            ApprovalTimestamp = approvalTimestamp;
        }

        //--------------------------------------------------------------

        public int ArgumentCount()
        {
            return AllowedArguments.Count;
        }

        public bool AllowsArgument(

            string name

        )
        {
            return AllowedArguments.ContainsKey(

                name

            );
        }

        public string Summary()
        {
            return

                $"{ToolId} @ {EndpointId}";
        }
    }
}
