use std::collections::HashMap;


#[derive(Clone, Debug)]
pub struct ToolEndpoint {

    pub tool_id: String,

    pub endpoint_id: String,

    pub connector: String,

    pub active: bool

}

pub struct ToolRegistry {

    endpoints:

        HashMap<String, ToolEndpoint>

}

impl ToolRegistry {

    pub fn new() -> Self {

        Self {

            endpoints:

                HashMap::new()

        }

    }

    //------------------------------------------------------------------
    // Registration
    //------------------------------------------------------------------

    pub fn register(

        &mut self,

        endpoint: ToolEndpoint

    ) {

        self.endpoints.insert(

            endpoint.tool_id.clone(),

            endpoint

        );

    }

    //------------------------------------------------------------------
    // Runtime Resolution
    //------------------------------------------------------------------

    pub fn resolve(

        &self,

        tool_id: &str

    ) -> Result<&ToolEndpoint, String> {

        match self.endpoints.get(

            tool_id

        ) {

            Some(endpoint)

                if endpoint.active =>

            {

                Ok(endpoint)

            }

            Some(_) =>

                Err(

                    "Endpoint is inactive."

                        .into()

                ),

            None =>

                Err(

                    "Tool endpoint not found."

                        .into()

                )

        }

    }

    //------------------------------------------------------------------
    // Queries
    //------------------------------------------------------------------

    pub fn contains(

        &self,

        tool_id: &str

    ) -> bool {

        self.endpoints.contains_key(

            tool_id

        )

    }

    pub fn endpoint_count(

        &self

    ) -> usize {

        self.endpoints.len()

    }

    pub fn summary(

        &self

    ) -> String {

        format!(

            "Registered {} tool endpoints",

            self.endpoint_count()

        )

    }

}
