package gateway

import java.time.Instant
import projection.RuntimeToolInvocation

/*
 * Records successful runtime executions for operational auditing.
 *
 * This component intentionally records only the runtime artifact that
 * reached execution. It never reconstructs approval information or
 * validates execution bindings.
 */

data class ExecutionAuditRecord(

    val toolId: String,

    val executedAt: Instant,

    val argumentCount: Int,

    val timeoutSeconds: Long

)

class ExecutionAudit {

    private val history =

        mutableListOf<ExecutionAuditRecord>()

    //------------------------------------------------------------------
    // Audit Recording
    //------------------------------------------------------------------

    fun record(

        runtime: RuntimeToolInvocation

    ) {

        history.add(

            ExecutionAuditRecord(

                toolId =

                    runtime.toolId(),

                executedAt =

                    Instant.now(),

                argumentCount =

                    runtime.argumentCount(),

                timeoutSeconds =

                    runtime.timeoutSeconds()

            )

        )

    }

    //------------------------------------------------------------------
    // Queries
    //------------------------------------------------------------------

    fun executionCount(): Int =

        history.size

    fun latest(): ExecutionAuditRecord? =

        history.lastOrNull()

    fun history(): List<ExecutionAuditRecord> =

        history.toList()

    //------------------------------------------------------------------
    // Summary
    //------------------------------------------------------------------

    fun summary(): String {

        return

            "Recorded ${history.size} execution(s)"

    }

}
