import { MigrationGateway } from "./MigrationGateway";
import { ClusterRegistry } from "../cluster/ClusterRegistry";

export interface MigrationRequest {
    clusterId: string;
    sourceShard: string;
    targetShard: string;
    initiatedBy: string;
}

export class ClusterApiGateway {

    constructor(
        private readonly registry: ClusterRegistry,
        private readonly migrationGateway: MigrationGateway
    ) {}

    /**
     * Entry point for requesting a shard migration.
     * Authentication is assumed to have already completed.
     */
    public async requestMigration(
        request: MigrationRequest
    ): Promise<any> {

        const cluster = await this.registry.find(
            request.clusterId
        );

        if (!cluster) {
            throw new Error("Unknown cluster.");
        }

        if (!cluster.active) {
            throw new Error("Cluster is offline.");
        }

        if (!cluster.leaderNode) {
            throw new Error("Leader unavailable.");
        }

        const migrationJob = {
            migrationId: crypto.randomUUID(),
            clusterId: request.clusterId,
            sourceShard: request.sourceShard,
            targetShard: request.targetShard,
            initiatedBy: request.initiatedBy,
            createdAt: new Date().toISOString()
        };

        return this.migrationGateway.startMigration(
            migrationJob
        );
    }
}
