use crate::consensus::{
    ConsensusCommit,
    QuorumTracker,
};

pub struct ConsensusCoordinator<'a> {
    quorum_tracker: &'a QuorumTracker,
}

impl<'a> ConsensusCoordinator<'a> {

    pub fn new(
        quorum_tracker: &'a QuorumTracker,
    ) -> Self {

        Self {
            quorum_tracker,
        }

    }

    //------------------------------------------------------------------
    // Public API
    //------------------------------------------------------------------

    pub fn begin_consensus(
        &self,
        cluster_id: &str,
        source_shard: &str,
        target_shard: &str,
    ) -> Result<ConsensusCommit, String> {

        let quorum = self.quorum_tracker.collect_votes(
            cluster_id,
        )?;

        if !quorum.quorum_reached {
            return Err(
                "Consensus quorum not achieved."
                    .into(),
            );
        }

        let commit = ConsensusCommit::new(
            cluster_id.to_string(),
            source_shard.to_string(),
            target_shard.to_string(),
            quorum.term,
            quorum.commit_index,
            true,
        );

        Ok(commit)
    }

    //------------------------------------------------------------------

    pub fn verify_commit(
        &self,
        commit: &ConsensusCommit,
    ) -> bool {

        commit.commit_confirmed
            && commit.commit_index > 0

    }
}
