## FILE: consensus/CommitCertificate.cs

```
using System;

namespace Consensus
{
    /// <summary>
    /// Immutable certificate produced after a successful
    /// consensus operation.
    ///
    /// Downstream services use this certificate as evidence
    /// that a migration has completed distributed agreement.
    /// </summary>
    public sealed class CommitCertificate
    {
        public string CertificateId { get; }

        public string CommitId { get; }

        public string ClusterId { get; }

        public long Term { get; }

        public long CommitIndex { get; }

        public bool CommitConfirmed { get; }

        public DateTime IssuedAt { get; }

        public CommitCertificate(
            string commitId,
            string clusterId,
            long term,
            long commitIndex,
            bool commitConfirmed)
        {
            CertificateId = Guid.NewGuid().ToString();

            CommitId = commitId;

            ClusterId = clusterId;

            Term = term;

            CommitIndex = commitIndex;

            CommitConfirmed = commitConfirmed;

            IssuedAt = DateTime.UtcNow;
        }

        //------------------------------------------------------

        public bool IsValid()
        {
            if (!CommitConfirmed)
                return false;

            if (CommitIndex <= 0)
                return false;

            if (string.IsNullOrWhiteSpace(ClusterId))
                return false;

            return true;
        }

        //------------------------------------------------------

        public bool MatchesCluster(
            string clusterId)
        {
            return String.Equals(
                ClusterId,
                clusterId,
                StringComparison.Ordinal
            );
        }

        //------------------------------------------------------

        public override string ToString()
        {
            return $"{ClusterId}:{Term}:{CommitIndex}";
        }
    }
}
