class MigrationAuthorization

  def initialize(commit_policy)
    @commit_policy = commit_policy
  end

  # ----------------------------------------------------------
  # Public API
  # ----------------------------------------------------------

  def authorize(plan)

    validate(plan)

    unless @commit_policy.evaluate(plan)
      raise "Migration policy rejected."
    end

    AuthorizationDecision.new(

      migration_id: plan.migrationId,

      cluster_id: plan.clusterId,

      source_shard: plan.sourceShard,

      target_shard: plan.targetShard,

      leader_term: plan.leaderTerm,

      commit_index: plan.commitIndex,

      approved: true

    )

  end

  # ----------------------------------------------------------

  private

  def validate(plan)

    raise "Migration plan required." if plan.nil?

    raise "Missing cluster." if plan.clusterId.nil? || plan.clusterId.empty?

    raise "Missing migration id." if plan.migrationId.nil? || plan.migrationId.empty?

    raise "Invalid leader term." if plan.leaderTerm <= 0

    raise "Invalid commit index." if plan.commitIndex <= 0

  end

end

# --------------------------------------------------------------

AuthorizationDecision = Struct.new(

  :migration_id,

  :cluster_id,

  :source_shard,

  :target_shard,

  :leader_term,

  :commit_index,

  :approved,

  keyword_init: true

)
