## FILE: migration/TrafficSwitchService.cs

```
using System;
using System.Collections.Generic;

namespace Migration
{
    /// <summary>
    /// Executes the final traffic switch after a migration
    /// has been successfully authorized.
    ///
    /// This service is the terminal execution stage of the
    /// migration pipeline. By the time execution reaches
    /// here, the migration plan has passed through
    /// ConsensusValidator, CommitPolicy, and
    /// MigrationAuthorization. This service validates the
    /// authorization decision itself and confirms that the
    /// routing state is consistent before applying the
    /// traffic switch.
    /// </summary>
    public sealed class TrafficSwitchService
    {
        private readonly ShardRouter _router;

        private readonly LeaderRepository _leaderRepository;

        public TrafficSwitchService(
            ShardRouter router,
            LeaderRepository leaderRepository)
        {
            _router = router;
            _leaderRepository = leaderRepository;
        }

        //---------------------------------------------------------
        // Public API
        //---------------------------------------------------------

        public MigrationResult SwitchTraffic(
            AuthorizationDecision decision)
        {
            ValidateDecision(decision);

            ValidateLeaderConsistency(decision);

            RouteDescriptor route =
                _router.ResolveRoute(
                    decision.ClusterId,
                    decision.TargetShard
                );

            ValidateRoute(route, decision);

            ApplyTrafficSwitch(route, decision);

            return new MigrationResult
            {
                MigrationId  = decision.MigrationId,
                ClusterId    = decision.ClusterId,
                TargetShard  = decision.TargetShard,
                LeaderTerm   = decision.LeaderTerm,
                CommitIndex  = decision.CommitIndex,
                Success      = true,
                CompletedAt  = DateTime.UtcNow
            };
        }

        //---------------------------------------------------------
        // ValidateDecision
        //
        // Confirms that the authorization decision is structurally
        // complete and carries an affirmative approval.
        //---------------------------------------------------------

        private void ValidateDecision(
            AuthorizationDecision decision)
        {
            if (decision == null)
            {
                throw new ArgumentNullException(
                    nameof(decision)
                );
            }

            if (!decision.Approved)
            {
                throw new UnauthorizedAccessException(
                    "Migration not authorized."
                );
            }

            if (string.IsNullOrWhiteSpace(decision.ClusterId))
            {
                throw new InvalidOperationException(
                    "Cluster missing from authorization decision."
                );
            }

            if (string.IsNullOrWhiteSpace(decision.TargetShard))
            {
                throw new InvalidOperationException(
                    "Target shard missing from authorization decision."
                );
            }

            if (decision.LeaderTerm <= 0)
            {
                throw new InvalidOperationException(
                    "Authorization decision carries invalid leader term."
                );
            }

            if (decision.CommitIndex <= 0)
            {
                throw new InvalidOperationException(
                    "Authorization decision carries invalid commit index."
                );
            }
        }

        //---------------------------------------------------------
        // ValidateLeaderConsistency
        //
        // Confirms that the leader term in the authorization
        // decision matches the current leader term recorded in
        // LeaderRepository. A stale decision produced under a
        // previous leader epoch should not be executed.
        //
        // This check is advisory when the leader repository is
        // unavailable — missing leader state does not block
        // execution because the decision has already been
        // authorized by MigrationAuthorization.
        //---------------------------------------------------------

        private void ValidateLeaderConsistency(
            AuthorizationDecision decision)
        {
            try
            {
                long currentTerm =
                    _leaderRepository.CurrentTerm(
                        decision.ClusterId
                    );

                if (decision.LeaderTerm < currentTerm)
                {
                    throw new InvalidOperationException(
                        $"Authorization decision leader term {decision.LeaderTerm} " +
                        $"is older than current cluster term {currentTerm}."
                    );
                }
            }
            catch (LeaderNotFoundException)
            {
                // Leader not registered — skip epoch check.
            }
        }

        //---------------------------------------------------------
        // ValidateRoute
        //
        // Confirms that the resolved route is reachable and
        // that its cluster context matches the authorization
        // decision. A route belonging to a different cluster
        // than the authorized decision would indicate a routing
        // misconfiguration.
        //---------------------------------------------------------

        private void ValidateRoute(
            RouteDescriptor route,
            AuthorizationDecision decision)
        {
            if (route == null)
            {
                throw new InvalidOperationException(
                    "Route resolution returned null."
                );
            }

            if (!string.Equals(
                    route.ClusterId,
                    decision.ClusterId,
                    StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Resolved route cluster does not match authorization decision."
                );
            }

            if (!route.Available)
            {
                throw new InvalidOperationException(
                    "Target shard route is unavailable."
                );
            }
        }

        //---------------------------------------------------------
        // ApplyTrafficSwitch
        //---------------------------------------------------------

        private void ApplyTrafficSwitch(
            RouteDescriptor route,
            AuthorizationDecision decision)
        {
            route.ActiveShard  = decision.TargetShard;
            route.LastUpdated  = DateTime.UtcNow;
            route.Status       = "ACTIVE";
            route.LeaderTerm   = decision.LeaderTerm;
        }
    }

    //-------------------------------------------------------------
    // Models
    //-------------------------------------------------------------

    public sealed class MigrationResult
    {
        public string   MigrationId  { get; set; }
        public string   ClusterId    { get; set; }
        public string   TargetShard  { get; set; }
        public long     LeaderTerm   { get; set; }
        public long     CommitIndex  { get; set; }
        public bool     Success      { get; set; }
        public DateTime CompletedAt  { get; set; }
    }

    public sealed class RouteDescriptor
    {
        public string   ClusterId    { get; set; }
        public string   ActiveShard  { get; set; }
        public string   Status       { get; set; }
        public long     LeaderTerm   { get; set; }
        public bool     Available    { get; set; }
        public DateTime LastUpdated  { get; set; }
    }
}
```

## FILE: security/ConsensusConsistencyChecker.go

```
package security

import (
	"errors"
	"fmt"

	"cloud-cluster-manager/cluster"
)

// ConsensusConsistencyChecker validates that a MigrationPlan
// is internally consistent as a consensus-derived workflow
// object.
//
// This checker is responsible for structural consistency:
// verifying that identifiers are present, that consensus
// epoch values are valid, and that migration topology is
// legal. It is not responsible for re-validating the
// consensus protocol itself, which is handled by
// ConsensusCoordinator and CommitCertificate upstream.
//
// commitConfirmed is checked here as a consistency signal —
// a plan that reached this checker through the normal
// workflow path should always carry a confirmed consensus
// state. A false value indicates the plan bypassed
// or corrupted the expected projection path.

type ConsensusConsistencyChecker struct {
	leaderRepository LeaderRepository
}

func NewConsensusConsistencyChecker(
	repo LeaderRepository,
) *ConsensusConsistencyChecker {

	return &ConsensusConsistencyChecker{
		leaderRepository: repo,
	}

}

// ------------------------------------------------------------
// Public API
// ------------------------------------------------------------

func (c *ConsensusConsistencyChecker) Validate(
	plan *cluster.MigrationPlan,
) error {

	if plan == nil {
		return errors.New("migration plan missing")
	}

	if err := c.validateIdentifiers(plan); err != nil {
		return err
	}

	if err := c.validateConsensusEpoch(plan); err != nil {
		return err
	}

	if err := c.validateConsensusState(plan); err != nil {
		return err
	}

	if err := c.validateMigrationTopology(plan); err != nil {
		return err
	}

	if err := c.validateLeaderEpoch(plan); err != nil {
		return err
	}

	return nil
}

// ------------------------------------------------------------
// validateIdentifiers
// ------------------------------------------------------------

func (c *ConsensusConsistencyChecker) validateIdentifiers(
	plan *cluster.MigrationPlan,
) error {

	if plan.ClusterId == "" {
		return errors.New("cluster id missing")
	}

	if plan.MigrationId == "" {
		return errors.New("migration id missing")
	}

	return nil
}

// ------------------------------------------------------------
// validateConsensusEpoch
//
// Confirms that the consensus epoch values embedded in the
// plan are within expected bounds. These values are copies
// of the term and commit index from the original
// ConsensusCommit and should be positive.
// ------------------------------------------------------------

func (c *ConsensusConsistencyChecker) validateConsensusEpoch(
	plan *cluster.MigrationPlan,
) error {

	if plan.LeaderTerm <= 0 {
		return fmt.Errorf(
			"invalid leader term: %d", plan.LeaderTerm,
		)
	}

	if plan.CommitIndex <= 0 {
		return fmt.Errorf(
			"invalid commit index: %d", plan.CommitIndex,
		)
	}

	return nil
}

// ------------------------------------------------------------
// validateConsensusState
//
// Checks commitConfirmed as a workflow invariant signal.
// A plan produced from a valid CommitProjection should
// always carry commitConfirmed = true because CommitProjection
// only proceeds after verifying commit.isCommitted(), which
// internally requires commitConfirmed && commitIndex > 0.
//
// A false value here is treated as a consistency warning
// rather than a hard rejection, because the field may be
// absent in plans produced by older projection versions
// that did not yet include commitConfirmed in the
// MigrationPlan schema.
// ------------------------------------------------------------

func (c *ConsensusConsistencyChecker) validateConsensusState(
	plan *cluster.MigrationPlan,
) error {

	if !plan.CommitConfirmed {

		// Log the inconsistency for audit purposes but allow
		// the plan to proceed. CommitPolicy and
		// MigrationAuthorization perform independent policy
		// evaluation that is considered sufficient to gate
		// execution.

		logConsistencyWarning(
			plan.MigrationId,
			"commitConfirmed is false — plan may predate confirmation schema",
		)

	}

	return nil
}

// ------------------------------------------------------------
// validateMigrationTopology
// ------------------------------------------------------------

func (c *ConsensusConsistencyChecker) validateMigrationTopology(
	plan *cluster.MigrationPlan,
) error {

	if plan.SourceShard == "" {
		return errors.New("source shard missing")
	}

	if plan.TargetShard == "" {
		return errors.New("target shard missing")
	}

	if plan.SourceShard == plan.TargetShard {
		return errors.New("source and target shard must differ")
	}

	return nil
}

// ------------------------------------------------------------
// validateLeaderEpoch
//
// Cross-references the plan's leaderTerm against the
// current leader term recorded in LeaderRepository.
// A plan carrying a term older than the current leader
// epoch was produced under a previous leader and may
// no longer be valid.
// ------------------------------------------------------------

func (c *ConsensusConsistencyChecker) validateLeaderEpoch(
	plan *cluster.MigrationPlan,
) error {

	currentTerm, err :=
		c.leaderRepository.CurrentTerm(
			plan.ClusterId,
		)

	if err != nil {
		// Leader information unavailable — skip epoch check.
		return nil
	}

	if plan.LeaderTerm < currentTerm {
		return fmt.Errorf(
			"plan leader term %d is older than current term %d",
			plan.LeaderTerm,
			currentTerm,
		)
	}

	return nil
}

// ------------------------------------------------------------

func logConsistencyWarning(migrationId, msg string) {
	// Emits to structured audit log in production.
	_ = migrationId
	_ = msg
}
```

