```
local ShardRouter = {}
ShardRouter.__index = ShardRouter

----------------------------------------------------------------------
-- Constructor
----------------------------------------------------------------------

function ShardRouter.new(clusterRegistry)

    local self = {

        clusterRegistry = clusterRegistry

    }

    setmetatable(self, ShardRouter)

    return self
end

----------------------------------------------------------------------
-- Public API
----------------------------------------------------------------------

function ShardRouter:resolveRoute(
    clusterId,
    targetShard
)

    self:validate(
        clusterId,
        targetShard
    )

    local cluster =
        self.clusterRegistry:get(clusterId)

    if cluster == nil then
        error("Cluster not found.")
    end

    local endpoint =
        self:findShardEndpoint(
            cluster,
            targetShard
        )

    return {

        clusterId = clusterId,

        targetShard = targetShard,

        endpoint = endpoint,

        available = true

    }

end

----------------------------------------------------------------------
-- Validation
----------------------------------------------------------------------

function ShardRouter:validate(

    clusterId,

    targetShard

)

    assert(
        clusterId ~= nil and clusterId ~= "",
        "Cluster ID required."
    )

    assert(
        targetShard ~= nil and targetShard ~= "",
        "Target shard required."
    )

end

----------------------------------------------------------------------
-- Internal Helpers
----------------------------------------------------------------------

function ShardRouter:findShardEndpoint(

    cluster,

    shard

)

    for _, node in ipairs(cluster.shards) do

        if node.id == shard then
            return node.endpoint
        end

    end

    error("Target shard not found.")

end

----------------------------------------------------------------------
-- Diagnostics
----------------------------------------------------------------------

function ShardRouter:describeRoute(

    clusterId,

    shard

)

    local route = self:resolveRoute(

        clusterId,

        shard

    )

    return {

        cluster = route.clusterId,

        shard = route.targetShard,

        endpoint = route.endpoint

    }

end

----------------------------------------------------------------------
-- Health
----------------------------------------------------------------------

function ShardRouter:isReachable(

    clusterId,

    shard

)

    local ok, _ = pcall(function()

        self:resolveRoute(

            clusterId,

            shard

        )

    end)

    return ok

end

return ShardRouter
