  def migration_failed(cluster) do

    increment(
      "migration.failed",
      cluster
    )

  end

  def consensus_completed(cluster) do

    increment(
      "consensus.completed",
      cluster
    )

  end

  def consensus_failed(cluster) do

    increment(
      "consensus.failed",
      cluster
    )

  end

  #-------------------------------------------------------------

  defp increment(metric, cluster) do

    :telemetry.execute(

      [String.to_atom(metric)],

      %{count: 1},

      %{cluster: cluster}

    )

  end

