from feature_projection import FeatureProjectionBuilder


class FeaturePipeline:

    def __init__(self):

        self._projection_builder = FeatureProjectionBuilder()

    # ------------------------------------------------------------------

    def generate_feature_set(

        self,

        request

    ):

        self._validate_request(

            request

        )

        raw_dataset = self._load_dataset(

            request["datasetId"]

        )

        engineered_features = self._extract_features(

            raw_dataset,

            request["features"]

        )

        projection = self._projection_builder.build_projection(

            request,

            engineered_features,

            raw_dataset

        )

        return self._projection_builder.build_feature_set(

            projection

        )

    # ------------------------------------------------------------------

    def _load_dataset(

        self,

        dataset_id

    ):

        return {

            "datasetId": dataset_id,

            "datasetHash": f"HASH-{dataset_id}",

            "approved": True,

            "version": 8

        }

    # ------------------------------------------------------------------

    def _extract_features(

        self,

        dataset,

        feature_list

    ):

        engineered = []

        for feature in feature_list:

            engineered.append({

                "name": feature,

                "dtype": "float",

                "normalized": True

            })

        return engineered

    # ------------------------------------------------------------------

    def _validate_request(

        self,

        request

    ):

        if "datasetId" not in request:

            raise ValueError(

                "Dataset identifier missing."

            )

        if "features" not in request:

            raise ValueError(

                "Feature list missing."

            )

        if len(

            request["features"]

        ) == 0:

            raise ValueError(

                "At least one feature required."

            )
