from datetime import datetime


########################################################################


class ModelTrainer:

    def __init__(

        self,

        approval_policy,

        schema_validator,

        dataset_validator,

        metrics

    ):

        self._approval_policy = approval_policy

        self._schema_validator = schema_validator

        self._dataset_validator = dataset_validator

        self._metrics = metrics

    # ------------------------------------------------------------------

    def train(

        self,

        bundle,

        experiment,

        configuration

    ):

        self._validate_training_request(

            bundle,

            configuration

        )

        self._validate_bundle(

            bundle

        )

        self._validate_experiment(

            experiment

        )

        training_context = self._build_training_context(

            bundle,

            experiment,

            configuration

        )

        model = self._execute_training(

            training_context

        )

        self._metrics.record_training_job()

        return {

            "modelId":

                model["modelId"],

            "status":

                "COMPLETED",

            "trainedAt":

                datetime.utcnow(),

            "experimentId":

                experiment["experimentId"]

        }

    # ------------------------------------------------------------------

    def _validate_training_request(

        self,

        bundle,

        configuration

    ):

        self._approval_policy.validate_training_approval(

            {

                "datasetId":

                    bundle.dataset_id,

                "datasetHash":

                    bundle.dataset_hash,

                "featureSchema":

                    bundle.feature_schema,

                "approvalRevision":

                    bundle.approval_revision,

                "fingerprint":

                    bundle.fingerprint

            }

        )

        self._schema_validator.validate(

            {

                "featureSetId":

                    bundle.feature_set_id,

                "lineageVersion":

                    1,

                "featureSchema":

                    bundle.feature_schema

            },

            configuration["expectedSchema"]

        )

    # ------------------------------------------------------------------

    def _validate_bundle(

        self,

        bundle

    ):

        bundle.validate()

        self._dataset_validator.validate(

            {

                "datasetId":

                    bundle.dataset_id,

                "datasetHash":

                    bundle.dataset_hash

            },

            {

                "datasetId":

                    bundle.dataset_id,

                "datasetHash":

                    bundle.dataset_hash,

                "approved":

                    True,

                "version":

                    1

            }

        )

    # ------------------------------------------------------------------

    def _validate_experiment(

        self,

        experiment

    ):

        if not experiment.get(

            "experimentId"

        ):

            raise ValueError(

                "Experiment identifier missing."

            )

        if experiment.get(

            "status"

        ) != "READY":

            raise ValueError(

                "Experiment not ready."

            )

    # ------------------------------------------------------------------

    def _build_training_context(

        self,

        bundle,

        experiment,

        configuration

    ):

        return {

            "featureSetId":

                bundle.feature_set_id,

            "datasetId":

                bundle.dataset_id,

            "datasetHash":

                bundle.dataset_hash,

            "featureSchema":

                bundle.feature_schema,

            "approvalRevision":

                bundle.approval_revision,

            "experiment":

                experiment,

            "configuration":

                configuration

        }

    # ------------------------------------------------------------------

    def _execute_training(

        self,

        context

    ):

        return {

            "modelId":

                f"mdl-{context['featureSetId']}",

            "trainedAt":

                datetime.utcnow()

        }
