## FILE: serialization/registry_codec.ts

```
export interface TrainingBundleMessage {

    featureSetId: string;

    datasetId: string;

    datasetHash: string;

    lineageVersion: number;

    featureSchema: unknown[];

    featureGroup: string;

    approvalRevision: number;

    createdBy: string;

    fingerprint: string;

}

//////////////////////////////////////////////////////////////////////

export class RegistryCodec {

    //----------------------------------------------------------------

    encode(

        bundle: TrainingBundleMessage

    ): string {

        this.validate(

            bundle

        );

        return JSON.stringify(

            bundle

        );

    }

    //----------------------------------------------------------------

    decode(

        payload: string

    ): TrainingBundleMessage {

        const bundle =

            JSON.parse(

                payload

            ) as TrainingBundleMessage;

        this.validate(

            bundle

        );

        return bundle;

    }

    //----------------------------------------------------------------

    private validate(

        bundle: TrainingBundleMessage

    ): void {

        if (!bundle.featureSetId)

            throw new Error(

                "Feature set identifier missing."

            );

        if (!bundle.datasetId)

            throw new Error(

                "Dataset identifier missing."

            );

        if (!bundle.datasetHash)

            throw new Error(

                "Dataset hash missing."

            );

        if (bundle.lineageVersion <= 0)

            throw new Error(

                "Invalid lineage version."

            );

        if (!bundle.featureSchema ||

            bundle.featureSchema.length === 0)

            throw new Error(

                "Feature schema missing."

            );

        if (bundle.approvalRevision <= 0)

            throw new Error(

                "Invalid approval revision."

            );

        if (!bundle.fingerprint)

            throw new Error(

                "Bundle fingerprint missing."

            );

    }

}
