class DatasetValidator:

    # ------------------------------------------------------------------

    def validate(

        self,

        feature_set,

        dataset

    ):

        self._validate_dataset_identity(

            feature_set,

            dataset

        )

        self._validate_dataset_hash(

            feature_set,

            dataset

        )

        self._validate_dataset_state(

            dataset

        )

        return True

    # ------------------------------------------------------------------

    def _validate_dataset_identity(

        self,

        feature_set,

        dataset

    ):

        if feature_set["datasetId"] != dataset["datasetId"]:

            raise ValueError(

                "Dataset identifier mismatch."

            )

    # ------------------------------------------------------------------

    def _validate_dataset_hash(

        self,

        feature_set,

        dataset

    ):

        if (

            feature_set["datasetHash"]

            !=

            dataset["datasetHash"]

        ):

            raise ValueError(

                "Dataset hash mismatch."

            )

    # ------------------------------------------------------------------

    def _validate_dataset_state(

        self,

        dataset

    ):

        if not dataset.get(

            "approved",

            False

        ):

            raise ValueError(

                "Dataset not approved."

            )

        if dataset.get(

            "version",

            0

        ) <= 0:

            raise ValueError(

                "Invalid dataset version."

            )

        if not dataset.get(

            "datasetHash"

        ):

            raise ValueError(

                "Dataset hash missing."

            )
