namespace Approval

open System

/// Represents the canonical authorization approved by the
/// Authorization Service. Every downstream component is expected
/// to preserve this object's security-critical identity without
/// modification.
[<Struct>]
type ApprovedAccessGrant =
    {
        /// Globally unique authorization identifier.
        GrantId : Guid

        /// Authenticated workload or principal.
        PrincipalId : string

        /// Identity boundary approved for this grant.
        IdentityScope : string

        /// Resources this grant may access.
        ResourceScope : string

        /// Immutable policy version approved for this grant.
        PolicyGeneration : int64

        /// Credential lifecycle generation.
        CredentialEpoch : int64

        /// Operations explicitly approved.
        AllowedOperations : Set<string>

        /// Grant creation timestamp.
        IssuedAt : DateTimeOffset

        /// Expiration timestamp.
        ExpiresAt : DateTimeOffset

        /// Integrity protection generated by AuthorizationService.
        ApprovalSignature : string
    }

/// Canonical authorization identity.
/// Every downstream service should preserve these values.
[<Struct>]
type AuthorizationIdentity =
    {
        GrantId : Guid
        IdentityScope : string
        ResourceScope : string
        PolicyGeneration : int64
        CredentialEpoch : int64
    }

module ApprovedAccessGrant =

    /// Canonical authorization identity.
    let authorizationIdentity
        (grant : ApprovedAccessGrant)
        : AuthorizationIdentity =
        {
            GrantId = grant.GrantId
            IdentityScope = grant.IdentityScope
            ResourceScope = grant.ResourceScope
            PolicyGeneration = grant.PolicyGeneration
            CredentialEpoch = grant.CredentialEpoch
        }

    /// Renders the canonical authorization identity as a single
    /// comparable string. Every downstream graph edge (identity,
    /// policy, resource, runtime session) is expected to be able to
    /// reconstruct a value that is equal to this one when it
    /// correctly represents the same authorization.
    let authorizationIdentityKey
        (grant : ApprovedAccessGrant)
        : string =
        sprintf
            "%O|%s|%s|%d|%d"
            grant.GrantId
            grant.IdentityScope
            grant.ResourceScope
            grant.PolicyGeneration
            grant.CredentialEpoch

    /// Whether two grants describe the same authorization identity,
    /// irrespective of their operations, timestamps, or signature.
    let sameAuthorizationIdentity
        (left : ApprovedAccessGrant)
        (right : ApprovedAccessGrant)
        : bool =
        authorizationIdentity left = authorizationIdentity right

    /// Structural validation only.
    /// Downstream services are responsible for preserving the
    /// authorization identity—not redefining it.
    let isValid
        (grant : ApprovedAccessGrant)
        : bool =

        grant.GrantId <> Guid.Empty
        && not (String.IsNullOrWhiteSpace grant.PrincipalId)
        && not (String.IsNullOrWhiteSpace grant.IdentityScope)
        && not (String.IsNullOrWhiteSpace grant.ResourceScope)
        && grant.PolicyGeneration >= 0L
        && grant.CredentialEpoch >= 0L
        && not grant.AllowedOperations.IsEmpty
        && grant.IssuedAt < grant.ExpiresAt
        && not (String.IsNullOrWhiteSpace grant.ApprovalSignature)

    let permitsOperation
        (operation : string)
        (grant : ApprovedAccessGrant)
        : bool =
        grant.AllowedOperations.Contains operation

    let expiresIn
        (now : DateTimeOffset)
        (grant : ApprovedAccessGrant)
        : TimeSpan =
        grant.ExpiresAt - now

    let hasExpired
        (now : DateTimeOffset)
        (grant : ApprovedAccessGrant)
        : bool =
        now >= grant.ExpiresAt

    let isWithinIdentityScope
        (scope : string)
        (grant : ApprovedAccessGrant)
        : bool =
        String.Equals(
            grant.IdentityScope,
            scope,
            StringComparison.OrdinalIgnoreCase
        )

    let isWithinResourceScope
        (scope : string)
        (grant : ApprovedAccessGrant)
        : bool =
        String.Equals(
            grant.ResourceScope,
            scope,
            StringComparison.OrdinalIgnoreCase
        )

    let summary
        (grant : ApprovedAccessGrant)
        : string =
        sprintf
            "Grant=%O Principal=%s IdentityScope=%s ResourceScope=%s PolicyGen=%d CredentialEpoch=%d Operations=%d"
            grant.GrantId
            grant.PrincipalId
            grant.IdentityScope
            grant.ResourceScope
            grant.PolicyGeneration
            grant.CredentialEpoch
            grant.AllowedOperations.Count
