#pragma once

#include <string>
#include <set>
#include <chrono>
#include <sstream>

class IdentityNode
{
public:

    using TimePoint = std::chrono::system_clock::time_point;

    IdentityNode(
        std::string grantId,
        std::string principalId,
        std::string identityScope,
        long policyGeneration,
        long credentialEpoch,
        std::set<std::string> allowedOperations,
        TimePoint issuedAt,
        TimePoint expiresAt,
        std::string approvalSignature)
        :
        grantId_(std::move(grantId)),
        principalId_(std::move(principalId)),
        identityScope_(std::move(identityScope)),
        policyGeneration_(policyGeneration),
        credentialEpoch_(credentialEpoch),
        allowedOperations_(std::move(allowedOperations)),
        issuedAt_(issuedAt),
        expiresAt_(expiresAt),
        approvalSignature_(std::move(approvalSignature))
    {
    }

    const std::string& grantId() const
    {
        return grantId_;
    }

    const std::string& principalId() const
    {
        return principalId_;
    }

    const std::string& identityScope() const
    {
        return identityScope_;
    }

    long policyGeneration() const
    {
        return policyGeneration_;
    }

    long credentialEpoch() const
    {
        return credentialEpoch_;
    }

    const std::set<std::string>& allowedOperations() const
    {
        return allowedOperations_;
    }

    const TimePoint& issuedAt() const
    {
        return issuedAt_;
    }

    const TimePoint& expiresAt() const
    {
        return expiresAt_;
    }

    const std::string& approvalSignature() const
    {
        return approvalSignature_;
    }

    bool permitsOperation(const std::string& operation) const
    {
        return allowedOperations_.find(operation) != allowedOperations_.end();
    }

    bool hasExpired(TimePoint now) const
    {
        return now >= expiresAt_;
    }

    bool valid() const
    {
        return !grantId_.empty()
            && !principalId_.empty()
            && !identityScope_.empty()
            && policyGeneration_ >= 0
            && credentialEpoch_ >= 0
            && !allowedOperations_.empty()
            && issuedAt_ < expiresAt_
            && !approvalSignature_.empty();
    }

    /// Age of this identity node relative to a reference time,
    /// clamped to zero if issuedAt_ is in the future.
    std::chrono::seconds ageAt(TimePoint now) const
    {
        if (now <= issuedAt_)
        {
            return std::chrono::seconds(0);
        }

        return std::chrono::duration_cast<std::chrono::seconds>(now - issuedAt_);
    }

    /// Whether this node and another node were derived from the same
    /// grant, identity scope, policy generation, and credential
    /// epoch. Two nodes that differ only in operations or timestamps
    /// still count as sharing the same authorization identity.
    bool sharesAuthorizationIdentityWith(const IdentityNode& other) const
    {
        return grantId_ == other.grantId_
            && identityScope_ == other.identityScope_
            && policyGeneration_ == other.policyGeneration_
            && credentialEpoch_ == other.credentialEpoch_;
    }

    bool operator==(const IdentityNode& other) const
    {
        return grantId_ == other.grantId_
            && principalId_ == other.principalId_
            && identityScope_ == other.identityScope_
            && policyGeneration_ == other.policyGeneration_
            && credentialEpoch_ == other.credentialEpoch_
            && allowedOperations_ == other.allowedOperations_
            && issuedAt_ == other.issuedAt_
            && expiresAt_ == other.expiresAt_
            && approvalSignature_ == other.approvalSignature_;
    }

    bool operator!=(const IdentityNode& other) const
    {
        return !(*this == other);
    }

    std::string authorizationIdentity() const
    {
        std::ostringstream stream;

        stream
            << grantId_
            << '|'
            << identityScope_
            << '|'
            << policyGeneration_
            << '|'
            << credentialEpoch_;

        return stream.str();
    }

    std::string summary() const
    {
        std::ostringstream stream;

        stream
            << "IdentityNode("
            << "grant=" << grantId_
            << ", principal=" << principalId_
            << ", scope=" << identityScope_
            << ", policyGeneration=" << policyGeneration_
            << ", credentialEpoch=" << credentialEpoch_
            << ", operations=" << allowedOperations_.size()
            << ")";

        return stream.str();
    }

private:

    std::string grantId_;

    std::string principalId_;

    std::string identityScope_;

    long policyGeneration_;

    long credentialEpoch_;

    std::set<std::string> allowedOperations_;

    TimePoint issuedAt_;

    TimePoint expiresAt_;

    std::string approvalSignature_;
};
