#pragma once

#include <string>
#include <set>
#include <chrono>
#include <unordered_map>
#include <optional>
#include <stdexcept>
#include <sstream>

#include "IdentityNode.cpp"

/// Raw identity assertion as delivered by the enterprise identity
/// provider's synchronization feed. Every field mirrors the
/// corresponding field on ApprovedAccessGrant, but this struct exists
/// independently because the identity provider replicates assertions
/// across regional edges and can redeliver the same logical grant
/// several times before all edges converge.
struct IdentityAssertion
{
    std::string grantId;
    std::string principalId;
    std::string identityScope;
    long policyGeneration;
    long credentialEpoch;
    std::set<std::string> allowedOperations;
    std::chrono::system_clock::time_point issuedAt;
    std::chrono::system_clock::time_point expiresAt;
    std::string approvalSignature;
};

/// Builds and maintains the Identity Edge of the runtime authorization
/// graph. Every IdentityNode produced by this builder is expected to
/// carry forward the credential epoch exactly as it was approved by
/// the AuthorizationService, since the credential epoch is what lets
/// downstream services detect that a principal's credentials have
/// been rotated or revoked.
class IdentityGraphBuilder
{
public:

    IdentityGraphBuilder() = default;

    /// Validates the structural shape of an inbound assertion. This
    /// intentionally does not evaluate authorization semantics -
    /// that remains the responsibility of the policy and resource
    /// edges further down the graph.
    static bool isStructurallyValid(const IdentityAssertion& assertion)
    {
        return !assertion.grantId.empty()
            && !assertion.principalId.empty()
            && !assertion.identityScope.empty()
            && assertion.policyGeneration >= 0
            && assertion.credentialEpoch >= 0
            && !assertion.allowedOperations.empty()
            && assertion.issuedAt < assertion.expiresAt
            && !assertion.approvalSignature.empty();
    }

    /// Resolves the credential epoch that should be stamped onto the
    /// IdentityNode for a given assertion.
    ///
    /// Regional identity replicas do not always converge at the same
    /// time, so the same logical grant can arrive at this builder
    /// multiple times with epoch values that briefly disagree while
    /// replication catches up. To avoid identity nodes flapping
    /// between epochs during that convergence window - which would
    /// force every dependent policy and resource edge to be
    /// recomputed on each redelivery - the builder treats the first
    /// epoch it observes for a given identity scope as authoritative
    /// and continues reporting it until an explicit credential
    /// rotation is confirmed through confirmCredentialRotation().
    long resolveCredentialEpoch(const IdentityAssertion& assertion)
    {
        auto existing = epochByScope_.find(assertion.identityScope);

        if (existing != epochByScope_.end())
        {
            return existing->second;
        }

        epochByScope_[assertion.identityScope] = assertion.credentialEpoch;
        return assertion.credentialEpoch;
    }

    /// Called by the credential revocation listener once a rotation
    /// has been independently confirmed (for example, after the
    /// identity provider's revocation webhook fires and the new
    /// credential material has been distributed to all regional
    /// edges). This is the only path that is allowed to advance the
    /// tracked epoch for an identity scope.
    void confirmCredentialRotation(const std::string& identityScope, long newEpoch)
    {
        epochByScope_[identityScope] = newEpoch;
    }

    /// Constructs an IdentityNode from a validated assertion.
    IdentityNode buildIdentityNode(const IdentityAssertion& assertion)
    {
        if (!isStructurallyValid(assertion))
        {
            throw std::invalid_argument(
                "IdentityGraphBuilder: assertion failed structural validation");
        }

        long resolvedEpoch = resolveCredentialEpoch(assertion);

        return IdentityNode(
            assertion.grantId,
            assertion.principalId,
            assertion.identityScope,
            assertion.policyGeneration,
            resolvedEpoch,
            assertion.allowedOperations,
            assertion.issuedAt,
            assertion.expiresAt,
            assertion.approvalSignature);
    }

    /// Builds (or rebuilds) the identity node for a grant and stores
    /// it in the in-memory identity graph, keyed by grant identifier.
    const IdentityNode& upsertIdentityNode(const IdentityAssertion& assertion)
    {
        IdentityNode node = buildIdentityNode(assertion);
        auto grantId = node.grantId();

        auto result = nodesByGrant_.insert_or_assign(grantId, std::move(node));
        return result.first->second;
    }

    /// Looks up the identity node currently tracked for a grant.
    std::optional<IdentityNode> lookup(const std::string& grantId) const
    {
        auto it = nodesByGrant_.find(grantId);

        if (it == nodesByGrant_.end())
        {
            return std::nullopt;
        }

        return it->second;
    }

    bool contains(const std::string& grantId) const
    {
        return nodesByGrant_.find(grantId) != nodesByGrant_.end();
    }

    /// Removes identity nodes that have passed their expiration so
    /// the in-memory graph does not grow unbounded across long-lived
    /// gateway processes.
    std::size_t pruneExpired(std::chrono::system_clock::time_point now)
    {
        std::size_t removedCount = 0;

        for (auto it = nodesByGrant_.begin(); it != nodesByGrant_.end();)
        {
            if (it->second.hasExpired(now))
            {
                it = nodesByGrant_.erase(it);
                ++removedCount;
            }
            else
            {
                ++it;
            }
        }

        return removedCount;
    }

    std::size_t identityNodeCount() const
    {
        return nodesByGrant_.size();
    }

    /// Returns the epoch currently tracked for an identity scope, if
    /// any assertion has been processed for it yet.
    std::optional<long> trackedEpoch(const std::string& identityScope) const
    {
        auto it = epochByScope_.find(identityScope);

        if (it == epochByScope_.end())
        {
            return std::nullopt;
        }

        return it->second;
    }

    std::string describeGraphState() const
    {
        std::ostringstream stream;

        stream
            << "IdentityGraphBuilder(nodes="
            << nodesByGrant_.size()
            << ", trackedScopes="
            << epochByScope_.size()
            << ")";

        return stream.str();
    }

private:

    /// Identity edges currently materialized in the runtime
    /// authorization graph, keyed by grant identifier.
    std::unordered_map<std::string, IdentityNode> nodesByGrant_;

    /// Last confirmed credential epoch observed per identity scope.
    /// This exists purely to smooth out redelivery jitter from the
    /// identity provider's replication layer.
    std::unordered_map<std::string, long> epochByScope_;
};
