## FILE: policy/PolicyNode.rs

```
//! Policy edge of the runtime authorization graph.
//!
//! A `PolicyNode` represents the outcome of evaluating enterprise
//! policy for a single approved grant against a specific identity
//! scope and resource scope pair. It is intentionally immutable once
//! constructed - policy changes are represented by producing a new
//! node with an incremented `policy_generation`, never by mutating an
//! existing one in place.

use std::collections::HashSet;
use std::time::{Duration, SystemTime};

/// A single evaluated policy edge.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PolicyNode {
    pub grant_id: String,
    pub identity_scope: String,
    pub resource_scope: String,
    pub policy_generation: i64,
    pub allowed_operations: HashSet<String>,
    pub evaluated_at: SystemTime,
    pub ttl: Duration,
}

/// Errors that can occur while constructing a `PolicyNode`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PolicyNodeError {
    MissingGrantId,
    MissingIdentityScope,
    MissingResourceScope,
    NegativePolicyGeneration,
    EmptyAllowedOperations,
}

impl std::fmt::Display for PolicyNodeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PolicyNodeError::MissingGrantId => write!(f, "grant_id must not be empty"),
            PolicyNodeError::MissingIdentityScope => {
                write!(f, "identity_scope must not be empty")
            }
            PolicyNodeError::MissingResourceScope => {
                write!(f, "resource_scope must not be empty")
            }
            PolicyNodeError::NegativePolicyGeneration => {
                write!(f, "policy_generation must not be negative")
            }
            PolicyNodeError::EmptyAllowedOperations => {
                write!(f, "allowed_operations must not be empty")
            }
        }
    }
}

impl std::error::Error for PolicyNodeError {}

/// The canonical fields that identify which authorization instance a
/// policy edge belongs to. Two policy edges are considered part of
/// the same authorization only when every field here matches.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct PolicyAuthorizationIdentity {
    pub grant_id: String,
    pub identity_scope: String,
    pub resource_scope: String,
    pub policy_generation: i64,
}

impl PolicyNode {
    /// Constructs a new policy edge, validating that every field is
    /// well formed before it can enter the runtime graph.
    pub fn new(
        grant_id: impl Into<String>,
        identity_scope: impl Into<String>,
        resource_scope: impl Into<String>,
        policy_generation: i64,
        allowed_operations: HashSet<String>,
        evaluated_at: SystemTime,
        ttl: Duration,
    ) -> Result<Self, PolicyNodeError> {
        let grant_id = grant_id.into();
        let identity_scope = identity_scope.into();
        let resource_scope = resource_scope.into();

        if grant_id.trim().is_empty() {
            return Err(PolicyNodeError::MissingGrantId);
        }

        if identity_scope.trim().is_empty() {
            return Err(PolicyNodeError::MissingIdentityScope);
        }

        if resource_scope.trim().is_empty() {
            return Err(PolicyNodeError::MissingResourceScope);
        }

        if policy_generation < 0 {
            return Err(PolicyNodeError::NegativePolicyGeneration);
        }

        if allowed_operations.is_empty() {
            return Err(PolicyNodeError::EmptyAllowedOperations);
        }

        Ok(PolicyNode {
            grant_id,
            identity_scope,
            resource_scope,
            policy_generation,
            allowed_operations,
            evaluated_at,
            ttl,
        })
    }

    /// The canonical authorization identity that this edge claims to
    /// belong to.
    pub fn authorization_identity(&self) -> PolicyAuthorizationIdentity {
        PolicyAuthorizationIdentity {
            grant_id: self.grant_id.clone(),
            identity_scope: self.identity_scope.clone(),
            resource_scope: self.resource_scope.clone(),
            policy_generation: self.policy_generation,
        }
    }

    /// Whether this policy edge permits the given operation.
    pub fn permits_operation(&self, operation: &str) -> bool {
        self.allowed_operations.contains(operation)
    }

    /// Whether this evaluation result has aged out and needs to be
    /// recomputed from the source policy engine.
    pub fn is_stale(&self, now: SystemTime) -> bool {
        match now.duration_since(self.evaluated_at) {
            Ok(elapsed) => elapsed >= self.ttl,
            // If the clock appears to have gone backwards, treat the
            // node as stale rather than trusting a negative duration.
            Err(_) => true,
        }
    }

    /// Whether this edge represents a strictly newer policy decision
    /// than `other` for the same grant.
    pub fn supersedes(&self, other: &PolicyNode) -> bool {
        self.grant_id == other.grant_id && self.policy_generation > other.policy_generation
    }

    pub fn summary(&self) -> String {
        format!(
            "PolicyNode(grant={}, identityScope={}, resourceScope={}, policyGeneration={}, operations={})",
            self.grant_id,
            self.identity_scope,
            self.resource_scope,
            self.policy_generation,
            self.allowed_operations.len()
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_operations() -> HashSet<String> {
        let mut ops = HashSet::new();
        ops.insert("schedule.read".to_string());
        ops.insert("schedule.write".to_string());
        ops
    }

    #[test]
    fn rejects_empty_grant_id() {
        let result = PolicyNode::new(
            "",
            "ground-ops",
            "ground-station-7",
            1,
            sample_operations(),
            SystemTime::now(),
            Duration::from_secs(300),
        );

        assert_eq!(result.unwrap_err(), PolicyNodeError::MissingGrantId);
    }

    #[test]
    fn newer_generation_supersedes_older_generation() {
        let older = PolicyNode::new(
            "grant-1",
            "ground-ops",
            "ground-station-7",
            1,
            sample_operations(),
            SystemTime::now(),
            Duration::from_secs(300),
        )
        .unwrap();

        let newer = PolicyNode::new(
            "grant-1",
            "ground-ops",
            "ground-station-7",
            2,
            sample_operations(),
            SystemTime::now(),
            Duration::from_secs(300),
        )
        .unwrap();

        assert!(newer.supersedes(&older));
        assert!(!older.supersedes(&newer));
    }
}
