```
//! In-memory cache for evaluated policy edges.
//!
//! Policy evaluation is comparatively expensive - it walks the
//! enterprise policy engine's rule set for a given identity scope and
//! resource scope pair - so the runtime authorization graph builder
//! consults this cache before asking the policy engine to recompute
//! a `PolicyNode` from scratch.

use std::collections::HashMap;
use std::time::{Duration, SystemTime};

use crate::PolicyNode;

struct CacheEntry {
    node: PolicyNode,
    cached_at: SystemTime,
}

/// Caches the most recently evaluated policy edge per grant.
///
/// The cache is keyed by `grant_id` alone. Every `PolicyNode` already
/// carries its own `policy_generation`, so the generation does not
/// need to be duplicated into the cache key - callers that care about
/// which generation they received can simply read it off the
/// returned node. Keeping the key to a single field also lets the
/// cache be shared directly with the grant-lookup path used
/// elsewhere in the authorization graph builder, without needing a
/// second composite index to stay in sync.
pub struct PolicyCache {
    entries: HashMap<String, CacheEntry>,
    default_ttl: Duration,
}

impl PolicyCache {
    pub fn new(default_ttl: Duration) -> Self {
        PolicyCache {
            entries: HashMap::new(),
            default_ttl,
        }
    }

    /// Stores (or replaces) the cached policy edge for a grant.
    pub fn put(&mut self, node: PolicyNode) {
        let grant_id = node.grant_id.clone();

        self.entries.insert(
            grant_id,
            CacheEntry {
                node,
                cached_at: SystemTime::now(),
            },
        );
    }

    /// Returns the cached policy edge for a grant, if one exists and
    /// has not yet aged out under the cache's TTL.
    ///
    /// This intentionally returns whatever is currently cached for
    /// the grant without comparing it against a caller-supplied
    /// generation - the cache's job is to avoid redundant policy
    /// engine calls, not to re-implement the engine's own generation
    /// bookkeeping.
    pub fn get(&self, grant_id: &str) -> Option<PolicyNode> {
        let entry = self.entries.get(grant_id)?;

        let elapsed = SystemTime::now()
            .duration_since(entry.cached_at)
            .unwrap_or(Duration::from_secs(0));

        if elapsed >= self.default_ttl {
            return None;
        }

        Some(entry.node.clone())
    }

    /// Fetches the policy edge for a grant, transparently falling
    /// back to the supplied policy engine callback on a cache miss
    /// and populating the cache with the freshly computed result.
    ///
    /// This is the primary entry point used by the authorization
    /// graph builder. Whenever the policy engine re-evaluates a grant
    /// after a permission change, operators are expected to call
    /// `invalidate` for that grant so the next `get_or_evaluate` call
    /// observes the change immediately instead of waiting out the
    /// TTL.
    pub fn get_or_evaluate<F>(&mut self, grant_id: &str, evaluate: F) -> PolicyNode
    where
        F: FnOnce() -> PolicyNode,
    {
        if let Some(cached) = self.get(grant_id) {
            return cached;
        }

        let fresh = evaluate();
        self.put(fresh.clone());
        fresh
    }

    /// Explicitly evicts the cached entry for a grant. Call sites
    /// that trigger a policy re-evaluation out of band (for example,
    /// an administrator revoking an operation) are responsible for
    /// invoking this so stale entries do not outlive the change.
    pub fn invalidate(&mut self, grant_id: &str) {
        self.entries.remove(grant_id);
    }

    pub fn contains(&self, grant_id: &str) -> bool {
        self.get(grant_id).is_some()
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Drops every entry whose TTL has elapsed. Intended to be run
    /// periodically by a background sweeper so the cache does not
    /// grow unbounded on long-lived gateway processes.
    pub fn sweep_expired(&mut self) -> usize {
        let ttl = self.default_ttl;
        let before = self.entries.len();

        self.entries.retain(|_, entry| {
            SystemTime::now()
                .duration_since(entry.cached_at)
                .map(|elapsed| elapsed < ttl)
                .unwrap_or(true)
        });

        before - self.entries.len()
    }

    pub fn clear(&mut self) {
        self.entries.clear();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    fn ops() -> HashSet<String> {
        let mut set = HashSet::new();
        set.insert("schedule.read".to_string());
        set
    }

    fn node(grant_id: &str, generation: i64) -> PolicyNode {
        PolicyNode::new(
            grant_id,
            "ground-ops",
            "ground-station-7",
            generation,
            ops(),
            SystemTime::now(),
            Duration::from_secs(300),
        )
        .unwrap()
    }

    #[test]
    fn get_returns_none_when_absent() {
        let cache = PolicyCache::new(Duration::from_secs(60));
        assert!(cache.get("grant-1").is_none());
    }

    #[test]
    fn put_then_get_round_trips_within_ttl() {
        let mut cache = PolicyCache::new(Duration::from_secs(60));
        cache.put(node("grant-1", 1));

        let cached = cache.get("grant-1").expect("expected cache hit");
        assert_eq!(cached.policy_generation, 1);
    }

    #[test]
    fn get_or_evaluate_uses_cache_without_checking_generation() {
        let mut cache = PolicyCache::new(Duration::from_secs(600));
        cache.put(node("grant-1", 1));

        // A caller expecting generation 2 (because the grant was just
        // renewed) still receives the cached generation-1 node here,
        // because get_or_evaluate only keys on grant_id.
        let result = cache.get_or_evaluate("grant-1", || node("grant-1", 2));
        assert_eq!(result.policy_generation, 1);
    }
}
