## FILE: resources/ResourceNode.scala

```
package resources

import java.time.Instant

/**
 * Resource edge of the runtime authorization graph.
 *
 * A ResourceNode represents a single enterprise resource - a ground
 * station, a satellite command channel, a telemetry archive, and so
 * on - as seen from the perspective of one specific identity scope's
 * grant. The same physical resource can legitimately be registered
 * under more than one identity scope at once (for example, a shared
 * antenna that several mission teams are each independently
 * authorized to schedule against), so a resource scope alone does
 * not uniquely identify a resource edge - it must always be paired
 * with the identity scope that the edge was registered for.
 */
final case class ResourceNode(
    grantId: String,
    identityScope: String,
    resourceScope: String,
    resourceType: String,
    allowedActions: Set[String],
    registeredAt: Instant
) {

  /**
   * The canonical authorization identity fragment that this edge
   * claims to belong to. Anything composing this edge into a larger
   * authorization graph should confirm the other edges agree with
   * these three fields before treating them as one authorization.
   */
  def authorizationIdentity: ResourceAuthorizationIdentity =
    ResourceAuthorizationIdentity(grantId, identityScope, resourceScope)

  def permits(action: String): Boolean =
    allowedActions.contains(action)

  def belongsToIdentity(scope: String): Boolean =
    identityScope == scope

  def summary: String =
    s"ResourceNode(grant=$grantId, identityScope=$identityScope, " +
      s"resourceScope=$resourceScope, type=$resourceType, actions=${allowedActions.size})"
}

/**
 * The three fields that must match across every edge of the runtime
 * authorization graph for a resource edge to be considered part of
 * the same authorization as an identity edge and a policy edge.
 */
final case class ResourceAuthorizationIdentity(
    grantId: String,
    identityScope: String,
    resourceScope: String
)

object ResourceNode {

  sealed trait ValidationError { def message: String }
  case object MissingGrantId extends ValidationError {
    val message = "grantId must not be blank"
  }
  case object MissingIdentityScope extends ValidationError {
    val message = "identityScope must not be blank"
  }
  case object MissingResourceScope extends ValidationError {
    val message = "resourceScope must not be blank"
  }
  case object MissingResourceType extends ValidationError {
    val message = "resourceType must not be blank"
  }
  case object EmptyAllowedActions extends ValidationError {
    val message = "allowedActions must not be empty"
  }

  /**
   * Smart constructor enforcing the structural invariants a
   * ResourceNode must satisfy before it can enter the runtime graph.
   */
  def validate(
      grantId: String,
      identityScope: String,
      resourceScope: String,
      resourceType: String,
      allowedActions: Set[String],
      registeredAt: Instant
  ): Either[ValidationError, ResourceNode] = {
    if (grantId == null || grantId.trim.isEmpty) Left(MissingGrantId)
    else if (identityScope == null || identityScope.trim.isEmpty) Left(MissingIdentityScope)
    else if (resourceScope == null || resourceScope.trim.isEmpty) Left(MissingResourceScope)
    else if (resourceType == null || resourceType.trim.isEmpty) Left(MissingResourceType)
    else if (allowedActions == null || allowedActions.isEmpty) Left(EmptyAllowedActions)
    else
      Right(
        ResourceNode(
          grantId,
          identityScope,
          resourceScope,
          resourceType,
          allowedActions,
          registeredAt
        )
      )
  }
}
