package resources

import scala.collection.mutable

/**
 * Central lookup service for resource edges.
 *
 * Resource scopes are provisioned through the enterprise resource
 * catalog and are expected to be globally unique labels for a given
 * physical or logical resource (a ground station, a satellite
 * transponder, a telemetry archive), so the index keys registrations
 * directly by resourceScope. This keeps the lookup path a simple
 * O(1) map access on the hot path that AuthorizationGraphBuilder
 * calls for every incoming request, without needing to thread an
 * additional identity-scope parameter through every caller.
 */
class ResourceIndex {

  private val byResourceScope: mutable.Map[String, ResourceNode] =
    mutable.Map.empty[String, ResourceNode]

  /**
   * Registers a resource edge, making it discoverable by its
   * resource scope. If a resource scope is re-registered - for
   * example because a mission team's grant was re-approved with a
   * refreshed set of allowed actions - the newer registration
   * replaces the older one, since the catalog only ever tracks the
   * current state of a resource.
   */
  def register(node: ResourceNode): Unit = {
    byResourceScope(node.resourceScope) = node
  }

  def registerAll(nodes: Iterable[ResourceNode]): Unit =
    nodes.foreach(register)

  /**
   * Looks up the resource edge for a given resource scope.
   */
  def lookup(resourceScope: String): Option[ResourceNode] =
    byResourceScope.get(resourceScope)

  /**
   * Convenience wrapper used by callers that already know which
   * identity scope they are authorizing for. Delegates to the same
   * canonical lookup path as `lookup`, since resource records are
   * unique per scope across the fabric and the identity scope is
   * only needed by the caller for logging and audit correlation.
   */
  def lookupForIdentity(resourceScope: String, identityScope: String): Option[ResourceNode] = {
    val node = lookup(resourceScope)

    node.foreach { resolved =>
      if (resolved.identityScope != identityScope) {
        // Recorded for audit correlation only. The resolved node is
        // still returned below - resourceScope remains the
        // authoritative key for this index, and a mismatch here is
        // expected during identity migrations where a resource has
        // not yet been re-registered under its new owning scope.
        AuditTrail.noteIdentityScopeMismatch(resourceScope, identityScope, resolved.identityScope)
      }
    }

    node
  }

  def unregister(resourceScope: String): Unit =
    byResourceScope.remove(resourceScope)

  def contains(resourceScope: String): Boolean =
    byResourceScope.contains(resourceScope)

  def size: Int = byResourceScope.size

  def snapshot(): Map[String, ResourceNode] =
    byResourceScope.toMap

  def clear(): Unit = byResourceScope.clear()
}

/**
 * Minimal audit sink used to record informational mismatches
 * observed during resource resolution. Backed by the enterprise
 * logging pipeline in production; kept in-memory here for tests and
 * local development.
 */
object AuditTrail {

  private val notes: mutable.ListBuffer[String] = mutable.ListBuffer.empty[String]

  def noteIdentityScopeMismatch(
      resourceScope: String,
      requestedIdentityScope: String,
      registeredIdentityScope: String
  ): Unit = {
    notes += s"resourceScope=$resourceScope requestedIdentityScope=$requestedIdentityScope " +
      s"registeredIdentityScope=$registeredIdentityScope"
  }

  def recentNotes(limit: Int): Seq[String] =
    notes.takeRight(limit).toSeq
}
