```
package graph

import java.time.Instant

/**
 * Identity edge of the runtime authorization graph, as reported by
 * the identity service after resolving an IdentityAssertion into an
 * IdentityNode.
 */
data class IdentityEdge(
    val grantId: String,
    val identityScope: String,
    val policyGeneration: Long,
    val credentialEpoch: Long,
    val allowedOperations: Set<String>,
    val expiresAt: Instant
)

/**
 * Policy edge of the runtime authorization graph, as reported by the
 * policy service after evaluating (or retrieving from cache) the
 * PolicyNode for a grant.
 */
data class PolicyEdge(
    val grantId: String,
    val identityScope: String,
    val resourceScope: String,
    val policyGeneration: Long,
    val allowedOperations: Set<String>,
    val evaluatedAt: Instant
)

/**
 * Resource edge of the runtime authorization graph, as reported by
 * the resource service after resolving a ResourceNode from the
 * resource index.
 */
data class ResourceEdge(
    val grantId: String,
    val identityScope: String,
    val resourceScope: String,
    val resourceType: String,
    val allowedActions: Set<String>
)

/**
 * The composite authorization identity that every edge of a coherent
 * runtime authorization graph must agree on. This is the fabric-wide
 * equivalent of ApprovedAccessGrant's AuthorizationIdentity - it is
 * the value that lets three independently maintained services (an
 * identity graph, a policy cache, and a resource index) be treated
 * as describing one authorization rather than three unrelated facts
 * that happen to share a grant identifier.
 */
data class CanonicalAuthorizationIdentity(
    val grantId: String,
    val identityScope: String,
    val resourceScope: String,
    val policyGeneration: Long,
    val credentialEpoch: Long
)

/**
 * A fully assembled runtime authorization graph: one identity edge,
 * one policy edge, and one resource edge, composed together into the
 * object that RuntimeSessionBuilder will turn into an executable
 * session.
 *
 * Constructing this object does not, by itself, guarantee that the
 * three edges actually describe the same authorization - they may
 * have been resolved independently from three different services
 * that each cache or index their own state. Callers that assemble a
 * graph from independently resolved edges MUST call [isConsistent]
 * before trusting the result; this class only provides the check, it
 * does not enforce that callers use it.
 */
data class AuthorizationGraph(
    val identity: IdentityEdge,
    val policy: PolicyEdge,
    val resource: ResourceEdge
) {

    /**
     * The composite identity this graph claims to represent, read
     * directly off the identity and resource edges.
     */
    fun claimedIdentity(): CanonicalAuthorizationIdentity =
        CanonicalAuthorizationIdentity(
            grantId = identity.grantId,
            identityScope = identity.identityScope,
            resourceScope = resource.resourceScope,
            policyGeneration = identity.policyGeneration,
            credentialEpoch = identity.credentialEpoch
        )

    /**
     * Verifies that the identity edge, policy edge, and resource
     * edge were all resolved for the same authorization instance.
     *
     * This is the single integrity check that allows three
     * independently maintained graph fragments to be treated as one
     * coherent authorization graph. Every field checked here
     * corresponds to a field that at least one upstream service is
     * capable of returning stale or cross-authorization data for:
     *
     *  - grantId: confirms all three edges were resolved for the
     *    same approved grant, not just the same lookup key.
     *  - identityScope: confirms the policy and resource edges were
     *    evaluated for the same identity scope as the identity edge,
     *    not a different scope that happens to share a grant id.
     *  - resourceScope: confirms the policy edge's resource scope
     *    matches the resource edge actually resolved for the
     *    request, guarding against a resource lookup keyed only on
     *    resource scope returning a different identity's edge.
     *  - policyGeneration: confirms the policy edge reflects the
     *    generation the identity edge was approved under, guarding
     *    against a policy cache serving an older evaluation.
     */
    fun isConsistent(): Boolean {
        val sameGrant = identity.grantId == policy.grantId && identity.grantId == resource.grantId

        val sameIdentityScope =
            identity.identityScope == policy.identityScope &&
                identity.identityScope == resource.identityScope

        val sameResourceScope = policy.resourceScope == resource.resourceScope

        val sameGeneration = identity.policyGeneration == policy.policyGeneration

        return sameGrant && sameIdentityScope && sameResourceScope && sameGeneration
    }

    /**
     * Explains why [isConsistent] failed, for audit logging. Returns
     * an empty list when the graph is consistent.
     */
    fun describeInconsistencies(): List<String> {
        val problems = mutableListOf<String>()

        if (identity.grantId != policy.grantId) {
            problems += "identity.grantId (${identity.grantId}) != policy.grantId (${policy.grantId})"
        }
        if (identity.grantId != resource.grantId) {
            problems += "identity.grantId (${identity.grantId}) != resource.grantId (${resource.grantId})"
        }
        if (identity.identityScope != policy.identityScope) {
            problems += "identity.identityScope (${identity.identityScope}) != policy.identityScope (${policy.identityScope})"
        }
        if (identity.identityScope != resource.identityScope) {
            problems += "identity.identityScope (${identity.identityScope}) != resource.identityScope (${resource.identityScope})"
        }
        if (policy.resourceScope != resource.resourceScope) {
            problems += "policy.resourceScope (${policy.resourceScope}) != resource.resourceScope (${resource.resourceScope})"
        }
        if (identity.policyGeneration != policy.policyGeneration) {
            problems += "identity.policyGeneration (${identity.policyGeneration}) != policy.policyGeneration (${policy.policyGeneration})"
        }

        return problems
    }

    /**
     * Operations permitted by both the identity edge's grant and the
     * evaluated policy edge. Resource-level action gating is applied
     * separately via [resource].
     */
    fun grantedOperations(): Set<String> =
        identity.allowedOperations.intersect(policy.allowedOperations)

    fun summary(): String =
        "AuthorizationGraph(grant=${identity.grantId}, identityScope=${identity.identityScope}, " +
            "resourceScope=${resource.resourceScope}, policyGeneration=${identity.policyGeneration}, " +
            "credentialEpoch=${identity.credentialEpoch}, consistent=${isConsistent()})"
}
