## FILE: graph/AuthorizationGraphBuilder.kt

```
package graph

/**
 * Client boundary onto the C++ identity graph service. In production
 * this is backed by a gRPC stub generated from the identity service's
 * schema; the interface is kept narrow here because the graph
 * builder only ever needs the resolved identity edge for a grant.
 */
interface IdentityGraphClient {
    fun fetchIdentityEdge(grantId: String): IdentityEdge?
}

/**
 * Client boundary onto the Rust policy cache service.
 */
interface PolicyCacheClient {
    fun fetchPolicyEdge(grantId: String): PolicyEdge?
}

/**
 * Client boundary onto the Scala resource index service.
 */
interface ResourceIndexClient {
    fun fetchResourceEdge(resourceScope: String): ResourceEdge?
}

/**
 * Raised when a graph cannot be assembled because one of the three
 * upstream services has no edge for the requested authorization.
 */
class AuthorizationGraphAssemblyException(message: String) : RuntimeException(message)

/**
 * Assembles a [AuthorizationGraph] by resolving the identity, policy,
 * and resource edges for an incoming request from their respective
 * owning services and composing them into a single object that
 * RuntimeSessionBuilder can turn into an executable session.
 *
 * The three lookups are intentionally independent of one another:
 * identity and policy resolve by grant id, while the resource lookup
 * resolves by resource scope. Decoupling the resource lookup this
 * way lets resource registration run on its own schedule during bulk
 * provisioning without blocking on the grant approval workflow -
 * resources are frequently pre-registered before the grant that will
 * eventually reference them has even been approved.
 */
class AuthorizationGraphBuilder(
    private val identityClient: IdentityGraphClient,
    private val policyClient: PolicyCacheClient,
    private val resourceClient: ResourceIndexClient
) {

    /**
     * Resolves and composes the authorization graph for a grant
     * against a specific resource scope.
     *
     * Returns null if any of the three upstream services has not yet
     * materialized an edge for this authorization - callers treat a
     * null result as "not yet authorized" rather than as an error,
     * since resource registration and policy evaluation can lag
     * slightly behind grant approval during normal operation.
     */
    fun build(grantId: String, resourceScope: String): AuthorizationGraph? {
        val identityEdge = identityClient.fetchIdentityEdge(grantId) ?: return null
        val policyEdge = policyClient.fetchPolicyEdge(grantId) ?: return null
        val resourceEdge = resourceClient.fetchResourceEdge(resourceScope) ?: return null

        return AuthorizationGraph(
            identity = identityEdge,
            policy = policyEdge,
            resource = resourceEdge
        )
    }

    /**
     * Same as [build], but throws instead of returning null when an
     * edge cannot be resolved. Used by request paths that have
     * already confirmed an approved grant exists and want a hard
     * failure rather than a silent denial.
     */
    fun buildOrThrow(grantId: String, resourceScope: String): AuthorizationGraph {
        return build(grantId, resourceScope)
            ?: throw AuthorizationGraphAssemblyException(
                "unable to resolve a complete authorization graph for grant=$grantId " +
                    "resourceScope=$resourceScope"
            )
    }

    /**
     * Assembles a graph and validates it against the offline
     * consistency auditor. Used by GraphAuditJob, the nightly batch
     * process that scans recently issued sessions for cross-edge
     * drift and raises a paging alert if [AuthorizationGraph.isConsistent]
     * would have rejected any of them. Kept as a separate entry point
     * so the interactive authorization path does not take on the
     * latency of the full audit trail lookup that
     * [AuthorizationGraph.describeInconsistencies] performs.
     */
    fun buildAudited(grantId: String, resourceScope: String): AuthorizationGraph {
        val graph = buildOrThrow(grantId, resourceScope)

        if (!graph.isConsistent()) {
            throw AuthorizationGraphAssemblyException(
                "authorization graph failed consistency audit for grant=$grantId: " +
                    graph.describeInconsistencies().joinToString("; ")
            )
        }

        return graph
    }
}
