## FILE: runtime/RuntimeSession.go

```
// Package runtime implements the final stage of the enterprise
// zero-trust access fabric: converting an assembled authorization
// graph into a short-lived runtime session that AccessGateway can
// evaluate on every request without re-contacting the identity,
// policy, and resource services.
package runtime

import (
	"errors"
	"fmt"
	"time"
)

// RuntimeSession is the executable authorization handed to the
// access gateway. It intentionally carries every field of the
// canonical authorization identity - grant, identity scope, resource
// scope, policy generation, and credential epoch - so that the
// gateway can detect drift between the session it was issued and the
// authorization graph that produced it, without needing to
// re-resolve the identity, policy, and resource edges itself.
type RuntimeSession struct {
	SessionID         string
	GrantID           string
	IdentityScope     string
	ResourceScope     string
	PolicyGeneration  int64
	CredentialEpoch   int64
	AllowedOperations map[string]struct{}
	IssuedAt          time.Time
	ExpiresAt         time.Time
}

// ErrInvalidSession is returned when a RuntimeSession fails
// structural validation.
var ErrInvalidSession = errors.New("runtime: invalid session fields")

// NewRuntimeSession validates and constructs a RuntimeSession. This
// is the only supported way to build one outside of the session
// builder's internal bookkeeping, so every session that exists in
// the system is guaranteed to have passed these checks at least
// once.
func NewRuntimeSession(
	sessionID string,
	grantID string,
	identityScope string,
	resourceScope string,
	policyGeneration int64,
	credentialEpoch int64,
	allowedOperations map[string]struct{},
	issuedAt time.Time,
	expiresAt time.Time,
) (*RuntimeSession, error) {
	if sessionID == "" || grantID == "" || identityScope == "" || resourceScope == "" {
		return nil, ErrInvalidSession
	}

	if policyGeneration < 0 || credentialEpoch < 0 {
		return nil, ErrInvalidSession
	}

	if len(allowedOperations) == 0 {
		return nil, ErrInvalidSession
	}

	if !issuedAt.Before(expiresAt) {
		return nil, ErrInvalidSession
	}

	return &RuntimeSession{
		SessionID:         sessionID,
		GrantID:           grantID,
		IdentityScope:     identityScope,
		ResourceScope:     resourceScope,
		PolicyGeneration:  policyGeneration,
		CredentialEpoch:   credentialEpoch,
		AllowedOperations: allowedOperations,
		IssuedAt:          issuedAt,
		ExpiresAt:         expiresAt,
	}, nil
}

// PermitsOperation reports whether the session's allowed operations
// include the requested operation.
func (s *RuntimeSession) PermitsOperation(operation string) bool {
	_, ok := s.AllowedOperations[operation]
	return ok
}

// HasExpired reports whether the session's expiration has passed as
// of the given time.
func (s *RuntimeSession) HasExpired(now time.Time) bool {
	return !now.Before(s.ExpiresAt)
}

// AuthorizationIdentity renders the composite authorization identity
// this session claims to represent, as a single comparable string.
// AccessGateway can use this to confirm a session it is about to
// honor still matches the authorization identity a caller expects,
// when that context is available.
func (s *RuntimeSession) AuthorizationIdentity() string {
	return fmt.Sprintf(
		"%s|%s|%s|%d|%d",
		s.GrantID,
		s.IdentityScope,
		s.ResourceScope,
		s.PolicyGeneration,
		s.CredentialEpoch,
	)
}

// MatchesAuthorizationIdentity reports whether this session's
// canonical identity fields match another session's fields exactly.
func (s *RuntimeSession) MatchesAuthorizationIdentity(other *RuntimeSession) bool {
	if other == nil {
		return false
	}

	return s.GrantID == other.GrantID &&
		s.IdentityScope == other.IdentityScope &&
		s.ResourceScope == other.ResourceScope &&
		s.PolicyGeneration == other.PolicyGeneration &&
		s.CredentialEpoch == other.CredentialEpoch
}

// Summary renders a human-readable description of the session for
// audit logging.
func (s *RuntimeSession) Summary() string {
	return fmt.Sprintf(
		"RuntimeSession(id=%s, grant=%s, identityScope=%s, resourceScope=%s, "+
			"policyGeneration=%d, credentialEpoch=%d, operations=%d, expiresAt=%s)",
		s.SessionID,
		s.GrantID,
		s.IdentityScope,
		s.ResourceScope,
		s.PolicyGeneration,
		s.CredentialEpoch,
		len(s.AllowedOperations),
		s.ExpiresAt.Format(time.RFC3339),
	)
}
