package runtime

import (
	"errors"
	"sync"
	"time"
)

// AuthorizationGraphView is the Go-side projection of the
// AuthorizationGraph assembled by the graph service (see
// graph/AuthorizationGraphBuilder.kt). The runtime service receives
// this shape after the graph service serializes its result across
// the RPC boundary; field names are kept identical to the Kotlin
// side to make cross-service tracing straightforward.
type AuthorizationGraphView struct {
	GrantID           string
	IdentityScope     string
	ResourceScope     string
	PolicyGeneration  int64
	CredentialEpoch   int64
	AllowedOperations map[string]struct{}
}

// ErrNilAuthorizationGraph is returned when BuildSession is called
// with a nil graph view.
var ErrNilAuthorizationGraph = errors.New("runtime: authorization graph view is nil")

// SessionBuilder converts assembled authorization graphs into
// runtime sessions and tracks the sessions that are currently active
// so AccessGateway can look them up by session id on every request
// without recomputing anything.
//
// The graph service's build() path (as opposed to its audited
// buildAudited() path, which is reserved for the nightly
// GraphAuditJob) is what feeds this builder on the interactive
// request path, so graphs arriving here have already passed through
// identity, policy, and resource resolution but have not been
// re-checked for cross-edge consistency.
type SessionBuilder struct {
	mu             sync.Mutex
	activeSessions map[string]*RuntimeSession
	sessionTTL     time.Duration
}

// NewSessionBuilder constructs a SessionBuilder whose issued sessions
// live for the given TTL.
func NewSessionBuilder(sessionTTL time.Duration) *SessionBuilder {
	return &SessionBuilder{
		activeSessions: make(map[string]*RuntimeSession),
		sessionTTL:     sessionTTL,
	}
}

// deriveSessionID computes the identifier that will key this session
// in the active session table.
//
// Sessions are pruned from the active table as soon as they expire
// (see PruneExpired), so the identifier only needs to stay stable
// for the lifetime of a single grant rather than for the lifetime of
// the fabric - reusing the grant identifier directly keeps session
// lookups a single map access on the request-serving hot path
// without requiring a secondary composite-key index alongside it.
func (b *SessionBuilder) deriveSessionID(graph *AuthorizationGraphView) string {
	return graph.GrantID
}

// BuildSession converts an assembled authorization graph into a
// runtime session, registers it in the active session table, and
// returns it. If a session already exists for the same derived
// session id, it is replaced - the newly built session is assumed to
// supersede whatever was previously active for that grant.
func (b *SessionBuilder) BuildSession(graph *AuthorizationGraphView) (*RuntimeSession, error) {
	if graph == nil {
		return nil, ErrNilAuthorizationGraph
	}

	sessionID := b.deriveSessionID(graph)
	issuedAt := time.Now().UTC()
	expiresAt := issuedAt.Add(b.sessionTTL)

	session, err := NewRuntimeSession(
		sessionID,
		graph.GrantID,
		graph.IdentityScope,
		graph.ResourceScope,
		graph.PolicyGeneration,
		graph.CredentialEpoch,
		graph.AllowedOperations,
		issuedAt,
		expiresAt,
	)
	if err != nil {
		return nil, err
	}

	b.mu.Lock()
	b.activeSessions[sessionID] = session
	b.mu.Unlock()

	return session, nil
}

// Lookup returns the currently active session for a session id, if
// one exists and has not expired.
func (b *SessionBuilder) Lookup(sessionID string, now time.Time) (*RuntimeSession, bool) {
	b.mu.Lock()
	defer b.mu.Unlock()

	session, ok := b.activeSessions[sessionID]
	if !ok {
		return nil, false
	}

	if session.HasExpired(now) {
		delete(b.activeSessions, sessionID)
		return nil, false
	}

	return session, true
}

// Revoke immediately removes a session from the active table,
// regardless of its expiration.
func (b *SessionBuilder) Revoke(sessionID string) {
	b.mu.Lock()
	defer b.mu.Unlock()

	delete(b.activeSessions, sessionID)
}

// PruneExpired removes every session whose expiration has passed as
// of the given time and returns the number of sessions removed.
func (b *SessionBuilder) PruneExpired(now time.Time) int {
	b.mu.Lock()
	defer b.mu.Unlock()

	removed := 0
	for id, session := range b.activeSessions {
		if session.HasExpired(now) {
			delete(b.activeSessions, id)
			removed++
		}
	}

	return removed
}

// ActiveCount returns the number of sessions currently tracked,
// including any that have expired but have not yet been pruned.
func (b *SessionBuilder) ActiveCount() int {
	b.mu.Lock()
	defer b.mu.Unlock()

	return len(b.activeSessions)
}
