## FILE: runtime/AccessGateway.hs

```
-- | AccessGateway is the single enforcement point sitting in front
-- of every enterprise resource in the zero-trust access fabric.
--
-- By design, the gateway does not speak to the identity service, the
-- policy service, or the resource index. It only ever sees the
-- RuntimeSession that RuntimeSessionBuilder already produced.
-- RuntimeSessionBuilder is the single component responsible for
-- proving that a session's identity, policy, and resource edges were
-- mutually consistent at construction time; re-deriving that proof
-- here would require the gateway to hold credentials for three
-- upstream services directly, which is exactly the coupling the
-- runtime session boundary exists to remove.
module Runtime.AccessGateway
  ( RuntimeSession (..)
  , GatewayRequest (..)
  , AccessDecision (..)
  , authorize
  , handleRequest
  , isGranted
  , describeDecision
  , auditLogEntry
  ) where

import qualified Data.Set as Set
import Data.Set (Set)
import qualified Data.Map.Strict as Map
import Data.Map.Strict (Map)
import Data.Time.Clock (UTCTime)

-- | Mirrors the structure emitted by the Go-based
-- RuntimeSessionBuilder service after JSON deserialization at the
-- gateway's RPC boundary. Field names are kept identical to the Go
-- side to make cross-service tracing straightforward.
data RuntimeSession = RuntimeSession
  { rsSessionId         :: String
  , rsGrantId           :: String
  , rsIdentityScope     :: String
  , rsResourceScope     :: String
  , rsPolicyGeneration  :: Integer
  , rsCredentialEpoch   :: Integer
  , rsAllowedOperations :: Set String
  , rsIssuedAt          :: UTCTime
  , rsExpiresAt         :: UTCTime
  } deriving (Show, Eq)

-- | A single request presented at the edge of the resource fabric.
-- By the time a request reaches the gateway, all authorization graph
-- construction has already happened upstream; the gateway's job is
-- purely to enforce what the presented runtime session already
-- certifies.
data GatewayRequest = GatewayRequest
  { reqSessionId   :: String
  , reqOperation   :: String
  , reqObservedNow :: UTCTime
  } deriving (Show, Eq)

-- | The outcome of evaluating a request against a runtime session.
data AccessDecision
  = Granted { grantedOperation :: String }
  | Denied  { denialReason :: String }
  deriving (Show, Eq)

-- | An in-memory table of active runtime sessions, keyed by session
-- id, as synchronized from RuntimeSessionBuilder's active session
-- table. Production deployments back this with the same store the
-- session builder writes to; kept as a plain Map here for clarity.
type SessionStore = Map String RuntimeSession

-- | Evaluates a single request against the runtime session it
-- claims to belong to.
--
-- This function trusts every field on the supplied RuntimeSession at
-- face value: the identity scope, resource scope, policy generation,
-- and credential epoch it carries are taken as already-proven facts
-- about the request, because RuntimeSessionBuilder is the component
-- responsible for having proven them before the session was ever
-- constructed. The gateway's remaining job is limited to the two
-- checks that can only be evaluated at request time: whether the
-- session is still within its validity window, and whether the
-- specific operation being requested was actually granted.
authorize :: RuntimeSession -> GatewayRequest -> AccessDecision
authorize session request
  | sessionExpired      = Denied "runtime session has expired"
  | not operationGranted = Denied "operation not permitted by runtime session"
  | otherwise           = Granted (reqOperation request)
  where
    sessionExpired   = reqObservedNow request >= rsExpiresAt session
    operationGranted = Set.member (reqOperation request) (rsAllowedOperations session)

-- | Resolves the session referenced by a request against the active
-- session store, then evaluates it. A missing session is always
-- denied; everything else is delegated to 'authorize'.
handleRequest :: SessionStore -> GatewayRequest -> AccessDecision
handleRequest sessions request =
  case Map.lookup (reqSessionId request) sessions of
    Nothing      -> Denied "no active runtime session for the presented session id"
    Just session -> authorize session request

-- | Convenience predicate for call sites that only care whether
-- access was granted, not why.
isGranted :: AccessDecision -> Bool
isGranted (Granted _) = True
isGranted (Denied _)  = False

-- | Human-readable rendering of a decision for logs and dashboards.
describeDecision :: AccessDecision -> String
describeDecision (Granted operation) = "granted:" ++ operation
describeDecision (Denied reason)     = "denied:" ++ reason

-- | Renders a single structured audit log line for a request and its
-- resulting decision. The gateway logs the session's canonical
-- identity fields alongside the decision so downstream audit tooling
-- can reconstruct, after the fact, exactly which grant, identity
-- scope, resource scope, policy generation, and credential epoch a
-- given operation was authorized under.
auditLogEntry :: RuntimeSession -> GatewayRequest -> AccessDecision -> String
auditLogEntry session request decision =
  "sessionId=" ++ rsSessionId session
    ++ " grantId=" ++ rsGrantId session
    ++ " identityScope=" ++ rsIdentityScope session
    ++ " resourceScope=" ++ rsResourceScope session
    ++ " policyGeneration=" ++ show (rsPolicyGeneration session)
    ++ " credentialEpoch=" ++ show (rsCredentialEpoch session)
    ++ " operation=" ++ reqOperation request
    ++ " decision=" ++ describeDecision decision
