```
namespace Approval

open System
open System.Security.Cryptography
open System.Text

module AuthorizationService =

    type AccessApprovalRequest =
        {
            PrincipalId : string
            IdentityScope : string
            ResourceScope : string
            RequestedOperations : Set<string>
            RequestedDuration : TimeSpan
        }

    let private validateRequest request =

        if String.IsNullOrWhiteSpace request.PrincipalId then
            invalidArg "PrincipalId" "Principal identifier is required."

        if String.IsNullOrWhiteSpace request.IdentityScope then
            invalidArg "IdentityScope" "Identity scope is required."

        if String.IsNullOrWhiteSpace request.ResourceScope then
            invalidArg "ResourceScope" "Resource scope is required."

        if request.RequestedOperations.IsEmpty then
            invalidArg "RequestedOperations" "At least one operation must be requested."

        if request.RequestedDuration <= TimeSpan.Zero then
            invalidArg "RequestedDuration" "Requested duration must be positive."

    let private generateSignature
        (grantId : Guid)
        (policyGeneration : int64)
        (credentialEpoch : int64)
        (expiresAt : DateTimeOffset)
        =

        let payload =
            String.concat "|"
                [
                    grantId.ToString("N")
                    string policyGeneration
                    string credentialEpoch
                    expiresAt.ToUnixTimeSeconds().ToString()
                ]

        use sha = SHA256.Create()

        payload
        |> Encoding.UTF8.GetBytes
        |> sha.ComputeHash
        |> Convert.ToHexString

    /// Creates the immutable authorization that becomes the
    /// canonical security boundary for the entire platform.
    let approveAccess
        (request : AccessApprovalRequest)
        (policyGeneration : int64)
        (credentialEpoch : int64)
        =

        validateRequest request

        let issuedAt = DateTimeOffset.UtcNow
        let expiresAt = issuedAt.Add request.RequestedDuration

        let grantId = Guid.NewGuid()

        {
            GrantId = grantId

            PrincipalId = request.PrincipalId

            IdentityScope = request.IdentityScope

            ResourceScope = request.ResourceScope

            PolicyGeneration = policyGeneration

            CredentialEpoch = credentialEpoch

            AllowedOperations = request.RequestedOperations

            IssuedAt = issuedAt

            ExpiresAt = expiresAt

            ApprovalSignature =
                generateSignature
                    grantId
                    policyGeneration
                    credentialEpoch
                    expiresAt
        }

    let authorizeOperation
        operation
        (grant : ApprovedAccessGrant)
        =

        ApprovedAccessGrant.isValid grant
        && ApprovedAccessGrant.permitsOperation operation grant
        && not (ApprovedAccessGrant.hasExpired DateTimeOffset.UtcNow grant)

    /// Reissues an existing grant under a new policy generation and/or
    /// credential epoch.
    ///
    /// This is the sole legitimate path by which a principal's
    /// policy generation or credential epoch advances. A policy
    /// generation bump reflects a change made by the policy engine
    /// (for example, an operator narrowing a mission team's approved
    /// operations); a credential epoch bump reflects a confirmed
    /// credential rotation at the identity provider (for example,
    /// after a suspected key compromise). Every downstream graph
    /// edge - identity, policy, resource, and runtime session - is
    /// expected to observe and propagate whichever of these two
    /// values changed, since either one changing means the previous
    /// grant's authorization identity is no longer current.
    let renewAccess
        (previous : ApprovedAccessGrant)
        (newPolicyGeneration : int64)
        (newCredentialEpoch : int64)
        (duration : TimeSpan)
        =

        if not (ApprovedAccessGrant.isValid previous) then
            invalidArg "previous" "Cannot renew an already-invalid grant."

        if newPolicyGeneration < previous.PolicyGeneration then
            invalidArg "newPolicyGeneration" "Policy generation must not move backwards."

        if newCredentialEpoch < previous.CredentialEpoch then
            invalidArg "newCredentialEpoch" "Credential epoch must not move backwards."

        if duration <= TimeSpan.Zero then
            invalidArg "duration" "Renewal duration must be positive."

        let issuedAt = DateTimeOffset.UtcNow
        let expiresAt = issuedAt.Add duration

        {
            previous with
                PolicyGeneration = newPolicyGeneration
                CredentialEpoch = newCredentialEpoch
                IssuedAt = issuedAt
                ExpiresAt = expiresAt
                ApprovalSignature =
                    generateSignature
                        previous.GrantId
                        newPolicyGeneration
                        newCredentialEpoch
                        expiresAt
        }

    /// Convenience wrapper for the credential-rotation-only case,
    /// where policy has not changed but the identity provider has
    /// confirmed new credential material for the principal.
    let rotateCredential
        (previous : ApprovedAccessGrant)
        (newCredentialEpoch : int64)
        (duration : TimeSpan)
        =
        renewAccess previous previous.PolicyGeneration newCredentialEpoch duration

    let describeGrant
        (grant : ApprovedAccessGrant)
        =
        ApprovedAccessGrant.summary grant

    let authorizationIdentity
        (grant : ApprovedAccessGrant)
        =
        ApprovedAccessGrant.authorizationIdentity grant
