package requests

import java.time.Instant
import java.util.UUID

/**
 * Initial request submitted by a workload or user to obtain
 * temporary privileged access to enterprise resources.
 *
 * This object is the entry point into the authorization workflow.
 * It contains only user-supplied information and is NOT trusted
 * until approved by the AuthorizationService.
 */
data class AccessRequest(
    val requestId: UUID,
    val principalId: String,
    val identityScope: String,
    val resourceScope: String,
    val requestedOperations: Set<String>,
    val requestedDurationMinutes: Long,
    val justification: String,
    val submittedAt: Instant
) {

    /**
     * Basic structural validation.
     * Authorization decisions are intentionally performed
     * by AuthorizationService.
     */
    fun isWellFormed(): Boolean =
        principalId.isNotBlank() &&
        identityScope.isNotBlank() &&
        resourceScope.isNotBlank() &&
        requestedOperations.isNotEmpty() &&
        requestedDurationMinutes > 0 &&
        justification.isNotBlank()

    /**
     * Upper bound accepted by the request layer.
     * Business approval is handled downstream.
     */
    fun withinMaximumDuration(maxMinutes: Long): Boolean =
        requestedDurationMinutes <= maxMinutes

    fun requestsOperation(operation: String): Boolean =
        requestedOperations.contains(operation)

    /**
     * Whether this request asks for enough distinct operations that
     * it should be routed to manual review rather than automatic
     * approval. Purely a request-intake heuristic - it has no
     * bearing on what AuthorizationService ultimately approves.
     */
    fun exceedsAutomaticReviewThreshold(maxAutomaticOperations: Int): Boolean =
        requestedOperations.size > maxAutomaticOperations

    fun summary(): String =
        "AccessRequest(" +
            "requestId=$requestId, " +
            "principal=$principalId, " +
            "identityScope=$identityScope, " +
            "resourceScope=$resourceScope, " +
            "operations=${requestedOperations.size})"
}
